INSERT INTO public.quiz_categories (id, slug, icon_name, accent_color, title_en, title_uz, title_ru, description_en, description_uz, description_ru, display_order) VALUES ('cat-programming', 'programming', 'Code', '#4F46E5', 'Programming', 'Dasturlash', 'Программирование', 'Master modern web engineering across HTML5 architecture, CSS styling & layouts, and React JS development.', 'HTML5 arxitekturasi, CSS dizayn va maketlar hamda React JS dasturlash bo''yicha zamonaviy veb-muhandislikni egallang.', 'Освойте современную веб-разработку: архитектуру HTML5, стилизацию и верстку CSS, а также разработку на React JS.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_categories (id, slug, icon_name, accent_color, title_en, title_uz, title_ru, description_en, description_uz, description_ru, display_order) VALUES ('cat-russian', 'russian-language', 'BookOpen', '#E11D48', 'Russian Language', 'Rus tili', 'Русский язык', 'Build fluency in Russian from Cyrillic alphabet and core grammar to verbs, nouns, sentence construction, and reading.', 'Kirill alifbosi va asosiy grammatikadan tortib fe''llar, otlar, gap tuzish va matnni tushunishgacha rus tilini mukammal o''rganing.', 'Развивайте владение русским языком: от алфавита и базовой лексики до грамматики, глаголов, существительных и чтения.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_categories (id, slug, icon_name, accent_color, title_en, title_uz, title_ru, description_en, description_uz, description_ru, display_order) VALUES ('cat-english', 'english-language', 'Globe', '#0284C7', 'English Language', 'Ingliz tili', 'Английский язык', 'Strengthen global communication with English vocabulary, tenses, grammar, pronouns, reading comprehension, and advanced usage.', 'Ingliz tili lug''ati, zamonlar, grammatika, olmoshlar, o''qib tushunish va ilg''or til ko''nikmalari bilan xalqaro muloqotni kuchaytiring.', 'Укрепите навыки международного общения: английская лексика, времена, грамматика, местоимения, чтение и продвинутый уровень.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_categories (id, slug, icon_name, accent_color, title_en, title_uz, title_ru, description_en, description_uz, description_ru, display_order) VALUES ('cat-mathematics', 'mathematics', 'Calculator', '#059669', 'Mathematics', 'Matematika', 'Математика', 'Sharpen quantitative reasoning across arithmetic, fractions, percentages, algebra, equations, geometry, and advanced math.', 'Arifmetika, kasrlar, foizlar, algebra, tenglamalar, geometriya va oliy matematika bo''yicha mantiqiy fikrlashni charxlang.', 'Отточите математическое мышление: дроби, арифметика, проценты, алгебра, уравнения, геометрия и высшая математика.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('html-basics', 'cat-programming', 'html', 'HTML', 'HTML', 'HTML', 'html-basics', 'HTML Basics', 'HTML Asoslari', 'Основы HTML', 'Document structure, DOCTYPE declaration, head, body, and core web page fundamentals.', 'Hujjat tuzilishi, DOCTYPE deklaratsiyasi, head, body va veb-sahifa asoslari.', 'Структура документа, декларация DOCTYPE, теги head, body и базовые принципы веб-страниц.', 'basic', 10, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('html-tags', 'cat-programming', 'html', 'HTML', 'HTML', 'HTML', 'html-tags', 'HTML Tags', 'HTML Teglari', 'HTML Теги', 'Headings, paragraphs, lists, text formatting, inline vs block-level elements.', 'Sarlavhalar, abzaslar, roʻyxatlar, matnni formatlash hamda qatorli va blokli elementlar.', 'Заголовки, абзацы, списки, форматирование текста, строчные и блочные элементы.', 'basic', 10, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('html-forms', 'cat-programming', 'html', 'HTML', 'HTML', 'HTML', 'html-forms', 'Forms and Inputs', 'Formalar va Kiritish Maydonlari', 'Формы и поля ввода', 'Form elements, input types, labels, select dropdowns, checkboxes, radio buttons, and validation.', 'Form elementlari, input turlari, label, select, checkbox, radio tugmalar va validatsiya.', 'Элементы форм, типы input, метки label, выпадающие списки, чекбоксы и валидация.', 'intermediate', 10, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('html-semantic', 'cat-programming', 'html', 'HTML', 'HTML', 'HTML', 'html-semantic', 'Semantic HTML', 'Semantik HTML', 'Семантический HTML', 'Meaningful layout tags including header, nav, main, article, section, aside, and footer.', 'Maʼnoli sahifa tuzilishi: header, nav, main, article, section, aside va footer teglari.', 'Смысловая разметка страницы: теги header, nav, main, article, section, aside и footer.', 'intermediate', 10, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('html-tables', 'cat-programming', 'html', 'HTML', 'HTML', 'HTML', 'html-tables', 'Tables', 'Jadvallar (Tables)', 'Таблицы', 'Building structured data tables with table, thead, tbody, tr, th, td, colspan, and rowspan.', 'table, thead, tbody, tr, th, td, colspan va rowspan yordamida maʼlumotlar jadvalini yaratish.', 'Создание таблиц данных с помощью table, thead, tbody, tr, th, td, colspan и rowspan.', 'intermediate', 10, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('html-links-images', 'cat-programming', 'html', 'HTML', 'HTML', 'HTML', 'html-links-images', 'Links and Images', 'Havolalar va Rasmlar', 'Ссылки и изображения', 'Anchor tags, relative vs absolute URLs, target attributes, responsive images, and alt text.', 'Anchor (a) tegi, nisbiy va absolyut manzillar, target atributi, rasmlar va alt matni.', 'Теги ссылок, относительные и абсолютные URL, атрибут target, изображения и атрибут alt.', 'basic', 10, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('html-attributes', 'cat-programming', 'html', 'HTML', 'HTML', 'HTML', 'html-attributes', 'HTML Attributes', 'HTML Atributlari', 'Атрибуты HTML', 'Global attributes: id, class, data-*, title, style, hidden, tabindex, and ARIA accessibility.', 'Global atributlar: id, class, data-*, title, style, hidden, tabindex va ARIA imkoniyatlari.', 'Глобальные атрибуты: id, class, data-*, title, style, hidden, tabindex и доступность ARIA.', 'intermediate', 10, 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('html-advanced', 'cat-programming', 'html', 'HTML', 'HTML', 'HTML', 'html-advanced', 'Advanced HTML', 'Ilgʻor HTML (Advanced)', 'Продвинутый HTML', 'HTML5 APIs, Canvas, SVG, audio/video media, meta SEO tags, OpenGraph, and web performance.', 'HTML5 API-lari, Canvas, SVG, audio/video media, SEO meta teglari va veb-samaradorlik.', 'HTML5 API, Canvas, SVG, аудио/видео мультимедиа, мета-теги SEO и производительность.', 'advanced', 10, 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('css-basics', 'cat-programming', 'css', 'CSS', 'CSS', 'CSS', 'css-basics', 'CSS Basics', 'CSS Asoslari', 'Основы CSS', 'Syntax rules, inline/internal/external stylesheets, the box model, margin, border, and padding.', 'Sintaksis qoidalari, uslub ulash usullari, Box Model, margin, border va padding.', 'Синтаксис CSS, способы подключения стилей, блочная модель (Box Model), margin, border и padding.', 'basic', 10, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('css-selectors', 'cat-programming', 'css', 'CSS', 'CSS', 'CSS', 'css-selectors', 'Selectors', 'Selektorlar (Selectors)', 'Селекторы', 'Class, ID, attribute, combinator, pseudo-class (:hover, :nth-child), and pseudo-element selectors.', 'Class, ID, atribut, kombinatorlar, psevdo-klasslar (:hover, :nth-child) va psevdo-elementlar.', 'Селекторы классов, ID, атрибутов, комбинаторы, псевдоклассы (:hover, :nth-child) и псевдоэлементы.', 'basic', 10, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('css-colors', 'cat-programming', 'css', 'CSS', 'CSS', 'CSS', 'css-colors', 'Colors and Backgrounds', 'Ranglar va Orqa Fonlar', 'Цвета и фоны', 'HEX, RGB, RGBA, HSL color models, opacity, background images, and linear/radial gradients.', 'HEX, RGB, RGBA, HSL rang modellari, shaffoflik, orqa fon rasmlari va chiziqli/radial gradiyentlar.', 'Цветовые модели HEX, RGB, RGBA, HSL, прозрачность, фоновые изображения и градиенты.', 'basic', 10, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('css-flexbox', 'cat-programming', 'css', 'CSS', 'CSS', 'CSS', 'css-flexbox', 'Flexbox', 'Flexbox Maketi', 'Flexbox верстка', 'One-dimensional layouts with display: flex, flex-direction, justify-content, align-items, and flex-wrap.', 'Bir oʻlchovli maketlar: display: flex, flex-direction, justify-content, align-items va flex-wrap.', 'Одномерные макеты: display: flex, flex-direction, justify-content, align-items и flex-wrap.', 'intermediate', 10, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('css-grid', 'cat-programming', 'css', 'CSS', 'CSS', 'CSS', 'css-grid', 'CSS Grid', 'CSS Grid Tizimi', 'CSS Grid сетки', 'Two-dimensional grid systems, grid-template-columns, fr unit, gap, grid areas, and auto-fit.', 'Ikki oʻlchovli toʻr tizimi: grid-template-columns, fr birligi, gap, grid-area va auto-fit.', 'Двумерные сетки: grid-template-columns, единица fr, gap, области сетки и auto-fit.', 'intermediate', 10, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('css-positioning', 'cat-programming', 'css', 'CSS', 'CSS', 'CSS', 'css-positioning', 'Positioning', 'Joylashuv (Positioning)', 'Позиционирование', 'Understanding static, relative, absolute, fixed, and sticky positioning along with z-index stacking.', 'static, relative, absolute, fixed va sticky joylashuv turlari hamda z-index qatlamlari.', 'Типы позиционирования static, relative, absolute, fixed, sticky и управление слоями z-index.', 'intermediate', 10, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('css-animations', 'cat-programming', 'css', 'CSS', 'CSS', 'CSS', 'css-animations', 'Animations', 'Animatsiyalar', 'Анимации и переходы', 'Smooth transitions, @keyframes rules, transform properties, timing functions, and GPU performance.', 'Silliq oʻtishlar (transition), @keyframes qoidalari, transform xossalari va vaqt funksiyalari.', 'Плавные переходы transition, правила @keyframes, трансформации transform и функции времени.', 'advanced', 10, 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('css-responsive', 'cat-programming', 'css', 'CSS', 'CSS', 'CSS', 'css-responsive', 'Responsive Design', 'Moslashuvchan Dizayn (Responsive)', 'Адаптивный дизайн', 'Media queries, mobile-first strategy, viewport units (vw, vh), rem/em scaling, and fluid typography.', 'Media soʻrovlar (@media), mobile-first yondashuvi, vw/vh birliklari, rem/em va moslashuvchan shriftlar.', 'Медиа-запросы @media, подход mobile-first, единицы vw/vh, rem/em и адаптивная типографика.', 'advanced', 10, 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('react-basics', 'cat-programming', 'react', 'React JS', 'React JS', 'React JS', 'react-basics', 'React Basics', 'React Asoslari', 'Основы React', 'Virtual DOM, declarative UI philosophy, single-page applications, and root rendering.', 'Virtual DOM, deklarativ interfeys tamoyillari, SPA ilovalar va React ildiz renderlash.', 'Виртуальный DOM, декларативный UI, одностраничные приложения (SPA) и корневой рендеринг.', 'basic', 10, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('react-components', 'cat-programming', 'react', 'React JS', 'React JS', 'React JS', 'react-components', 'Components', 'Komponentlar', 'Компоненты', 'Functional components, component composition, reusability, pure functions, and export/import patterns.', 'Funksional komponentlar, kompozitsiya, qayta foydalanish va modul eksport/import usullari.', 'Функциональные компоненты, композиция, переиспользование кода и модульная архитектура.', 'basic', 10, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('react-jsx', 'cat-programming', 'react', 'React JS', 'React JS', 'React JS', 'react-jsx', 'JSX', 'JSX Sintaksisi', 'Синтаксис JSX', 'JavaScript XML expressions, className vs class, fragments, conditional rendering, and list keys.', 'JavaScript XML ifodalari, className, Fragmentlar, shartli renderlash va roʻyxat kalitlari (key).', 'Выражения JSX, className, фрагменты, условный рендеринг и ключи списков (key).', 'basic', 10, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('react-props', 'cat-programming', 'react', 'React JS', 'React JS', 'React JS', 'react-props', 'Props', 'Props (Xususiyatlar)', 'Пропсы (Props)', 'Passing data top-down, prop destructuring, default values, children prop, and immutability.', 'Maʼlumotlarni yuqoridan pastga uzatish, destrukturizatsiya, children prop va oʻzgarmaslik.', 'Передача данных сверху вниз, деструктуризация пропсов, проп children и неизменяемость.', 'intermediate', 10, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('react-state', 'cat-programming', 'react', 'React JS', 'React JS', 'React JS', 'react-state', 'State', 'State (Holat Boshqaruvi)', 'Состояние (State)', 'Component memory, reactive re-rendering, lifting state up, and derived state principles.', 'Komponent xotirasi, reaktiv qayta chizish, holatni yuqoriga koʻtarish (lifting state up).', 'Память компонента, реактивный ререндеринг, подъем состояния (lifting state up).', 'intermediate', 10, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('react-usestate', 'cat-programming', 'react', 'React JS', 'React JS', 'React JS', 'react-usestate', 'useState', 'useState Xuki', 'Хук useState', 'State hook syntax, functional state updates, updating objects/arrays immutably, and lazy initialization.', 'useState sintaksisi, funksional yangilash, obyekt va massivlarni immutatsion yangilash.', 'Синтаксис useState, функциональные обновления, иммутабельное обновление объектов и массивов.', 'intermediate', 10, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('react-useeffect', 'cat-programming', 'react', 'React JS', 'React JS', 'React JS', 'react-useeffect', 'useEffect', 'useEffect Xuki', 'Хук useEffect', 'Side effects, dependency arrays, cleanup functions, data fetching, and lifecycle synchronization.', 'Yon taʼsirlar (side effects), bogʻliqliklar massivi, tozalash (cleanup) va API soʻrovlari.', 'Побочные эффекты, массив зависимостей, функция очистки (cleanup) и загрузка данных.', 'intermediate', 10, 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('react-router', 'cat-programming', 'react', 'React JS', 'React JS', 'React JS', 'react-router', 'React Router', 'React Router Navigatsiya', 'Маршрутизация React Router', 'Client-side routing, BrowserRouter, Routes, Route, Link, useNavigate, useParams, and nested routes.', 'Mijoz tomonida marshrutlash, Routes, Route, Link, useNavigate, useParams va ichki yoʻllar.', 'Клиентская маршрутизация, Routes, Route, Link, хуки useNavigate, useParams и вложенные роуты.', 'intermediate', 10, 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('react-events', 'cat-programming', 'react', 'React JS', 'React JS', 'React JS', 'react-events', 'Events', 'Hodisalar (Events)', 'События в React', 'Synthetic events, onClick, onChange, onSubmit, preventDefault, and passing arguments to handlers.', 'Sintetik hodisalar, onClick, onChange, onSubmit, preventDefault va funksiyalarga argument uzatish.', 'Синтетические события, onClick, onChange, onSubmit, preventDefault и передача аргументов.', 'basic', 10, 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('react-advanced', 'cat-programming', 'react', 'React JS', 'React JS', 'React JS', 'react-advanced', 'Advanced React', 'Ilgʻor React (Advanced)', 'Продвинутый React', 'Context API, useReducer, useMemo, useCallback, custom hooks, React.memo, and performance optimization.', 'Context API, useReducer, useMemo, useCallback, maxsus xuklar va ishlash tezligini optimallashtirish.', 'Context API, useReducer, useMemo, useCallback, кастомные хуки, React.memo и оптимизация.', 'advanced', 10, 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('ru-alphabet', 'cat-russian', 'russian', 'Russian Language', 'Rus tili', 'Русский язык', 'ru-alphabet', 'Russian Alphabet', 'Rus Alifbosi', 'Русский алфавит', '33 Cyrillic letters, vowels, consonants, hard and soft signs (ъ, ь), and pronunciation rules.', '33 ta kirill harfi, unli va undosh tovushlar, ayirish va yumshatish belgilari (ъ, ь) hamda talaffuz.', '33 буквы русского алфавита, гласные и согласные звуки, твердый и мягкий знаки, фонетика.', 'basic', 10, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('ru-vocabulary', 'cat-russian', 'russian', 'Russian Language', 'Rus tili', 'Русский язык', 'ru-vocabulary', 'Basic Vocabulary', 'Asosiy Lug''at Boyligi', 'Базовая лексика', 'Everyday greetings, family, numbers, time, professions, synonyms, and antonyms in Russian.', 'Kundalik salomlashish, oila, sonlar, vaqt, kasblar, sinonim va antonim soʻzlar.', 'Повседневная лексика, приветствия, семья, числительные, синонимы и антонимы.', 'basic', 10, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('ru-grammar', 'cat-russian', 'russian', 'Russian Language', 'Rus tili', 'Русский язык', 'ru-grammar', 'Grammar', 'Grammatika va Kelishiklar', 'Грамматика и падежи', 'The six Russian grammatical cases (падежи), gender agreement, adjectives, and prepositions.', 'Rus tilidagi 6 ta kelishik (падежи), rodlar moslashuvi, sifatlar va predloglar.', 'Шесть падежей русского языка, согласование по родам и числам, прилагательные и предлоги.', 'intermediate', 10, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('ru-verbs', 'cat-russian', 'russian', 'Russian Language', 'Rus tili', 'Русский язык', 'ru-verbs', 'Verbs', 'Fe''llar (Глаголы)', 'Глаголы', 'First and second conjugation, imperfective vs perfective aspects (НСВ/СВ), tenses, and verbs of motion.', 'Birinchi va ikkinchi tuslanish, tugallangan va tugallanmagan fe''l turlari, zamonlar va harakat fe''llari.', 'Первое и второе спряжение, совершенный и несовершенный вид глагола, времена и глаголы движения.', 'intermediate', 10, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('ru-nouns', 'cat-russian', 'russian', 'Russian Language', 'Rus tili', 'Русский язык', 'ru-nouns', 'Nouns', 'Otlar (Существительные)', 'Имена существительные', 'Masculine, feminine, and neuter genders, singular/plural forms, animate vs inanimate nouns, and declensions.', 'Erkak, ayol va oʻrta rod (мужской, женский, средний род), birlik va koʻplik, jonli va jonsiz otlar.', 'Мужской, женский и средний род, единственное и множественное число, склонения существительных.', 'basic', 10, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('ru-sentences', 'cat-russian', 'russian', 'Russian Language', 'Rus tili', 'Русский язык', 'ru-sentences', 'Sentence Construction', 'Gap Tuzish (Синтаксис)', 'Построение предложений', 'Subject and predicate structure, word order, conjunctions, complex sentences, and punctuation.', 'Ega va kesim, soʻz tartibi, bogʻlovchilar, qoʻshma gaplar va tinish belgilari.', 'Подлежащее и сказуемое, порядок слов, союзы, сложносочиненные и сложноподчиненные предложения.', 'intermediate', 10, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('ru-reading', 'cat-russian', 'russian', 'Russian Language', 'Rus tili', 'Русский язык', 'ru-reading', 'Reading Comprehension', 'O''qib Tushunish', 'Понимание прочитанного', 'Analyzing short Russian texts, identifying main ideas, context clues, and idiomatic meanings.', 'Rus tilidagi matnlarni tahlil qilish, asosiy gʻoyani topish va kontekst orqali maʼnoni anglash.', 'Анализ текстов на русском языке, определение главной мысли, контекста и смысловых деталей.', 'intermediate', 10, 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('ru-advanced', 'cat-russian', 'russian', 'Russian Language', 'Rus tili', 'Русский язык', 'ru-advanced', 'Advanced Russian', 'Ilg''or Rus Tili', 'Продвинутый русский язык', 'Participles (причастия), gerunds (деепричастия), stylistics, proverbs, phraseologisms, and orthoepy.', 'Sifatdosh (причастие), ravishdosh (деепричастие), frazeologizmlar, uslubiyat va urgʻu qoidalari.', 'Причастия и деепричастия, фразеологизмы, стилистика речи, орфоэпия и сложная пунктуация.', 'advanced', 10, 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('en-alphabet', 'cat-english', 'english', 'English Language', 'Ingliz tili', 'Английский язык', 'en-alphabet', 'English Alphabet', 'Ingliz Alifbosi va Fonetika', 'Английский алфавит', '26 Latin letters, vowels and consonants, silent letters, digraphs (th, sh, ch, ph), and phonetics.', '26 ta harf, unli va undoshlar, oʻqilmaydigan harflar, harf birikmalari (th, sh, ch, ph) va talaffuz.', '26 букв английского алфавита, гласные и согласные, немые буквы, диграфы и правила чтения.', 'basic', 10, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('en-vocabulary', 'cat-english', 'english', 'English Language', 'Ingliz tili', 'Английский язык', 'en-vocabulary', 'Basic Vocabulary', 'Asosiy Lug''at Boyligi', 'Базовая лексика', 'Essential daily words, collocations, synonyms, antonyms, prefixes, suffixes, and thematic vocabulary.', 'Kundalik zarur soʻzlar, iboralar, sinonimlar, antonimlar, old va orqa qoʻshimchalar.', 'Ключевой словарный запас, устойчивые выражения, синонимы, антонимы, префиксы и суффиксы.', 'basic', 10, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('en-grammar', 'cat-english', 'english', 'English Language', 'Ingliz tili', 'Английский язык', 'en-grammar', 'Grammar', 'Ingliz Tili Grammatikasi', 'Грамматика английского', 'Articles (a, an, the), countable/uncountable nouns, comparatives, superlatives, and prepositions.', 'Artikllar (a, an, the), sanaladigan va sanalmaydigan otlar, sifat darajalari va predloglar.', 'Артикли (a, an, the), исчисляемые и неисчисляемые существительные, степени сравнения и предлоги.', 'intermediate', 10, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('en-tenses', 'cat-english', 'english', 'English Language', 'Ingliz tili', 'Английский язык', 'en-tenses', 'Tenses', 'Zamonlar (English Tenses)', 'Времена английского глагола', 'Present, Past, and Future across Simple, Continuous, Perfect, and Perfect Continuous aspects.', 'Present, Past va Future zamonlari: Simple, Continuous, Perfect va Perfect Continuous shakllari.', 'Система времен английского языка: Simple, Continuous, Perfect и Perfect Continuous.', 'intermediate', 10, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('en-verbs', 'cat-english', 'english', 'English Language', 'Ingliz tili', 'Английский язык', 'en-verbs', 'Verbs', 'Fe''llar va Modal Fe''llar', 'Глаголы и модальные глаголы', 'Irregular verbs, modal verbs (can, must, should, might), phrasal verbs, gerunds, and infinitives.', 'Noto''g''ri fe''llar, modal fe''llar (can, must, should), iborali fe''llar (phrasal verbs), gerund va infinitiv.', 'Неправильные глаголы, модальные глаголы, фразовые глаголы, герундий и инфинитив.', 'intermediate', 10, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('en-pronouns', 'cat-english', 'english', 'English Language', 'Ingliz tili', 'Английский язык', 'en-pronouns', 'Pronouns', 'Olmoshlar (Pronouns)', 'Местоимения', 'Subject, object, possessive, reflexive (myself, themselves), demonstrative, and relative pronouns.', 'Kishilik, egalik, oʻzlik (myself, themselves), koʻrsatish va nisbiy olmoshlar.', 'Личные, объектные, притяжательные, возвратные, указательные и относительные местоимения.', 'basic', 10, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('en-sentences', 'cat-english', 'english', 'English Language', 'Ingliz tili', 'Английский язык', 'en-sentences', 'Sentence Construction', 'Gap Tuzish (Sentence Structure)', 'Построение предложений', 'SVO word order, question tags, relative clauses, passive voice, and conditional sentences (0, 1, 2, 3).', 'Soʻz tartibi (SVO), tasdiq/soʻroq gaplar, majhul nisbat (Passive Voice) va shart ergash gaplar (Conditionals).', 'Порядок слов, разделительные вопросы, страдательный залог (Passive Voice) и условные предложения.', 'intermediate', 10, 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('en-reading', 'cat-english', 'english', 'English Language', 'Ingliz tili', 'Английский язык', 'en-reading', 'Reading Comprehension', 'Matnni O''qib Tushunish', 'Чтение и понимание текста', 'Extracting key facts, author tone, inference, logical connectors, and academic passage comprehension.', 'Matndan asosiy faktlarni topish, muallif fikrini anglash va akademik matnlarni tahlil qilish.', 'Анализ английских текстов, поиск ключевых фактов, логических связей и выводов из контекста.', 'intermediate', 10, 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('en-advanced', 'cat-english', 'english', 'English Language', 'Ingliz tili', 'Английский язык', 'en-advanced', 'Advanced English', 'Ilg''or Ingliz Tili (C1/C2)', 'Продвинутый английский (C1/C2)', 'Inversion, subjunctive mood, mixed conditionals, advanced idioms, academic vocabulary, and discourse markers.', 'Inversiya, subjunctive mood, aralash shart gaplar, murakkab idiomalar va akademik leksika.', 'Инверсия, сослагательное наклонение, смешанные условные предложения, идиомы и академический стиль.', 'advanced', 10, 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('math-fractions', 'cat-mathematics', 'math', 'Mathematics', 'Matematika', 'Математика', 'math-fractions', 'Fractions', 'Kasrlar (Fractions)', 'Дроби', 'Proper and improper fractions, mixed numbers, simplifying, common denominators, and decimal conversion.', 'To''g''ri va noto''g''ri kasrlar, aralash sonlar, kasrlarni qisqartirish, umumiy maxraj va o''nli kasrlar.', 'Обыкновенные и десятичные дроби, сокращение дробей, общий знаменатель и смешанные числа.', 'basic', 10, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('math-addition', 'cat-mathematics', 'math', 'Mathematics', 'Matematika', 'Математика', 'math-addition', 'Addition', 'Qo''shish Amali', 'Сложение', 'Multi-digit addition, decimals, negative numbers, arithmetic series sums, and mental math strategies.', 'Ko''p xonali sonlarni qo''shish, o''nli kasrlar, manfiy sonlar va arifmetik qator yig''indisi.', 'Сложение многозначных чисел, десятичных дробей, отрицательных чисел и арифметических рядов.', 'basic', 10, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('math-subtraction', 'cat-mathematics', 'math', 'Mathematics', 'Matematika', 'Математика', 'math-subtraction', 'Subtraction', 'Ayirish Amali', 'Вычитание', 'Differences of integers, decimals, signed numbers, borrowing techniques, and word problems.', 'Butun sonlar, oʻnli kasrlar, ishorali sonlar ayirmasi va matnli masalalar.', 'Вычитание целых чисел, десятичных дробей, чисел с разными знаками и текстовые задачи.', 'basic', 10, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('math-multiplication', 'cat-mathematics', 'math', 'Mathematics', 'Matematika', 'Математика', 'math-multiplication', 'Multiplication', 'Ko''paytirish Amali', 'Умножение', 'Multi-digit products, distributive property, powers of 10, exponents, and factor properties.', 'Ko''p xonali sonlarni ko''paytirish, taqsimot qonuni, darajalar va ko''paytuvchilar xossalari.', 'Умножение многозначных чисел, распределительный закон, степени и свойства множителей.', 'basic', 10, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('math-division', 'cat-mathematics', 'math', 'Mathematics', 'Matematika', 'Математика', 'math-division', 'Division', 'Bo''lish Amali', 'Деление', 'Quotients, remainders, divisibility rules (by 2, 3, 4, 5, 9, 11), GCD, LCM, and ratios.', 'Bo''linma va qoldiq, bo''linish belgilari (2, 3, 4, 5, 9, 11 ga), EKUB, EKUK va nisbatlar.', 'Частное и остаток, признаки делимости, НОД, НОК и пропорции.', 'basic', 10, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('math-percentages', 'cat-mathematics', 'math', 'Mathematics', 'Matematika', 'Математика', 'math-percentages', 'Percentages', 'Foizlar (Percentages)', 'Проценты', 'Percentage calculations, discounts, tax, compound interest, percentage change, and profit/loss.', 'Foiz hisoblash, chegirmalar, murakkab foiz, foiz oʻzgarishi hamda foyda va zarar masalalari.', 'Вычисление процентов, скидки, сложные проценты, процентное изменение и задачи на сплавы/доли.', 'intermediate', 10, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('math-algebra', 'cat-mathematics', 'math', 'Mathematics', 'Matematika', 'Математика', 'math-algebra', 'Algebra', 'Algebra', 'Алгебра', 'Polynomials, factoring identities, exponents, radicals, functions, and algebraic simplification.', 'Koʻphadlar, qisqa koʻpaytirish formulalari, daraja va ildizlar, funksiyalar hamda soddalashtirish.', 'Многочлены, формулы сокращенного умножения, степени, корни, функции и преобразования.', 'intermediate', 10, 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('math-equations', 'cat-mathematics', 'math', 'Mathematics', 'Matematika', 'Математика', 'math-equations', 'Equations', 'Tenglamalar', 'Уравнения', 'Linear equations, quadratic equations (discriminant & Vieta theorem), systems of equations, and inequalities.', 'Chiziqli va kvadrat tenglamalar (diskriminant va Viyet teoremasi), tenglamalar sistemasi.', 'Линейные и квадратные уравнения (дискриминант, теорема Виета), системы уравнений и неравенства.', 'intermediate', 10, 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('math-geometry', 'cat-mathematics', 'math', 'Mathematics', 'Matematika', 'Математика', 'math-geometry', 'Geometry', 'Geometriya', 'Геометрия', 'Triangles, Pythagorean theorem, circles, polygons, area, perimeter, volume, and angles.', 'Uchburchaklar, Pifagor teoremasi, aylana, koʻpburchaklar yuzi, perimetri, hajm va burchaklar.', 'Треугольники, теорема Пифагора, окружность, площадь, периметр, объем фигур и углы.', 'intermediate', 10, 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_topics (id, category_id, subject_id, subject_name_en, subject_name_uz, subject_name_ru, slug, title_en, title_uz, title_ru, description_en, description_uz, description_ru, difficulty_tier, question_count, display_order) VALUES ('math-advanced', 'cat-mathematics', 'math', 'Mathematics', 'Matematika', 'Математика', 'math-advanced', 'Advanced Mathematics', 'Oliy va Ilgʻor Matematika', 'Высшая математика', 'Logarithms, trigonometry, limits, derivatives, definite integrals, combinatorics, and probability.', 'Logarifmlar, trigonometriya, limitlar, hosila, aniq integral, kombinatorika va ehtimollar nazariyasi.', 'Логарифмы, тригонометрия, пределы, производные, интегралы, комбинаторика и теория вероятностей.', 'advanced', 10, 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-basics-q1', 'html-basics', 1, 'basic', 1, 'What does HTML stand for?', 'HTML qisqartmasining to''liq ma''nosi nima?', 'Как расшифровывается HTML?', 'HTML stands for HyperText Markup Language, the standard markup language for documents designed to be displayed in a web browser.', 'HTML — HyperText Markup Language degan ma''noni anglatadi va veb-sahifalarni yaratish uchun standart belgilash tili hisoblanadi.', 'HTML расшифровывается как HyperText Markup Language — стандартный язык разметки документов в вебе.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-basics-q2', 'html-basics', 2, 'basic', 1, 'Which declaration must appear at the very top of an HTML5 document?', 'HTML5 hujjatining eng yuqori qismida qaysi deklaratsiya yozilishi shart?', 'Какая декларация должна находиться в самом начале документа HTML5?', '<!DOCTYPE html> tells the browser to render the document in standards-compliant HTML5 mode.', '<!DOCTYPE html> brauzerga hujjatni HTML5 standart rejimida aks ettirish kerakligini bildiradi.', '<!DOCTYPE html> указывает браузеру обрабатывать страницу в стандартном режиме HTML5.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-basics-q3', 'html-basics', 3, 'basic', 1, 'Which element is the root element of an HTML page?', 'HTML sahifasining ildiz (root) elementi qaysi?', 'Какой элемент является корневым элементом HTML-страницы?', 'The <html> element is the root element that wraps all other content on the page.', '<html> elementi sahifadagi barcha boshqa tarkibni o''rab turuvchi ildiz elementdir.', 'Элемент <html> является корневым контейнером, содержащим все остальные элементы страницы.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-basics-q4', 'html-basics', 4, 'basic', 1, 'Where is the visible content of an HTML document placed?', 'HTML hujjatining foydalanuvchiga ko''rinadigan qismi qaysi teg ichiga joylashtiriladi?', 'Внутри какого тега размещается видимое содержимое HTML-документа?', 'The <body> element contains all the visible contents of an HTML document, such as headings, paragraphs, and images.', '<body> elementi sarlavhalar, abzaslar va rasmlar kabi sahifaning barcha ko''rinadigan qismlarini o''z ichiga oladi.', 'Элемент <body> содержит всё видимое содержимое страницы: заголовки, абзацы, изображения и др.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-basics-q5', 'html-basics', 5, 'intermediate', 1.5, 'Which tag inside <head> sets the text shown in the browser tab?', '<head> ichidagi qaysi teg brauzer varag''ida (tab) ko''rinadigan matnni belgilaydi?', 'Какой тег внутри <head> задаёт текст, отображаемый на вкладке браузера?', 'The <title> element defines the document title shown in the browser title bar or page tab.', '<title> elementi brauzer sarlavha satrida yoki sahifa varag''ida ko''rsatiladigan hujjat nomini belgilaydi.', 'Элемент <title> определяет заголовок документа, который отображается на вкладке браузера.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-basics-q6', 'html-basics', 6, 'intermediate', 1.5, 'How do you write a comment in HTML?', 'HTML-da izoh (comment) qanday yoziladi?', 'Как правильно написать комментарий в HTML?', 'HTML comments start with <!-- and end with --> and are ignored by the browser when rendering.', 'HTML izohlari <!-- bilan boshlanib, --> bilan tugaydi va brauzer tomonidan ekranga chiqarilmaydi.', 'Комментарии в HTML начинаются с <!-- и заканчиваются --> и не отображаются браузером.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-basics-q7', 'html-basics', 7, 'intermediate', 1.5, 'Which meta tag ensures proper character encoding for Unicode/UTF-8?', 'Qaysi meta teg Unicode/UTF-8 belgilar kodirovkasini to''g''ri ishlashini ta''minlaydi?', 'Какой мета-тег обеспечивает корректную кодировку символов Unicode/UTF-8?', '<meta charset="UTF-8"> declares the character encoding capable of representing virtually all characters and symbols.', '<meta charset="UTF-8"> deyarli barcha til belgilari va simvollarni aks ettira oladigan kodirovkani e''lon qiladi.', '<meta charset="UTF-8"> задаёт кодировку документа, поддерживающую символы практически всех языков мира.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-basics-q8', 'html-basics', 8, 'intermediate', 1.5, 'What happens when multiple consecutive spaces are typed inside an HTML paragraph?', 'HTML abzas (<p>) ichida ketma-ket bir nechta bo''sh joy (probel) yozilsa nima sodir bo''ladi?', 'Что происходит, если внутри HTML-абзаца (<p>) ввести несколько пробелов подряд?', 'By default, HTML collapses sequences of whitespace characters into a single space when rendering.', 'Odatiy holatda, HTML ketma-ket kelgan bo''sh joy belgilarini sahifada bitta probel sifatida aks ettiradi.', 'По умолчанию браузер схлопывает последовательности пробельных символов в HTML в один пробел.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-basics-q9', 'html-basics', 9, 'advanced', 2.2, 'What does omitting <!DOCTYPE html> cause modern browsers to enter?', '<!DOCTYPE html> yozilmasa, zamonaviy brauzerlar qaysi rejimga o''tib qoladi?', 'В какой режим переходят современные браузеры при отсутствии <!DOCTYPE html>?', 'Without a valid doctype, browsers render the page in Quirks Mode to emulate legacy browser behavior.', 'To''g''ri doctype ko''rsatilmasa, brauzerlar eski brauzerlar xatti-harakatiga taqlid qiluvchi Quirks Mode rejimida ishlaydi.', 'Без корректного doctype браузеры включают Quirks Mode (режим совместимости со старыми версиями браузеров).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-basics-q10', 'html-basics', 10, 'advanced', 2.2, 'Which HTML entity represents a non-breaking space?', 'Qaysi HTML entity uzilmaydigan bo''sh joyni (non-breaking space) ifodalaydi?', 'Какая HTML-сущность представляет неразрывный пробел?', '&nbsp; inserts a non-breaking space that prevents an automatic line break at its position and does not collapse.', '&nbsp; qatorning avtomatik uzilishiga yo''l qo''ymaydigan va qisqarib ketmaydigan bo''sh joy qo''shadi.', 'Сущность &nbsp; вставляет неразрывный пробел, препятствующий автоматическому переносу строки в этом месте.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tags-q1', 'html-tags', 1, 'basic', 1, 'Which HTML tag defines the largest and most important heading?', 'Qaysi HTML tegi eng katta va eng muhim sarlavhani belgilaydi?', 'Какой HTML-тег определяет самый крупный и важный заголовок?', '<h1> defines the highest-level heading, while <h6> defines the lowest-level heading.', '<h1> eng yuqori darajadagi sarlavhani, <h6> esa eng quyi darajadagi sarlavhani belgilaydi.', 'Тег <h1> задаёт заголовок первого (самого важного) уровня, а <h6> — шестого.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tags-q2', 'html-tags', 2, 'basic', 1, 'Which tag is used to create a paragraph in HTML?', 'HTML-da abzas (paragraf) yaratish uchun qaysi teg ishlatiladi?', 'Какой тег используется для создания абзаца в HTML?', 'The <p> tag defines a paragraph of text and is a block-level element.', '<p> tegi matn abzasini belgilaydi va blok darajasidagi element hisoblanadi.', 'Тег <p> определяет текстовый абзац и является блочным элементом.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tags-q3', 'html-tags', 3, 'basic', 1, 'Which void element inserts a single line break?', 'Qaysi yopilmaydigan (void) element bitta qator ko''chirishni (line break) amalga oshiradi?', 'Какой одиночный (void) элемент вставляет перенос строки?', 'The <br> tag produces a line break in text without starting a new paragraph.', '<br> tegi yangi abzas boshlamasdan matnda yangi qatorga o''tishni hosil qiladi.', 'Тег <br> выполняет перевод строки внутри текста без создания нового абзаца.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tags-q4', 'html-tags', 4, 'basic', 1, 'Which tag creates an unordered (bulleted) list?', 'Qaysi teg tartiblanmagan (nuqtali) ro''yxat yaratadi?', 'Какой тег создаёт маркированный (неупорядоченный) список?', 'The <ul> tag defines an unordered list, with each item wrapped in an <li> tag.', '<ul> tegi tartiblanmagan ro''yxatni belgilaydi, uning har bir bandi <li> tegi ichiga olinadi.', 'Тег <ul> создаёт маркированный список, каждый пункт которого помещается в тег <li>.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tags-q5', 'html-tags', 5, 'intermediate', 1.5, 'What is the difference between <strong> and <b> in HTML5?', 'HTML5-da <strong> va <b> teglari o''rtasida qanday farq bor?', 'В чём разница между тегами <strong> и <b> в HTML5?', '<strong> conveys strong importance to screen readers and search engines, whereas <b> draws attention without extra semantic importance.', '<strong> ekran o''quvchi dasturlar va qidiruv tizimlariga matnning muhimligini bildiradi, <b> esa qo''shimcha ma''nosiz qalin qiladi.', 'Тег <strong> передаёт высокую важность содержимого, а <b> просто выделяет текст жирным без семантической нагрузки.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tags-q6', 'html-tags', 6, 'intermediate', 1.5, 'Which tag preserves both spaces and line breaks exactly as written in the source code?', 'Qaysi teg bo''sh joylar va qator ko''chirishlarni kodda qanday yozilgan bo''lsa, xuddi shunday saqlaydi?', 'Какой тег сохраняет все пробелы и переносы строк точно так, как они написаны в исходном коде?', 'The <pre> element represents preformatted text, preserving whitespace and line breaks as written.', '<pre> elementi oldindan formatlangan matnni ifodalaydi hamda bo''sh joy va qatorlarni o''z holicha saqlaydi.', 'Элемент <pre> отображает предварительно отформатированный текст с сохранением всех пробелов и переносов строк.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tags-q7', 'html-tags', 7, 'intermediate', 1.5, 'Which tag is used to define a list item inside both <ul> and <ol>?', 'Ham <ul>, ham <ol> ichida ro''yxat bandini belgilash uchun qaysi teg ishlatiladi?', 'Какой тег используется для создания пункта списка внутри как <ul>, так и <ol>?', 'The <li> (list item) element is used to represent an item inside ordered (<ol>) and unordered (<ul>) lists.', '<li> elementi tartiblangan (<ol>) va tartiblanmagan (<ul>) ro''yxatlar ichidagi bandni ifodalash uchun ishlatiladi.', 'Элемент <li> (list item) определяет отдельный элемент внутри списков <ol> и <ul>.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tags-q8', 'html-tags', 8, 'intermediate', 1.5, 'Which element represents a thematic break or horizontal divider between paragraph-level elements?', 'Abzas darajasidagi elementlar orasida mavzuli ajratish yoki gorizontal chiziqni qaysi element ifodalaydi?', 'Какой элемент представляет собой тематический разделитель (горизонтальную линию) между разделами?', 'The <hr> tag represents a thematic break between paragraph-level elements and renders as a horizontal rule.', '<hr> tegi abzaslar o''rtasidagi mavzuli o''tishni bildiradi va gorizontal chiziq sifatida ko''rinadi.', 'Тег <hr> обозначает тематический переход между абзацами и отображается как горизонтальная линия.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tags-q9', 'html-tags', 9, 'advanced', 2.2, 'Which pair of tags is used inside a description list (<dl>) for terms and their descriptions?', 'Tavsif ro''yxati (<dl>) ichida atamalar va ularning ta''riflari uchun qaysi teglar juftligi ishlatiladi?', 'Какая пара тегов используется внутри списка описаний (<dl>) для терминов и их определений?', 'Inside a <dl>, <dt> specifies the description term and <dd> provides the description details.', '<dl> ichida <dt> atamani (description term), <dd> esa uning izohini (description details) belgilaydi.', 'Внутри <dl> тег <dt> задаёт термин, а <dd> — его описание или определение.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tags-q10', 'html-tags', 10, 'advanced', 2.2, 'Which inline tag tells the browser where it would be okay to add a line-break inside a long word if needed?', 'Qaysi inline teg uzun so''z ichida zarurat tug''ilganda qatorni uzish mumkin bo''lgan joyni brauzerga ko''rsatadi?', 'Какой строчный тег указывает браузеру место возможного переноса внутри длинного слова?', 'The <wbr> (Word Break Opportunity) element specifies where in a text it would be acceptable to add a line-break.', '<wbr> (Word Break Opportunity) elementi uzun matn yoki URL qayerdan keyingi qatorga bo''linishi mumkinligini ko''rsatadi.', 'Тег <wbr> (Word Break Opportunity) указывает место, где браузер может разорвать длинное слово при переносе строки.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-forms-q1', 'html-forms', 1, 'basic', 1, 'Which HTML element is used to wrap interactive controls for submitting user input?', 'Foydalanuvchi kiritgan ma''lumotlarni yuborish uchun interaktiv elementlarni o''rab turuvchi HTML tegi qaysi?', 'Какой HTML-элемент используется как контейнер для полей ввода и отправки данных пользователя?', 'The <form> element defines an HTML form used to collect and submit user input.', '<form> elementi foydalanuvchi ma''lumotlarini yig''ish va serverga yuborish uchun mo''ljallangan formani belgilaydi.', 'Элемент <form> определяет HTML-форму для сбора и отправки пользовательских данных.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-forms-q2', 'html-forms', 2, 'basic', 1, 'Which input type masks the characters typed by the user?', 'Qaysi input turi foydalanuvchi yozayotgan belgilarni yashirib (nuqta yoki yulduzcha qilib) ko''rsatadi?', 'Какой тип поля <input> скрывает вводимые пользователем символы?', '<input type="password"> creates a single-line text field whose value is obscured for privacy.', '<input type="password"> xavfsizlik uchun kiritilgan qiymati yashirin ko''rinadigan bir qatorli maydon yaratadi.', '<input type="password"> создаёт текстовое поле, в котором вводимые символы маскируются.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-forms-q3', 'html-forms', 3, 'basic', 1, 'Which element is used to create a multi-line text input control?', 'Ko''p qatorli matn kiritish maydonini yaratish uchun qaysi element ishlatiladi?', 'Какой элемент используется для создания многострочного поля ввода текста?', 'The <textarea> element defines a multi-line plain-text editing control.', '<textarea> elementi ko''p qatorli oddiy matn kiritish va tahrirlash maydonini yaratadi.', 'Элемент <textarea> представляет собой многострочное поле для ввода текста.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-forms-q4', 'html-forms', 4, 'basic', 1, 'How do you associate a <label> element with a specific <input> element via attributes?', 'Atributlar orqali <label> elementini ma''lum bir <input> elementi bilan qanday bog''lash mumkin?', 'Как связать элемент <label> с конкретным полем <input> с помощью атрибутов?', 'Setting the <label>''s "for" attribute equal to the <input>''s "id" links them together for accessibility and click focus.', '<label> ning "for" atributiga <input> ning "id" qiymatini berish ularni bog''laydi va label bosilganda inputga fokus beradi.', 'Значение атрибута "for" тега <label> должно совпадать с "id" поля <input>, чтобы связать их.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-forms-q5', 'html-forms', 5, 'intermediate', 1.5, 'What must radio buttons (<input type="radio">) share so that only one option in a group can be selected?', 'Guruhdagi radio tugmalardan (<input type="radio">) faqat bittasini tanlash mumkin bo''lishi uchun ularning qaysi atributi bir xil bo''lishi kerak?', 'Какой атрибут должен иметь одинаковое значение у радиокнопок (<input type="radio">), чтобы можно было выбрать только одну из группы?', 'Radio buttons that share the same "name" attribute belong to the same mutually exclusive group.', 'Bir xil "name" atributiga ega bo''lgan radio tugmalar bitta guruhga birlashadi va ulardan faqat bittasini tanlash mumkin bo''ladi.', 'Радиокнопки с одинаковым атрибутом "name" объединяются в одну группу, где возможен выбор только одного варианта.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-forms-q6', 'html-forms', 6, 'intermediate', 1.5, 'Which attribute prevents a form from being submitted if an input field is left empty?', 'Agar kiritish maydoni bo''sh qoldirilsa, formani yuborishga yo''l qo''ymaydigan atribut qaysi?', 'Какой атрибут запрещает отправку формы, если обязательное поле ввода оставлено пустым?', 'The boolean "required" attribute specifies that the user must fill in a value before submitting the form.', 'Mantiqiy "required" atributi formani yuborishdan oldin foydalanuvchi ushbu maydonni to''ldirishi shartligini belgilaydi.', 'Булев атрибут "required" указывает, что поле обязательно должно быть заполнено перед отправкой формы.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-forms-q7', 'html-forms', 7, 'intermediate', 1.5, 'What is the default type of a <button> inside a <form> if the type attribute is not specified?', 'Agar <form> ichidagi <button> elementida type atributi ko''rsatilmasa, uning standart (default) turi qanday bo''ladi?', 'Какой тип по умолчанию имеет элемент <button> внутри <form>, если атрибут type не указан?', 'Inside a <form>, a <button> without a type attribute defaults to type="submit", which submits the form.', '<form> ichida type atributi yozilmagan <button> odatiy holatda type="submit" bo''ladi va formani yuboradi.', 'Внутри <form> кнопка <button> без указанного атрибута type по умолчанию имеет тип "submit" и отправляет форму.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-forms-q8', 'html-forms', 8, 'intermediate', 1.5, 'Which elements are used together to create a dropdown selection list?', 'Ochiluvchi tanlov ro''yxatini (dropdown) yaratish uchun qaysi elementlar birgalikda ishlatiladi?', 'Какие элементы используются вместе для создания выпадающего списка выбора?', 'The <select> element creates a drop-down list, and <option> elements define the available choices inside it.', '<select> elementi ochiluvchi ro''yxatni yaratadi, <option> elementlari esa uning ichidagi variantlarni belgilaydi.', 'Элемент <select> создаёт выпадающий список, а вложенные теги <option> определяют доступные варианты выбора.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-forms-q9', 'html-forms', 9, 'advanced', 2.2, 'What is the key difference between the "disabled" and "readonly" attributes on an input field during form submission?', 'Formani yuborish vaqtida kiritish maydonidagi "disabled" va "readonly" atributlari o''rtasidagi asosiy farq nima?', 'В чём ключевое отличие атрибутов "disabled" и "readonly" у поля ввода при отправке формы?', 'A disabled input cannot be focused and its value is excluded from form submission, whereas a readonly input''s value is still submitted.', 'Disabled qilingan input fokus olmaydi va uning qiymati forma bilan yuborilmaydi, readonly input qiymati esa yuboriladi.', 'Значение поля с атрибутом disabled не включается в отправляемые данные формы, тогда как значение поля с readonly отправляется.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-forms-q10', 'html-forms', 10, 'advanced', 2.2, 'Which elements group related controls inside a form and provide a caption for that group?', 'Forma ichida o''zaro bog''liq elementlarni guruhlash va shu guruhga sarlavha berish uchun qaysi teglar ishlatiladi?', 'Какие элементы группируют связанные поля внутри формы и задают заголовок для этой группы?', '<fieldset> groups related controls in a form, and <legend> provides an accessible caption for the fieldset.', '<fieldset> formadagi bog''liq maydonlarni guruhlaydi, <legend> esa ushbu guruh uchun sarlavha vazifasini bajaradi.', 'Тег <fieldset> группирует связанные элементы формы, а <legend> задаёт заголовок для этой группы.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-semantic-q1', 'html-semantic', 1, 'basic', 1, 'What does "semantic HTML" mean?', '"Semantik HTML" deganda nima tushuniladi?', 'Что означает понятие «семантический HTML»?', 'Semantic HTML uses meaningful elements like <article>, <nav>, and <main> to convey document structure to browsers and assistive technologies.', 'Semantik HTML brauzerlar va yordamchi texnologiyalarga hujjat tuzilishini tushuntirish uchun <article>, <nav> va <main> kabi ma''noli teglardan foydalanadi.', 'Семантический HTML предполагает использование смысловых тегов (<article>, <nav>, <main>), описывающих роль содержимого.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-semantic-q2', 'html-semantic', 2, 'basic', 1, 'Which semantic element is intended to hold major navigation links?', 'Qaysi semantik element asosiy navigatsiya havolalarini saqlash uchun mo''ljallangan?', 'Какой семантический элемент предназначен для размещения основных навигационных ссылок?', 'The <nav> element represents a section of a page whose purpose is to provide navigation links.', '<nav> elementi sahifaning navigatsiya havolalarini taqdim etuvchi bo''limini ifodalaydi.', 'Элемент <nav> определяет раздел страницы, содержащий основные навигационные ссылки.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-semantic-q3', 'html-semantic', 3, 'basic', 1, 'How many visible <main> elements should exist on a single HTML page at once?', 'Bitta HTML sahifada bir vaqtning o''zida nechta ko''rinadigan (hidden bo''lmagan) <main> elementi bo''lishi kerak?', 'Сколько видимых элементов <main> должно присутствовать на одной HTML-странице одновременно?', 'A document must not have more than one visible <main> element because it represents the dominant content of the <body>.', 'Hujjatda bittadan ortiq ko''rinadigan <main> elementi bo''lmasligi kerak, chunki u <body> ning asosiy mazmunini ifodalaydi.', 'В документе должен быть только один видимый элемент <main>, так как он содержит уникальное основное содержимое страницы.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-semantic-q4', 'html-semantic', 4, 'basic', 1, 'Which semantic tag defines the bottom section of a page or section, typically containing copyright or contact info?', 'Odatda mualliflik huquqi yoki aloqa ma''lumotlarini o''z ichiga oluvchi sahifa yoki bo''limning pastki qismini qaysi semantik teg belgilaydi?', 'Какой семантический тег определяет нижнюю часть страницы или раздела, обычно содержащую копирайт или контакты?', 'The <footer> element represents a footer for its nearest ancestor sectioning content or root element.', '<footer> elementi sahifa yoki eng yaqin bo''limning quyi qismini (podvalini) ifodalaydi.', 'Элемент <footer> определяет подвал (нижний колонтитул) страницы или ближайшего секционного раздела.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-semantic-q5', 'html-semantic', 5, 'intermediate', 1.5, 'Which element should be used for a self-contained composition like a blog post or news story that could be distributed independently?', 'Blog posti yoki yangilik xabari kabi mustaqil tarqatilishi mumkin bo''lgan yaxlit materiallar uchun qaysi element ishlatilishi kerak?', 'Какой элемент следует использовать для самостоятельного материала (например, поста в блоге или новости), который можно распространять отдельно?', 'The <article> element represents a self-contained composition in a document, page, or site.', '<article> elementi hujjat yoki saytdagi mustaqil va tugallangan tarkibiy qismni (maqola, post) ifodalaydi.', 'Элемент <article> предназначен для независимого, самодостаточного фрагмента контента, такого как статья или запись в блоге.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-semantic-q6', 'html-semantic', 6, 'intermediate', 1.5, 'Which element represents content tangentially related to the content around it, such as a sidebar or callout box?', 'Yon panel (sidebar) yoki qo''shimcha eslatma kabi asosiy tarkibga bilvosita aloqador bo''lgan qismni qaysi element ifodalaydi?', 'Какой элемент представляет содержимое, косвенно связанное с основным контентом, например боковую панель (сайдбар)?', 'The <aside> element represents a portion of a document whose content is only indirectly related to the main content.', '<aside> elementi asosiy mazmunga bilvosita bog''liq bo''lgan yon panel yoki qo''shimcha blokni ifodalaydi.', 'Элемент <aside> определяет блок с дополнительной информацией, косвенно связанной с основным содержимым (например, сайдбар).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-semantic-q7', 'html-semantic', 7, 'intermediate', 1.5, 'Which pair of semantic tags is used to encapsulate an image or diagram along with its caption?', 'Rasm yoki diagrammani uning izohi (tagyozuvi) bilan birga o''rab olish uchun qaysi semantik teglar juftligi ishlatiladi?', 'Какая пара семантических тегов используется для группировки иллюстрации (изображения, схемы) и подписи к ней?', '<figure> wraps self-contained media content, and <figcaption> provides a caption or legend for it.', '<figure> mustaqil media tarkibni o''rab oladi, <figcaption> esa unga izoh (sarlavha) beradi.', 'Элемент <figure> оборачивает иллюстрацию, а <figcaption> задаёт текстовую подпись к ней.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-semantic-q8', 'html-semantic', 8, 'intermediate', 1.5, 'Which semantic element is used to highlight or mark text for reference or search relevance?', 'Matnning ma''lum qismini alohida ajratib ko''rsatish (bo''yab belgilash) uchun qaysi semantik element ishlatiladi?', 'Какой семантический элемент используется для выделения (подсветки) фрагмента текста, актуального в данном контексте?', 'The <mark> element represents text that is marked or highlighted for reference or notation purposes.', '<mark> elementi ma''lumot yoki qidiruv natijasiga e''tibor qaratish uchun belgilangan (ajratib bo''yalgan) matnni ifodalaydi.', 'Элемент <mark> выделяет (подсвечивает) фрагмент текста, имеющий особую значимость в текущем контексте.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-semantic-q9', 'html-semantic', 9, 'advanced', 2.2, 'Which attribute of the <time> element provides a machine-readable format of a date or time?', '<time> elementining qaysi atributi sana yoki vaqtni kompyuter tushunadigan (machine-readable) formatda taqdim etadi?', 'Какой атрибут элемента <time> задаёт дату или время в машиночитаемом формате?', 'The "datetime" attribute of <time> translates the human-readable text into a standard machine-readable ISO format.', '<time> tegining "datetime" atributi inson o''qiydigan vaqtni kompyuterlar uchun standart ISO formatiga o''giradi.', 'Атрибут "datetime" элемента <time> содержит дату или время в стандартном машиночитаемом формате ISO.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-semantic-q10', 'html-semantic', 10, 'advanced', 2.2, 'Which native HTML element pair creates an interactive disclosure widget that the user can open and close without JavaScript?', 'Qaysi HTML elementlar juftligi JavaScript-siz ochilib-yopiladigan interaktiv blok (akkordeon) yaratadi?', 'Какая пара нативных HTML-элементов создаёт интерактивный раскрывающийся блок (аккордеон) без использования JavaScript?', '<details> creates a disclosure widget whose visible heading is provided by a child <summary> element.', '<details> yashirin ma''lumotlar vidjetini yaratadi, uning ko''rinib turuvchi sarlavhasi esa <summary> elementi orqali beriladi.', 'Элемент <details> создаёт раскрывающийся блок, а вложенный тег <summary> задаёт его видимый заголовок.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tables-q1', 'html-tables', 1, 'basic', 1, 'Which tag is used to define a table row in HTML?', 'HTML-da jadval qatorini belgilash uchun qaysi teg ishlatiladi?', 'Какой тег используется для создания строки таблицы в HTML?', 'The <tr> (table row) element defines a row of cells in a table.', '<tr> (table row) elementi jadvaldagi kataklar qatorini belgilaydi.', 'Элемент <tr> (table row) определяет строку ячеек в HTML-таблице.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tables-q2', 'html-tables', 2, 'basic', 1, 'Which tag defines a standard data cell inside a table row?', 'Jadval qatori ichida oddiy ma''lumot katagini qaysi teg belgilaydi?', 'Какой тег определяет обычную ячейку с данными внутри строки таблицы?', 'The <td> (table data) element defines a standard data-holding cell of a table.', '<td> (table data) elementi jadvalning ma''lumot saqlovchi oddiy katagini belgilaydi.', 'Элемент <td> (table data) создаёт стандартную ячейку данных таблицы.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tables-q3', 'html-tables', 3, 'basic', 1, 'Which tag is used to create a table header cell that renders bold and centered by default?', 'Odatiy holatda qalin va markazda joylashadigan jadval sarlavha katagini yaratish uchun qaysi teg ishlatiladi?', 'Какой тег создаёт заголовочную ячейку таблицы, текст в которой по умолчанию жирный и выровнен по центру?', 'The <th> (table header) element defines a cell as the header of a group of table cells.', '<th> (table header) elementi jadval ustuni yoki qatori uchun sarlavha katagini belgilaydi.', 'Элемент <th> (table header) определяет ячейку-заголовок для столбца или строки таблицы.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tables-q4', 'html-tables', 4, 'basic', 1, 'Which element adds a title or explanation directly inside a <table> element?', '<table> elementining bevosita ichida jadvalga sarlavha yoki izoh qo''shuvchi element qaysi?', 'Какой элемент добавляет заголовок или подпись непосредственно внутрь элемента <table>?', 'The <caption> element specifies the caption (or title) of a table and must be the first child of <table>.', '<caption> elementi jadval sarlavhasini belgilaydi va <table> ning birinchi farzand elementi bo''lishi kerak.', 'Элемент <caption> задаёт заголовок таблицы и размещается первым дочерним элементом внутри <table>.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tables-q5', 'html-tables', 5, 'intermediate', 1.5, 'Which attribute makes a table cell span across multiple columns horizontally?', 'Qaysi atribut jadval katagini gorizontal ravishda bir nechta ustunga birlashtiradi (cho''zadi)?', 'Какой атрибут позволяет ячейке таблицы объединять (занимать) несколько столбцов по горизонтали?', 'The "colspan" attribute defines the number of columns a table cell should span.', '"colspan" atributi bitta jadval katagi nechta ustunni egallashi kerakligini belgilaydi.', 'Атрибут "colspan" указывает, на сколько столбцов должна растягиваться ячейка таблицы.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tables-q6', 'html-tables', 6, 'intermediate', 1.5, 'Which attribute allows a table cell to span downward across multiple rows?', 'Qaysi atribut jadval katagini vertikal ravishda bir nechta qatorga birlashtirish imkonini beradi?', 'Какой атрибут позволяет ячейке таблицы растягиваться вниз на несколько строк?', 'The "rowspan" attribute specifies the number of rows a cell should span vertically.', '"rowspan" atributi katak vertikal bo''yicha nechta qatorni birlashtirishini ko''rsatadi.', 'Атрибут "rowspan" задаёт количество строк, которые объединяет ячейка по вертикали.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tables-q7', 'html-tables', 7, 'intermediate', 1.5, 'Which three semantic elements group the header, body, and footer rows of a table?', 'Jadvalning sarlavha, asosiy tana va yakuniy qatorlarini guruhlovchi uchta semantik element qaysilar?', 'Какие три семантических элемента группируют строки шапки, основной части и подвала таблицы?', '<thead>, <tbody>, and <tfoot> semantically group table rows into header, body, and summary sections.', '<thead>, <tbody> va <tfoot> jadval qatorlarini semantik jihatdan sarlavha, asosiy qism va quyi qismga ajratadi.', 'Теги <thead>, <tbody> и <tfoot> семантически разделяют строки таблицы на шапку, тело и итоговую часть.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tables-q8', 'html-tables', 8, 'intermediate', 1.5, 'If you write a <table> with <tr> elements directly inside it, what element does the browser automatically insert in the DOM?', 'Agar <table> ichiga to''g''ridan-to''g''ri <tr> elementlarini yozsangiz, brauzer DOM daraxtiga avtomatik ravishda qaysi elementni qo''shib qo''yadi?', 'Какой элемент браузер автоматически добавит в DOM, если поместить теги <tr> непосредственно внутрь <table>?', 'Browsers automatically wrap bare <tr> elements inside an implicit <tbody> element in the DOM.', 'Brauzerlar ochiq yozilgan <tr> elementlarini DOM-da avtomatik ravishda <tbody> elementi ichiga o''rab oladi.', 'Браузер автоматически оборачивает строки <tr> в неявный элемент <tbody> при построении DOM-дерева.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tables-q9', 'html-tables', 9, 'advanced', 2.2, 'Which attribute on a <th> element explicitly tells screen readers whether the header applies to a row or a column?', '<th> elementidagi qaysi atribut ekran o''quvchi dasturlarga (screen readers) sarlavha qatorga yoki ustunga tegishli ekanligini aniq bildiradi?', 'Какой атрибут тега <th> явно указывает скринридерам, к чему относится заголовок — к строке или к столбцу?', 'The "scope" attribute (e.g., scope="col" or scope="row") improves accessibility by defining which cells a <th> relates to.', '"scope" atributi (masalan, scope="col" yoki scope="row") <th> katagi qaysi ustun yoki qatorga tegishli ekanini aniqlab, qulaylikni oshiradi.', 'Атрибут "scope" (со значениями "col" или "row") повышает доступность таблицы, указывая направление действия заголовка <th>.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-tables-q10', 'html-tables', 10, 'advanced', 2.2, 'Which element is used inside <table> to apply shared formatting or classes to entire columns without repeating attributes on every cell?', 'Har bir katakka qayta-qayta atribut yozmasdan, butun ustunlarga umumiy uslub berish uchun <table> ichida qaysi element ishlatiladi?', 'Какой элемент внутри <table> позволяет применять общие стили к целым столбцам без дублирования атрибутов в каждой ячейке?', '<colgroup> and <col> define groups of columns in a table for applying shared styles or widths.', '<colgroup> va <col> jadvaldagi ustunlar guruhiga umumiy kenglik yoki uslub berish uchun ishlatiladi.', 'Элементы <colgroup> и <col> позволяют группировать столбцы таблицы для задания им общей ширины или базовых стилей.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-links-images-q1', 'html-links-images', 1, 'basic', 1, 'Which attribute of the <a> tag specifies the URL of the page the link goes to?', '<a> tegining qaysi atributi havola olib boradigan sahifa manzilini (URL) belgilaydi?', 'Какой атрибут тега <a> указывает URL-адрес страницы, на которую ведёт ссылка?', 'The "href" (Hypertext Reference) attribute specifies the destination URL of an anchor element.', '"href" (Hypertext Reference) atributi havola yo''naltirilgan manzilni (URL) belgilaydi.', 'Атрибут "href" (Hypertext Reference) задаёт целевой адрес ссылки.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-links-images-q2', 'html-links-images', 2, 'basic', 1, 'Which two attributes should always be included on an <img> element?', '<img> elementida har doim qaysi ikkita asosiy atribut bo''lishi kerak?', 'Какие два основных атрибута всегда следует указывать у элемента <img>?', '"src" specifies the path to the image file, and "alt" provides alternative text for screen readers and broken images.', '"src" rasm fayliga yo''lni ko''rsatadi, "alt" esa rasm yuklanmaganda yoki ekran o''quvchilar uchun muqobil matnni taqdim etadi.', 'Атрибут "src" задаёт путь к изображению, а "alt" содержит альтернативный текст для доступности и на случай ошибки загрузки.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-links-images-q3', 'html-links-images', 3, 'basic', 1, 'How do you make a link open in a new browser tab or window?', 'Havolani yangi brauzer varag''ida (tab) yoki oynasida ochiladigan qilish uchun qaysi atribut yoziladi?', 'Как сделать так, чтобы ссылка открывалась в новой вкладке или окне браузера?', 'Setting target="_blank" on an <a> tag instructs the browser to open the linked document in a new tab.', '<a> tegiga target="_blank" yozish brauzerga havolani yangi varaqda (tabda) ochishni buyuradi.', 'Значение target="_blank" у тега <a> указывает браузеру открыть ссылку в новой вкладке.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-links-images-q4', 'html-links-images', 4, 'basic', 1, 'How do you create a link that opens the user''s email program to send an email?', 'Foydalanuvchining elektron pochta dasturini ochuvchi havola qanday yaratiladi?', 'Как создать ссылку, которая открывает почтовый клиент пользователя для отправки письма?', 'The "mailto:" URI scheme inside the href attribute opens the default email client addressed to the specified recipient.', 'href atributi ichidagi "mailto:" sxemasi ko''rsatilgan manzilga xat yozish uchun standart pochta dasturini ochadi.', 'Схема "mailto:" в атрибуте href открывает почтовую программу по умолчанию для отправки письма указанному адресату.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-links-images-q5', 'html-links-images', 5, 'intermediate', 1.5, 'How do you link to an element with id="contact" on the same page?', 'Shu sahifaning o''zidagi id="contact" bo''lgan elementga olib boruvchi ichki havola qanday yoziladi?', 'Как создать якорную ссылку на элемент с id="contact" на этой же странице?', 'Using a hash symbol (#) followed by the element''s ID in href creates an in-page anchor jump.', 'href ichida panjara (#) belgisidan keyin elementning ID nomini yozish sahifa ichidagi o''sha bo''limga o''tishni ta''minlaydi.', 'Символ решётки (#) перед ID элемента в атрибуте href создаёт внутреннюю ссылку-якорь для перехода к этому блоку.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-links-images-q6', 'html-links-images', 6, 'intermediate', 1.5, 'Which attribute on an <img> tag delays loading off-screen images until the user scrolls near them?', '<img> tegidagi qaysi atribut ekrandan tashqaridagi rasmlarni foydalanuvchi ularga yaqinlashguncha yuklamay turishni ta''minlaydi?', 'Какой атрибут тега <img> откладывает загрузку изображений за пределами экрана до момента прокрутки страницы к ним?', 'loading="lazy" instructs the browser to defer fetching the image until it approaches the viewport.', 'loading="lazy" brauzerga rasm ko''rish maydoniga (viewport) yaqinlashmaguncha uni yuklashni kechiktirishni buyuradi.', 'Атрибут loading="lazy" включает нативную ленивую загрузку изображения по мере приближения области просмотра.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-links-images-q7', 'html-links-images', 7, 'intermediate', 1.5, 'Why is it important to specify "width" and "height" attributes on <img> elements?', 'Nima uchun <img> elementlarida "width" va "height" atributlarini ko''rsatish muhim?', 'Почему важно указывать атрибуты "width" и "height" у элементов <img>?', 'Setting width and height lets the browser calculate the aspect ratio and reserve layout space before the image finishes downloading.', 'Width va height ko''rsatilsa, brauzer rasm yuklanib bo''lguncha uning proporsiyasini hisoblab, sahifada joy ajratib turadi.', 'Указание width и height позволяет браузеру вычислить пропорции и зарезервировать место до загрузки картинки, предотвращая скачки макета.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-links-images-q8', 'html-links-images', 8, 'intermediate', 1.5, 'Which attribute on an <a> tag prompts the browser to save the linked file instead of navigating to it?', '<a> tegidagi qaysi atribut brauzerga havola bo''yicha o''tish o''rniga u yerdagi faylni yuklab olishni buyuradi?', 'Какой атрибут тега <a> указывает браузеру скачать файл по ссылке вместо перехода к нему?', 'The "download" attribute instructs the browser to treat the linked URL as a file download.', '"download" atributi brauzerga bog''langan URL manzilni ko''rib chiqish emas, balki fayl sifatida yuklab olish kerakligini bildiradi.', 'Атрибут "download" заставляет браузер скачивать ресурс по ссылке, а не открывать его в окне.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-links-images-q9', 'html-links-images', 9, 'advanced', 2.2, 'Which element wraps multiple <source> elements and an <img> to serve different image formats or art directions based on media queries?', 'Media so''rovlar asosida turli rasm formatlari yoki o''lchamlarini taqdim etish uchun bir nechta <source> va bitta <img> ni o''rab turuvchi element qaysi?', 'Какой элемент оборачивает несколько тегов <source> и один <img> для адаптивной подгрузки разных форматов или версий изображения?', 'The <picture> element contains zero or more <source> elements and one <img> element to offer alternative image versions for different display scenarios.', '<picture> elementi turli ekranlar yoki zamonaviy formatlar (WebP, AVIF) uchun bir nechta <source> va bitta zaxira <img> elementini birlashtiradi.', 'Элемент <picture> содержит теги <source> и обязательный <img>, позволяя браузеру выбрать оптимальный формат или кроп изображения.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-links-images-q10', 'html-links-images', 10, 'advanced', 2.2, 'What security attribute value should be paired with target="_blank" when linking to untrusted external sites?', 'Ishonchsiz tashqi saytlarga target="_blank" orqali havola berganda xavfsizlik uchun qaysi atribut qiymati qo''shilishi kerak?', 'Какое значение атрибута необходимо добавлять для безопасности при использовании target="_blank" на внешние сайты?', 'rel="noopener noreferrer" prevents the newly opened page from accessing the original window via window.opener and hides referrer info.', 'rel="noopener noreferrer" yangi ochilgan sahifaga window.opener orqali asl sahifani boshqarishni taqiqlaydi va referrer ma''lumotini yashiradi.', 'Атрибут rel="noopener noreferrer" защищает от доступа новой вкладки к исходному окну через window.opener и скрывает заголовок Referer.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-attributes-q1', 'html-attributes', 1, 'basic', 1, 'Which rule applies to the "id" attribute in an HTML document?', 'HTML hujjatida "id" atributiga nisbatan qaysi qoida amal qiladi?', 'Какое правило действует для атрибута "id" в HTML-документе?', 'The "id" global attribute defines a unique identifier that must not be duplicated anywhere else in the document.', '"id" global atributi butun hujjat davomida takrorlanmasligi shart bo''lgan noyob identifikatorni belgilaydi.', 'Глобальный атрибут "id" задаёт уникальный идентификатор элемента, который не должен повторяться на странице.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-attributes-q2', 'html-attributes', 2, 'basic', 1, 'How do you assign multiple CSS classes to a single HTML element?', 'Bitta HTML elementiga bir nechta CSS klasslarini qanday biriktirish mumkin?', 'Как назначить несколько CSS-классов одному HTML-элементу?', 'Multiple classes are applied to an element by separating each class name with a space inside one "class" attribute.', 'Bitta "class" atributi ichida klass nomlarini bo''sh joy (probel) bilan ajratib yozish orqali elementga bir nechta klass beriladi.', 'Несколько классов указываются внутри одного атрибута "class" через обычный пробел.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-attributes-q3', 'html-attributes', 3, 'basic', 1, 'Which global attribute displays advisory information as a tooltip when the mouse hovers over an element?', 'Sichqoncha element ustiga olib borilganda qalqib chiquvchi maslahat matnini (tooltip) ko''rsatadigan global atribut qaysi?', 'Какой глобальный атрибут отображает всплывающую подсказку (tooltip) при наведении курсора мыши на элемент?', 'The global "title" attribute provides additional advisory text, typically rendered as a tooltip on hover.', 'Global "title" atributi qo''shimcha ma''lumot beradi va odatda kursor olib borilganda tooltip sifatida ko''rinadi.', 'Глобальный атрибут "title" содержит дополнительную информацию об элементе, которая обычно показывается во всплывающей подсказке.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-attributes-q4', 'html-attributes', 4, 'basic', 1, 'Which attribute is used on the <html> tag to declare the primary language of the document?', 'Hujjatning asosiy tilini e''lon qilish uchun <html> tegida qaysi atribut ishlatiladi?', 'Какой атрибут используется в теге <html> для указания основного языка документа?', 'The "lang" attribute (e.g., <html lang="en">) helps screen readers, search engines, and translation tools identify the page language.', '"lang" atributi (masalan, <html lang="uz">) ekran o''quvchilar, qidiruv tizimlari va tarjimonlarga sahifa tilini aniqlashga yordam beradi.', 'Атрибут "lang" (например, <html lang="ru">) помогает скринридерам, поисковикам и переводчикам определить язык текста.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-attributes-q5', 'html-attributes', 5, 'intermediate', 1.5, 'How do you create valid custom data attributes in HTML5 to store extra information on an element?', 'Elementda qo''shimcha ma''lumot saqlash uchun HTML5-da to''g''ri maxsus (custom) atributlar qanday yaratiladi?', 'Как в HTML5 создаются валидные пользовательские атрибуты для хранения дополнительных данных в элементе?', 'Attributes starting with "data-" form custom data attributes accessible in JavaScript via the element.dataset property.', '"data-" bilan boshlanadigan atributlar maxsus ma''lumot atributlari bo''lib, JavaScript-da element.dataset orqali o''qiladi.', 'Атрибуты с префиксом "data-" позволяют хранить произвольные данные, доступные в JavaScript через свойство element.dataset.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-attributes-q6', 'html-attributes', 6, 'intermediate', 1.5, 'Which global boolean attribute hides an element so it is not rendered on the page?', 'Qaysi global mantiqiy (boolean) atribut elementni sahifada ko''rinmaydigan qilib yashiradi?', 'Какой глобальный булев атрибут скрывает элемент, чтобы он не отображался на странице?', 'The boolean "hidden" attribute indicates that the element is not yet, or is no longer, relevant and prevents the browser from rendering it.', 'Mantiqiy "hidden" atributi element hozircha ko''rsatilmasligi kerakligini bildiradi va brauzer uni ekranga chiqarmaydi.', 'Глобальный булев атрибут "hidden" указывает браузеру не отображать данный элемент на странице.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-attributes-q7', 'html-attributes', 7, 'intermediate', 1.5, 'Which attribute makes any HTML element directly editable by the user in the browser?', 'Qaysi atribut har qanday HTML elementning matnini brauzerning o''zida foydalanuvchi tomonidan tahrirlanadigan qiladi?', 'Какой атрибут делает содержимое любого HTML-элемента редактируемым прямо в браузере?', 'Setting contenteditable="true" turns a standard HTML element into an interactive rich-text editable region.', 'contenteditable="true" atributi oddiy HTML elementini foydalanuvchi bevosita yozib o''zgartira oladigan maydonga aylantiradi.', 'Атрибут contenteditable="true" позволяет пользователю редактировать текстовое содержимое элемента прямо на странице.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-attributes-q8', 'html-attributes', 8, 'intermediate', 1.5, 'Which attribute is used to apply inline CSS rules directly to an individual HTML element?', 'Alohida bir HTML elementiga to''g''ridan-to''g''ri inline CSS qoidalarini yozish uchun qaysi atribut ishlatiladi?', 'Какой атрибут используется для применения встроенных (inline) CSS-стилей непосредственно к HTML-элементу?', 'The "style" attribute contains inline CSS declarations applied directly to that specific element.', '"style" atributi faqat o''sha elementning o''ziga ta''sir qiluvchi inline CSS xossalarini o''z ichiga oladi.', 'Атрибут "style" позволяет задать встроенные CSS-свойства непосредственно для конкретного элемента.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-attributes-q9', 'html-attributes', 9, 'advanced', 2.2, 'What does setting tabindex="0" on a non-interactive element like a <div> do?', '<div> kabi interaktiv bo''lmagan elementga tabindex="0" berilsa nima sodir bo''ladi?', 'Что даёт установка атрибута tabindex="0" для неинтерактивного элемента, например <div>?', 'tabindex="0" allows an element that is not normally focusable to receive keyboard focus in the normal DOM document order.', 'tabindex="0" odatda fokus olmaydigan elementga DOM tartibida klaviatura (Tab) orqali fokus olish imkonini beradi.', 'Значение tabindex="0" включает элемент в стандартную последовательность обхода клавишей Tab согласно порядку в DOM.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-attributes-q10', 'html-attributes', 10, 'advanced', 2.2, 'What is the effect of setting tabindex="-1" on an HTML element?', 'HTML elementiga tabindex="-1" qiymatini berish qanday natija beradi?', 'Какой эффект даёт установка атрибута tabindex="-1" на HTML-элементе?', 'tabindex="-1" prevents sequential keyboard navigation with the Tab key while still allowing programmatic focus via element.focus().', 'tabindex="-1" Tab tugmasi bilan fokusga tushishni to''xtatadi, biroq element.focus() metodi orqali fokus berishga ruxsat etadi.', 'Значение tabindex="-1" убирает элемент из навигации по клавише Tab, но сохраняет возможность сфокусироваться на нём через element.focus().') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-advanced-q1', 'html-advanced', 1, 'basic', 1, 'Which HTML5 element provides a bitmap drawing surface controlled via JavaScript for 2D graphics and WebGL?', 'JavaScript yordamida 2D grafika va WebGL chizish uchun pikselli (bitmap) maydon taqdim etuvchi HTML5 elementi qaysi?', 'Какой элемент HTML5 предоставляет растровую область для рисования 2D-графики и WebGL с помощью JavaScript?', 'The <canvas> element is used to draw graphics on the fly via scripting (usually JavaScript) using 2D or WebGL contexts.', '<canvas> elementi JavaScript (2D yoki WebGL konteksti) yordamida dinamik grafika va animatsiyalar chizish uchun ishlatiladi.', 'Элемент <canvas> служит контейнером для динамического рисования растровой графики через JavaScript API (2D или WebGL).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-advanced-q2', 'html-advanced', 2, 'basic', 1, 'Which attribute must be added to an <audio> or <video> tag to display the browser''s native play, pause, and volume buttons?', 'Brauzerning standart ijro etish (play), to''xtatish (pause) va ovoz tugmalarini ko''rsatish uchun <audio> yoki <video> tegiga qaysi atribut qo''shilishi kerak?', 'Какой атрибут необходимо добавить к тегу <audio> или <video>, чтобы отобразить стандартные кнопки управления плеером?', 'The boolean "controls" attribute instructs the browser to expose its built-in media playback interface.', 'Mantiqiy "controls" atributi brauzerga media pleyerning ichki boshqaruv tugmalarini ko''rsatishni buyuradi.', 'Булев атрибут "controls" включает отображение встроенной панели управления воспроизведением медиафайла.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-advanced-q3', 'html-advanced', 3, 'basic', 1, 'Which element is used to embed another HTML page within the current HTML document?', 'Joriy HTML hujjat ichiga boshqa bir HTML sahifani joylashtirish (ramkada ko''rsatish) uchun qaysi element ishlatiladi?', 'Какой элемент используется для встраивания другой HTML-страницы внутрь текущего документа?', 'The <iframe> (Inline Frame) element represents a nested browsing context, embedding another HTML page into the current one.', '<iframe> (Inline Frame) elementi joriy sahifa ichiga boshqa bir veb-sahifani ichki oyna sifatida joylashtiradi.', 'Элемент <iframe> (Inline Frame) создаёт вложенный контекст просмотра, позволяя встроить одну веб-страницу в другую.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-advanced-q4', 'html-advanced', 4, 'basic', 1, 'What is the primary difference between <svg> and <canvas>?', '<svg> va <canvas> o''rtasidagi asosiy farq nima?', 'В чём заключается главное отличие между <svg> и <canvas>?', '<svg> defines scalable vector graphics using DOM nodes, whereas <canvas> draws immediate-mode pixels without creating inner DOM nodes.', '<svg> DOM tugunlaridan iborat masshtablanuvchi vektor grafikani ifodalaydi, <canvas> esa ichki DOM yaratmasdan piksellar chizadi.', '<svg> описывает масштабируемую векторную графику через узлы DOM, а <canvas> рисует пиксели на растровом холсте без внутренних DOM-элементов.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-advanced-q5', 'html-advanced', 5, 'intermediate', 1.5, 'What is the difference between <script async> and <script defer> when loading external JavaScript?', 'Tashqi JavaScript faylini yuklashda <script async> va <script defer> o''rtasida qanday farq bor?', 'В чём разница между атрибутами <script async> и <script defer> при загрузке внешнего скрипта?', 'Both download in parallel, but "defer" waits until the HTML document is fully parsed and preserves script order, while "async" executes immediately upon download.', 'Ikkalasi ham parallel yuklanadi, ammo "defer" HTML to''liq o''qib bo''lingach tartib bilan ishlaydi, "async" esa yuklanishi bilanoq darhol ishga tushadi.', 'Оба загружают скрипт параллельно, но "defer" ждёт окончания парсинга HTML и сохраняет порядок выполнения, а "async" запускает скрипт сразу после скачивания.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-advanced-q6', 'html-advanced', 6, 'intermediate', 1.5, 'Which HTML5 element holds client-side markup that is NOT rendered when the page loads, but can be cloned and inserted via JavaScript?', 'Sahifa yuklanganda ekranga chiqmaydigan, lekin JavaScript orqali nusxalab sahifaga qo''shish mumkin bo''lgan shablonni qaysi HTML5 elementi saqlaydi?', 'Какой элемент HTML5 хранит фрагмент разметки, который НЕ отображается при загрузке страницы, но может быть клонирован и вставлен через JavaScript?', 'The <template> element holds inert HTML fragments that are not rendered until instantiated via JavaScript.', '<template> elementi JavaScript orqali chaqirilmaguncha ekranda aks etmaydigan tayyor HTML qoliplarini saqlash uchun ishlatiladi.', 'Элемент <template> содержит инертный фрагмент HTML, который не рендерится браузером до тех пор, пока его не клонируют с помощью JavaScript.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-advanced-q7', 'html-advanced', 7, 'intermediate', 1.5, 'Which native HTML element represents a modal or non-modal dialog box that can be opened with .showModal()?', 'JavaScript-dagi .showModal() metodi orqali ochilishi mumkin bo''lgan modal oynani qaysi standart HTML elementi ifodalaydi?', 'Какой нативный HTML-элемент представляет модальное или немодальное диалоговое окно, открываемое методом .showModal()?', 'The <dialog> element provides a native accessible modal or dialog box with built-in focus trapping and backdrop support.', '<dialog> elementi fokusni ushlab turuvchi va orqa fonni xiralashtiruvchi (::backdrop) tayyor qulay modal oyna yaratadi.', 'Элемент <dialog> позволяет создавать нативные модальные окна со встроенным управлением фокусом и псевдоэлементом ::backdrop.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-advanced-q8', 'html-advanced', 8, 'intermediate', 1.5, 'Which attribute on an <iframe> enables strict security restrictions (such as blocking scripts and forms) unless specific permissions are listed?', '<iframe> elementida skriptlar va formalarni bloklash kabi qat''iy xavfsizlik cheklovlarini yoquvchi atribut qaysi?', 'Какой атрибут элемента <iframe> включает строгие ограничения безопасности (блокировку скриптов, форм и др.), если явно не указаны разрешения?', 'The "sandbox" attribute applies extra restrictions to the content in an <iframe> to prevent untrusted code execution.', '"sandbox" atributi <iframe> ichidagi tarkibga qo''shimcha xavfsizlik cheklovlarini qo''llab, zararli kodlar ishlashining oldini oladi.', 'Атрибут "sandbox" накладывает строгие ограничения безопасности на содержимое <iframe>.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-advanced-q9', 'html-advanced', 9, 'advanced', 2.2, 'What is the purpose of the "aria-label" attribute in web accessibility?', 'Veb-qulaylikda (accessibility) "aria-label" atributining vazifasi nima?', 'Каково назначение атрибута "aria-label" в веб-доступности (accessibility)?', '"aria-label" defines a string value that labels an interactive element for assistive technologies when visible text is absent.', '"aria-label" ko''rinadigan matni yo''q interaktiv elementlarga (masalan, ikonka tugmalarga) yordamchi texnologiyalar o''qiy oladigan nom beradi.', 'Атрибут "aria-label" предоставляет доступное имя элемента для экранных дикторов, когда на экране нет видимого текста.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('html-advanced-q10', 'html-advanced', 10, 'advanced', 2.2, 'Which <link> rel value instructs the browser to establish an early network connection (DNS + TCP + TLS) to an external domain before resources are requested?', 'Resurslar so''ralishidan oldin tashqi domen bilan erta tarmoq ulanishini (DNS + TCP + TLS) o''rnatishni brauzerga buyuruvchi <link> rel qiymati qaysi?', 'Какое значение атрибута rel у тега <link> указывает браузеру заранее установить соединение (DNS + TCP + TLS) с внешним доменом?', '<link rel="preconnect"> tells the browser to perform DNS lookup, TCP handshake, and TLS negotiation ahead of time to reduce latency.', '<link rel="preconnect"> kechikishni kamaytirish uchun brauzerga DNS qidiruvi, TCP va TLS ulanishlarini oldindan bajarib qo''yishni buyuradi.', '<link rel="preconnect"> позволяет браузеру заранее выполнить DNS-запрос, TCP-рукопожатие и TLS-согласование с нужным сервером.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-basics-q1', 'css-basics', 1, 'basic', 1, 'What does CSS stand for?', 'CSS qisqartmasining to''liq ma''nosi nima?', 'Как расшифровывается CSS?', 'CSS stands for Cascading Style Sheets, used to describe the presentation and layout of HTML documents.', 'CSS — Cascading Style Sheets bo''lib, HTML hujjatlarning tashqi ko''rinishi va maketini bezash uchun ishlatiladi.', 'CSS расшифровывается как Cascading Style Sheets (каскадные таблицы стилей) и отвечает за визуальное оформление HTML.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-basics-q2', 'css-basics', 2, 'basic', 1, 'Which HTML tag is used to link an external CSS file inside the <head> section?', '<head> bo''limi ichida tashqi CSS faylni ulash uchun qaysi HTML tegi ishlatiladi?', 'Какой HTML-тег используется внутри <head> для подключения внешнего CSS-файла?', '<link rel="stylesheet" href="..."> is the standard way to attach an external CSS stylesheet to an HTML document.', '<link rel="stylesheet" href="..."> — tashqi CSS uslublar faylini HTML hujjatga ulashning standart usuli hisoblanadi.', 'Тег <link rel="stylesheet" href="..."> — стандартный способ подключения внешней таблицы стилей к странице.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-basics-q3', 'css-basics', 3, 'basic', 1, 'How do you write a comment in CSS?', 'CSS-da izoh (comment) qanday yoziladi?', 'Как правильно написать комментарий в CSS?', 'CSS uses /* to start a comment and */ to close it, for both single-line and multi-line comments.', 'CSS-da bir qatorli va ko''p qatorli izohlar /* bilan boshlanib, */ bilan yopiladi.', 'В CSS как однострочные, так и многострочные комментарии заключаются между символами /* и */.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-basics-q4', 'css-basics', 4, 'basic', 1, 'Which CSS property controls the space INSIDE an element, between its content and its border?', 'Qaysi CSS xossasi elementning ICHKI bo''shlig''ini (uning tarkibi va chegarasi orasidagi masofani) boshqaradi?', 'Какое CSS-свойство управляет ВНУТРЕННИМ отступом элемента (между содержимым и рамкой)?', 'Padding is the inner space between an element''s content box and its border.', 'Padding — elementning ichki mazmuni (content) bilan uning ramkasi (border) orasidagi ichki masofadir.', 'Свойство padding задаёт внутренний отступ между содержимым элемента и его границей (border).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-basics-q5', 'css-basics', 5, 'intermediate', 1.5, 'What does "box-sizing: border-box" do to an element''s width and height calculation?', '"box-sizing: border-box" xossasi elementning kengligi (width) va balandligi (height) hisoblanishiga qanday ta''sir qiladi?', 'Как свойство "box-sizing: border-box" влияет на расчёт ширины и высоты элемента?', 'With box-sizing: border-box, an element''s specified width and height include content, padding, and border.', 'box-sizing: border-box berilganda, elementga yozilgan width va height qiymatlari ichiga content, padding va border kiradi.', 'При box-sizing: border-box заданные значения width и height включают в себя содержимое, внутренние отступы (padding) и рамку (border).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-basics-q6', 'css-basics', 6, 'intermediate', 1.5, 'Which CSS property controls the space OUTSIDE an element''s border, separating it from neighboring elements?', 'Element chegarasidan (border) TASHQARIDAGI bo''shliqni (qo''shni elementlardan uzoqlikni) qaysi CSS xossasi boshqaradi?', 'Какое CSS-свойство задаёт ВНЕШНИЙ отступ за пределами рамки элемента?', 'Margin defines the outer transparent area around an element''s border that separates it from other elements.', 'Margin element ramkasidan tashqaridagi bo''sh maydonni belgilab, uni qo''shni elementlardan ajratib turadi.', 'Свойство margin определяет внешний отступ вокруг рамки элемента, отделяющий его от соседних элементов.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-basics-q7', 'css-basics', 7, 'intermediate', 1.5, 'What is the difference between "display: none" and "visibility: hidden"?', '"display: none" va "visibility: hidden" o''rtasida qanday farq bor?', 'В чём отличие между "display: none" и "visibility: hidden"?', 'display: none removes the element from the document flow completely, whereas visibility: hidden makes it invisible while preserving its layout box.', 'display: none elementni sahifa oqimidan butunlay olib tashlaydi, visibility: hidden esa uni ko''rinmas qilib, joyini bo''sh qoldiradi.', 'display: none исключает элемент из потока документа, а visibility: hidden делает его невидимым, сохраняя занимаемое им место в макете.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-basics-q8', 'css-basics', 8, 'intermediate', 1.5, 'In the shorthand "margin: 10px 20px;", what are the top/bottom and left/right margin values?', '"margin: 10px 20px;" qisqa yozuvida tepa/past va chap/o''ng masofalar qanday taqsimlanadi?', 'Как распределяются отступы в краткой записи "margin: 10px 20px;"?', 'When two values are given to margin or padding, the first applies to top and bottom, and the second applies to left and right.', 'Margin yoki padding uchun ikkita qiymat berilsa, birinchisi tepa va pastga, ikkinchisi esa chap va o''ng tomonlarga qo''llanadi.', 'При указании двух значений первое задаёт верхний и нижний отступы, а второе — левый и правый.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-basics-q9', 'css-basics', 9, 'advanced', 2.2, 'How do you define and use a CSS Custom Property (CSS Variable)?', 'CSS o''zgaruvchisi (Custom Property) qanday e''lon qilinadi va qanday ishlatiladi?', 'Как правильно объявить и использовать CSS-переменную (Custom Property)?', 'CSS Custom Properties start with two dashes (--name) and are accessed using the var(--name) function.', 'CSS o''zgaruvchilari ikkita tire (--nomi) bilan e''lon qilinadi va var(--nomi) funksiyasi yordamida chaqiriladi.', 'Пользовательские CSS-свойства объявляются с двойным дефисом (--name) и подставляются с помощью функции var(--name).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-basics-q10', 'css-basics', 10, 'advanced', 2.2, 'What happens when two adjacent vertical block elements have margin-bottom: 30px and margin-top: 20px in normal flow?', 'Oddiy oqimda ustma-ust joylashgan ikkita blok elementning birida margin-bottom: 30px, ikkinchisida margin-top: 20px bo''lsa, ular orasidagi masofa qancha bo''ladi?', 'Чему будет равно расстояние между двумя соседними вертикальными блоками в обычном потоке, если у верхнего margin-bottom: 30px, а у нижнего margin-top: 20px?', 'Due to CSS margin collapsing, adjacent vertical margins in normal block flow combine into a single margin equal to the largest individual margin (30px).', 'CSS-da vertikal marginlar birlashishi (margin collapsing) tufayli ular qo''shilmaydi, balki ikkalasidan kattasi (30px) olinadi.', 'Из-за схлопывания вертикальных отступов (margin collapsing) итоговое расстояние между блоками будет равно большему из двух отступов — 30px.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-selectors-q1', 'css-selectors', 1, 'basic', 1, 'Which symbol prefixes a CSS class selector?', 'CSS-da klass selektori qaysi belgi bilan boshlanadi?', 'Какой символ ставится перед именем класса в CSS-селекторе?', 'A class selector starts with a dot (e.g., .card) and matches all elements containing that class name.', 'Klass selektori nuqta bilan boshlanadi (masalan, .card) va shu klassga ega barcha elementlarni tanlaydi.', 'Селектор класса начинается с точки (например, .card) и выбирает все элементы с указанным классом.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-selectors-q2', 'css-selectors', 2, 'basic', 1, 'Which symbol prefixes a CSS ID selector?', 'CSS-da ID selektori qaysi belgi bilan boshlanadi?', 'Какой символ используется в начале селектора по идентификатору (ID)?', 'An ID selector begins with a hash symbol (e.g., #header) and targets the element with that unique ID.', 'ID selektori panjara (#) belgisi bilan boshlanadi (masalan, #header) va o''sha noyob ID-ga ega elementni tanlaydi.', 'Селектор идентификатора начинается с символа решётки (например, #header) и выбирает элемент с соответствующим атрибутом id.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-selectors-q3', 'css-selectors', 3, 'basic', 1, 'What does the universal selector (*) select in CSS?', 'CSS-da universal selektor (*) nimani tanlaydi?', 'Что выбирает универсальный селектор (*) в CSS?', 'The asterisk (*) is the universal selector in CSS and matches elements of any type.', 'Yulduzcha (*) CSS-da universal selektor bo''lib, sahifadagi barcha turdagi elementlarni tanlaydi.', 'Звёздочка (*) является универсальным селектором, который соответствует всем элементам на странице.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-selectors-q4', 'css-selectors', 4, 'basic', 1, 'Which pseudo-class applies styles when a user moves their mouse cursor over an element?', 'Foydalanuvchi sichqoncha kursorini element ustiga olib borganda uslub beruvchi psevdo-klass qaysi?', 'Какой псевдокласс применяет стили при наведении курсора мыши на элемент?', 'The :hover pseudo-class matches when the user designates an element with a pointing device such as a mouse.', ':hover psevdo-klassi foydalanuvchi sichqoncha kursorini element ustiga olib borganda ishга tushadi.', 'Псевдокласс :hover срабатывает, когда пользователь наводит указатель мыши на элемент.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-selectors-q5', 'css-selectors', 5, 'intermediate', 1.5, 'What is the difference between the selectors "div p" and "div > p"?', '"div p" va "div > p" selektorlari o''rtasida qanday farq bor?', 'В чём разница между селекторами "div p" и "div > p"?', 'A space is the descendant combinator (any nesting depth), while ">" is the child combinator (only direct children).', 'Bo''sh joy har qanday ichki darajadagi avlodlarni tanlaydi, ">" esa faqat birinchi darajali bevosita farzandlarni tanlaydi.', 'Пробел выбирает всех потомков на любой глубине вложенности, а комбинатор ">" — только непосредственных (прямых) детей.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-selectors-q6', 'css-selectors', 6, 'intermediate', 1.5, 'Which selector targets every even-numbered list item (2nd, 4th, 6th, etc.)?', 'Qaysi selektor har bir juft tartibdagi ro''yxat bandini (2-, 4-, 6- va h.k.) tanlaydi?', 'Какой селектор выбирает каждый чётный элемент списка (2-й, 4-й, 6-й и т. д.)?', 'The :nth-child(even) or :nth-child(2n) pseudo-class matches elements whose numeric position among siblings is even.', ':nth-child(even) yoki :nth-child(2n) psevdo-klassi tengdosh elementlar orasida juft o''rinda turganlarini tanlaydi.', 'Псевдокласс :nth-child(even) или :nth-child(2n) выбирает элементы с чётными порядковыми номерами среди соседей.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-selectors-q7', 'css-selectors', 7, 'intermediate', 1.5, 'Which attribute selector matches all <a> elements whose "href" attribute starts with "https"?', '"href" atributi "https" bilan boshlanadigan barcha <a> elementlarini qaysi atribut selektori tanlaydi?', 'Какой селектор атрибутов выберет все ссылки <a>, у которых значение "href" начинается с "https"?', 'The ^= operator in an attribute selector matches values that begin with the specified prefix string.', 'Atribut selektoridagi ^= operatori qiymati ko''rsatilgan matn bilan boshlanadigan elementlarni topadi.', 'Оператор ^= в селекторе атрибута проверяет, начинается ли значение атрибута с указанной подстроки.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-selectors-q8', 'css-selectors', 8, 'intermediate', 1.5, 'Which CSS property is required inside a "::before" or "::after" pseudo-element for it to be generated and rendered?', '"::before" yoki "::after" psevdo-elementi ekranda paydo bo''lishi uchun uning ichida qaysi CSS xossasi bo''lishi shart?', 'Какое CSS-свойство обязательно должно быть указано у псевдоэлементов "::before" и "::after", чтобы они отобразились на странице?', 'Pseudo-elements ::before and ::after will not render unless their "content" property is specified (even as an empty string content: "").', '::before va ::after psevdo-elementlari ishlashi uchun ularda "content" xossasi (hatto bo''sh satr content: "" bo''lsa ham) yozilishi shart.', 'Псевдоэлементы ::before и ::after не создаются браузером без свойства "content" (даже если оно пустое: content: "").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-selectors-q9', 'css-selectors', 9, 'advanced', 2.2, 'Rank these CSS selector types from HIGHEST specificity to LOWEST specificity:', 'Quyidagi CSS selektor turlarini ustunlik darajasi (specificity) ENG YUQORIDAN ENG PASTGA qarab joylashtiring:', 'Расположите типы CSS-селекторов в порядке убывания их специфичности (от САМОЙ ВЫСОКОЙ к САМОЙ НИЗКОЙ):', 'Specificity weights follow the hierarchy: Inline styles (1,0,0,0) > ID selectors (0,1,0,0) > Classes/attributes/pseudo-classes (0,0,1,0) > Elements/pseudo-elements (0,0,0,1).', 'CSS specificity tartibi: Inline uslublar (1,0,0,0) > ID selektorlar (0,1,0,0) > Klass/atribut/psevdo-klasslar (0,0,1,0) > Teg/psevdo-elementlar (0,0,0,1).', 'Иерархия специфичности: инлайновые стили (1,0,0,0) > селекторы ID (0,1,0,0) > классы/атрибуты/псевдоклассы (0,0,1,0) > теги/псевдоэлементы (0,0,0,1).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-selectors-q10', 'css-selectors', 10, 'advanced', 2.2, 'What is the specificity weight of the :where() pseudo-class function compared to :is()?', ':where() psevdo-klass funksiyasining specificity (ustunlik) qiymati :is() bilan solishtirganda qanday?', 'Какова специфичность функционального псевдокласса :where() по сравнению с :is()?', ':where() always has zero specificity (0,0,0,0), making it ideal for easily-overridable default library styles, whereas :is() adopts its highest argument''s specificity.', ':where() har doim nol (0,0,0,0) ustunlikka ega bo''lib, keyinchalik qayta yozish oson bo''lgan bazaviy uslublar uchun juda qulay.', 'Псевдокласс :where() всегда имеет нулевую специфичность, что позволяет легко переопределять базовые стили без повышения веса селекторов.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-colors-q1', 'css-colors', 1, 'basic', 1, 'Which CSS property changes the text color of an element?', 'Elementning matn rangini qaysi CSS xossasi o''zgartiradi?', 'Какое CSS-свойство изменяет цвет текста элемента?', 'The "color" property sets the foreground color value of an element''s text and text decorations.', '"color" xossasi elementning matni va matn bezaklarining asosiy rangini belgilaydi.', 'Свойство "color" устанавливает цвет текста элемента и его текстовых декораций.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-colors-q2', 'css-colors', 2, 'basic', 1, 'What color does the hexadecimal code "#ffffff" represent?', '"#ffffff" o''n oltilik (HEX) rang kodi qaysi rangni ifodalaydi?', 'Какой цвет обозначает шестнадцатеричный код "#ffffff"?', 'In RGB hex notation (#RRGGBB), maximum values (ff = 255) for Red, Green, and Blue combine to produce pure white.', 'HEX formatida (#RRGGBB) qizil, yashil va ko''k kanallarning maksimal (ff = 255) qiymati sof oq rangni hosil qiladi.', 'В HEX-записи (#RRGGBB) максимальные значения всех трёх каналов (ff = 255) дают чистый белый цвет.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-colors-q3', 'css-colors', 3, 'basic', 1, 'In rgba(255, 0, 0, 0.5), what does the fourth value (0.5) control?', 'rgba(255, 0, 0, 0.5) ifodasidagi to''rtinchi qiymat (0.5) nimani boshqaradi?', 'За что отвечает четвёртый параметр (0.5) в функции rgba(255, 0, 0, 0.5)?', 'The fourth parameter in rgba() is the alpha channel, ranging from 0.0 (fully transparent) to 1.0 (fully opaque).', 'rgba() funksiyasidagi to''rtinchi parametr alfa kanali bo''lib, 0.0 (to''liq shaffof) dan 1.0 (to''liq tiniq) gacha qiymat oladi.', 'Четвёртый аргумент в rgba() задаёт альфа-канал (непрозрачность) от 0 (полностью прозрачный) до 1 (полностью непрозрачный).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-colors-q4', 'css-colors', 4, 'basic', 1, 'Which CSS property sets an image as the background of an element?', 'Elementning orqa foniga rasm qo''yish uchun qaysi CSS xossasi ishlatiladi?', 'Какое CSS-свойство устанавливает фоновое изображение для элемента?', 'The "background-image" property sets one or more background images on an element using url("...").', '"background-image" xossasi url("...") yordamida elementga bitta yoki bir nechta fon rasmini o''rnatadi.', 'Свойство "background-image" с функцией url("...") задаёт фоновое изображение элемента.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-colors-q5', 'css-colors', 5, 'intermediate', 1.5, 'What does "background-size: cover" do to a background image?', '"background-size: cover" xossasi orqa fon rasmiga qanday ta''sir ko''rsatadi?', 'Что делает значение "background-size: cover" с фоновым изображением?', 'background-size: cover scales the image as large as possible without stretching so the container has no uncovered background area.', 'background-size: cover rasmni cho''zmasdan konteynerda bo''sh joy qolmaydigan qilib to''liq qoplaydi.', 'Значение cover масштабирует изображение с сохранением пропорций так, чтобы оно целиком заполнило контейнер без пустых областей.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-colors-q6', 'css-colors', 6, 'intermediate', 1.5, 'Which CSS function creates a smooth color transition along a straight line (e.g., top to bottom or at an angle)?', 'To''g''ri chiziq bo''ylab (masalan, tepadan pastga yoki ma''lum burchak ostida) silliq rang o''tishini yaratuvchi CSS funksiyasi qaysi?', 'Какая CSS-функция создаёт плавный цветовой переход вдоль прямой линии (например, сверху вниз или под углом)?', 'linear-gradient() creates an image consisting of a progressive transition between two or more colors along a straight line.', 'linear-gradient() to''g''ri chiziq bo''ylab ikki yoki undan ortiq ranglar orasidagi silliq o''tishni (gradient) hosil qiladi.', 'Функция linear-gradient() создаёт линейный градиент — плавный переход между двумя и более цветами вдоль заданного направления.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-colors-q7', 'css-colors', 7, 'intermediate', 1.5, 'What do the letters H, S, and L stand for in the hsl() color function?', 'hsl() rang funksiyasidagi H, S va L harflari nimani anglatadi?', 'Что означают буквы H, S и L в цветовой модели hsl()?', 'HSL represents colors by Hue (0-360 deg on the color wheel), Saturation (0%-100%), and Lightness (0%-100%).', 'HSL ranglarni Hue (0-360 daraja rang doirasi), Saturation (0%-100% to''yinganlik) va Lightness (0%-100% yorug''lik) orqali ifodalaydi.', 'Модель HSL задаёт цвет через Hue (цветовой тон в градусах 0–360), Saturation (насыщенность 0–100%) и Lightness (светлоту 0–100%).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-colors-q8', 'css-colors', 8, 'intermediate', 1.5, 'What is the key difference between setting "opacity: 0.5" on a card versus setting "background-color: rgba(0, 0, 0, 0.5)"?', 'Kartochkaga "opacity: 0.5" berish bilan "background-color: rgba(0, 0, 0, 0.5)" berishning asosiy farqi nimada?', 'В чём ключевое отличие между установкой "opacity: 0.5" для блока и "background-color: rgba(0, 0, 0, 0.5)"?', 'The opacity property applies transparency to the whole element subtree, whereas an rgba() background leaves child text at full opacity.', 'opacity xossasi element va uning ichidagi barcha matn/rasmlarni shaffof qiladi, rgba() esa faqat fonning o''zini shaffof qiladi.', 'Свойство opacity применяет прозрачность ко всему элементу вместе с его содержимым, тогда как rgba() задаёт прозрачность только для фона.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-colors-q9', 'css-colors', 9, 'advanced', 2.2, 'What does the CSS keyword "currentColor" represent?', 'CSS-dagi "currentColor" kalit so''zi qanday qiymatni ifodalaydi?', 'Что представляет собой ключевое слово "currentColor" в CSS?', 'currentColor resolves to the element''s computed "color" value, making it easy to sync SVG icons, borders, or shadows with the text color.', 'currentColor elementning joriy matn rangiga ("color") teng bo''ladi; bu SVG ikonkalar va ramkalarni matn rangi bilan bir xil saqlashda juda qulay.', 'Ключевое слово currentColor ссылается на текущее значение свойства color элемента, что удобно для окрашивания SVG-иконок и рамок в цвет текста.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-colors-q10', 'css-colors', 10, 'advanced', 2.2, 'Which CSS property applies graphical effects like blur or color shifting to the area BEHIND an element (glassmorphism effect)?', 'Elementning ORQASIDAGI sohaga xiralashtirish (blur) kabi grafik effektlarni qo''llab, "shisha" (glassmorphism) effektini yaratuvchi CSS xossasi qaysi?', 'Какое CSS-свойство применяет графические эффекты (например, размытие blur) к области ПОЗАДИ элемента для создания эффекта матового стекла?', 'backdrop-filter (e.g., backdrop-filter: blur(10px)) applies filter effects to the content visible behind a semi-transparent element.', 'backdrop-filter (masalan, backdrop-filter: blur(10px)) yarim shaffof element ortidan ko''rinib turgan fonni xiralashtirish imkonini beradi.', 'Свойство backdrop-filter (например, backdrop-filter: blur(10px)) применяет фильтры к содержимому, находящемуся за полупрозрачным элементом.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-flexbox-q1', 'css-flexbox', 1, 'basic', 1, 'Which declaration turns an element into a flex container?', 'Qaysi CSS qoidasi elementni flex-konteynerga aylantiradi?', 'Какое объявление превращает элемент во flex-контейнер?', 'Setting display: flex (or display: inline-flex) enables a flex formatting context for all of its direct children.', 'display: flex (yoki display: inline-flex) xossasi elementni flex-konteyner qiladi va uning bevosita farzandlarini flex-elementga aylantiradi.', 'Свойство display: flex (или inline-flex) создаёт flex-контейнер и включает гибкую раскладку для его прямых потомков.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-flexbox-q2', 'css-flexbox', 2, 'basic', 1, 'What is the default value of "flex-direction" in a flex container?', 'Flex-konteynerda "flex-direction" xossasining standart (default) qiymati qanday?', 'Какое значение по умолчанию имеет свойство "flex-direction" у flex-контейнера?', 'By default, flex-direction is "row", placing flex items horizontally from left to right (in LTR languages).', 'Odatiy holatda flex-direction qiymati "row" bo''lib, elementlarni gorizontal qator bo''ylab chapdan o''ngga joylashtiradi.', 'По умолчанию flex-direction равен "row", поэтому flex-элементы выстраиваются в строку слева направо.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-flexbox-q3', 'css-flexbox', 3, 'basic', 1, 'Which property aligns flex items along the MAIN axis?', 'Qaysi xossa flex-elementlarni ASOSIY o''q (main axis) bo''ylab tekislaydi?', 'Какое свойство выравнивает flex-элементы вдоль ГЛАВНОЙ оси (main axis)?', 'justify-content controls how space is distributed between and around flex items along the main axis.', 'justify-content asosiy o''q bo''ylab elementlarning joylashuvi va ular orasidagi bo''sh joy taqsimotini boshqaradi.', 'Свойство justify-content отвечает за выравнивание и распределение пространства вдоль главной оси flex-контейнера.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-flexbox-q4', 'css-flexbox', 4, 'basic', 1, 'Which property aligns flex items along the CROSS axis (perpendicular to the main axis)?', 'Qaysi xossa flex-elementlarni KESISHUVCHI (ko''ndalang / cross) o''q bo''ylab tekislaydi?', 'Какое свойство выравнивает flex-элементы вдоль ПОПЕРЕЧНОЙ оси (cross axis)?', 'align-items aligns flex items along the cross axis of the current flex line.', 'align-items joriy qatordagi flex-elementlarni ko''ndalang o''q (cross axis) bo''yicha tekislaydi.', 'Свойство align-items выравнивает элементы внутри строки вдоль поперечной оси контейнера.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-flexbox-q5', 'css-flexbox', 5, 'intermediate', 1.5, 'By default, flex items try to fit onto one line. Which property allows them to wrap onto multiple lines?', 'Odatiy holatda flex-elementlar bitta qatorga sig''ishga harakat qiladi. Ularni bir nechta qatorga ko''chishiga (tushishiga) qaysi xossa ruxsat beradi?', 'По умолчанию flex-элементы пытаются уместиться в одну строку. Какое свойство разрешает им переноситься на новые строки?', 'flex-wrap: wrap allows flex items to break into multiple lines when there is not enough space on a single line.', 'flex-wrap: wrap bitta qatorda joy yetmaganda flex-elementlarning keyingi qatorga tushishiga ruxsat beradi.', 'Свойство flex-wrap: wrap позволяет элементам переноситься на следующую строку, если они не помещаются в контейнере.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-flexbox-q6', 'css-flexbox', 6, 'intermediate', 1.5, 'Which property defines how much a flex item should grow relative to other items when extra free space is available?', 'Konteynerda bo''sh joy bo''lganda flex-element boshqalariga nisbatan qanchalik kengayishi (o''sishi) kerakligini qaysi xossa belgilaydi?', 'Какое свойство определяет, насколько flex-элемент может увеличиваться относительно других при наличии свободного места?', 'flex-grow specifies the flex grow factor, which determines how much of the remaining free space in the flex container is assigned to the item.', 'flex-grow konteynerdagi ortiqcha bo''sh joyning qancha ulushi ushbu elementga berilishini (o''sish koeffitsiyentini) belgilaydi.', 'Свойство flex-grow задаёт коэффициент увеличения элемента за счёт свободного пространства во flex-контейнере.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-flexbox-q7', 'css-flexbox', 7, 'intermediate', 1.5, 'Which property can be set on a single flex item to override the container''s "align-items" value just for that item?', 'Konteynerning "align-items" qoidasini faqat bitta flex-elementning o''zi uchun o''zgartirishda qaysi xossadan foydalaniladi?', 'Какое свойство задаётся отдельному flex-элементу, чтобы переопределить для него общее выравнивание "align-items"?', 'align-self overrides a flex container''s align-items value for a specific individual flex item.', 'align-self alohida olingan bitta flex-elementni ko''ndalang o''q bo''yicha mustaqil tekislash imkonini beradi.', 'Свойство align-self позволяет переопределить выравнивание по поперечной оси (align-items) для конкретного flex-элемента.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-flexbox-q8', 'css-flexbox', 8, 'intermediate', 1.5, 'Which property cleanly adds fixed spacing ONLY between flex items (rows and columns) without adding outer margins on the edges?', 'Chekkalarga ortiqcha margin qo''shmasdan, FAQAT flex-elementlar orasiga aniq masofa (bo''shliq) qo''shuvchi xossa qaysi?', 'Какое свойство задаёт фиксированные отступы ТОЛЬКО между flex-элементами, не добавляя лишних отступов по внешним краям?', 'The "gap" property (or row-gap / column-gap) explicitly controls the gutter size between flex or grid items.', '"gap" xossasi (yoki row-gap / column-gap) flex va grid elementlari orasidagi masofani chekkalarga ta''sir qilmasdan boshqaradi.', 'Свойство "gap" создаёт отступы непосредственно между элементами в строках и столбцах во Flexbox и Grid.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-flexbox-q9', 'css-flexbox', 9, 'advanced', 2.2, 'In the shorthand "flex: 1;", what do the three underlying properties (flex-grow, flex-shrink, flex-basis) expand to?', '"flex: 1;" qisqa yozuvi uchta asosiy xossaga (flex-grow, flex-shrink, flex-basis) qanday yoyiladi?', 'Во что разворачиваются три составляющих свойства (flex-grow, flex-shrink, flex-basis) при краткой записи "flex: 1;"?', 'Setting flex: 1 is shorthand for flex: 1 1 0%, allowing the item to grow and shrink equally from a zero base size.', 'flex: 1 qisqartmasi flex: 1 1 0% ga teng bo''lib, elementga 0% bazaviy o''lchamdan boshlab teng o''sish va qisqarish imkonini beradi.', 'Запись flex: 1 эквивалентна flex: 1 1 0%, что позволяет элементам равномерно делить пространство независимо от исходного размера контента.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-flexbox-q10', 'css-flexbox', 10, 'advanced', 2.2, 'What is the difference between "justify-content: space-between" and "justify-content: space-evenly"?', '"justify-content: space-between" va "justify-content: space-evenly" o''rtasida qanday farq bor?', 'В чём отличие между "justify-content: space-between" и "justify-content: space-evenly"?', 'space-between places zero space at the container edges, while space-evenly distributes identical spacing between items and at both ends.', 'space-between chekkalarda bo''sh joy qoldirmaydi, space-evenly esa elementlar orasida ham, chekkalarda ham bir xil masofa hosil qiladi.', 'При space-between крайние элементы прижаты к краям контейнера, а при space-evenly расстояния между элементами и до краёв контейнера полностью равны.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-grid-q1', 'css-grid', 1, 'basic', 1, 'Which CSS declaration turns an element into a two-dimensional Grid container?', 'Qaysi CSS qoidasi elementni ikki o''lchovli Grid konteyneriga aylantiradi?', 'Какое CSS-свойство превращает элемент в двумерный Grid-контейнер?', 'display: grid (or inline-grid) establishes a grid formatting context for two-dimensional row and column layouts.', 'display: grid (yoki inline-grid) qatorlar va ustunlardan iborat ikki o''lchovli maket yaratish uchun grid-konteyner hosil qiladi.', 'Свойство display: grid (или inline-grid) создаёт блочный или строчный грид-контейнер для двумерной раскладки.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-grid-q2', 'css-grid', 2, 'basic', 1, 'Which property defines the number and widths of columns in a CSS Grid layout?', 'CSS Grid maketida ustunlarning soni va kengligini qaysi xossa belgilaydi?', 'Какое свойство задаёт количество и ширину столбцов в CSS Grid?', 'grid-template-columns specifies the track list and sizing functions for the columns of a grid container.', 'grid-template-columns grid konteyneridagi ustunlarning soni va har birining o''lchamini belgilaydi.', 'Свойство grid-template-columns определяет структуру и размеры столбцов грид-сетки.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-grid-q3', 'css-grid', 3, 'basic', 1, 'What does the "fr" unit represent in CSS Grid?', 'CSS Grid-da "fr" o''lchov birligi nimani bildiradi?', 'Что обозначает единица измерения "fr" в CSS Grid?', 'The "fr" (fractional) unit distributes a proportion of the remaining available space in the grid container.', '"fr" (ulush/fraction) birligi grid konteyneridagi bo''sh joyni ustunlar yoki qatorlar o''rtasida proporsional taqsimlaydi.', 'Единица "fr" (fraction) представляет собой долю свободного пространства в грид-контейнере.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-grid-q4', 'css-grid', 4, 'basic', 1, 'How can you write "grid-template-columns: 1fr 1fr 1fr 1fr;" more concisely using a CSS Grid function?', '"grid-template-columns: 1fr 1fr 1fr 1fr;" qoidasini CSS Grid funksiyasi yordamida qanday qilib qisqaroq yozish mumkin?', 'Как можно записать "grid-template-columns: 1fr 1fr 1fr 1fr;" короче с помощью функции CSS Grid?', 'The repeat(count, track) function repeats a track definition a specified number of times.', 'repeat(soni, o''lcham) funksiyasi ustun yoki qator o''lchamlarini ko''rsatilgan marta takrorlash uchun ishlatiladi.', 'Функция repeat(количество, размер) позволяет компактно задать повторяющиеся столбцы или строки сетки.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-grid-q5', 'css-grid', 5, 'intermediate', 1.5, 'What does "grid-column: 1 / 3;" on a grid item do?', 'Grid elementiga berilgan "grid-column: 1 / 3;" xossasi nima vazifani bajaradi?', 'Что делает свойство "grid-column: 1 / 3;", заданное для грид-элемента?', 'grid-column: 1 / 3 sets grid-column-start to line 1 and grid-column-end to line 3, spanning across two column tracks.', 'grid-column: 1 / 3 elementni 1-ustun chizig''idan 3-chiziqqacha, ya''ni 2 ta ustun kengligida joylashtiradi.', 'Запись grid-column: 1 / 3 указывает начальную линию 1 и конечную линию 3, благодаря чему элемент занимает два столбца.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-grid-q6', 'css-grid', 6, 'intermediate', 1.5, 'What does the "minmax(200px, 1fr)" function do in a grid track definition?', 'Grid o''lchamlarida "minmax(200px, 1fr)" funksiyasi qanday ishlaydi?', 'Что делает функция "minmax(200px, 1fr)" при описании дорожки грида?', 'minmax(min, max) defines a size range so the track never shrinks below min and can expand up to max.', 'minmax(min, max) ustun yoki qatorning eng kichik (min) va eng katta (max) o''lcham chegarasini belgilaydi.', 'Функция minmax(min, max) задаёт минимальный и максимальный предел размера для столбца или строки грида.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-grid-q7', 'css-grid', 7, 'intermediate', 1.5, 'Which properties are used together to create named visual layout regions in CSS Grid?', 'CSS Grid-da nomlangan vizual maket sohalarini yaratish uchun qaysi xossalar birgalikda ishlatiladi?', 'Какие свойства используются вместе для создания именованных областей макета в CSS Grid?', 'grid-template-areas defines a visual ASCII-like map of named grid cells, and grid-area assigns items to those named regions.', 'grid-template-areas konteynerda nomlangan hududlar xaritasini tuzadi, grid-area esa elementlarni o''sha hududlarga biriktiradi.', 'Свойство grid-template-areas описывает схему областей в контейнере, а grid-area привязывает дочерние элементы к этим именам.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-grid-q8', 'css-grid', 8, 'intermediate', 1.5, 'Which shorthand property centers grid items both vertically and horizontally inside their grid cells with "center"?', '"center" qiymati berilganda grid elementlarini o''z kataklari ichida ham vertikal, ham gorizontal markazlashtiradigan qisqa xossa qaysi?', 'Какое сокращённое свойство со значением "center" выравнивает элементы по центру ячеек одновременно по вертикали и горизонтали?', 'place-items is the shorthand for align-items and justify-items; setting place-items: center centers items along both axes.', 'place-items — align-items va justify-items uchun qisqartma bo''lib, place-items: center elementlarni ikkala o''q bo''yicha markazga qo''yadi.', 'Свойство place-items объединяет align-items и justify-items, поэтому place-items: center центрирует содержимое ячеек по обеим осям.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-grid-q9', 'css-grid', 9, 'advanced', 2.2, 'In "repeat(auto-fit, minmax(200px, 1fr))" vs "repeat(auto-fill, minmax(200px, 1fr))", how do they differ when there are fewer items than could fit in a row?', 'Qatorga sig''ishi mumkin bo''lganidan kamroq element bo''lganda, "auto-fit" va "auto-fill" o''rtasida qanday farq yuzaga keladi?', 'В чём разница между "auto-fit" и "auto-fill" в выражении "repeat(..., minmax(200px, 1fr))", когда элементов в строке меньше, чем может поместиться?', 'auto-fit collapses any empty repeated tracks to 0px so existing items stretch to fill the container, whereas auto-fill preserves empty column tracks.', 'auto-fit bo''sh qolgan ustunlarni 0px gacha yopib, bor elementlarni butun kenglik bo''ylab yoyadi; auto-fill esa bo''sh kataklar joyini saqlaydi.', 'При малом числе элементов auto-fit схлопывает пустые колонки и растягивает карточки на всю ширину, а auto-fill оставляет пустые ячейки в строке.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-grid-q10', 'css-grid', 10, 'advanced', 2.2, 'What does "grid-template-columns: subgrid;" allow a nested grid item to do?', '"grid-template-columns: subgrid;" xossasi ichki (nested) grid elementiga qanday imkoniyat beradi?', 'Что позволяет сделать значение "grid-template-columns: subgrid;" у вложенного грид-элемента?', 'subgrid allows a grid item that is also a grid container to adopt the track definition of its parent grid along that axis.', 'subgrid o''zi ham grid-konteyner bo''lgan elementga ota gridning ustun yoki qator chiziqlarini to''g''ridan-to''g''ri meros qilib olish imkonini beradi.', 'Значение subgrid позволяет вложенному грид-контейнеру использовать дорожки и линии родительской сетки для сквозного выравнивания контента.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-positioning-q1', 'css-positioning', 1, 'basic', 1, 'What is the default "position" value of all HTML elements?', 'Barcha HTML elementlarining standart (default) "position" qiymati qanday bo''ladi?', 'Какое значение свойства "position" имеют все HTML-элементы по умолчанию?', 'By default, every element has position: static, meaning it follows normal document flow and ignores top, right, bottom, left, and z-index.', 'Odatiy holatda barcha elementlar position: static bo''lib, hujjatning tabiiy oqimida joylashadi va top/left/z-index xossalariga bo''ysunmaydi.', 'По умолчанию все элементы имеют position: static, располагаются в обычном потоке, а свойства top, left, right, bottom и z-index на них не действуют.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-positioning-q2', 'css-positioning', 2, 'basic', 1, 'What happens when you apply "position: relative; top: 20px;" to an element?', 'Elementga "position: relative; top: 20px;" berilsa nima sodir bo''ladi?', 'Что произойдёт, если задать элементу "position: relative; top: 20px;"?', 'position: relative offsets the element relative to its normal position without affecting the layout position of surrounding elements.', 'position: relative elementni o''zining asl joyiga nisbatan siljitadi va atrofdagi boshqa elementlarning joylashuvini buzmaydi.', 'При position: relative элемент смещается относительно своего обычного положения, а зарезервированное за ним место в потоке остаётся нетронутым.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-positioning-q3', 'css-positioning', 3, 'basic', 1, 'Which position value pins an element relative to the browser viewport so it stays in the same place even when the page is scrolled?', 'Sahifa aylantirilganda (scroll qilinganda) ham elementni brauzer oynasiga (viewport) nisbatan bir joyda qotirib qo''yadigan position qiymati qaysi?', 'Какое значение position фиксирует элемент относительно окна браузера (viewport) так, что он остаётся на месте при прокрутке страницы?', 'position: fixed removes the element from normal flow and positions it relative to the viewport so it does not move on scroll.', 'position: fixed elementni umumiy oqimdan chiqaradi va brauzer oynasiga bog''lab qo''yadi, natijada u scroll paytida qimirlamaydi.', 'Значение position: fixed извлекает элемент из потока и привязывает его к окну браузера, оставляя неподвижным при скролле.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-positioning-q4', 'css-positioning', 4, 'basic', 1, 'Which CSS property controls the vertical stacking order (which element appears in front or behind) of positioned elements?', 'Pozitsiyalangan elementlarning ustma-ust joylashish tartibini (qaysi biri oldinda yoki orqada ko''rinishini) qaysi CSS xossasi boshqaradi?', 'Какое CSS-свойство управляет порядком наложения позиционированных элементов друг на друга по оси Z (какой элемент спереди, а какой сзади)?', 'The z-index property specifies the stack level of a positioned (or flex/grid) element along the z-axis.', 'z-index xossasi pozitsiyalangan (yoki flex/grid) elementlarning Z o''qi bo''yicha qatlam tartibini belgilaydi.', 'Свойство z-index определяет порядок наложения позиционированных элементов (и элементов флекс/грид) по вертикальной оси Z.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-positioning-q5', 'css-positioning', 5, 'intermediate', 1.5, 'What is an element with "position: absolute" positioned relative to?', '"position: absolute" berilgan element nimaga nisbatan joylashadi?', 'Относительно чего позиционируется элемент со свойством "position: absolute"?', 'An absolutely positioned element is positioned relative to its closest ancestor with a position other than static (commonly position: relative).', 'Absolute element position qiymati "static" bo''lmagan (odatda position: relative berilgan) eng yaqin ota elementiga nisbatan joylashadi.', 'Абсолютно позиционированный элемент отсчитывает координаты от ближайшего предка с position, отличным от static (чаще всего relative).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-positioning-q6', 'css-positioning', 6, 'intermediate', 1.5, 'How does "position: sticky" behave?', '"position: sticky" qanday ishlaydi?', 'Как работает значение "position: sticky"?', 'A sticky element toggles between relative and fixed positioning depending on the user''s scroll position, constrained within its scrolling ancestor/parent.', 'Sticky element scroll ma''lum nuqtaga (masalan, top: 0) yetguncha oddiy oqimda harakatlanadi va ota bloki tugaguncha ekranga yopishib turadi.', 'Элемент со свойством sticky остаётся в потоке как relative, пока прокрутка не достигнет порога (например, top: 0), после чего удерживается на месте внутри родителя.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-positioning-q7', 'css-positioning', 7, 'intermediate', 1.5, 'Which CSS shorthand property sets "top", "right", "bottom", and "left" all at once?', '"top", "right", "bottom" va "left" xossalarining barchasini bittada belgilovchi qisqa CSS xossasi qaysi?', 'Какое сокращённое CSS-свойство задаёт значения "top", "right", "bottom" и "left" одновременно?', 'The "inset" property is a shorthand that corresponds to the top, right, bottom, and/or left properties (e.g., inset: 0; stretches an absolute element to all 4 edges).', '"inset" xossasi top, right, bottom va left uchun qisqartma hisoblanadi (masalan, inset: 0; barcha to''rt tomonni 0 qiladi).', 'Свойство "inset" — это краткая запись для top, right, bottom и left (например, inset: 0 растягивает абсолютный элемент на весь блок).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-positioning-q8', 'css-positioning', 8, 'intermediate', 1.5, 'Why might "z-index: 999;" have NO effect on a standard <div> element?', 'Nima uchun oddiy <div> elementiga berilgan "z-index: 999;" hech qanday ta''sir ko''rsatmasligi mumkin?', 'Почему свойство "z-index: 999;" может НЕ работать на обычном элементе <div>?', 'z-index has no effect on statically positioned elements unless they are direct children of a flex or grid container.', 'position: static bo''lgan oddiy elementlarda (agar ular flex yoki grid farzandi bo''lmasa) z-index ishlamaydi.', 'Свойство z-index игнорируется у элементов с position: static (за исключением непосредственных детей flex- и grid-контейнеров).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-positioning-q9', 'css-positioning', 9, 'advanced', 2.2, 'How do you perfectly center an element with "position: absolute; top: 50%; left: 50%;" when its width and height are unknown?', 'Kengligi va balandligi noma''lum bo''lgan "position: absolute; top: 50%; left: 50%;" elementni qanday qilib aniq markazga keltirish mumkin?', 'Как идеально отцентрировать элемент со свойствами "position: absolute; top: 50%; left: 50%;", если его ширина и высота заранее неизвестны?', 'top: 50% and left: 50% align the element''s top-left corner to the center, and transform: translate(-50%, -50%) shifts it back by half of its own width and height.', 'top: 50% va left: 50% elementning yuqori-chap burchagini markazga qo''yadi, transform: translate(-50%, -50%) esa uni o''z o''lchamining yarmiga orqaga surib, qoq markazga keltiradi.', 'Свойства top: 50% и left: 50% помещают в центр верхний левый угол элемента, а transform: translate(-50%, -50%) сдвигает его назад ровно на половину собственных размеров.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-positioning-q10', 'css-positioning', 10, 'advanced', 2.2, 'Why does "position: sticky; top: 0;" fail to stick when any ancestor element has "overflow: hidden" or "overflow: auto"?', 'Ota (ajdod) elementlardan birida "overflow: hidden" yoki "overflow: auto" bo''lsa, nima uchun "position: sticky; top: 0;" oynaga nisbatan ishlamay qoladi?', 'Почему "position: sticky; top: 0;" перестаёт прилипать при прокрутке страницы, если у одного из родителей задано "overflow: hidden" или "overflow: auto"?', 'A sticky element sticks to its nearest scrolling ancestor; setting overflow to hidden/auto/scroll on an ancestor makes that ancestor the scroll container instead of the viewport.', 'Sticky element o''zining eng yaqin scroll konteyneriga bog''lanadi; ota elementdagi overflow: hidden esa oynaning scrollini to''sib qo''yadi.', 'Элемент со свойством sticky привязывается к ближайшему предку с контекстом прокрутки, поэтому overflow: hidden на родителе блокирует отслеживание скролла окна.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-animations-q1', 'css-animations', 1, 'basic', 1, 'Which CSS property smoothly animates changes to CSS property values over a specified duration (e.g., on :hover)?', 'CSS xossalari qiymatining o''zgarishini (masalan, :hover bo''lganda) ma''lum vaqt davomida silliq o''tadigan qiluvchi xossa qaysi?', 'Какое CSS-свойство обеспечивает плавный переход при изменении значений свойств (например, при наведении :hover)?', 'The "transition" property defines a smooth animated transition between two states of an element.', '"transition" xossasi elementning ikki holati o''rtasida silliq animatsiyali o''tishni ta''minlaydi.', 'Свойство "transition" задаёт плавный анимированный переход между начальным и конечным состояниями элемента.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-animations-q2', 'css-animations', 2, 'basic', 1, 'Which CSS at-rule is used to define the intermediate steps and stages of a multi-step CSS animation?', 'Ko''p bosqichli CSS animatsiyasining oraliq qadamlarini (kadrlarini) e''lon qilish uchun qaysi @-qoida ishlatiladi?', 'Какая CSS-директива (@-правило) используется для описания ключевых кадров многошаговой анимации?', 'The @keyframes at-rule controls the intermediate steps in a CSS animation sequence using percentages (0% to 100%) or "from" and "to".', '@keyframes qoidasi 0% dan 100% gacha (yoki "from" va "to") bo''lgan animatsiya kadrlaridagi holatlarni belgilab beradi.', 'Директива @keyframes определяет ключевые кадры анимации с помощью процентов (от 0% до 100%) или ключевых слов from и to.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-animations-q3', 'css-animations', 3, 'basic', 1, 'Which CSS property lets you rotate, scale, skew, or translate an element in 2D or 3D space?', 'Qaysi CSS xossasi elementni 2D yoki 3D fazoda aylantirish (rotate), kattalashtirish (scale), og''dirish (skew) yoki surish (translate) imkonini beradi?', 'Какое CSS-свойство позволяет поворачивать, масштабировать, наклонять или сдвигать элемент в 2D- или 3D-пространстве?', 'The "transform" property modifies the coordinate space of the CSS visual formatting model using functions like translate(), rotate(), and scale().', '"transform" xossasi translate(), rotate() va scale() kabi funksiyalar yordamida elementning shaklini yoki joylashuvini o''zgartiradi.', 'Свойство "transform" применяет к элементу геометрические преобразования: сдвиг (translate), поворот (rotate), масштабирование (scale) и наклон (skew).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-animations-q4', 'css-animations', 4, 'basic', 1, 'How do you make a CSS @keyframes animation repeat endlessly?', 'CSS @keyframes animatsiyasini to''xtovsiz (cheksiz) takrorlanadigan qilish uchun qaysi xossa va qiymat beriladi?', 'Как сделать так, чтобы CSS-анимация повторялась бесконечно?', 'Setting animation-iteration-count: infinite causes the animation cycle to repeat forever.', 'animation-iteration-count: infinite xossasi animatsiya siklining cheksiz marta qaytarilishini ta''minlaydi.', 'Свойство animation-iteration-count со значением infinite запускает бесконечное повторение анимации.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-animations-q5', 'css-animations', 5, 'intermediate', 1.5, 'What does "animation-fill-mode: forwards;" do when an animation finishes running?', 'Animatsiya tugagandan so''ng "animation-fill-mode: forwards;" xossasi nima qiladi?', 'Что делает свойство "animation-fill-mode: forwards;" после завершения CSS-анимации?', 'animation-fill-mode: forwards instructs the element to keep the computed values defined by the last keyframe encountered during execution.', 'animation-fill-mode: forwards animatsiya yakunlangach element oxirgi kadrda (100%) erishgan ko''rinishida qolishini ta''minlaydi.', 'Значение forwards заставляет элемент остаться в конечном состоянии последнего ключевого кадра после окончания анимации.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-animations-q6', 'css-animations', 6, 'intermediate', 1.5, 'What does a timing function like "ease-in-out" or "cubic-bezier(...)" control in an animation or transition?', 'Animatsiya yoki o''tishda "ease-in-out" yoki "cubic-bezier(...)" kabi vaqt funksiyalari (timing-function) nimani boshqaradi?', 'За что отвечает функция времени (timing-function), такая как "ease-in-out" или "cubic-bezier(...)", в анимациях и переходах?', 'The timing-function establishes the acceleration curve so that the speed of the transition can vary over its duration.', 'Timing-function animatsiya qaysi qismda sekin va qaysi qismda tez harakatlanishini (tezlanish egri chizig''ini) belgilaydi.', 'Функция времени определяет кривую ускорения, регулируя, как меняется скорость анимации от начала к концу.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-animations-q7', 'css-animations', 7, 'intermediate', 1.5, 'Which CSS property changes the pivot point around which a "transform: rotate(45deg)" rotation occurs?', '"transform: rotate(45deg)" aylanishi sodir bo''ladigan tayanch nuqtani (markazni) qaysi CSS xossasi o''zgartiradi?', 'Какое CSS-свойство изменяет точку опоры (центр вращения), вокруг которой выполняется "transform: rotate(45deg)"?', 'transform-origin (defaulting to 50% 50% / center) sets the point around which a transformation such as rotation or scaling is applied.', 'transform-origin (standart qiymati 50% 50%) aylanish yoki kattalashish amalga oshadigan tayanch nuqtani belgilaydi.', 'Свойство transform-origin (по умолчанию center) задаёт координаты точки, относительно которой применяются трансформации.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-animations-q8', 'css-animations', 8, 'intermediate', 1.5, 'What does "animation-direction: alternate;" do in a multi-iteration animation?', 'Ko''p marta takrorlanadigan animatsiyada "animation-direction: alternate;" xossasi qanday ishlaydi?', 'Как работает свойство "animation-direction: alternate;" при многократном повторении анимации?', 'animation-direction: alternate reverses the animation direction on every other cycle for a smooth back-and-forth effect.', 'animation-direction: alternate animatsiyani bir marta boshidan oxirigacha, keyingi safar esa oxiridan boshiga qarab silliq qaytaradi.', 'Значение alternate заставляет анимацию проигрываться от начала к концу, а затем плавно возвращаться от конца к началу на каждом чётном витке.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-animations-q9', 'css-animations', 9, 'advanced', 2.2, 'Which two CSS properties are best to animate for smooth 60fps GPU-composited performance without triggering expensive layout reflows or repaints?', 'Qimmat layout qayta hisoblanishiga (reflow/repaint) sabab bo''lmasdan, GPU yordamida silliq 60fps ishlashi uchun qaysi ikkita CSS xossasini animatsiya qilish eng ma''qul?', 'Какие два CSS-свойства лучше всего анимировать для плавной работы в 60 FPS на GPU без вызова тяжёлых перерасчётов макета (reflow) и перерисовки (repaint)?', 'Animating transform and opacity can be handled directly by the browser''s compositor thread on the GPU without recalculating layout or painting.', 'transform va opacity animatsiyalari maketni qayta hisoblamasdan, to''g''ridan-to''g''ri GPU kompozitor oqimida juda tez va silliq bajariladi.', 'Анимация свойств transform и opacity обрабатывается композитором на GPU, не вызывая перерасчёта геометрии (Layout) и перерисовки (Paint).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-animations-q10', 'css-animations', 10, 'advanced', 2.2, 'Which media query should you use to respect users who have requested minimal motion or disabled animations in their operating system settings?', 'Operatsion tizim sozlamalarida animatsiyalarni kamaytirishni so''ragan foydalanuvchilar uchun qaysi media so''rovdan foydalanish kerak?', 'Какой медиа-запрос следует использовать, чтобы отключить или упростить анимации для пользователей, включивших уменьшение движения в настройках ОС?', '@media (prefers-reduced-motion: reduce) detects if the user has requested the system to minimize non-essential motion for accessibility.', '@media (prefers-reduced-motion: reduce) foydalanuvchi tizimda ortiqcha harakat va animatsiyalarni kamaytirish rejimini yoqqanligini aniqlaydi.', 'Медиа-запрос @media (prefers-reduced-motion: reduce) позволяет определить, что пользователь предпочёл минимизировать анимации в целях доступности.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-responsive-q1', 'css-responsive', 1, 'basic', 1, 'Which <meta> tag is essential in the HTML <head> for responsive design to work properly on mobile devices?', 'Mobil qurilmalarda moslashuvchan (responsive) dizayn to''g''ri ishlashi uchun HTML <head> qismida qaysi <meta> teg bo''lishi shart?', 'Какой тег <meta> необходим внутри <head>, чтобы адаптивный дизайн корректно отображался на мобильных устройствах?', 'The viewport meta tag instructs mobile browsers to match the layout viewport width to the device''s actual screen width.', 'Viewport meta tegi mobil brauzerlarga sahifa kengligini qurilmaning haqiqiy ekran kengligiga moslashtirishni buyuradi.', 'Мета-тег viewport указывает мобильному браузеру установить ширину области просмотра равной реальной ширине экрана устройства.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-responsive-q2', 'css-responsive', 2, 'basic', 1, 'Which CSS at-rule applies styles conditionally based on screen width or device characteristics?', 'Ekran kengligi yoki qurilma xususiyatlariga qarab shartli ravishda uslublarni qo''llaydigan CSS qoidasi qaysi?', 'Какая CSS-директива позволяет применять стили в зависимости от ширины экрана или характеристик устройства?', 'The @media at-rule is used in media queries to apply styles only when specific conditions (like max-width or min-width) are met.', '@media qoidasi ekran o''lchami kabi ma''lum shartlar (masalan, max-width yoki min-width) bajarilgandagina CSS uslublarini ishga tushiradi.', 'Директива @media используется для создания медиа-запросов, активирующих стили при выполнении заданных условий (например, ширины экрана).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-responsive-q3', 'css-responsive', 3, 'basic', 1, 'What does the CSS unit "100vw" represent?', 'CSS-da "100vw" o''lchov birligi nimani bildiradi?', 'Что означает единица измерения "100vw" в CSS?', '1vw equals 1% of the viewport''s width, so 100vw spans the full width of the browser viewport.', '1vw ko''rish oynasi (viewport) kengligining 1 foiziga teng, demak 100vw brauzer oynasining to''liq kengligini bildiradi.', 'Единица 1vw равна 1% ширины окна просмотра, поэтому 100vw соответствует полной ширине viewport.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-responsive-q4', 'css-responsive', 4, 'basic', 1, 'Which classic CSS rule ensures images scale down proportionally on smaller screens without overflowing their container?', 'Kichik ekranlarda rasmlar o''z konteyneridan chiqib ketmasdan, proporsional ravishda kichrayishini ta''minlaydigan klassik CSS qoidasi qaysi?', 'Какое классическое CSS-правило позволяет изображениям пропорционально уменьшаться на узких экранах, не выходя за пределы контейнера?', 'max-width: 100%; height: auto; prevents an image from exceeding its container''s width while maintaining its original aspect ratio.', 'max-width: 100%; height: auto; rasmga o''z konteyneridan kattalashib ketmaslikni va asl proporsiyasini saqlagan holda moslashishni buyuradi.', 'Правило max-width: 100%; height: auto; не даёт картинке стать шире родительского блока и сохраняет её исходные пропорции.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-responsive-q5', 'css-responsive', 5, 'intermediate', 1.5, 'What is the difference between the "em" and "rem" units in CSS?', 'CSS-da "em" va "rem" o''lchov birliklari o''rtasida qanday farq bor?', 'В чём разница между единицами измерения "em" и "rem" в CSS?', 'rem (root em) scales consistently against the root <html> element''s font-size, avoiding the compounding multiplication issue of nested em units.', 'rem (root em) doimo <html> elementining shrift o''lchamiga asoslanadi, em esa ichma-ich elementlarda ko''payib ketishi mumkin.', 'Единица rem (root em) всегда отсчитывается от font-size тега <html>, тогда как em зависит от шрифта родителя и может накапливаться при вложенности.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-responsive-q6', 'css-responsive', 6, 'intermediate', 1.5, 'In a "Mobile-First" responsive CSS approach, how are base styles and media queries structured?', '"Mobile-First" (avval mobil) moslashuvchan CSS yondashuvida bazaviy uslublar va media so''rovlar qanday tuziladi?', 'Как строятся базовые стили и медиа-запросы при подходе «Mobile-First» (сначала мобильные)?', 'Mobile-first CSS writes default styles for small viewports and uses min-width media queries to layer on complexity as screen space increases.', 'Mobile-first yondashuvida asosiy kod kichik ekranlar uchun yozilib, ekran kattalashgani sari min-width media so''rovlari bilan boyitiladi.', 'При Mobile-First стили по умолчанию ориентированы на мобильные экраны, а адаптация под широкие экраны добавляется через @media (min-width: ...).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-responsive-q7', 'css-responsive', 7, 'intermediate', 1.5, 'What does the CSS function "clamp(1rem, 2.5vw, 2rem)" do for fluid typography?', 'Moslashuvchan tipografikada "clamp(1rem, 2.5vw, 2rem)" CSS funksiyasi qanday vazifani bajaradi?', 'Что делает CSS-функция "clamp(1rem, 2.5vw, 2rem)" при создании отзывчивой типографики?', 'clamp(min, preferred, max) locks a fluid value between a defined minimum bound and maximum bound.', 'clamp(min, ideal, max) o''zgaruvchan qiymatni eng kichik (min) va eng katta (max) chegara orasida ushlab turadi.', 'Функция clamp(мин, предпочтительное, макс) позволяет значению плавно изменяться в пределах заданного минимума и максимума.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-responsive-q8', 'css-responsive', 8, 'intermediate', 1.5, 'Which CSS property forces an element box to maintain a proportional width-to-height ratio (such as 16 / 9 for a video wrapper)?', 'Qaysi CSS xossasi elementga kenglik va balandlikning aniq proporsional nisbatini (masalan, video bloki uchun 16 / 9) saqlab turishni buyuradi?', 'Какое CSS-свойство задаёт элементу фиксированное соотношение сторон (например, 16 / 9 для карточки или видео)?', 'The "aspect-ratio" property (e.g., aspect-ratio: 16 / 9;) sets a preferred width-to-height ratio for an element''s box.', '"aspect-ratio" xossasi (masalan, aspect-ratio: 16 / 9;) element qutisi uchun kenglikning balandlikka bo''lgan nisbatini avtomatik saqlaydi.', 'Свойство "aspect-ratio" (например, aspect-ratio: 16 / 9;) автоматически поддерживает заданное соотношение ширины и высоты элемента.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-responsive-q9', 'css-responsive', 9, 'advanced', 2.2, 'How do CSS Container Queries (@container) differ from traditional Media Queries (@media)?', 'CSS Konteyner so''rovlari (@container) an''anaviy Media so''rovlardan (@media) nimasi bilan farq qiladi?', 'Чем контейнерные запросы (@container) отличаются от традиционных медиа-запросов (@media)?', 'While @media queries the global viewport dimensions, @container lets a component adapt its styles based on the size of its containing parent (with container-type: inline-size).', '@media butun ekran (viewport) o''lchamini tekshirsa, @container komponentga o''zining ota konteyneri o''lchamiga qarab moslashish imkonini beradi.', 'В отличие от @media, проверяющего размер всего окна браузера, @container позволяет стилизовать компонент в зависимости от ширины его родительского контейнера.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('css-responsive-q10', 'css-responsive', 10, 'advanced', 2.2, 'What problem does the dynamic viewport height unit "100dvh" solve on mobile browsers compared to "100vh"?', 'Mobil brauzerlarda "100vh" bilan solishtirganda dinamik "100dvh" birligi qanday muammoni hal qiladi?', 'Какую проблему в мобильных браузерах решает динамическая единица высоты "100dvh" по сравнению с классической "100vh"?', '100dvh (dynamic viewport height) accounts for the dynamic showing and hiding of mobile browser UI bars, unlike 100vh which often overflows under the bottom toolbar.', '100dvh (dynamic viewport height) mobil brauzerlarning yuqori/pastki panellari yashiringanda yoki chiqqanda balandlikni avtomatik qayta hisoblaydi.', 'Единица 100dvh (dynamic viewport height) учитывает выдвижные панели интерфейса мобильного браузера, предотвращая перекрытие нижней части экрана.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-basics-q1', 'react-basics', 1, 'basic', 1, 'What is React primarily used for?', 'React asosan nima uchun ishlatiladi?', 'Для чего в основном используется React?', 'React is a JavaScript library developed for building fast and interactive user interfaces.', 'React — tezkor va interaktiv foydalanuvchi interfeyslarini yaratish uchun ishlab chiqilgan JavaScript kutubxonasi.', 'React — это JavaScript-библиотека, разработанная для создания быстрых и интерактивных пользовательских интерфейсов.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-basics-q2', 'react-basics', 2, 'basic', 1, 'Which company created and maintains React?', 'React qaysi kompaniya tomonidan yaratilgan va qo''llab-quvvatlanadi?', 'Какая компания создала и поддерживает React?', 'React was created by Jordan Walke at Meta (formerly Facebook) and open-sourced in 2013.', 'React Meta (sobiq Facebook) kompaniyasida Jordan Walke tomonidan yaratilgan va 2013-yilda ochiq kodli qilingan.', 'React был создан Джорданом Уоком в компании Meta (ранее Facebook) и открыт в 2013 году.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-basics-q3', 'react-basics', 3, 'basic', 1, 'What is the Virtual DOM in React?', 'React-da Virtual DOM nima?', 'Что такое Virtual DOM в React?', 'The Virtual DOM is an in-memory object tree that React uses to compute minimal DOM updates efficiently.', 'Virtual DOM — bu React minimal DOM yangilanishlarini samarali hisoblash uchun ishlatadigan xotiradagi obyektlar daraxtidir.', 'Virtual DOM — это дерево объектов в памяти, которое React использует для эффективного вычисления минимальных обновлений DOM.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-basics-q4', 'react-basics', 4, 'basic', 1, 'Which package is responsible for rendering React components into the browser DOM?', 'React komponentlarini brauzer DOM-iga render qilish uchun qaysi paket javobgar?', 'Какой пакет отвечает за рендеринг компонентов React в DOM браузера?', 'The react-dom package provides DOM-specific methods such as createRoot() to render React elements in the browser.', 'react-dom paketi React elementlarini brauzerda render qilish uchun createRoot() kabi DOM-ga xos metodlarni taqdim etadi.', 'Пакет react-dom предоставляет специфичные для DOM методы, такие как createRoot(), для рендеринга элементов React в браузере.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-basics-q5', 'react-basics', 5, 'intermediate', 1.5, 'How do you initialize a React 18 root for rendering an application?', 'Ilovani render qilish uchun React 18 root obyektini qanday ishga tushirasiz?', 'Как инициализировать корень React 18 для рендеринга приложения?', 'React 18 introduced the createRoot API in react-dom/client to enable concurrent rendering features.', 'React 18 parallel renderlash imkoniyatlarini yoqish uchun react-dom/client ichida createRoot API-ni taqdim etdi.', 'В React 18 был представлен API createRoot в react-dom/client для поддержки возможностей конкурентного рендеринга.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-basics-q6', 'react-basics', 6, 'intermediate', 1.5, 'What is the process called when React compares the new Virtual DOM with the previous one?', 'React yangi Virtual DOM-ni oldingisi bilan solishtiradigan jarayon nima deb ataladi?', 'Как называется процесс, когда React сравнивает новый Virtual DOM с предыдущим?', 'Reconciliation is the diffing algorithm React uses to determine which parts of the actual DOM need to be updated.', 'Reconciliation — bu haqiqiy DOM-ning qaysi qismlarini yangilash kerakligini aniqlash uchun React ishlatadigan farqlash algoritmi.', 'Согласование (Reconciliation) — это алгоритм сравнения, который React использует для определения того, какие части реального DOM нужно обновить.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-basics-q7', 'react-basics', 7, 'intermediate', 1.5, 'What does unidirectional data flow mean in React?', 'React-da bir yo''nalishli ma''lumotlar oqimi nimani anglatadi?', 'Что означает однонаправленный поток данных в React?', 'In React, parent components pass data down to child components through props, ensuring predictable state management.', 'React-da ona komponentlar ma''lumotlarni bola komponentlarga props orqali uzatadi, bu esa holatni oldindan aytib bo''ladigan tarzda boshqarishni ta''minlaydi.', 'В React родительские компоненты передают данные дочерним компонентам через props, что обеспечивает предсказуемое управление состоянием.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-basics-q8', 'react-basics', 8, 'intermediate', 1.5, 'What is the purpose of <React.StrictMode>?', '<React.StrictMode> ning maqsadi nima?', 'Какова цель <React.StrictMode>?', 'StrictMode is a development-only tool that performs extra checks and warnings for its descendants.', 'StrictMode faqat ishlab chiqishda qo''llaniladigan vosita bo''lib, o''zining ichki komponentlari uchun qo''shimcha tekshiruvlar va ogohlantirishlarni bajaradi.', 'StrictMode — это инструмент только для разработки, который выполняет дополнительные проверки и выводит предупреждения для своих потомков.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-basics-q9', 'react-basics', 9, 'advanced', 2.2, 'What is React Fiber?', 'React Fiber nima?', 'Что такое React Fiber?', 'React Fiber is the reimplementation of React''s core algorithm that allows rendering work to be split into chunks and prioritized.', 'React Fiber — bu React asosiy algoritmining qayta yozilgan talqini bo''lib, renderlash ishini bo''laklarga bo''lish va ustuvorlik berish imkonini beradi.', 'React Fiber — это переработанный основной алгоритм React, позволяющий разбивать работу по рендерингу на части и назначать им приоритеты.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-basics-q10', 'react-basics', 10, 'advanced', 2.2, 'What happens during hydration in a server-side rendered (SSR) React app?', 'Server tomonda render qilingan (SSR) React ilovasida gidratsiya (hydration) vaqtida nima sodir bo''ladi?', 'Что происходит во время гидратации (hydration) в React-приложении с серверным рендерингом (SSR)?', 'Hydration makes static server-rendered HTML interactive by attaching React''s event handlers without recreating the DOM nodes.', 'Gidratsiya DOM tugunlarini qayta yaratmasdan, React hodisa ishhlovchilarini biriktirish orqali serverdan kelgan statik HTML-ni interaktiv qiladi.', 'Гидратация делает статический серверный HTML интерактивным, привязывая обработчики событий React без пересоздания узлов DOM.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-components-q1', 'react-components', 1, 'basic', 1, 'How must React component names always start?', 'React komponentlari nomi doimo qanday harf bilan boshlanishi shart?', 'С чего всегда должны начинаться имена компонентов в React?', 'React treats components starting with lowercase letters as standard HTML tags and capitalized ones as custom React components.', 'React kichik harf bilan boshlangan elementlarni oddiy HTML teglari, katta harf bilan boshlanganlarini esa maxsus React komponentlari deb qabul qiladi.', 'React воспринимает элементы со строчной буквы как стандартные HTML-теги, а с заглавной — как пользовательские компоненты React.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-components-q2', 'react-components', 2, 'basic', 1, 'What does a functional component in React return to describe the UI?', 'React-da funksional komponent foydalanuvchi interfeysini tavsiflash uchun nima qaytaradi?', 'Что возвращает функциональный компонент в React для описания интерфейса?', 'A functional component is a JavaScript function that returns JSX elements (or null/primitives) to be rendered.', 'Funksional komponent — bu render qilinishi kerak bo''lgan JSX elementlarini (yoki null/primitivlarni) qaytaradigan JavaScript funksiyasidir.', 'Функциональный компонент — это функция JavaScript, которая возвращает элементы JSX (или null/примитивы) для рендеринга.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-components-q3', 'react-components', 3, 'basic', 1, 'Which keyword is used to make a component available for import in other files?', 'Komponentni boshqa fayllarda import qilish mumkin bo''lishi uchun qaysi kalit so''z ishlatiladi?', 'Какое ключевое слово используется, чтобы сделать компонент доступным для импорта в других файлах?', 'Standard ES modules use export (named or default) so components can be imported across files.', 'Standart ES modullari komponentlarni boshqa fayllarda import qilish uchun export (nomlangan yoki default) kalit so''zidan foydalanadi.', 'Стандартные ES-модули используют export (именованный или по умолчанию), чтобы компоненты можно было импортировать в другие файлы.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-components-q4', 'react-components', 4, 'basic', 1, 'In a React class component, which method is mandatory to define?', 'React klass komponentida qaysi metodni aniqlash majburiy?', 'Какой метод обязательно должен быть определен в классовом компоненте React?', 'Every React class component extending React.Component must implement a render() method that returns JSX.', 'React.Component-dan meros olgan har bir klass komponenti JSX qaytaradigan render() metodiga ega bo''lishi shart.', 'Каждый классовый компонент React, наследующий React.Component, обязан реализовать метод render(), возвращающий JSX.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-components-q5', 'react-components', 5, 'intermediate', 1.5, 'What does it mean for a React component to be "pure"?', 'React komponentining "pure" (sof) bo''lishi nimani anglatadi?', 'Что означает «чистота» (purity) компонента в React?', 'Pure components behave like mathematical functions during render: same inputs (props, state, context) produce the same JSX output.', 'Sof komponentlar render vaqtida matematik funksiyalar kabi ishlaydi: bir xil kiruvchi ma''lumotlar (props, state, context) bir xil JSX natijasini beradi.', 'Чистые компоненты ведут себя при рендеринге как математические функции: одинаковые входные данные (props, state, context) дают одинаковый JSX.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-components-q6', 'react-components', 6, 'intermediate', 1.5, 'What is Component Composition in React?', 'React-da komponentlar kompozitsiyasi (Component Composition) nima?', 'Что такое композиция компонентов (Component Composition) в React?', 'React favors composition over inheritance, allowing complex UIs to be assembled by nesting smaller components.', 'React meros olishdan ko''ra kompozitsiyani afzal ko''radi, bu esa kichikroq komponentlarni ichma-ich joylashtirish orqali murakkab interfeyslarni yig''ish imkonini beradi.', 'React предпочитает композицию наследованию, позволяя собирать сложные интерфейсы путем вложения небольших компонентов друг в друга.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-components-q7', 'react-components', 7, 'intermediate', 1.5, 'Why should you never define a component function inside another component function?', 'Nima uchun bitta komponent funksiyasini boshqa komponent funksiyasi ichida e''lon qilmaslik kerak?', 'Почему никогда не следует объявлять функцию компонента внутри другой функции компонента?', 'Defining a component inside another creates a new component type on every render, forcing React to unmount and remount it repeatedly.', 'Komponentni boshqasi ichida e''lon qilish har bir renderda yangi komponent turini yaratadi va React-ni uni qayta-qayta o''chirib-yoqishga (unmount/remount) majbur qiladi.', 'Объявление компонента внутри другого создает новый тип компонента при каждом рендере, заставляя React постоянно размонтировать и монтировать его заново.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-components-q8', 'react-components', 8, 'intermediate', 1.5, 'How many default exports can a single JavaScript module file have?', 'Bitta JavaScript modul faylida nechta default export bo''lishi mumkin?', 'Сколько экспортов по умолчанию (default export) может быть в одном файле модуля JavaScript?', 'A JavaScript file can have at most one default export, though it can have any number of named exports.', 'JavaScript faylida ko''pi bilan bitta default export bo''lishi mumkin, ammo nomlangan (named) exportlar soni cheklanmagan.', 'Файл JavaScript может иметь не более одного экспорта по умолчанию (default export), но сколько угодно именованных экспортов.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-components-q9', 'react-components', 9, 'advanced', 2.2, 'What does React.memo() do when wrapping a functional component?', 'Funksional komponentni React.memo() ga o''rash nima vazifani bajaradi?', 'Что делает React.memo() при оборачивании функционального компонента?', 'React.memo is a higher-order component that memoizes the rendered output and skips unnecessary re-renders when props remain shallowly equal.', 'React.memo — yuqori tartibli komponent bo''lib, render natijasini eslab qoladi va props-lar o''zgarmaganda keraksiz qayta renderlarni o''tkazib yuboradi.', 'React.memo — это компонент высшего порядка, который мемоизирует результат рендеринга и пропускает лишние перерисовки, если props поверхностно равны.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-components-q10', 'react-components', 10, 'advanced', 2.2, 'What is the difference between a Controlled and an Uncontrolled component?', 'Controlled (boshqariladigan) va Uncontrolled (boshqarilmaydigan) komponent o''rtasida qanday farq bor?', 'В чем разница между контролируемым (Controlled) и неконтролируемым (Uncontrolled) компонентом?', 'Controlled components use React state as the single source of truth for input values, whereas uncontrolled components rely on the DOM (often accessed via refs).', 'Controlled komponentlar kiritish qiymatlari uchun yagona haqiqat manbai sifatida React holatidan foydalanadi, uncontrolled komponentlar esa DOM-ga (ko''pincha ref orqali) tayanadi.', 'Контролируемые компоненты используют состояние React как единственный источник истины для значений полей, тогда как неконтролируемые полагаются на сам DOM (обычно через ref).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-jsx-q1', 'react-jsx', 1, 'basic', 1, 'What does JSX stand for?', 'JSX qisqartmasi nimani anglatadi?', 'Как расшифровывается JSX?', 'JSX stands for JavaScript XML, a syntax extension that lets you write HTML-like markup inside JavaScript.', 'JSX — JavaScript XML degan ma''noni anglatadi va JavaScript ichida HTML-ga o''xshash belgilash tilini yozish imkonini beruvchi sintaksis kengaytmasidir.', 'JSX расшифровывается как JavaScript XML — расширение синтаксиса, позволяющее писать HTML-подобную разметку внутри JavaScript.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-jsx-q2', 'react-jsx', 2, 'basic', 1, 'How do you embed a JavaScript expression inside JSX?', 'JSX ichiga JavaScript ifodasini qanday joylashtirasiz?', 'Как встроить JavaScript-выражение внутрь JSX?', 'Curly braces { } allow you to evaluate any valid JavaScript expression dynamically inside JSX markup.', 'Jingalak qavslar { } JSX belgilash kodi ichida har qanday to''g''ri JavaScript ifodasini dinamik ravishda hisoblash imkonini beradi.', 'Фигурные скобки { } позволяют динамически вычислять любое допустимое выражение JavaScript внутри разметки JSX.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-jsx-q3', 'react-jsx', 3, 'basic', 1, 'Which attribute is used in JSX instead of the HTML "class" attribute?', 'JSX-da HTML-dagi "class" atributi o''rniga qaysi atribut ishlatiladi?', 'Какой атрибут используется в JSX вместо HTML-атрибута "class"?', 'Because "class" is a reserved keyword in JavaScript, JSX uses "className" corresponding to the DOM property.', '"class" JavaScript-da band qilingan kalit so''z bo''lgani sababli, JSX DOM xususiyatiga mos keluvchi "className" atributidan foydalanadi.', 'Поскольку "class" является зарезервированным ключевым словом в JavaScript, в JSX используется "className", соответствующий свойству DOM.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-jsx-q4', 'react-jsx', 4, 'basic', 1, 'Why must a JSX expression return a single root element?', 'Nima uchun JSX ifodasi bitta ildiz (root) elementni qaytarishi shart?', 'Почему JSX-выражение должно возвращать один корневой элемент?', 'Under the hood, JSX elements are transformed into JavaScript function calls, and a function cannot return multiple unwrapped values.', 'Ichki tomondan JSX elementlari JavaScript funksiya chaqiruvlariga aylantiriladi, funksiya esa o''ralmagan bir nechta qiymatni qaytara olmaydi.', 'Под капотом элементы JSX преобразуются в вызовы функций JavaScript, а функция не может возвращать несколько необернутых значений.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-jsx-q5', 'react-jsx', 5, 'intermediate', 1.5, 'What is the purpose of a React Fragment (<>...</>)?', 'React Fragment (<>...</>) ning maqsadi nima?', 'Какова цель React Fragment (<>...</>)?', 'Fragments let you return multiple elements from a component without polluting the DOM with unnecessary <div> wrappers.', 'Fragmentlar DOM-ni keraksiz <div> o''ramlari bilan to''ldirmasdan, komponentdan bir nechta elementni qaytarish imkonini beradi.', 'Фрагменты позволяют возвращать несколько элементов из компонента, не засоряя DOM лишними обертками <div>.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-jsx-q6', 'react-jsx', 6, 'intermediate', 1.5, 'How are inline styles passed to a JSX element?', 'JSX elementiga ichki (inline) uslublar qanday uzatiladi?', 'Как передаются встроенные (inline) стили в элемент JSX?', 'The style attribute in JSX accepts a JavaScript object where CSS property names are written in camelCase.', 'JSX-dagi style atributi CSS xususiyat nomlari camelCase ko''rinishida yozilgan JavaScript obyektini qabul qiladi.', 'Атрибут style в JSX принимает объект JavaScript, в котором имена свойств CSS записаны в стиле camelCase.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-jsx-q7', 'react-jsx', 7, 'intermediate', 1.5, 'Which values are NOT rendered to the screen when placed inside JSX curly braces?', 'JSX jingalak qavslari ichiga qo''yilganda qaysi qiymatlar ekranga chiqarilmaydi (render qilinmaydi)?', 'Какие значения НЕ отображаются на экране при размещении внутри фигурных скобок JSX?', 'React ignores true, false, null, and undefined in JSX output, which makes conditional rendering with && convenient.', 'React JSX natijasida true, false, null va undefined qiymatlarini e''tiborsiz qoldiradi, bu esa && operatori bilan shartli renderlashni qulaylashtiradi.', 'React игнорирует true, false, null и undefined при выводе JSX, что делает удобным условный рендеринг с помощью оператора &&.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-jsx-q8', 'react-jsx', 8, 'intermediate', 1.5, 'Why is a unique "key" prop required when rendering a list of elements in JSX?', 'JSX-da elementlar ro''yxatini render qilishda nima uchun noyob "key" prop talab qilinadi?', 'Почему при рендеринге списка элементов в JSX требуется уникальный проп "key"?', 'Keys give elements a stable identity across renders so React can efficiently reorder, reuse, or remove DOM nodes.', 'Kalitlar (keys) elementlarga renderlar davomida barqaror identifikator beradi, natijada React DOM tugunlarini samarali qayta tartiblashi, ishlatishi yoki o''chirishi mumkin.', 'Ключи дают элементам стабильную идентичность между рендерами, чтобы React мог эффективно переупорядочивать, переиспользовать или удалять узлы DOM.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-jsx-q9', 'react-jsx', 9, 'advanced', 2.2, 'Why can writing `{count && <Badge />}` cause a bug when `count` is the number `0`?', 'Nima uchun `count` raqami `0` ga teng bo''lganda `{count && <Badge />}` deb yozish xatoga (bug) olib kelishi mumkin?', 'Почему запись `{count && <Badge />}` может вызвать ошибку отображении, когда `count` равен числу `0`?', 'Because `0 && <Badge />` evaluates to `0`, and React renders numbers in JSX, `0` appears on screen instead of nothing; use `count > 0 && <Badge />` instead.', '`0 && <Badge />` ifodasi `0` qaytaradi, React esa JSX-da sonlarni ekranga chiqargani uchun bo''sh joy o''rniga `0` ko''rinib qoladi; buning o''rniga `count > 0 && <Badge />` ishlatish kerak.', 'Поскольку `0 && <Badge />` возвращает `0`, а React рендерит числа в JSX, на экране появится `0`; вместо этого следует писать `count > 0 && <Badge />`.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-jsx-q10', 'react-jsx', 10, 'advanced', 2.2, 'What does the modern JSX transform (introduced in React 17) compile JSX elements into?', 'Zamonaviy JSX transformatsiyasi (React 17 da kiritilgan) JSX elementlarini nimaga kompilyatsiya qiladi?', 'Во что современная трансформация JSX (представленная в React 17) компилирует элементы JSX?', 'The React 17+ JSX transform automatically imports `jsx` from `react/jsx-runtime`, removing the need to manually `import React from "react"` in every file.', 'React 17+ JSX transformatsiyasi `react/jsx-runtime` dan `jsx` funksiyasini avtomatik import qiladi va har bir faylda qo''lda `import React from "react"` yozish zaruratini yo''qotadi.', 'Трансформация JSX в React 17+ автоматически импортирует `jsx` из `react/jsx-runtime`, избавляя от необходимости вручную писать `import React from "react"` в каждом файле.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-props-q1', 'react-props', 1, 'basic', 1, 'What are "props" in React?', 'React-da "props" nima?', 'Что такое "props" в React?', 'Props (short for properties) are arguments passed into React components, similar to function parameters.', 'Props (properties so''zining qisqartmasi) — xuddi funksiya parametrlari kabi React komponentlariga uzatiladigan argumentlardir.', 'Props (сокращение от properties) — это аргументы, передаваемые в компоненты React, аналогично параметрам функций.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-props-q2', 'react-props', 2, 'basic', 1, 'Can a child component directly modify its own props?', 'Bola komponent o''ziga kelgan props-larni to''g''ridan-to''g''ri o''zgartira oladimi?', 'Может ли дочерний компонент напрямую изменять свои собственные props?', 'Props are strictly read-only; if a component needs to change data, it should use state or ask the parent via a callback prop.', 'Props qat''iy ravishda faqat o''qish uchundir; agar komponent ma''lumotni o''zgartirishi kerak bo''lsa, u state-dan foydalanishi yoki callback prop orqali ona komponentga murojaat qilishi kerak.', 'Props предназначены строго только для чтения; если компоненту нужно изменить данные, он должен использовать state или вызвать callback-функцию от родителя.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-props-q3', 'react-props', 3, 'basic', 1, 'How do you destructure `title` and `count` directly in a functional component parameter list?', 'Funksional komponent parametrlar ro''yxatida `title` va `count` props-larini qanday qilib to''g''ridan-to''g''ri destrukturizatsiya qilasiz?', 'Как деструктурировать `title` и `count` непосредственно в списке параметров функционального компонента?', 'Since React passes all props as a single object in the first argument, you destructure it with `{ title, count }`.', 'React barcha props-larni birinchi argumentda bitta obyekt sifatida uzatgani uchun, uni `{ title, count }` ko''rinishida destrukturizatsiya qilasiz.', 'Поскольку React передает все props как единый объект в первом аргументе, его деструктурируют с помощью `{ title, count }`.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-props-q4', 'react-props', 4, 'basic', 1, 'Which special prop contains the content nested between the opening and closing tags of a component?', 'Komponentning ochuvchi va yopuvchi teglari orasiga joylashtirilgan kontent qaysi maxsus prop ichida bo''ladi?', 'Какой специальный проп содержит контент, вложенный между открывающим и закрывающим тегами компонента?', 'The `children` prop automatically receives whatever JSX elements or text are placed inside `<Component>...</Component>`.', '`children` prop-i `<Component>...</Component>` tegi ichiga joylashtirilgan har qanday JSX elementlari yoki matnni avtomatik ravishda qabul qiladi.', 'Проп `children` автоматически получает любые элементы JSX или текст, помещенные внутрь `<Component>...</Component>`.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-props-q5', 'react-props', 5, 'intermediate', 1.5, 'How do you specify a default value for a prop in a modern functional component?', 'Zamonaviy funksional komponentda prop uchun standart (default) qiymatni qanday belgilaysiz?', 'Как задать значение по умолчанию для пропа в современном функциональном компоненте?', 'JavaScript default parameter values in destructuring (`{ size = "md" }`) provide a fallback when the prop is `undefined`.', 'Destrukturizatsiyadagi JavaScript standart parametr qiymatlari (`{ size = "md" }`) prop `undefined` bo''lganda zaxira qiymatni ta''minlaydi.', 'Значения параметров по умолчанию в JavaScript при деструктуризации (`{ size = "md" }`) обеспечивают резервное значение, когда проп равен `undefined`.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-props-q6', 'react-props', 6, 'intermediate', 1.5, 'How can a child component send data back up to its parent component?', 'Bola komponent ma''lumotlarni o''zining ona komponentiga qanday qilib qaytarib yuborishi mumkin?', 'Как дочерний компонент может передать данные обратно родительскому компоненту?', 'Parents pass event handler functions as props to children, and children invoke those functions with data as arguments.', 'Ona komponentlar hodisa ishlovchi funksiyalarni bola komponentlarga props sifatida uzatadi, bola komponentlar esa bu funksiyalarni ma''lumotlar bilan chaqiradi.', 'Родители передают функции-обработчики в качестве props дочерним компонентам, а дочерние вызывают эти функции, передавая данные в аргументах.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-props-q7', 'react-props', 7, 'intermediate', 1.5, 'What does the spread syntax `<Card {...itemProps} />` do in JSX?', 'JSX-da `<Card {...itemProps} />` yoyish (spread) sintaksisi nima qiladi?', 'Что делает синтаксис расширения `<Card {...itemProps} />` в JSX?', 'JSX spread attributes forward all key-value pairs of an object as individual props to the receiving component.', 'JSX spread atributlari obyektning barcha kalit-qiymat juftliklarini qabul qiluvchi komponentga alohida props sifatida uzatadi.', 'Атрибуты расширения в JSX передают все пары ключ-значение объекта как отдельные props целевому компоненту.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-props-q8', 'react-props', 8, 'intermediate', 1.5, 'What is "prop drilling" in React?', 'React-da "prop drilling" nima?', 'Что такое «пробрасывание пропсов» (prop drilling) в React?', 'Prop drilling occurs when data is threaded through several layers of components that only forward the props downward.', 'Prop drilling — ma''lumotlar faqat pastga uzatish vazifasini bajaradigan bir necha qatlam komponentlar orqali o''tkazilganda yuzaga keladi.', 'Prop drilling возникает, когда данные протаскиваются через несколько уровней компонентов, которые лишь пересылают их дальше вниз.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-props-q9', 'react-props', 9, 'advanced', 2.2, 'Which two special props are consumed by React itself and are NOT forwarded into the component''s `props` object?', 'Qaysi ikkita maxsus prop React-ning o''zi tomonidan ishlatiladi va komponentning `props` obyektiga uzatilmaydi?', 'Какие два специальных пропа используются самим React и НЕ передаются в объект `props` компонента?', 'React uses `key` for reconciliation and `ref` for DOM/instance references, stripping them from the regular `props` object in React <=18.', 'React `key`-ni moslashtirish (reconciliation) uchun va `ref`-ni DOM havolalari uchun ishlatadi hamda React <=18 da ularni oddiy `props` obyektidan olib tashlaydi.', 'React использует `key` для согласования и `ref` для ссылок на DOM/экземпляры, не включая их в обычный объект `props` в React <=18.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-props-q10', 'react-props', 10, 'advanced', 2.2, 'What is the "Render Props" pattern in React?', 'React-da "Render Props" namunasi (pattern) nima?', 'Что представляет собой паттерн "Render Props" в React?', 'A component with a render prop takes a function that returns a React element and calls it instead of implementing its own fixed render logic.', 'Render prop-ga ega komponent o''zining qat''iy render mantiqini yozish o''rniga, React elementini qaytaradigan funksiyani qabul qiladi va uni chaqiradi.', 'Компонент с рендер-пропом принимает функцию, возвращающую React-элемент, и вызывает её вместо жестко заданной собственной разметки.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-state-q1', 'react-state', 1, 'basic', 1, 'What is "state" in a React component?', 'React komponentida "state" (holat) nima?', 'Что такое «состояние» (state) в компоненте React?', 'State holds data that changes over time within a component; updating state tells React to re-render the UI.', 'State komponent ichida vaqt o''tishi bilan o''zgaradigan ma''lumotlarni saqlaydi; holatni yangilash React-ga interfeysni qayta render qilishni buyuradi.', 'Состояние хранит данные, которые меняются со временем внутри компонента; обновление состояния указывает React перерисовать интерфейс.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-state-q2', 'react-state', 2, 'basic', 1, 'What happens when you mutate a state variable directly (e.g., `count = count + 1`) instead of using its state setter?', 'Holatni o''zgartiruvchi funksiya (setter) o''rniga holat o''zgaruvchisini to''g''ridan-to''g''ri o''zgartirsangiz (`count = count + 1`) nima sodir bo''ladi?', 'Что произойдет, если изменить переменную состояния напрямую (например, `count = count + 1`) вместо использования функции обновления?', 'Direct mutation bypasses React''s scheduling mechanism, so the UI remains stale and out of sync with the data.', 'To''g''ridan-to''g''ri o''zgartirish React-ning rejalashtirish mexanizmini chetlab o''tadi, shuning uchun interfeys yangilanmaydi.', 'Прямая мутация обходит механизм планирования React, поэтому интерфейс остается устаревшим и не синхронизируется с данными.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-state-q3', 'react-state', 3, 'basic', 1, 'How should you update an array or object stored in React state?', 'React holatida (state) saqlangan massiv yoki obyektni qanday yangilash kerak?', 'Как следует обновлять массив или объект, хранящийся в состоянии React?', 'State in React should be treated as immutable: always create a new object or array reference (e.g., with spread syntax, map, or filter).', 'React-da holat o''zgarmas (immutable) deb qabul qilinishi kerak: har doim yangi obyekt yoki massiv nusxasini (masalan, spread, map yoki filter yordamida) yarating.', 'К состоянию в React следует относиться как к неизменяемому (immutable): всегда создавайте новый объект или массив (например, через spread, map или filter).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-state-q4', 'react-state', 4, 'basic', 1, 'What is the main difference between props and state?', 'Props va state o''rtasidagi asosiy farq nima?', 'В чем основное различие между props и state?', 'Props are external read-only parameters passed by a parent, while state is private, mutable data owned by the component.', 'Props — ona komponent tomonidan uzatiladigan tashqi, faqat o''qish uchun parametrlar, state esa komponentning o''ziga tegishli ichki o''zgaruvchan ma''lumotdir.', 'Props — это внешние параметры только для чтения от родителя, а state — это внутренние изменяемые данные самого компонента.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-state-q5', 'react-state', 5, 'intermediate', 1.5, 'What does "lifting state up" mean in React?', 'React-da "lifting state up" (holatni yuqoriga ko''tarish) nimani anglatadi?', 'Что означает «поднятие состояния» (lifting state up) в React?', 'When two sibling components need to share and stay in sync with the same data, you move that state into their common parent component.', 'Ikki qardosh komponent bir xil ma''lumotni ulashishi va sinxron bo''lishi kerak bo''lganda, ushbu holat ularning umumiy ona komponentiga ko''chiriladi.', 'Когда двум соседним компонентам нужно совместно использовать одни и те же данные, это состояние перемещают в их общий родительский компонент.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-state-q6', 'react-state', 6, 'intermediate', 1.5, 'Why shouldn''t you store derived values (like `fullName` when you already have `firstName` and `lastName` in state) in a separate state variable?', 'Nima uchun hosilaviy qiymatlarni (masalan, state-da `firstName` va `lastName` bo''la turib, `fullName`-ni) alohida state o''zgaruvchisida saqlamaslik kerak?', 'Почему не следует хранить производные значения (например, `fullName`, когда в state уже есть `firstName` и `lastName`) в отдельной переменной состояния?', 'Values that can be computed directly from existing props or state should be calculated during render to avoid synchronization bugs.', 'Mavjud props yoki state-dan bevosita hisoblanishi mumkin bo''lgan qiymatlar sinxronizatsiya xatolarining oldini olish uchun render vaqtida hisoblanishi kerak.', 'Значения, которые можно вычислить напрямую из существующих props или state, следует вычислять прямо во время рендера, чтобы избежать ошибок рассинхронизации.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-state-q7', 'react-state', 7, 'intermediate', 1.5, 'What is "state batching" in React?', 'React-da "state batching" (holat yangilanishlarini guruhlash) nima?', 'Что такое «пакетирование обновлений состояния» (state batching) в React?', 'React batches multiple `setState` calls triggered in the same event into a single render pass to avoid unnecessary intermediate re-renders.', 'React keraksiz oraliq qayta renderlarning oldini olish uchun bitta hodisada chaqirilgan bir nechta `setState` yangilanishlarini bitta render jarayoniga birlashtiradi.', 'React группирует несколько вызовов обновления состояния в рамках одного события в один проход рендеринга, чтобы избежать лишних промежуточных перерисовок.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-state-q8', 'react-state', 8, 'intermediate', 1.5, 'How does React decide whether to preserve or reset a component''s state between renders?', 'React renderlar orasida komponent holatini saqlab qolish yoki noldan boshlashni qanday hal qiladi?', 'Как React решает, сохранить или сбросить состояние компонента между рендерами?', 'State is tied to a position in the render tree; if the component type at that position stays the same (with the same key), React preserves its state.', 'Holat render daraxtidagi o''ringa bog''langan; agar o''sha joydagi komponent turi (va key) o''zgarmasa, React uning holatini saqlab qoladi.', 'Состояние привязано к позиции в дереве рендеринга: если тип компонента на этой позиции (и его key) остается прежним, React сохраняет состояние.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-state-q9', 'react-state', 9, 'advanced', 2.2, 'How can you force React to reset a component''s internal state when switching between different items (e.g., switching chat recipients)?', 'Turli elementlar o''rtasida almashganda (masalan, chat suhbatdoshini almashtirganda) React-ni komponentning ichki holatini tozalashga (reset) qanday majburlash mumkin?', 'Как заставить React сбросить внутреннее состояние компонента при переключении между разными элементами (например, при смене собеседника в чате)?', 'Changing a component''s `key` tells React to treat it as a brand-new component instance, unmounting the old one and resetting all its state.', 'Komponentning `key` qiymatini o''zgartirish React-ga uni butunlay yangi komponent nusxasi sifatida ko''rishni, eskisini o''chirib, barcha holatini noldan boshlashni bildiradi.', 'Изменение пропа `key` указывает React рассматривать компонент как совершенно новый экземпляр, размонтируя старый и сбрасывая всё его состояние.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-state-q10', 'react-state', 10, 'advanced', 2.2, 'What did React 18''s "Automatic Batching" introduce compared to React 17?', 'React 18 dagi "Automatic Batching" (Avtomatik guruhlash) React 17 ga nisbatan qanday yangilik kiritdi?', 'Что нового привнесло «Автоматическое пакетирование» (Automatic Batching) в React 18 по сравнению с React 17?', 'In React 17, only React event handlers were batched; React 18 batches all state updates regardless of where they originate (promises, timeouts, native events).', 'React 17 da faqat React hodisa ishlovchilari guruhlangan bo''lsa, React 18 da barcha holat yangilanishlari qayerda chaqirilishidan qat''i nazar (promise, timeout, native event) avtomatik guruhlanadi.', 'В React 17 пакетировались только обработчики событий React; в React 18 автоматически пакетируются все обновления состояния, включая промисы, таймеры и нативные события.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-usestate-q1', 'react-usestate', 1, 'basic', 1, 'What does calling `useState(initialValue)` return?', '`useState(initialValue)` funksiyasini chaqirish nima qaytaradi?', 'Что возвращает вызов `useState(initialValue)`?', '`useState` returns a 2-element tuple `[state, setState]`, which is typically unpacked using array destructuring.', '`useState` ikki elementli `[state, setState]` massivini qaytaradi va u odatda massiv destrukturizatsiyasi yordamida ajratib olinadi.', '`useState` возвращает кортеж из двух элементов `[state, setState]`, который обычно распаковывается с помощью деструктуризации массива.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-usestate-q2', 'react-usestate', 2, 'basic', 1, 'When is the `initialValue` argument passed to `useState(initialValue)` used by React?', '`useState(initialValue)` ga uzatilgan `initialValue` argumenti React tomonidan qachon ishlatiladi?', 'Когда аргумент `initialValue`, переданный в `useState(initialValue)`, используется React?', 'React uses the initial state argument only on the first render and ignores it on subsequent re-renders.', 'React boshlang''ich holat argumentidan faqat birinchi renderda foydalanadi va keyingi qayta renderlarda uni e''tiborsiz qoldiradi.', 'React использует начальное значение состояния только при первом рендере и игнорирует его при последующих перерисовках.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-usestate-q3', 'react-usestate', 3, 'basic', 1, 'Where are you allowed to call `useState` inside a React component?', 'React komponenti ichida `useState` ni qayerda chaqirishga ruxsat beriladi?', 'Где разрешено вызывать `useState` внутри компонента React?', 'According to the Rules of Hooks, Hooks must only be called at the top level so they execute in the exact same order on every render.', 'Hook qoidalariga ko''ra, Hook-lar har bir renderda aynan bir xil tartibda bajarilishi uchun faqat eng yuqori darajada (top level) chaqirilishi shart.', 'Согласно Правилам хуков, хуки должны вызываться только на верхнем уровне, чтобы они выполнялись в одном и том же порядке при каждом рендере.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-usestate-q4', 'react-usestate', 4, 'basic', 1, 'If `const [count, setCount] = useState(0)`, what will `console.log(count)` print on the line immediately after `setCount(5)`?', 'Agar `const [count, setCount] = useState(0)` bo''lsa, `setCount(5)` chaqirilganidan darhol keyingi qatordagi `console.log(count)` nimani chiqaradi?', 'Если `const [count, setCount] = useState(0)`, что выведет `console.log(count)` на следующей строке сразу после вызова `setCount(5)`?', 'Calling `setCount` schedules a new render with the updated value; it does not change the `count` constant in the currently running function scope.', '`setCount`-ni chaqirish yangilangan qiymat bilan yangi renderni rejalashtiradi; u joriy ishlab turgan funksiya ichidagi `count` konstantasini o''zgartirmaydi.', 'Вызов `setCount` планирует новый рендер с обновленным значением; он не изменяет константу `count` в текущей выполняющейся функции.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-usestate-q5', 'react-usestate', 5, 'intermediate', 1.5, 'If `count` is `0`, what is the new value of `count` after calling `setCount(count + 1)` three times in the same event handler?', 'Agar `count` `0` ga teng bo''lsa, bitta hodisa ishlovchisi ichida `setCount(count + 1)` ketma-ket uch marta chaqirilgandan so''ng `count`-ning yangi qiymati necha bo''ladi?', 'Если `count` равен `0`, каким будет новое значение `count` после трехкратного вызова `setCount(count + 1)` в одном и том же обработчике события?', 'Because `count` is `0` in that render snapshot, all three calls execute `setCount(0 + 1)`, resulting in `1` after re-render.', 'Ushbu render kadrida `count` `0` ga teng bo''lgani uchun, uchala chaqiruv ham `setCount(0 + 1)` ni bajaradi va qayta renderdan so''ng natija `1` bo''ladi.', 'Поскольку в этом снимке рендера `count` равен `0`, все три вызова выполняют `setCount(0 + 1)`, что дает `1` после перерисовки.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-usestate-q6', 'react-usestate', 6, 'intermediate', 1.5, 'How do you reliably increment state multiple times in the same event handler based on the previous state?', 'Bitta hodisa ishlovchisi ichida oldingi holatga asoslanib holatni bir necha marta ishonchli tarzda qanday oshirish mumkin?', 'Как надежно увеличить состояние несколько раз в одном обработчике события на основе предыдущего состояния?', 'Passing an updater function `prev => prev + 1` queues the functions so each receives the latest pending state.', '`prev => prev + 1` yangilovchi funksiyasini uzatish funksiyalarni navbatga qo''yadi va har biri eng so''nggi kutilayotgan holatni qabul qiladi.', 'Передача функции обновления `prev => prev + 1` ставит функции в очередь, так что каждая получает самое актуальное промежуточное состояние.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-usestate-q7', 'react-usestate', 7, 'intermediate', 1.5, 'How does `useState` setter behave differently from class component `this.setState` when updating an object?', 'Obyektni yangilashda `useState` setter funksiyasi klass komponentdagi `this.setState` dan qanday farq qiladi?', 'Чем функция обновления `useState` отличается от `this.setState` классового компонента при обновлении объекта?', 'Unlike `this.setState` in classes, `useState` setter replaces the state value completely, so you must spread previous properties (`setUser(prev => ({ ...prev, age: 25 }))`).', 'Klasslardagi `this.setState`-dan farqli o''laroq, `useState` setter qiymatni to''liq almashtiradi, shuning uchun oldingi xususiyatlarni yoyib (`setUser(prev => ({ ...prev, age: 25 }))`) yozish kerak.', 'В отличие от `this.setState` в классах, сеттер `useState` полностью заменяет состояние, поэтому нужно копировать предыдущие свойства (`setUser(prev => ({ ...prev, age: 25 }))`).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-usestate-q8', 'react-usestate', 8, 'intermediate', 1.5, 'What is "lazy initial state" in `useState`?', '`useState`-da "lazy initial state" (kechiktirilgan boshlang''ich holat) nima?', 'Что такое «ленивая инициализация состояния» (lazy initial state) в `useState`?', 'If initial state requires an expensive calculation (like reading `localStorage`), passing an initializer function ensures it only executes once on mount.', 'Agar boshlang''ich holat og''ir hisob-kitobni (masalan, `localStorage`-ni o''qishni) talab qilsa, initsializator funksiyani uzatish uning faqat birinchi renderda bir marta ishlashini ta''minlaydi.', 'Если начальное состояние требует ресурсоемких вычислений (например, чтения `localStorage`), передача функции-инициализатора гарантирует, что она выполнится только один раз при монтировании.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-usestate-q9', 'react-usestate', 9, 'advanced', 2.2, 'What happens if you call a `useState` setter with the exact same value as the current state (according to `Object.is`)?', 'Agar `useState` setter funksiyasini joriy holat bilan aynan bir xil qiymat (`Object.is` bo''yicha) bilan chaqirsangiz nima bo''ladi?', 'Что произойдет, если вызвать сеттер `useState` с тем же самым значением, что и текущее состояние (согласно `Object.is`)?', 'React compares the new state with the previous state using `Object.is`; if they are identical, React bails out without scheduling a re-render.', 'React yangi holatni oldingisi bilan `Object.is` yordamida solishtiradi; agar ular bir xil bo''lsa, React qayta renderlashni rejalashtirmasdan to''xtaydi.', 'React сравнивает новое состояние с предыдущим с помощью `Object.is`; если они идентичны, React пропускает повторный рендеринг.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-usestate-q10', 'react-usestate', 10, 'advanced', 2.2, 'If you want to store a function itself inside `useState`, why must you wrap it in another function like `useState(() => myFunc)`?', 'Agar `useState` ichida funksiyaning o''zini qiymat sifatida saqlamoqchi bo''lsangiz, nima uchun uni `useState(() => myFunc)` kabi boshqa funksiyaga o''rashingiz shart?', 'Если вы хотите сохранить саму функцию внутри `useState`, почему её нужно оборачивать в другую функцию, например `useState(() => myFunc)`?', 'Since `useState(fn)` and `setState(fn)` invoke `fn` as an initializer/updater, returning your function from an outer wrapper `() => myFunc` stores `myFunc` as the state value.', '`useState(fn)` va `setState(fn)` uzatilgan `fn`-ni initsializator/yangilovchi sifatida ishga tushirgani sababli, funksiyangizni tashqi `() => myFunc` o''ramidan qaytarish `myFunc`-ning o''zini qiymat sifatida saqlaydi.', 'Поскольку `useState(fn)` и `setState(fn)` вызывают `fn` как инициализатор или апдейтер, возврат вашей функции из внешней обертки `() => myFunc` позволяет сохранить саму `myFunc` как значение.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-useeffect-q1', 'react-useeffect', 1, 'basic', 1, 'What is the primary purpose of the `useEffect` Hook in React?', 'React-da `useEffect` Hook-ining asosiy maqsadi nima?', 'Какова основная цель хука `useEffect` в React?', '`useEffect` lets you run side effects after rendering so your component can synchronize with external APIs, DOM, or network systems.', '`useEffect` komponentingizni tashqi API, DOM yoki tarmoq tizimlari bilan sinxronlashtirish uchun renderdan keyin yon ta''sirlarni (side effects) bajarish imkonini beradi.', '`useEffect` позволяет выполнять побочные эффекты после рендеринга для синхронизации компонента с внешними API, DOM или сетью.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-useeffect-q2', 'react-useeffect', 2, 'basic', 1, 'When does `useEffect(() => { ... }, [])` (with an empty dependency array) run in production?', 'Production muhitida bo''sh bog''liqliklar massiviga ega `useEffect(() => { ... }, [])` qachon ishga tushadi?', 'Когда в продакшене выполняется `useEffect(() => { ... }, [])` (с пустым массивом зависимостей)?', 'An empty dependency array `[]` tells React that the effect does not depend on any reactive values, so it only runs on mount.', 'Bo''sh bog''liqliklar massivi `[]` React-ga effekt hech qanday reaktiv qiymatga bog''liq emasligini bildiradi, shuning uchun u faqat o''rnatishda (mount) ishlaydi.', 'Пустой массив зависимостей `[]` сообщает React, что эффект не зависит ни от каких реактивных значений, поэтому он запускается только при монтировании.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-useeffect-q3', 'react-useeffect', 3, 'basic', 1, 'What happens if you omit the dependency array completely in `useEffect(() => { ... })`?', 'Agar `useEffect(() => { ... })` da bog''liqliklar massivini butunlay yozmasangiz nima bo''ladi?', 'Что произойдет, если полностью опустить массив зависимостей в `useEffect(() => { ... })`?', 'Without a dependency array, the effect executes after every render commit of the component.', 'Bog''liqliklar massivi bo''lmasa, effekt komponentning har bir renderidan keyin qayta ishga tushadi.', 'Без массива зависимостей эффект выполняется после каждого рендера компонента.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-useeffect-q4', 'react-useeffect', 4, 'basic', 1, 'How do you specify a cleanup operation (such as clearing a timer or unsubscribing) inside `useEffect`?', '`useEffect` ichida tozalash (cleanup) amalini (masalan, taymerni to''xtatish yoki obunani bekor qilishni) qanday belgilaysiz?', 'Как задать операцию очистки (например, остановку таймера или отписку) внутри `useEffect`?', 'Returning a function from your `useEffect` callback registers a cleanup routine that runs before the effect re-runs and when the component unmounts.', '`useEffect` callback funksiyasidan funksiya qaytarish (return) effekt qayta ishlashidan oldin va komponent o''chirilganda (unmount) bajariladigan tozalash jarayonini ro''yxatdan o''tkazadi.', 'Возврат функции из колбэка `useEffect` регистрирует процедуру очистки, которая выполняется перед повторным запуском эффекта и при размонтировании компонента.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-useeffect-q5', 'react-useeffect', 5, 'intermediate', 1.5, 'When does a `useEffect` cleanup function execute?', '`useEffect`-ning tozalash (cleanup) funksiyasi qachon bajariladi?', 'Когда выполняется функция очистки (cleanup) в `useEffect`?', 'React runs the cleanup function from the previous render before running the next effect, as well as a final time on unmount.', 'React keyingi effektni ishga tushirishdan oldin oldingi renderning tozalash funksiyasini, shuningdek unmount vaqtida oxirgi marta ishga tushiradi.', 'React вызывает функцию очистки предыдущего рендера перед запуском следующего эффекта, а также в последний раз при размонтировании.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-useeffect-q6', 'react-useeffect', 6, 'intermediate', 1.5, 'Why can calling `setState` unconditionally inside a `useEffect` without a dependency array cause an infinite loop?', 'Nima uchun bog''liqliklar massiviga ega bo''lmagan `useEffect` ichida shartsiz `setState` chaqirish cheksiz siklga olib keladi?', 'Почему безусловный вызов `setState` внутри `useEffect` без массива зависимостей приводит к бесконечному циклу?', 'Updating state causes a re-render, and an effect without a dependency array (or depending on that state) runs after every render, creating an endless cycle.', 'Holatni yangilash qayta renderlashga sabab bo''ladi, bog''liqliklar massiviga ega bo''lmagan effekt esa har bir renderdan keyin ishlab, tugamas siklni hosil qiladi.', 'Обновление состояния вызывает ререндер, а эффект без массива зависимостей выполняется после каждого рендера, создавая бесконечный цикл.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-useeffect-q7', 'react-useeffect', 7, 'intermediate', 1.5, 'How should you use an `async/await` function inside `useEffect`?', '`useEffect` ichida `async/await` funksiyasidan qanday foydalanish kerak?', 'Как правильно использовать `async/await` функцию внутри `useEffect`?', 'An effect callback must return either nothing (`undefined`) or a cleanup function, whereas an `async` function always returns a Promise.', 'Effekt callback funksiyasi hech narsa (`undefined`) yoki tozalash funksiyasini qaytarishi shart, `async` funksiya esa har doim Promise qaytaradi.', 'Колбэк эффекта должен возвращать либо ничего (`undefined`), либо функцию очистки, тогда как `async`-функция всегда возвращает Promise.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-useeffect-q8', 'react-useeffect', 8, 'intermediate', 1.5, 'Which values should be included in the `useEffect` dependency array?', '`useEffect` bog''liqliklar massiviga qaysi qiymatlar kiritilishi kerak?', 'Какие значения должны быть включены в массив зависимостей `useEffect`?', 'Every reactive value referenced inside the effect must be declared in its dependency array to prevent stale closures.', 'Eskirgan yopilishlarning (stale closures) oldini olish uchun effekt ichida ishlatilgan har bir reaktiv qiymat uning bog''liqliklar massivida ko''rsatilishi shart.', 'Каждое реактивное значение, используемое внутри эффекта, должно быть указано в массиве зависимостей, чтобы избежать устаревших замыканий (stale closures).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-useeffect-q9', 'react-useeffect', 9, 'advanced', 2.2, 'How do you prevent race conditions when fetching data inside `useEffect` as a dependency (like `userId`) changes rapidly?', 'Bog''liqlik (masalan, `userId`) tez o''zgarganda `useEffect` ichida ma''lumot yuklashda poyga holatlarining (race conditions) oldini qanday olasiz?', 'Как предотвратить состояние гонки (race condition) при загрузке данных в `useEffect`, когда зависимость (например, `userId`) быстро меняется?', 'Using an `AbortController` or setting `ignore = true` in the cleanup function ensures an older, slower request cannot overwrite newer state.', 'Tozalash funksiyasida `AbortController` ishlatish yoki `ignore = true` belgilash eskiroq va sekinroq so''rovning yangi holat ustiga yozib yuborolmasligini kafolatlaydi.', 'Использование `AbortController` или установка флага `ignore = true` в функции очистки гарантирует, что старый медленный запрос не перезапишет более новое состояние.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-useeffect-q10', 'react-useeffect', 10, 'advanced', 2.2, 'What is the key difference between `useEffect` and `useLayoutEffect`?', '`useEffect` va `useLayoutEffect` o''rtasidagi asosiy farq nima?', 'В чем ключевое различие между `useEffect` и `useLayoutEffect`?', '`useLayoutEffect` runs synchronously before browser paint, making it ideal for measuring DOM layout without visual flicker.', '`useLayoutEffect` brauzer ekranni chizishidan oldin sinxron ishlaydi, bu esa vizual miltillashsiz DOM o''lchamlarini o''lchash uchun juda mos keladi.', '`useLayoutEffect` выполняется синхронно до отрисовки экрана браузером, что идеально подходит для измерения DOM-элементов без визуального мерцания.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-router-q1', 'react-router', 1, 'basic', 1, 'What is React Router primarily used for in a Single Page Application (SPA)?', 'Bir sahifali ilovada (SPA) React Router asosan nima uchun ishlatiladi?', 'Для чего в основном используется React Router в одностраничном приложении (SPA)?', 'React Router synchronizes the UI with the browser URL on the client side without triggering full document reloads.', 'React Router hujjatni to''liq qayta yuklamasdan, mijoz tomonida interfeysni brauzer URL manzili bilan sinxronlashtiradi.', 'React Router синхронизирует интерфейс с URL браузера на стороне клиента без полной перезагрузки документа.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-router-q2', 'react-router', 2, 'basic', 1, 'Which React Router component uses the HTML5 History API to keep the UI in sync with the URL?', 'Qaysi React Router komponenti interfeysni URL bilan sinxron saqlash uchun HTML5 History API-dan foydalanadi?', 'Какой компонент React Router использует HTML5 History API для синхронизации интерфейса с URL?', '`<BrowserRouter>` wraps your application and uses the browser''s clean URL history stack (`pushState`, `popstate`).', '`<BrowserRouter>` ilovangizni o''rab oladi va brauzerning toza URL tarixi stekidan (`pushState`, `popstate`) foydalanadi.', '`<BrowserRouter>` оборачивает приложение и использует стек истории чистых URL браузера (`pushState`, `popstate`).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-router-q3', 'react-router', 3, 'basic', 1, 'Why should you use `<Link to="/about">` instead of `<a href="/about">` for internal navigation in React Router?', 'React Router-da ichki navigatsiya uchun `<a href="/about">` o''rniga nima uchun `<Link to="/about">` ishlatish kerak?', 'Почему для внутренней навигации в React Router следует использовать `<Link to="/about">` вместо `<a href="/about">`?', '`<Link>` prevents the browser''s default full-page reload and updates the URL via the router history, preserving React state.', '`<Link>` brauzerning odatiy to''liq sahifa qayta yuklanishining oldini oladi va React holatini saqlagan holda router tarixi orqali URL-ni yangilaydi.', '`<Link>` предотвращает стандартную полную перезагрузку страницы браузером и обновляет URL через историю роутера, сохраняя состояние React.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-router-q4', 'react-router', 4, 'basic', 1, 'In React Router v6, which props are used on `<Route>` to associate a URL path with a component?', 'React Router v6 da URL yo''lini komponent bilan bog''lash uchun `<Route>` da qaysi props-lar ishlatiladi?', 'Какие пропсы используются в `<Route>` в React Router v6 для связывания URL-пути с компонентом?', 'In React Router v6, routes are configured using `<Route path="/users" element={<Users />} />`.', 'React Router v6 da yo''nalishlar `<Route path="/users" element={<Users />} />` ko''rinishida sozlanadi.', 'В React Router v6 маршруты настраиваются с помощью `<Route path="/users" element={<Users />} />`.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-router-q5', 'react-router', 5, 'intermediate', 1.5, 'Which Hook is used in React Router v6 to navigate programmatically (e.g., after a form submission)?', 'React Router v6 da dasturiy ravishda boshqa sahifaga o''tish uchun (masalan, forma yuborilgandan keyin) qaysi Hook ishlatiladi?', 'Какой хук используется в React Router v6 для программной навигации (например, после отправки формы)?', '`useNavigate()` returns a function that lets you navigate programmatically, such as `navigate("/dashboard", { replace: true })`.', '`useNavigate()` dasturiy ravishda yo''naltirish imkonini beruvchi funksiyani qaytaradi, masalan: `navigate("/dashboard", { replace: true })`.', '`useNavigate()` возвращает функцию для программного перехода, например `navigate("/dashboard", { replace: true })`.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-router-q6', 'react-router', 6, 'intermediate', 1.5, 'How do you read dynamic URL parameters like `:productId` from a route path `/products/:productId`?', '`/products/:productId` yo''nalishidagi `:productId` kabi dinamik URL parametrlarini qanday o''qiysiz?', 'Как прочитать динамические параметры URL, такие как `:productId`, из маршрута `/products/:productId`?', '`useParams()` returns an object of key/value pairs of the dynamic params from the current URL that were matched by the `<Route path>`.', '`useParams()` joriy URL-dagi `<Route path>` ga mos kelgan dinamik parametrlarning kalit/qiymat juftliklaridan iborat obyektni qaytaradi.', '`useParams()` возвращает объект с парами ключ/значение динамических параметров текущего URL, совпавших с `<Route path>`.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-router-q7', 'react-router', 7, 'intermediate', 1.5, 'What is the purpose of the `<Outlet />` component in React Router v6?', 'React Router v6 da `<Outlet />` komponentining vazifasi nima?', 'Какова цель компонента `<Outlet />` в React Router v6?', 'A parent route element uses `<Outlet />` as a placeholder where its matching nested child routes will be rendered.', 'Ona yo''nalish elementi o''ziga mos keluvchi ichma-ich joylashgan bola yo''nalishlar render qilinadigan joy sifatida `<Outlet />` dan foydalanadi.', 'Родительский маршрут использует `<Outlet />` как место для рендеринга совпавших вложенных дочерних маршрутов.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-router-q8', 'react-router', 8, 'intermediate', 1.5, 'How do you define a "catch-all" (404 Not Found) route in React Router v6?', 'React Router v6 da barcha mavjud bo''lmagan manzillarni ushlab qoluvchi (404 Not Found) yo''nalishni qanday belgilaysiz?', 'Как определить перехватывающий маршрут (404 Not Found) для несуществующих страниц в React Router v6?', 'A `<Route path="*">` matches any URL when no other sibling route matches, making it ideal for 404 Not Found pages.', '`<Route path="*">` boshqa hech bir yo''nalish mos kelmaganda har qanday URL-ga mos tushadi va 404 sahifalari uchun ayni muddaodir.', '`<Route path="*">` совпадает с любым URL, если ни один другой маршрут не подошел, что идеально для страницы 404.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-router-q9', 'react-router', 9, 'advanced', 2.2, 'How does `<NavLink>` differ from `<Link>` in React Router?', 'React Router-da `<NavLink>` `<Link>` dan qanday farq qiladi?', 'Чем `<NavLink>` отличается от `<Link>` в React Router?', '`<NavLink>` is a specialized `<Link>` that automatically applies an `active` class or passes `{ isActive, isPending }` to its `className`/`style` function.', '`<NavLink>` — bu `<Link>` ning maxsus turi bo''lib, avtomatik ravishda `active` klassini qo''shadi yoki `className`/`style` funksiyasiga `{ isActive, isPending }` ni uzatadi.', '`<NavLink>` — это специализированный `<Link>`, который автоматически добавляет класс `active` или передает `{ isActive, isPending }` в функцию `className`/`style`.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-router-q10', 'react-router', 10, 'advanced', 2.2, 'Why is `<Navigate to="/login" replace />` commonly used inside a Protected Route component?', 'Himoyalangan yo''nalish (Protected Route) komponenti ichida nima uchun ko''pincha `<Navigate to="/login" replace />` ishlatiladi?', 'Почему внутри компонента защищенного маршрута (Protected Route) часто используется `<Navigate to="/login" replace />`?', 'Using `replace` overwrites the current history entry instead of pushing a new one, preventing redirect loops when the user clicks Back.', '`replace`-dan foydalanish yangi yozuv qo''shish o''rniga joriy tarix yozuvini ustidan yozadi va foydalanuvchi "Orqaga" tugmasini bosganda qayta yo''naltirish siklining oldini oladi.', 'Использование `replace` перезаписывает текущую запись в истории вместо добавления новой, предотвращая цикл перенаправлений при нажатии кнопки «Назад».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-events-q1', 'react-events', 1, 'basic', 1, 'How are event handler attributes named in React JSX?', 'React JSX-da hodisa ishlovchi (event handler) atributlar qanday nomlanadi?', 'Как именуются атрибуты обработчиков событий в React JSX?', 'React JSX event props follow camelCase naming conventions like `onClick`, `onSubmit`, and `onKeyDown`.', 'React JSX hodisa props-lari `onClick`, `onSubmit` va `onKeyDown` kabi camelCase nomlash qoidalariga amal qiladi.', 'Пропсы событий в React JSX следуют соглашению camelCase, например `onClick`, `onSubmit` и `onKeyDown`.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-events-q2', 'react-events', 2, 'basic', 1, 'What is the difference between `onClick={handleClick}` and `onClick={handleClick()}` in JSX?', 'JSX-da `onClick={handleClick}` va `onClick={handleClick()}` o''rtasida qanday farq bor?', 'В чем разница между `onClick={handleClick}` и `onClick={handleClick()}` в JSX?', 'You must pass a function reference (`handleClick`), not invoke it (`handleClick()`), otherwise it executes immediately on every render.', 'Hodisaga funksiya chaqiruvini (`handleClick()`) emas, balki funksiya havolasini (`handleClick`) uzatish kerak, aks holda u har bir renderda darhol ishlab ketadi.', 'Необходимо передавать ссылку на функцию (`handleClick`), а не вызывать её (`handleClick()`), иначе она будет выполняться сразу при каждом рендере.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-events-q3', 'react-events', 3, 'basic', 1, 'How do you prevent the default browser page reload when submitting a `<form>` in React?', 'React-da `<form>` yuborilganda (submit) brauzerning odatiy sahifa qayta yuklanishini qanday to''xtatasiz?', 'Как предотвратить стандартную перезагрузку страницы браузером при отправке `<form>` в React?', 'In React, returning `false` does not stop default behavior; you must explicitly call `event.preventDefault()` on the event object.', 'React-da `false` qaytarish standart xatti-harakatni to''xtatmaydi; hodisa obyektida `event.preventDefault()` metodini aniq chaqirish shart.', 'В React возврат `false` не отменяет стандартное поведение; необходимо явно вызвать `event.preventDefault()` у объекта события.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-events-q4', 'react-events', 4, 'basic', 1, 'In an `onChange` handler for an `<input>`, how do you access the current text typed by the user?', '`<input>` uchun `onChange` ishlovchisida foydalanuvchi kiritgan joriy matnni qanday olasiz?', 'Как в обработчике `onChange` для `<input>` получить текущий текст, введенный пользователем?', '`event.target` refers to the DOM `<input>` element that triggered the event, and `event.target.value` holds its current string value.', '`event.target` hodisani chaqirgan DOM `<input>` elementiga ishora qiladi, `event.target.value` esa uning joriy satr qiymatini saqlaydi.', '`event.target` ссылается на DOM-элемент `<input>`, вызвавший событие, а `event.target.value` содержит его текущее строковое значение.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-events-q5', 'react-events', 5, 'intermediate', 1.5, 'How do you pass a custom argument (like `item.id`) to an event handler in JSX?', 'JSX-da hodisa ishlovchisiga maxsus argumentni (masalan, `item.id`) qanday uzatasiz?', 'Как передать пользовательский аргумент (например, `item.id`) в обработчик события в JSX?', 'Wrapping the call in an arrow function `onClick={(e) => handleDelete(item.id, e)}` creates a function that calls `handleDelete` only when clicked.', 'Chaqiruvni `onClick={(e) => handleDelete(item.id, e)}` strelkali funksiyasiga o''rash faqat bosilgandagina `handleDelete`-ni chaqiradigan funksiya yaratadi.', 'Оборачивание вызова в стрелочную функцию `onClick={(e) => handleDelete(item.id, e)}` создает функцию, которая вызовет `handleDelete` только при клике.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-events-q6', 'react-events', 6, 'intermediate', 1.5, 'What is a `SyntheticEvent` in React?', 'React-da `SyntheticEvent` nima?', 'Что такое `SyntheticEvent` в React?', 'React wraps native browser events in `SyntheticEvent` instances so events behave identically across different browsers, while exposing `e.nativeEvent` if needed.', 'React hodisalar turli brauzerlarda bir xil ishlashi uchun mahalliy brauzer hodisalarini `SyntheticEvent` obyektlariga o''raydi va zarur bo''lsa `e.nativeEvent`-ni ham taqdim etadi.', 'React оборачивает нативные события браузера в экземпляры `SyntheticEvent`, чтобы события вели себя одинаково во всех браузерах, сохраняя доступ к `e.nativeEvent`.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-events-q7', 'react-events', 7, 'intermediate', 1.5, 'How do you stop an event on a child element from bubbling up to parent elements'' event handlers?', 'Bola elementdagi hodisaning ona elementlar hodisa ishlovchilariga ko''tarilishini (bubbling) qanday to''xtatasiz?', 'Как остановить всплытие (bubbling) события от дочернего элемента к обработчикам родительских элементов?', 'Calling `event.stopPropagation()` prevents the event from bubbling further up the React component tree.', '`event.stopPropagation()`-ni chaqirish hodisaning React komponentlar daraxti bo''ylab yuqoriga ko''tarilishini to''xtatadi.', 'Вызов `event.stopPropagation()` предотвращает дальнейшее всплытие события вверх по дереву компонентов React.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-events-q8', 'react-events', 8, 'intermediate', 1.5, 'How does React''s `onChange` event on text inputs differ from the native DOM `onchange` event?', 'Matn kiritish maydonlarida React-ning `onChange` hodisasi mahalliy DOM `onchange` hodisasidan qanday farq qiladi?', 'Чем событие `onChange` в React для текстовых полей отличается от нативного DOM-события `onchange`?', 'React maps `onChange` to the native `input` event so controlled components can update state in real time on every character change.', 'React boshqariladigan (controlled) komponentlar har bir belgi o''zgarishida holatni real vaqtda yangilay olishi uchun `onChange`-ni mahalliy `input` hodisasiga bog''laydi.', 'React связывает `onChange` с нативным событием `input`, чтобы контролируемые компоненты могли обновлять состояние в реальном времени при вводе каждого символа.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-events-q9', 'react-events', 9, 'advanced', 2.2, 'Where does React 17+ attach its delegated DOM event listeners under the hood?', 'React 17 va undan keyingi versiyalar ichki tomondan delegatsiya qilingan DOM hodisa tinglovchilarini qayerga biriktiradi?', 'Куда React 17+ прикрепляет свои делегированные обработчики событий DOM «под капотом»?', 'Starting in React 17, React attaches event listeners to the root DOM container rather than `document`, making it safer to mix multiple React trees or non-React code on the same page.', 'React 17 dan boshlab, React hodisa tinglovchilarini `document`-ga emas, balki ildiz DOM konteyneriga biriktiradi, bu esa bitta sahifada bir nechta React daraxtini yoki boshqa kodlarni birga ishlatishni xavfsizroq qiladi.', 'Начиная с React 17, React привязывает обработчики событий к корневому DOM-контейнеру, а не к `document`, что упрощает совмещение нескольких деревьев React или стороннего кода на одной странице.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-events-q10', 'react-events', 10, 'advanced', 2.2, 'How do you register an event listener for the capture phase instead of the bubble phase in React JSX?', 'React JSX-da hodisa tinglovchisini ko''tarilish (bubble) bosqichi o''rniga tutib olish (capture) bosqichi uchun qanday ro''yxatdan o''tkazasiz?', 'Как зарегистрировать обработчик события для фазы перехвата (capture) вместо фазы всплытия (bubble) в React JSX?', 'Adding `Capture` to any event prop name (e.g., `onClickCapture`, `onFocusCapture`) instructs React to invoke the handler during the capture phase.', 'Har qanday hodisa prop nomiga `Capture` qo''shish (masalan, `onClickCapture`, `onFocusCapture`) React-ga ishlovchini tutib olish (capture) bosqichida chaqirishni buyuradi.', 'Добавление `Capture` к имени любого пропа события (например, `onClickCapture`, `onFocusCapture`) указывает React вызывать обработчик во время фазы перехвата.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-advanced-q1', 'react-advanced', 1, 'basic', 1, 'What problem does the React Context API (`createContext` and `useContext`) solve?', 'React Context API (`createContext` va `useContext`) qanday muammoni hal qiladi?', 'Какую проблему решает React Context API (`createContext` и `useContext`)?', 'Context lets a parent component provide data to any component in the subtree below it, no matter how deeply nested.', 'Context ona komponentga ma''lumotlarni qanchalik chuqur joylashganidan qat''i nazar, o''zidan pastdagi daraxtning istalgan komponentiga uzatish imkonini beradi.', 'Контекст позволяет родительскому компоненту предоставлять данные любому компоненту в поддереве ниже него, независимо от глубины вложенности.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-advanced-q2', 'react-advanced', 2, 'basic', 1, 'What are the two main use cases for the `useRef` Hook?', '`useRef` Hook-idan foydalanishning ikkita asosiy holati qaysilar?', 'Каковы два основных сценария использования хука `useRef`?', '`useRef` returns a mutable `{ current }` object that persists for the lifetime of the component and does not trigger a re-render when `.current` is mutated.', '`useRef` komponentning butun yashash davri davomida saqlanib qoladigan va `.current` o''zgartirilganda qayta renderlashni chaqirmaydigan o''zgaruvchan `{ current }` obyektini qaytaradi.', '`useRef` возвращает изменяемый объект `{ current }`, который сохраняется на протяжении всей жизни компонента и не вызывает ререндер при изменении `.current`.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-advanced-q3', 'react-advanced', 3, 'intermediate', 1.5, 'What is the difference between `useMemo` and `useCallback`?', '`useMemo` va `useCallback` o''rtasida qanday farq bor?', 'В чем разница между `useMemo` и `useCallback`?', '`useMemo(() => fn(), deps)` memoizes the return value of `fn()`, while `useCallback(fn, deps)` memoizes the `fn` instance itself between renders.', '`useMemo(() => fn(), deps)` `fn()` qaytaradigan qiymatni eslab qoladi, `useCallback(fn, deps)` esa renderlar orasida `fn` funksiyasining o''zini eslab qoladi.', '`useMemo(() => fn(), deps)` мемоизирует возвращаемое значение `fn()`, а `useCallback(fn, deps)` мемоизирует сам экземпляр функции `fn` между рендерами.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-advanced-q4', 'react-advanced', 4, 'intermediate', 1.5, 'When is `useReducer` generally preferred over `useState`?', 'Qachon `useState` dan ko''ra `useReducer` afzal ko''riladi?', 'В каких случаях `useReducer` обычно предпочтительнее `useState`?', '`useReducer` centralizes complex state transitions inside a pure reducer function `(state, action) => newState`.', '`useReducer` murakkab holat o''tishlarini `(state, action) => newState` sof reduser funksiyasi ichida markazlashtiradi.', '`useReducer` централизует сложные переходы состояния внутри чистой функции-редьюсера `(state, action) => newState`.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-advanced-q5', 'react-advanced', 5, 'intermediate', 1.5, 'What must a Custom Hook name always start with in React?', 'React-da maxsus Hook (Custom Hook) nomi har doim nima bilan boshlanishi shart?', 'С чего всегда должно начинаться имя пользовательского хука (Custom Hook) в React?', 'Starting custom Hooks with `use` allows React and linters to verify that the Rules of Hooks are followed.', 'Maxsus Hook-larni `use` bilan boshlash React va linterlarga Hook qoidalariga rioya qilinayotganini tekshirish imkonini beradi.', 'Именование пользовательских хуков с префикса `use` позволяет React и линтерам проверять соблюдение Правил хуков.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-advanced-q6', 'react-advanced', 6, 'intermediate', 1.5, 'How do `React.lazy` and `<Suspense>` work together for code splitting?', 'Kod bo''laklash (code splitting) uchun `React.lazy` va `<Suspense>` birgalikda qanday ishlaydi?', 'Как `React.lazy` и `<Suspense>` работают вместе для разделения кода (code splitting)?', '`React.lazy(() => import("./Chart"))` defers loading the component''s code until it is rendered, while `<Suspense>` shows a fallback UI in the meantime.', '`React.lazy(() => import("./Chart"))` komponent kodini yuklashni u render qilingunga qadar kechiktiradi, `<Suspense>` esa shu vaqt ichida zaxira (fallback) interfeysini ko''rsatadi.', '`React.lazy(() => import("./Chart"))` откладывает загрузку кода компонента до момента его рендеринга, а `<Suspense>` тем временем показывает запасной интерфейс (fallback).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-advanced-q7', 'react-advanced', 7, 'advanced', 2.2, 'What is a React Portal (`ReactDOM.createPortal(child, container)`) used for?', 'React Portal (`ReactDOM.createPortal(child, container)`) nima uchun ishlatiladi?', 'Для чего используется React Portal (`ReactDOM.createPortal(child, container)`)?', 'Portals render children into a different DOM node (like `document.body`) to escape parent CSS `overflow: hidden` or `z-index` stacking contexts while preserving React event bubbling.', 'Portallar React hodisa ko''tarilishini (bubbling) saqlab qolgan holda, ona elementning CSS `overflow: hidden` yoki `z-index` cheklovlaridan chiqish uchun bolalarni boshqa DOM tuguniga (masalan, `document.body`-ga) render qiladi.', 'Порталы рендерят дочерние элементы в другой узел DOM (например, `document.body`), чтобы избежать проблем с родительскими CSS `overflow: hidden` или `z-index`, сохраняя всплытие событий по дереву React.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-advanced-q8', 'react-advanced', 8, 'advanced', 2.2, 'Why must Error Boundaries in React currently be implemented as Class Components (using `getDerivedStateFromError` or `componentDidCatch`)?', 'Nima uchun React-da Xato chegaralari (Error Boundaries) hozirda Klass komponentlari sifatida (`getDerivedStateFromError` yoki `componentDidCatch` yordamida) yozilishi shart?', 'Почему предохранители (Error Boundaries) в React должны реализовываться как классовые компоненты (с использованием `getDerivedStateFromError` или `componentDidCatch`)?', 'React has not yet introduced a Hook equivalent for catching rendering errors in the subtree, so Error Boundaries rely on class lifecycle methods.', 'React pastki daraxtdagi renderlash xatolarini tutib olish uchun hali Hook ekvivalentini taqdim etmagan, shuning uchun Error Boundaries klass hayot davri metodlariga tayanadi.', 'В React пока нет хука для перехвата ошибок рендеринга в дочернем поддереве, поэтому Error Boundaries полагаются на методы жизненного цикла классовых компонентов.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-advanced-q9', 'react-advanced', 9, 'advanced', 2.2, 'What is the purpose of the `useTransition` Hook introduced in React 18?', 'React 18 da kiritilgan `useTransition` Hook-ining maqsadi nima?', 'Какова цель хука `useTransition`, представленного в React 18?', '`useTransition` lets you wrap expensive state updates in `startTransition`, allowing urgent updates (like typing in an input) to interrupt them.', '`useTransition` og''ir holat yangilanishlarini `startTransition` ichiga o''rash imkonini beradi, bu esa shoshilinch yangilanishlarga (masalan, maydonga matn yozishga) ularni to''xtatib turishga ruxsat beradi.', '`useTransition` позволяет оборачивать ресурсоемкие обновления состояния в `startTransition`, давая срочным обновлениям (например, вводу текста) возможность прерывать их.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('react-advanced-q10', 'react-advanced', 10, 'advanced', 2.2, 'Does calling a custom Hook in two different components share the state variables inside that custom Hook between those two components?', 'Ikki xil komponentda bitta maxsus Hook-ni (Custom Hook) chaqirish ushbu Hook ichidagi holat o''zgaruvchilarini shu ikki komponent o''rtasida umumiy (shared) qiladimi?', 'Приводит ли вызов одного и того же пользовательского хука (Custom Hook) в двух разных компонентах к совместному использованию состояния внутри этого хука между компонентами?', 'Custom Hooks are a mechanism to reuse stateful logic; every time a component calls a custom Hook, all state and effects inside it are completely independent.', 'Maxsus Hook-lar — bu holat mantiqini qayta ishlatish mexanizmidir; komponent maxsus Hook-ni har safar chaqirganda, uning ichidagi barcha holat va effektlar butunlay mustaqil bo''ladi.', 'Пользовательские хуки — это механизм переиспользования логики; при каждом вызове хука в компоненте все состояния и эффекты внутри него полностью изолированы.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-alphabet-q1', 'ru-alphabet', 1, 'basic', 1, 'How many letters are in the modern Russian (Cyrillic) alphabet?', 'Hozirgi rus (kirill) alifbosida nechta harf bor?', 'Сколько букв в современном русском алфавите?', 'The modern Russian alphabet consists of 33 letters: 10 vowels, 21 consonants, and 2 signs.', 'Hozirgi rus alifbosi 33 ta harfdan iborat: 10 ta unli, 21 ta undosh va 2 ta belgi.', 'Современный русский алфавит состоит из 33 букв: 10 гласных, 21 согласной и 2 знаков.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-alphabet-q2', 'ru-alphabet', 2, 'basic', 1, 'Which two letters in the Russian alphabet do not produce any sound on their own?', 'Rus alifbosidagi qaysi ikki harf o''z holicha hech qanday tovush bildirmaydi?', 'Какие две буквы русского алфавита не обозначают звуков?', 'The hard sign (Ъ) and soft sign (Ь) modify adjacent consonants rather than producing their own sounds.', 'Ayirish belgisi (Ъ) va yumshatish belgisi (Ь) tovush bildirmaydi, balki undoshlarning talaffuziga ta''sir qiladi.', 'Твёрдый знак (Ъ) и мягкий знак (Ь) не обозначают отдельных звуков, а влияют на произношение соседних согласных.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-alphabet-q3', 'ru-alphabet', 3, 'basic', 1, 'Which Russian letter makes the "sh" sound (as in "ship"), always pronounced hard?', 'Qaysi rus harfi doimo qattiq talaffuz qilinadigan "sh" tovushini beradi?', 'Какая буква русского алфавита обозначает всегда твёрдый звук [ш]?', 'The letter Ш represents the hard voiceless retroflex fricative [ш], whereas Щ represents a soft [щ''].', 'Ш harfi doimo qattiq [ш] tovushini, Щ esa yumshoq va cho''ziq [щ''] tovushini ifodalaydi.', 'Буква Ш обозначает всегда твёрдый глухой шипящий звук [ш].') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-alphabet-q4', 'ru-alphabet', 4, 'basic', 1, 'How is the Russian letter "В" pronounced?', 'Rus alifbosidagi "В" harfi qanday talaffuz qilinadi?', 'Какой звук обозначает русская буква «В»?', 'Despite looking like the Latin B, the Cyrillic letter В represents the [v] sound.', 'Lotincha B harfiga o''xshasa-da, kirill alifbosidagi В harfi [v] tovushini ifodalaydi.', 'Буква «В» в русском алфавите обозначает звонкий согласный звук [в] или мягкий [в''].') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-alphabet-q5', 'ru-alphabet', 5, 'intermediate', 1.5, 'How many vowel letters (гласные буквы) exist in the Russian alphabet?', 'Rus alifbosida nechta unli harf (гласные буквы) mavjud?', 'Сколько гласных букв в русском алфавите?', 'There are 10 vowel letters in Russian: А, Е, Ё, И, О, У, Ы, Э, Ю, Я (representing 6 vowel phonemes).', 'Rus tilida 10 ta unli harf bor: А, Е, Ё, И, О, У, Ы, Э, Ю, Я (ular 6 ta unli tovushni beradi).', 'В русском алфавите 10 гласных букв: А, Е, Ё, И, О, У, Ы, Э, Ю, Я (и 6 гласных звуков).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-alphabet-q6', 'ru-alphabet', 6, 'intermediate', 1.5, 'Which group lists all four iotated vowels (vowels that can represent two sounds like [йа])?', 'Quyidagi qatorlardan qaysi birida ikki tovush berishi mumkin bo''lgan 4 ta unli harf ko''rsatilgan?', 'В каком ряду перечислены все четыре йотированные гласные буквы, которые могут обозначать два звука?', 'The letters Е, Ё, Ю, Я produce two sounds ([йэ], [йо], [йу], [йа]) at the start of a word, after vowels, or after Ъ/Ь.', 'Е, Ё, Ю, Я harflari so''z boshida, unlilardan keyin hamda Ъ va Ь belgilaridan keyin ikki tovushni ifodalaydi.', 'Буквы Е, Ё, Ю, Я обозначают два звука в начале слова, после гласных и после Ъ и Ь.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-alphabet-q7', 'ru-alphabet', 7, 'intermediate', 1.5, 'Which consonants in Russian are ALWAYS hard (всегда твёрдые), regardless of the following vowel?', 'Rus tilida qaysi undosh tovushlar o''zidan keyin kelgan harfdan qat''i nazar DOIMO qattiq talaffuz qilinadi?', 'Какие согласные звуки в русском языке являются всегда твёрдыми?', 'In Russian phonetics, [ж], [ш], and [ц] are unpaired hard consonants and are always pronounced hard.', 'Rus fonetikasida [ж], [ш] va [ц] undoshlari doimo qattiq talaffuz qilinadi.', 'Звуки [ж], [ш], [ц] в русском языке не имеют мягких пар и всегда остаются твёрдыми.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-alphabet-q8', 'ru-alphabet', 8, 'intermediate', 1.5, 'Which consonants in Russian are ALWAYS soft (всегда мягкие)?', 'Rus tilida qaysi undosh tovushlar DOIMO yumshoq (всегда мягкие) hisoblanadi?', 'Какие согласные звуки в русском языке являются всегда мягкими?', 'The consonants [й''], [ч''], and [щ''] have no hard counterparts and are always pronounced soft.', 'Rus tilida [й''], [ч''] va [щ''] tovushlari doimo yumshoq talaffuz qilinadi.', 'Согласные звуки [й''], [ч''], [щ''] в русском языке всегда мягкие и не имеют твёрдых пар.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-alphabet-q9', 'ru-alphabet', 9, 'advanced', 2.2, 'How many sounds and letters are in the Russian word "яблоко" (apple)?', 'Rus tilidagi "яблоко" (olma) so''zida nechta harf va nechta tovush bor?', 'Сколько букв и звуков в слове «яблоко»?', 'The initial letter "я" stands for two sounds [й''] and [а], giving 6 letters and 7 sounds ([й''аблака]).', 'So''z boshidagi "я" harfi ikki tovushni ([й''] va [а]) bergani uchun 6 ta harf va 7 ta tovush bor.', 'Буква «я» в начале слова обозначает два звука [й''] и [а], поэтому в слове 6 букв и 7 звуков.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-alphabet-q10', 'ru-alphabet', 10, 'advanced', 2.2, 'How is the unstressed letter "о" pronounced in standard Russian in the word "молоко" (milk)?', 'Adabiy rus tilida "молоко" (sut) so''zidagi urg''usiz "о" harflari qanday talaffuz qilinadi?', 'Как произносятся безударные гласные «о» в слове «молоко» в русском литературном языке?', 'In standard Russian, unstressed "о" undergoes vowel reduction (akanye) and sounds close to [а]: [малако́].', 'Adabiy rus tilida urg''usiz "о" unlisi reduksiyaga uchrab, [а] tovushiga yaqin talaffuz qilinadi: [малако́].', 'В безударном положении гласный «о» редуцируется (явление аканья), и слово произносится как [малако́].') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-vocabulary-q1', 'ru-vocabulary', 1, 'basic', 1, 'What does the Russian greeting "Здравствуйте" mean?', 'Rus tilidagi "Здравствуйте" salomlashish so''zi nimani anglatadi?', 'Что означает русское приветствие «Здравствуйте»?', '"Здравствуйте" is the standard formal greeting in Russian, literally wishing the listener good health.', '"Здравствуйте" — rus tilidagi rasmiy salomlashish shakli bo''lib, tinglovchiga sog''lik tilash ma''nosidan kelib chiqqan.', '«Здравствуйте» — вежливое приветствие, этимологически означающее пожелание здоровья.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-vocabulary-q2', 'ru-vocabulary', 2, 'basic', 1, 'Which Russian word means "thank you"?', 'Rus tilida qaysi so''z "rahmat" ma''nosini bildiradi?', 'Какое слово используется в русском языке для выражения благодарности?', '"Спасибо" means "thank you" (derived historically from "Спаси Бог" — "May God save you").', '"Спасибо" so''zi "rahmat" degan ma''noni anglatadi.', 'Слово «спасибо» выражает благодарность (исторически от «спаси Бог»).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-vocabulary-q3', 'ru-vocabulary', 3, 'basic', 1, 'What does the Russian word "семья" mean?', 'Rus tilidagi "семья" so''zi o''zbek tiliga qanday tarjima qilinadi?', 'Что означает русское слово «семья»?', '"Семья" means "family" in Russian.', '"Семья" so''zi o''zbek tilida "oila" degan ma''noni bildiradi.', 'Слово «семья» обозначает группу близких родственников.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-vocabulary-q4', 'ru-vocabulary', 4, 'basic', 1, 'Which days of the week do "вчера, сегодня, завтра" refer to?', 'Rus tilidagi "вчера, сегодня, завтра" so''zlari qanday tarjima qilinadi?', 'Что обозначают наречия времени «вчера, сегодня, завтра»?', '"Вчера" means yesterday, "сегодня" means today, and "завтра" means tomorrow.', '"Вчера" — kecha, "сегодня" — bugun, "завтра" — ertaga degan ma''noni anglatadi.', 'Эти наречия обозначают вчерашний, сегодняшний и завтрашний дни.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-vocabulary-q5', 'ru-vocabulary', 5, 'intermediate', 1.5, 'Which word is the exact antonym (opposite) of "горячий" (hot)?', '"Горячий" (issiq) sifatining antonimi (zid ma''nolisi) qaysi?', 'Какое слово является антонимом к прилагательному «горячий»?', '"Холодный" means "cold", which is the direct opposite of "горячий" (hot).', '"Холодный" (sovuq) so''zi "горячий" (issiq) so''zining zid ma''nolisidir.', 'Прилагательное «холодный» является прямым антонимом к слову «горячий».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-vocabulary-q6', 'ru-vocabulary', 6, 'intermediate', 1.5, 'What is the difference between the Russian adjectives "молодой" and "новый"?', 'Rus tilidagi "молодой" va "новый" sifatlari o''rtasida qanday ma''no farqi bor?', 'В чём разница в употреблении прилагательных «молодой» и «новый»?', '"Молодой" describes youth in people, animals, or plants, whereas "новый" describes something newly made or acquired.', '"Молодой" tirik mavjudotlarning yoshini, "новый" esa yangi yaratilgan yoki olingan narsalarni ifodalaydi.', 'Слово «молодой» характеризует небольшой возраст живых существ, а «новый» — недавно появившиеся предметы.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-vocabulary-q7', 'ru-vocabulary', 7, 'intermediate', 1.5, 'Notice the false friend: what does the Russian word "неделя" mean?', 'Rus tilidagi "неделя" so''zi nimani anglatadi?', 'Что означает русское существительное «неделя»?', 'In modern Russian, "неделя" means a week (seven days from Monday to Sunday).', 'Zamonaviy rus tilida "неделя" so''zi "hafta" (7 kun) degan ma''noni bildiradi.', 'В современном русском языке «неделя» — это единица времени, равная семи дням.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-vocabulary-q8', 'ru-vocabulary', 8, 'intermediate', 1.5, 'Which word is a synonym for "красивый" (beautiful/handsome)?', '"Красивый" (chiroyli, go''zal) so''zining sinonimi qaysi qatorda berilgan?', 'Какое слово является синонимом к прилагательному «красивый»?', '"Прекрасный" (wonderful, very beautiful) is a close synonym of "красивый".', '"Прекрасный" (go''zal, betakror) so''zi "красивый" sifatining sinonimidir.', 'Прилагательное «прекрасный» близко по значению к слову «красивый» и означает «очень красивый».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-vocabulary-q9', 'ru-vocabulary', 9, 'advanced', 2.2, 'What does the Russian idiom "рукой подать" mean?', 'Rus tilidagi "рукой подать" iborasi qanday ma''noni anglatadi?', 'Что означает русский фразеологизм «рукой подать»?', 'The idiom "рукой подать" literally translates to "within a hand''s reach" and means "very close".', '"Рукой подать" frazeologizmi "juda yaqin, bir qadam" degan ma''noni bildiradi.', 'Фразеологизм «рукой подать» означает «очень близко, на совсем небольшом расстоянии».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-vocabulary-q10', 'ru-vocabulary', 10, 'advanced', 2.2, 'Choose the correct paronym: "На улице был сильный, ___ день." (It was a windy day outside.)', 'To''g''ri paronimni tanlang: "На улице был сильный, ___ день." (Tashqarida shamolli kun edi.)', 'Выберите правильный пароним для предложения: «Осенью выдался холодный и ___ день».', '"Ветреный" means windy (or frivolous for a person), whereas "ветряной" means wind-powered (e.g. ветряная мельница — windmill).', 'Ob-havoga nisbatan "ветреный" (shamolli) so''zi, shamol kuchi bilan ishlaydigan mexanizmlarga nisbatan esa "ветряной" ishlatiladi.', 'О погоде с ветром говорят «ветреный день», тогда как «ветряной» означает приводимый в движение ветром (ветряная мельница).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-grammar-q1', 'ru-grammar', 1, 'basic', 1, 'How many grammatical cases (падежи) are there in modern Russian?', 'Hozirgi rus tilida nechta kelishik (падеж) mavjud?', 'Сколько падежей в современном русском языке?', 'Russian has 6 grammatical cases: Nominative, Genitive, Dative, Accusative, Instrumental, and Prepositional.', 'Rus tilida 6 ta kelishik mavjud: Именительный, Родительный, Дательный, Винительный, Творительный, Предложный.', 'В русском языке 6 падежей: именительный, родительный, дательный, винительный, творительный и предложный.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-grammar-q2', 'ru-grammar', 2, 'basic', 1, 'Which Russian case answers the questions "Кто? Что?" (Who? What?) and serves as the dictionary form?', 'Qaysi kelishik "Кто? Что?" (Kim? Nima?) savollariga javob bo''lib, so''zning boshlang''ich shakli hisoblanadi?', 'Какой падеж отвечает на вопросы «Кто? Что?» и является начальной формой слова?', 'The Nominative case (Именительный падеж) answers "Кто? Что?" and marks the subject of a sentence.', 'Именительный падеж (Bosh kelishik) "Кто? Что?" savollariga javob beradi va gapning egasini ifodalaydi.', 'Именительный падеж отвечает на вопросы «Кто? Что?» и является начальной формой существительного.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-grammar-q3', 'ru-grammar', 3, 'basic', 1, 'Which form of the adjective "новый" (new) agrees with the feminine noun "книга" (book)?', '"Книга" (kitob — женский род) oti bilan "новый" sifatining qaysi shakli moslashadi?', 'Какая форма прилагательного «новый» правильно согласуется с существительным женского рода «книга»?', 'Since "книга" is feminine singular in the nominative case, the adjective takes the feminine ending -ая: "новая книга".', '"Книга" so''zi женский род (ayol jinsi) birlikda bo''lgani uchun sifat ham -ая qo''shimchasini oladi: "новая книга".', 'Существительное «книга» женского рода, поэтому прилагательное принимает окончание -ая: «новая книга».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-grammar-q4', 'ru-grammar', 4, 'intermediate', 1.5, 'Complete the sentence using the Genitive case after "нет": "У меня нет ___ (брат)."', '"Нет" so''zidan keyin Родительный падеж shaklini qo''ying: "У меня нет ___ (брат)."', 'Поставьте слово в правильном падеже: «У меня нет ___ (брат)».', 'Negation of possession with "нет" requires the Genitive case (Родительный падеж: кого? чего? — брата).', 'Rus tilida "нет" (yo''q) so''zidan keyin ot Родительный падеж (кого? чего? — брата) shaklida keladi.', 'При отрицании со словом «нет» используется родительный падеж (нет кого? — брата).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-grammar-q5', 'ru-grammar', 5, 'intermediate', 1.5, 'Which case is required after the preposition "в" when answering "Где?" (Where / location): "Я живу в ___ (Москва)"?', '"Где?" (Qayerda?) savoliga javob berilganda "в" predlogidan keyin qaysi shakl ishlatiladi: "Я живу в ___ (Москва)"?', 'Какая форма используется для обозначения места (Где?): «Я живу в ___ (Москва)»?', 'Static location ("Где?" — Where?) with "в" or "на" uses the Prepositional case (Предложный падеж): в Москве.', 'Harakat yo''nalishini emas, balki joylashuvni ("Где?" — Qayerda?) bildirganda Предложный падеж ishlatiladi: в Москве.', 'Для обозначения местонахождения (вопрос «Где?») с предлогами «в» и «на» употребляется предложный падеж: в Москве.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-grammar-q6', 'ru-grammar', 6, 'intermediate', 1.5, 'Complete the sentence in the Instrumental case (Творительный падеж): "Он пишет ___ (ручка)." (He writes with a pen.)', 'Творительный падеж shaklini tanlang: "Он пишет ___ (ручка)." (U ruchka bilan yozyapti.)', 'Выберите правильную форму творительного падежа: «Он пишет ___ (ручка)».', 'The instrument or tool used to perform an action is expressed in the Instrumental case (чем? — ручкой) without a preposition.', 'Ish-harakat bajariladigan qurol Творительный падеж (чем? — ручкой) orqali predlogsiz ifodalanadi.', 'Орудие действия в русском языке выражается творительным падежом без предлога: пишет (чем?) ручкой.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-grammar-q7', 'ru-grammar', 7, 'intermediate', 1.5, 'How do you correctly say "I am 20 years old" in Russian?', 'Rus tilida "Men 20 yoshdaman" deb qanday to''g''ri aytiladi?', 'Как правильно сказать по-русски о возрасте: «___ двадцать лет»?', 'In Russian, age is expressed using an impersonal Dative construction: "Мне (Кому?) двадцать лет".', 'Rus tilida yoshni ifodalashda shaxs olmoshi Дательный падеж (Кому? — Мне) shaklida qo''llanadi.', 'При указании возраста лицо ставится в дательном падеже (Кому?): «Мне двадцать лет».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-grammar-q8', 'ru-grammar', 8, 'advanced', 2.2, 'Which form of the noun follows the numeral 5 in nominative/accusative contexts: "пять ___"?', '5 (пять) sonidan keyin "книга" oti qaysi shaklda keladi: "пять ___"?', 'Какая форма существительного используется после числительного «пять»: «пять ___»?', 'Numerals from 5 to 20 require the Genitive Plural (Родительный падеж множественного числа): пять книг.', '5 dan 20 gacha bo''lgan sonlardan keyin otlar Родительный падеж ko''plik shaklida keladi: пять книг.', 'После числительных от пяти до двадцати существительное ставится в родительном падеже множественного числа: пять книг.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-grammar-q9', 'ru-grammar', 9, 'advanced', 2.2, 'Choose the correct form of the relative pronoun "который": "Вот книга, ___ я вчера прочитал." (Here is the book that I read yesterday.)', '"Который" nisbiy olmoshining to''g''ri shaklini tanlang: "Вот книга, ___ я вчера прочитал."', 'Выберите правильную форму союзного слова «который»: «Вот книга, ___ я вчера прочитал».', '"Который" agrees in gender and number with "книга" (feminine singular), and takes its case from its role in the subordinate clause (прочитал что? — Винительный падеж: которую).', '"Который" jins va sonda "книга" (жен. род) bilan moslashadi, kelishigi esa ergash gapdagi vazifasiga ko''ra Винительный падеж (прочитал что? — которую) bo''ladi.', 'Слово «который» согласуется в роде и числе со словом «книга», а падеж зависит от глагола «прочитал» (прочитал что? — В. п.: которую).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-grammar-q10', 'ru-grammar', 10, 'advanced', 2.2, 'Which case does the preposition "благодаря" (thanks to / owing to) govern in Russian?', 'Rus tilidagi "благодаря" (tufayli, sharofati bilan) predlogi o''zidan keyin qaysi kelishikni talab qiladi?', 'Какого падежа требует производный предлог «благодаря»?', 'The prepositions "благодаря", "согласно", and "вопреки" always govern the Dative case (благодаря кому? чему? — благодаря помощи).', '"Благодаря", "согласно", "вопреки" predloglari doimo Дательный падеж (кому? чему?) kelishigini talab qiladi.', 'Производные предлоги «благодаря», «согласно», «вопреки» управляют только дательным падежом (благодаря кому? чему?).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-verbs-q1', 'ru-verbs', 1, 'basic', 1, 'What is the standard infinitive ending of most Russian verbs ( answering "Что делать?")?', 'Rus tilidagi ko''pchilik fe''llarning noaniq shakli (инфинитив) qaysi qo''shimcha bilan tugaydi?', 'На что обычно оканчивается неопределённая форма (инфинитив) русских глаголов?', 'Russian verb infinitives typically end in -ть (читать, говорить), and less commonly in -ти (идти) or -чь (печь).', 'Rus tilida инфинитив shaklidagi fe''llar odatda -ть (читать, говорить), ba''zan -ти (идти) yoki -чь (печь) bilan tugaydi.', 'Инфинитив русских глаголов обычно оканчивается на -ть (читать), реже на -ти (идти) или -чь (мочь).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-verbs-q2', 'ru-verbs', 2, 'basic', 1, 'Choose the correct present-tense form for "Мы" (We): "Мы ___ (читать) книгу."', '"Мы" (Biz) olmoshi uchun hozirgi zamon fe''l shaklini tanlang: "Мы ___ (читать) книгу."', 'Выберите правильную форму настоящего времени: «Мы ___ (читать) книгу».', 'For the 1st person plural ("мы") of a 1st-conjugation verb like "читать", the ending is -ем: "мы читаем".', 'I tuslanishdagi "читать" fe''ли 1-shaxs ko''plikda ("мы") -ем qo''shimchasini oladi: "мы читаем".', 'В первом лице множественного числа («мы») глагол I спряжения «читать» имеет форму «читаем».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-verbs-q3', 'ru-verbs', 3, 'basic', 1, 'Which verb belongs to the 2nd conjugation (II спряжение)?', 'Quyidagi fe''llardan qaysi biri II tuslanishga (II спряжение) mansub?', 'Какой из перечисленных глаголов относится ко II спряжению?', 'Most verbs ending in -ить in the infinitive (like "говорить" — мы говорим, они говорят) belong to the 2nd conjugation.', 'Инфинитивда -ить bilan tugaydigan aksariyat fe''llar (masalan, "говорить" — они говорят) II спряжение гуруҳига киради.', 'Глагол «говорить» оканчивается в инфинитиве на -ить и относится ко II спряжению (они говорят).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-verbs-q4', 'ru-verbs', 4, 'basic', 1, 'How do Russian verbs agree with the subject in the Past Tense (Прошедшее время)?', 'Rus tilida o''tgan zamon (Прошедшее время) fe''llari ega bilan qaysi grammatik kategoriyalarda moslashadi?', 'По каким грамматическим признакам изменяются русские глаголы в прошедшем времени?', 'In the past tense, Russian verbs change by gender in the singular (он читал, она читала, оно читало) and by number (они читали), not by person.', 'O''tgan zamonda rus fe''llari shaxs bo''yicha emas, balki jins (он читал, она читала, оно читало) va son (они читали) bo''yicha o''zгаради.', 'В прошедшем времени глаголы изменяются по числам, а в единственном числе — по родам.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-verbs-q5', 'ru-verbs', 5, 'intermediate', 1.5, 'What is the difference between "делать" (несовершенный вид) and "сделать" (совершенный вид)?', '"Делать" (несовершенный вид) va "сделать" (совершенный вид) fe''llari o''rtasida qanday farq bor?', 'В чём заключается различие между глаголами «делать» (несовершенный вид) и «сделать» (совершенный вид)?', 'Imperfective verbs (несовершенный вид, "что делать?") describe ongoing/repeated processes, while perfective verbs (совершенный вид, "что сделать?") describe completed actions.', 'Несовершенный вид (что делать?) davomiy yoki takroriy jarayonni, совершенный вид (что сделать?) esa tugallangan natijali harakatni ifodalaydi.', 'Глаголы несовершенного вида обозначают процесс или повторяемость, а совершенного вида — завершённость и результат.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-verbs-q6', 'ru-verbs', 6, 'intermediate', 1.5, 'Choose the correct verb of motion: "Сейчас я ___ в школу пешком." (Right now I am walking to school on foot — one direction.)', 'Harakat fe''lini tanlang: "Сейчас я ___ в школу пешком." (Hozir men maktabga piyoda ketyapman — bir yo''nalishda.)', 'Выберите правильный глагол движения: «Сейчас я ___ в школу пешком (в одном направлении)».', '"Иду" (from "идти") describes movement on foot in a single direction happening right now, whereas "хожу" describes habitual or multi-directional walking.', 'Ayni paytda bir yo''nalishda piyoda ketayotganda "идти" ("я иду") fe''li, doimiy qatnashda esa "ходить" ("я хожу") ishlatiladi.', 'Глагол «идти» («я иду») обозначает движение пешком в одном направлении в данный момент.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-verbs-q7', 'ru-verbs', 7, 'intermediate', 1.5, 'Which sentence correctly uses the compound future tense (будущее сложное время) of an imperfective verb?', 'Qaysi gapda несовершенный вид fe''lining murakkab kelasi zamon (будущее сложное) shakli to''g''ri qo''llangan?', 'В каком предложении правильно образовано будущее сложное время глагола несовершенного вида?', 'The compound future tense is formed with conjugated "быть" (буду, будешь...) + imperfective infinitive (читать): "буду читать".', 'Murakkab kelasi zamon "быть" ko''makchi fe''ли (буду, будешь...) va несовершенный вид инфинитивидан yasaladi: "буду читать".', 'Будущее сложное время образуется из личной формы глагола «быть» и инфинитива глагола несовершенного вида: «буду читать».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-verbs-q8', 'ru-verbs', 8, 'intermediate', 1.5, 'How do you correctly say "I like studying" using the reflexive verb "нравиться"?', '"Нравиться" o''zlik fe''lidan foydalanib "Menga o''qish yoqadi" deb qanday to''g''ri yoziladi?', 'В каком варианте правильно употреблены формы на -тся / -ться: «Мне (нравит?ся) (учит?ся)»?', '"Нравится" answers "что делает?" (3rd person singular, no Ь), while "учиться" answers "что делать?" (infinitive, with Ь).', '"Нравится" so''rog''i "что делает?" (Ь belgisiz), "учиться" so''rog''i esa "что делать?" (инфинитив, Ь belgisi bilan) bo''ladi.', 'Глагол «нравится» отвечает на вопрос «что делает?» (пишется без Ь), а инфинитив «учиться» — на вопрос «что делать?» (с Ь).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-verbs-q9', 'ru-verbs', 9, 'advanced', 2.2, 'Which of these verbs ending in "-ить" is an EXCEPTION that conjugates according to the 1st conjugation?', 'Quyidagi "-ить" bilan tugaydigan fe''llardan qaysi biri istisno tariqasida I спряжение bo''yicha tuslanadi?', 'Какой из глаголов на -ить является исключением и относится к I спряжению?', 'The verbs "брить" (бреешь, бреют) and "стелить" (стелешь, стелют) end in -ить but are exceptions belonging to the 1st conjugation.', '"Брить" (бреют) va "стелить" (стелют) fe''llari -ить bilan tugasa-da, istisno sifatida I спряжение гуруҳига киради.', 'Глаголы «брить» и «стелить» являются исключениями и спрягаются по I спряжению (ты бреешь, они бреют).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-verbs-q10', 'ru-verbs', 10, 'advanced', 2.2, 'Identify the correct active past participle (действительное причастие прошедшего времени) of the verb "прочитать":', '"Прочитать" fe''lidan yasalgan o''tgan zamon aniq sifatdoshini (действительное причастие прошедшего времени) toping:', 'Укажите действительное причастие прошедшего времени, образованное от глагола «прочитать»:', 'Active past participles are formed with the suffix -вш- or -ш- added to the past stem: прочита-ть -> прочитавший (the one who read).', 'Действительное причастие прошедшего времени -вш- (yoki -ш-) suffiksi yordamida yasaladi: прочитавший (o''qib chiqqan odam).', 'Действительное причастие прошедшего времени образуется с помощью суффикса -вш-: «прочитавший».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-nouns-q1', 'ru-nouns', 1, 'basic', 1, 'What are the three grammatical genders of Russian nouns in the singular?', 'Rus tilida otlarning birlikdagi uchta grammatik jinsi (род) qaysilar?', 'Какие три грамматических рода имеют имена существительные в русском языке?', 'Every Russian noun belongs to one of three grammatical genders: мужской род (он), женский род (она), or средний род (оно).', 'Rus tilidagi har bir ot uchta grammatik jinsdan biriga mansub: мужской род (он), женский род (она) yoki средний род (оно).', 'В русском языке существительные распределяются по трём родам: мужскому, женскому и среднему.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-nouns-q2', 'ru-nouns', 2, 'basic', 1, 'What is the grammatical gender of the nouns "окно" (window) and "море" (sea)?', '"Окно" (deraza) va "море" (dengiz) otlari qaysi grammatik jinsga (род) mansub?', 'К какому роду относятся существительные «окно» и «море»?', 'Nouns ending in -о or -е in the nominative singular (like окно, море) are typically neuter (средний род — оно).', 'Bosh kelishikda -о yoki -е bilan tugaydigan otlar (окно, море) средний род (оно) hisoblanadi.', 'Существительные с окончаниями -о и -е в начальной форме относятся к среднему роду (оно моё).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-nouns-q3', 'ru-nouns', 3, 'basic', 1, 'What is the grammatical gender of the nouns "папа" (dad), "дядя" (uncle), and "дедушка" (grandfather)?', '"Папа" (dada), "дядя" (amaki/tog''a) va "дедушка" (bobo) so''zlari qaysi rodga киради?', 'К какому роду относятся существительные «папа», «дядя» и «дедушка»?', 'Although "папа", "дядя", and "дедушка" end in -а/-я (1st declension), they are masculine (мой папа, добрый дедушка) because they refer to male family members.', 'Bu so''zlar -а/-я bilan tugasa-da, erkak kishilarni anglatgani sababli мужской род (мой папа, мой дедушка) hisoblanadi.', 'Несмотря на окончания -а/-я, эти слова относятся к мужскому роду по биологическому признаку (мой дедушка).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-nouns-q4', 'ru-nouns', 4, 'basic', 1, 'How do animate (одушевлённые) and inanimate (неодушевлённые) nouns differ in Russian?', 'Rus tilida shaxs/jonzot otlari (одушевлённые) va narsa otlari (неодушевлённые) qaysi so''roqlarga javob beradi?', 'На какие вопросы отвечают одушевлённые и неодушевлённые имена существительные?', 'In Russian grammar, living beings (people and animals) are animate and answer "Кто?" (Who?), whereas objects, plants, and phenomena are inanimate and answer "Что?" (What?).', 'Rus tilida odamlar va hayvonlar одушевлённые bo''lib "Кто?" savoliga, buyumlar, o''simliklar va hodisalar esa неодушевлённые bo''lib "Что?" savoliga javob beradi.', 'Одушевлённые существительные называют живых существ и отвечают на вопрос «Кто?», а неодушевлённые — на вопрос «Что?».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-nouns-q5', 'ru-nouns', 5, 'intermediate', 1.5, 'What is the grammatical gender of the noun "тетрадь" (notebook) vs. "словарь" (dictionary), both ending in soft sign (-ь)?', 'Ikkalasi ham yumshatish belgisi (-ь) bilan tugaydigan "тетрадь" (daftar) va "словарь" (lug''at) otlarining jinsi qanday?', 'Какого рода существительные «тетрадь» и «словарь», оканчивающиеся на мягкий знак (-ь)?', 'Nouns ending in -ь can be either feminine (моя тетрадь, ночь) or masculine (мой словарь, день), so their gender must be learned or checked.', '-Ь bilan tugaydigan otlar женский род (моя тетрадь) yoki мужской род (мой словарь) bo''lishi mumkin.', 'Существительные на мягкий знак могут быть как женского рода (моя тетрадь), так и мужского рода (мой словарь).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-nouns-q6', 'ru-nouns', 6, 'intermediate', 1.5, 'What are the irregular nominative plural forms of "человек" (person) and "ребёнок" (child)?', '"Человек" (odam) va "ребёнок" (bola) otlarining ko''plik (множественное число) shakли qaysi?', 'Каковы супплетивные формы именительного падежа множественного числа для слов «человек» и «ребёнок»?', 'In the nominative plural, "человек" becomes "люди" (people) and "ребёнок" becomes "дети" (children) or "ребята".', 'Бош келишик кўпликда "человек" сўзи "люди"га, "ребёнок" сўзи эса "дети" шаклига ўтади.', 'В именительном падеже множественного числа от слов «человек» и «ребёнок» образуются супплетивные формы «люди» и «дети».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-nouns-q7', 'ru-nouns', 7, 'intermediate', 1.5, 'Which group of nouns consists ONLY of 3rd-declension (III склонение) nouns?', 'Qaysi qatorda faqat 3-turlanishga (III склонение) kiruvchi otlar berilgan?', 'В каком ряду все существительные относятся к 3-му склонению?', 'The 3rd declension includes feminine nouns ending in a soft sign (-ь) in the nominative singular: ночь, мышь, тетрадь.', '3-turlanishga (III склонение) женский роддаги -ь bilan tugaydigan otlar kiradi: ночь, мышь, тетрадь.', 'К 3-му склонению относятся имена существительные женского рода с нулевым окончанием и мягким знаком на конце: ночь, мышь, тетрадь.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-nouns-q8', 'ru-nouns', 8, 'intermediate', 1.5, 'What is the correct Nominative Plural form of "дом" (house) and "город" (city)?', '"Дом" (uy) va "город" (shahar) otlarining ko''plik shakli (множественное число) qanday bo''ladi?', 'Как правильно образуется форма именительного падежа множественного числа от слов «дом» и «город»?', 'Several common masculine nouns form their nominative plural with a stressed "-а́" ending instead of "-ы/-и": дома́, города́, паспорта́, поезда́.', 'Ba''zi мужской род otlari ko''plikda urg''uli "-а́" qo''shimchasini oladi: дома́, города́, поезда́.', 'Ряд существительных мужского рода в именительном падеже множественного числа имеет ударное окончание -а́: дома́, города́.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-nouns-q9', 'ru-nouns', 9, 'advanced', 2.2, 'What is the grammatical gender of the indeclinable noun "кофе" (coffee) and "пальто" (coat) in standard Russian?', 'Turlanmaydigan "кофе" (qahva) va "пальто" (palto) otlarining adabiy rus tilidagi jinsi (род) qanday?', 'Какого рода несклоняемые существительные «кофе» и «пальто» по строгой литературной норме?', 'In strict literary Russian, "кофе" is masculine (горячий кофе), while inanimate indeclinable loanwords like "пальто", "метро", "такси" are neuter.', 'Adabiy me''yorga ko''ra "кофе" мужской род (горячий кофе), "пальто", "метро", "такси" kabi o''zlashма otlar esa средний род hisoblanadi.', 'По строгой литературной норме «кофе» относится к мужскому роду (крепкий кофе), а «пальто» — к среднему роду (зимнее пальто).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-nouns-q10', 'ru-nouns', 10, 'advanced', 2.2, 'Which group contains nouns that are used ONLY in the plural (pluralia tantum) in Russian?', 'Qaysi qatordagi otlar rus tilida FAQAT ko''plikda (только во множественном числе) qo''llanadi?', 'В каком ряду все существительные употребляются только во множественном числе?', 'Nouns like "ножницы" (scissors), "очки" (glasses), "каникулы" (school holidays), and "сутки" (24-hour day) have no singular form in Russian.', '"Ножницы" (qaychi), "очки" (ko''zoynak), "каникулы" (ta''til) va "сутки" (sutka) otlari rus tilida birlik shakliga ega emas.', 'Существительные «ножницы», «очки», «каникулы», «сутки» не имеют форм единственного числа.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-sentences-q1', 'ru-sentences', 1, 'basic', 1, 'How do you say "My brother is a student" in present-tense Russian?', 'Rus tilida hozirgi zamonda "Mening akam — talaba" gapi qanday tuziladi?', 'Как правильно построить предложение в настоящем времени: «Мой брат — ___»?', 'In modern Russian, the present-tense link verb "есть" (to be) is omitted, and a dash (тире) is placed between two nominative nouns.', 'Zamonaviy rus tilida hozirgi zamonda "есть" bog''lamasi tushib qoladi va ikki bosh kelishikdagi ot orasiga tire (—) qo''yiladi.', 'В настоящем времени глагол-связка «есть» опускается, а между подлежащим и сказуемым, выраженными существительными в И. п., ставится тире.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-sentences-q2', 'ru-sentences', 2, 'basic', 1, 'Which conjunction is used in Russian to express contrast ("but"), always preceded by a comma?', 'Rus tilida zidlikni ("lekin, ammo") ifodalovchi va oldidan doimo vergul qo''yiladigan bog''lovchi qaysi?', 'Какой противительный союз используется для противопоставления и всегда отделяется запятой?', '"Но" (and "а") are adversative conjunctions meaning "but/whereas", and a comma is always placed before them.', '"Но" (hamda "а") zidlov bog''lovchisi bo''lib, yozuvda undan oldin doimo vergul qo''yiladi.', 'Перед противительными союзами «но» и «а» в русском предложении всегда ставится запятая.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-sentences-q3', 'ru-sentences', 3, 'basic', 1, 'Which sentence uses the standard "У меня есть..." construction to say "I have a new book"?', '"Menda yangi kitob bor" mazmunini ifodalovchi to''g''ri ruscha gapni toping:', 'Какое предложение правильно передаёт значение обладания («I have a new book»)?', 'In the "У меня есть..." construction, the possessed item ("новая книга") is the grammatical subject and stands in the Nominative case.', '"У меня есть..." qurilmasida bor bo''lgan narsa ("новая книга") gapning grammatik egasi bo''lib, Именительный падеж shaklida keladi.', 'В конструкции «У меня есть...» предмет обладания является грамматическим подлежащим и стоит в именительном падеже: «новая книга».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-sentences-q4', 'ru-sentences', 4, 'intermediate', 1.5, 'What is the difference between the conjunctions "что" and "чтобы" in complex sentences?', 'Ergash gapli qo''shma gaplarda "что" va "чтобы" bog''lovchilari qanday farqlanadi?', 'В чём разница между союзами «что» и «чтобы» в сложноподчинённых предложениях?', '"Что" introduces factual clauses ("I know that..."), whereas "чтобы" introduces purpose or wish clauses ("in order to..." / "I want someone to...") and takes a past-tense verb form or infinitive.', '"Что" bog''lovchisi faktni ("Men bilamanki..."), "чтобы" esa maqsad yoki istakni ("...uchun" / "Men xohlaymanki...") bildiradi.', 'Союз «что» вводит придаточные изъяснительные о фактах, а «чтобы» выражает цель или желаемое действие.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-sentences-q5', 'ru-sentences', 5, 'intermediate', 1.5, 'How does word order affect meaning in "Поезд пришёл в восемь часов" vs. "В восемь часов пришёл поезд"?', '"Поезд пришёл в восемь часов" va "В восемь часов пришёл поезд" gaplarida so''z tartibi ma''noga qanday ta''sir qiladi?', 'Как порядок слов влияет на смысл в предложениях «Поезд пришёл в восемь часов» и «В восемь часов пришёл поезд»?', 'Russian uses flexible word order for topic-focus (theme-rheme) structure: the first sentence tells WHEN the train arrived, while the second tells WHAT arrived at 8 o''clock.', 'Rus tilida yangi ma''lumot (рема) gap oxirida keladi: birinchi gapda poyezd QACHON kelgani, ikkinchisida esa soat 8 da NIMA kelgani muhim.', 'В русском языке актуальное членение предложения ставит новую информацию (рему) в конец фразы.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-sentences-q6', 'ru-sentences', 6, 'intermediate', 1.5, 'Which sentence is an impersonal sentence (безличное предложение) describing a state of nature or person?', 'Qaysi gap tabiat yoki inson holatini ifodalovchi shaxssiz gap (безличное предложение) hisoblanadi?', 'Какое из предложений является безличным?', '"На улице сегодня холодно" is an impersonal sentence (безличное предложение) because it has no grammatical subject in the nominative case and cannot have one.', '"На улице сегодня холодно" gapida bosh kelishikdagi ega yo''q va bo''lishi ham mumkin emas — bu безличное предложение.', 'В предложении «На улице сегодня холодно» нет и не может быть подлежащего — это безличное предложение.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-sentences-q7', 'ru-sentences', 7, 'intermediate', 1.5, 'How do you form an indirect yes/no question ("He asked whether I would come") in Russian?', 'Rus tilida o''zlashtirma so''roq gap ("U mening kelish-kelmasligimni so''radi") qaysi yuklama yordamida tuziladi?', 'Как правильно оформить косвенный вопрос («Он спросил, ...»)?', 'Indirect yes/no questions in Russian use the particle "ли" placed immediately after the questioned word (usually the verb), not "если": "Он спросил, приду ли я."', 'Rus tilida "whether/if" ma''nosidagi o''zlashtirma so''roqda "если" emas, balki fe''ldan keyin keladigan "ли" yuklamasi ishlatiladi: "Он спросил, приду ли я."', 'В косвенном вопросе используется частица «ли», которая ставится сразу после слова, на которое падает логическое ударение (обычно глагола).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-sentences-q8', 'ru-sentences', 8, 'advanced', 2.2, 'Which sentence is correctly punctuated with a participial phrase (причастный оборот)?', 'Qaysi gapda sifatdosh oboroti (причастный оборот) tinish belgilari bilan to''g''ri ajratilgan?', 'В каком предложении правильно расставлены знаки препинания при причастном обороте?', 'A participial phrase (причастный оборот) placed AFTER the modified noun ("книга") must be set off by commas on both sides.', 'Аниқланмиш отдан ("книга") КЕЙИН келган причастный оборот ("лежащая на столе") икки томондан вергул билан ажратилади.', 'Причастный оборот, стоящий после определяемого слова («книга»), выделяется запятыми с двух сторон.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-sentences-q9', 'ru-sentences', 9, 'advanced', 2.2, 'Which sentence uses the adverbial participle phrase (деепричастный оборот) grammatically correctly?', 'Qaysi gapda ravishdosh oboroti (деепричастный оборот) grammatik jihatdan to''g''ri qo''llangan?', 'В каком предложении деепричастный оборот употреблён грамматически правильно?', 'Both the main verb ("попал") and the adverbial participle ("возвращаясь") must refer to the exact same grammatical subject ("я").', 'Деепричастие ("возвращаясь") ва асосий феъл-кесим ("попал") айнан битта эга ("я") томонидан бажарилган бўлиши шарт.', 'Действие, выраженное деепричастием («возвращаясь»), и действие глагола-сказуемого («попал») должны относиться к одному и тому же подлежащему («я»).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-sentences-q10', 'ru-sentences', 10, 'advanced', 2.2, 'How do you form an unreal/hypothetical conditional sentence in Russian?', 'Rus tilida noreal (faraziy) shart ergash gapли qo''shma gap qanday hosil qilinadi?', 'Как строится сложноподчинённое предложение с условием нереального (сослагательного) наклонения?', 'Unreal conditionals in Russian use the subjunctive mood (сослагательное наклонение): particle "бы" + past-tense verb form in both clauses.', 'Faraziy shart gaplarda ikkala qismda ham "бы" yuklamasi va o''tgan zamon fe''l shakli (сослагательное наклонение) ishlatiladi.', 'Для выражения нереального условия в обеих частях предложения используется форма сослагательного наклонения: глагол в форме прошедшего времени с частицей «бы».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-reading-q1', 'ru-reading', 1, 'basic', 1, 'Read the text: "Анна живёт в Санкт-Петербурге. Каждое утро она пьёт чай и едет на работу на метро." How does Anna get to work?', 'Matnni o''qing: "Анна живёт в Санкт-Петербурге. Каждое утро она пьёт чай и едет на работу на метро." Anna ishga qanday boradi?', 'Прочитайте текст: «Анна живёт в Санкт-Петербурге. Каждое утро она пьёт чай и едет на работу на метро». На чём Анна добирается до работы?', 'The text explicitly states: "едет на работу на метро" (she goes to work by metro).', 'Matnda "едет на работу на метро" (ishga metroda boradi) deb aniq aytilgan.', 'В тексте прямо сказано, что она «едет на работу на метро».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-reading-q2', 'ru-reading', 2, 'basic', 1, 'Read the announcement: "Библиотека открыта со вторника по субботу с 9:00 до 18:00. Воскресенье и понедельник — выходные дни." On which days is the library closed?', 'E''lonni o''qing: "Библиотека открыта со вторника по субботу с 9:00 до 18:00. Воскресенье и понедельник — выходные дни." Kutubxona qaysi kunlari yopiq?', 'Прочитайте объявление: «Библиотека открыта со вторника по субботу с 9:00 до 18:00. Воскресенье и понедельник — выходные дни». В какие дни библиотека не работает?', '"Выходные дни" means days off / closed days, which the announcement identifies as Sunday (воскресенье) and Monday (понедельник).', '"Выходные дни" dam olish kunlarini anglatadi, e''longa ko''ra bular yakshanba va dushanbadir.', 'В объявлении указано: «Воскресенье и понедельник — выходные дни».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-reading-q3', 'ru-reading', 3, 'basic', 1, 'Read the dialogue: "— Сколько стоит этот словарь? — Пятьсот рублей, но для студентов скидка сто рублей." How much will a student pay?', 'Dialogni o''qing: "— Сколько стоит этот словарь? — Пятьсот рублей, но для студентов скидка сто рублей." Talaba lug''at uchun qancha to''laydi?', 'Прочитайте диалог: «— Сколько стоит этот словарь? — Пятьсот рублей, но для студентов скидка сто рублей». Сколько заплатит студент?', 'The dictionary costs 500 (пятьсот) rubles with a 100 (сто) ruble student discount (скидка), so a student pays 400 rubles.', 'Lug''at 500 rubl turadi, talabalar uchun 100 rubl chegirma (скидка) bor, demak talaba 400 rubl to''laydi.', 'Словарь стоит 500 рублей, а скидка для студентов составляет 100 рублей (500 - 100 = 400 рублей).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-reading-q4', 'ru-reading', 4, 'intermediate', 1.5, 'Read the note: "Мама, я пошёл в спортзал, а потом зайду в магазин за хлебом. Вернусь к семи часам вечера. Дима." Where will Dima go FIRST?', 'Xatni o''qing: "Мама, я пошёл в спортзал, а потом зайду в магазин за хлебом. Вернусь к семи часам вечера. Дима." Dima AVVAL qayerga boradi?', 'Прочитайте записку: «Мама, я пошёл в спортзал, а потом зайду в магазин за хлебом. Вернусь к семи часам вечера. Дима». Куда Дима отправился сначала?', 'Dima writes "я пошёл в спортзал, а потом зайду в магазин" (I went to the gym, and afterwards I''ll stop by the store).', 'Dima avval sport zaliga ketganini ("я пошёл в спортзал"), keyin ("а потом") do''konga kirishini yozgan.', 'Сначала Дима пошёл в спортзал, а в магазин он собирается зайти «потом».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-reading-q5', 'ru-reading', 5, 'intermediate', 1.5, 'Read the weather report: "Завтра утром ожидается солнечная погода без осадков, однако к вечеру поднимется сильный ветер и пойдёт дождь." When will it rain?', 'Ob-havo ma''lumotini o''qing: "Завтра утром ожидается солнечная погода без осадков, однако к вечеру поднимется сильный ветер и пойдёт дождь." Yomg''ir qachon yog''adi?', 'Прочитайте прогноз погоды: «Завтра утром ожидается солнечная погода без осадков, однако к вечеру поднимется сильный ветер и пойдёт дождь». Когда ожидается дождь?', 'The forecast says the morning will be sunny without precipitation ("без осадков"), while strong wind and rain will arrive towards evening ("к вечеру").', 'Prognozga ko''ra ertalab yog''ingarchilik bo''lmaydi ("без осадков"), kechga yaqin ("к вечеру") esa shamol turib, yomg''ir yog''adi.', 'Согласно прогнозу, утром осадков не будет, а дождь пойдёт «к вечеру».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-reading-q6', 'ru-reading', 6, 'intermediate', 1.5, 'Read the passage: "Байкал — самое глубокое пресноводное озеро на Земле. В него впадает более трёхсот рек, а вытекает только одна — река Ангара." How many rivers flow OUT of Lake Baikal?', 'Matnni o''qing: "Байкал — самое глубокое пресноводное озеро на Земле. В него впадает более трёхсот рек, а вытекает только одна — река Ангара." Baykal ko''lidan nechta daryo OQIB CHIQADI?', 'Прочитайте отрывок: «Байкал — самое глубокое пресноводное озеро на Земле. В него впадает более трёхсот рек, а вытекает только одна — река Ангара». Сколько рек вытекает из Байкала?', '"Впадает" means flows into (over 300 rivers), while "вытекает" means flows out of (only one — the Angara).', '"Впадает" — quyiladi (300 dan ortiq), "вытекает" esa — oqib chiqadi (faqat bitta — Angara daryosi).', 'Глагол «впадает» означает приток воды, а «вытекает» — исток: из Байкала вытекает только одна река Ангара.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-reading-q7', 'ru-reading', 7, 'intermediate', 1.5, 'Read the passage: "Хотя Виктор долго готовился к собеседованию, в первые минуты он сильно волновался. Но доброжелательная улыбка директора сразу помогла ему успокоиться." What helped Viktor calm down?', 'Matnni o''qing: "Хотя Виктор долго готовился к собеседованию, в первые минуты он сильно волновался. Но доброжелательная улыбка директора сразу помогла ему успокоиться." Viktorga tinchlanishga nima yordam berdi?', 'Прочитайте текст: «Хотя Виктор долго готовился к собеседованию, в первые минуты он сильно волновался. Но доброжелательная улыбка директора сразу помогла ему успокоиться». Что помогло Виктору справиться с волнением?', 'The passage states: "доброжелательная улыбка директора сразу помогла ему успокоиться" (the director''s friendly smile immediately helped him calm down).', 'Matnda "доброжелательная улыбка директора сразу помогла ему успокоиться" (direktorning samimiy tabassumi darhol tinchlanishga yordam berdi) deyilgan.', 'В тексте говорится, что успокоиться ему помогла «доброжелательная улыбка директора».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-reading-q8', 'ru-reading', 8, 'advanced', 2.2, 'Read the excerpt: "Наука не просто накапливает факты: её главная задача — обнаружить закономерности, скрытые за разрозненными явлениями." According to the author, what is the main task of science?', 'Parchani o''qing: "Наука не просто накапливает факты: её главная задача — обнаружить закономерности, скрытые за разрозненными явлениями." Muallifning fikricha, ilm-fanning asosiy vazifasi nima?', 'Прочитайте высказывание: «Наука не просто накапливает факты: её главная задача — обнаружить закономерности, скрытые за разрозненными явлениями». В чём, по мнению автора, состоит главная задача науки?', '"Обнаружить закономерности, скрытые за разрозненными явлениями" means to discover the regularities/laws hidden behind disparate phenomena.', '"Обнаружить закономерности, скрытые за разрозненными явлениями" — tarqoq hodisalar ortidagi qonuniyatlarni topish demakdir.', 'Автор подчёркивает, что главная цель науки — находить общие закономерности за отдельными фактами.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-reading-q9', 'ru-reading', 9, 'advanced', 2.2, 'Read the literary passage: "Лес стоял молчаливый и торжественный, словно храм, в котором даже ветер не смел нарушить тишину." Which literary device is used in "словно храм"?', 'Adabiy parchani o''qing: "Лес стоял молчаливый и торжественный, словно храм, в котором даже ветер не смел нарушить тишину." "Словно храм" birikmasida qanday badiiy tasvir vositasi qo''llangan?', 'Прочитайте предложение: «Лес стоял молчаливый и торжественный, словно храм, в котором даже ветер не смел нарушить тишину». Какое средство художественной выразительности использовано в обороте «словно храм»?', 'The conjunction "словно" (as if / like) introduces an explicit comparison or simile (сравнительный оборот) comparing the forest to a temple.', '"Словно" (xuddi, go''yo) bog''lovchisi o''rmonni ibodatxonaga qiyoslovchi o''xshatish (сравнение) vositasidir.', 'Союз «словно» присоединяет сравнительный оборот («словно храм»), сопоставляющий лес с храмом.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-reading-q10', 'ru-reading', 10, 'advanced', 2.2, 'Read the critical statement: "Рецензент высоко оценил сюжет романа, но упрекнул автора в излишней назидательности финала." What criticism did the reviewer make?', 'Jumlani o''qing: "Рецензент высоко оценил сюжет романа, но упрекнул автора в излишней назидательности финала." Taqrizchi muallifni nimada tanqid qildi?', 'Прочитайте фразу: «Рецензент высоко оценил сюжет романа, но упрекнул автора в излишней назидательности финала». За что критик упрекнул писателя?', '"Излишняя назидательность" means excessive didacticism or moralizing preachiness in the novel''s finale.', '"Излишняя назидательность" — haddan ortiq pand-nasihatgo''ylik, didaktiklik degan ma''noni anglatadi.', 'Слово «назидательность» означает поучительность, склонность к прямому морализаторству.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-advanced-q1', 'ru-advanced', 1, 'intermediate', 1.5, 'In which word does the stress (ударение) fall on the LAST syllable according to Russian orthoepic norms?', 'Rus adabiy talaffuz me''yorlariga (орфоэпия) ko''ra qaysi so''zda urg''u OXIRГИ bo''g''inga tushadi?', 'В каком слове ударение в соответствии с орфоэпической нормой падает на последний слог?', 'In all present/future forms of the verb "звонить", the stress falls on the ending: звони́шь, звони́т, звоня́т (while краси́вее, то́рты, ба́нты stress the root).', '"Звонить" fe''ли tuslanganda urg''u doimo oxirgi bo''g''inga tushadi: звони́шь, звони́т, звоня́т.', 'В личных формах глагола «звонить» ударение неподвижно падает на окончание: звони́т, звони́шь, звоня́т.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-advanced-q2', 'ru-advanced', 2, 'intermediate', 1.5, 'How do the meanings of "одеть" and "надеть" differ in standard Russian?', 'Rus tilidagi "одеть" va "надеть" fe''llari qanday farqlanadi?', 'В чём заключается различие в употреблении глаголов «одеть» и «надеть»?', 'A classic mnemonic in Russian is: "Надеть одежду, одеть Надежду" ("надеть" + clothing item; "одеть" + person being dressed).', 'Rus tilida mashhur qoida bor: "Надеть одежду, одеть Надежду" ("надеть" — kiyimni kiymoq; "одеть" — kimsani kiyintirmoq).', 'Запомнить правило помогает формула: «Надеть одежду (что?), одеть Надежду (кого?)».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-advanced-q3', 'ru-advanced', 3, 'advanced', 2.2, 'In which phrase is the negative particle "не" written SEPARATELY from the participle?', 'Qaysi birikmada "не" inkor yuklamasi sifatdoshdan (причастие) AJRATIB yoziladi?', 'В каком случае частица «не» с причастием пишется РАЗДЕЛЬНО?', 'When a full participle has dependent words (зависимые слова like "ещё", "мной"), "не" is written separately: "ещё не прочитанная мной книга".', 'To''liq sifatdoshning o''ziga tobe so''zlari (зависимые слова: "ещё", "мной") bo''lsa, "не" yuklamasi ajratib yoziladi.', 'При наличии у полного причастия зависимых слов («ещё», «мной») частица «не» пишется раздельно.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-advanced-q4', 'ru-advanced', 4, 'advanced', 2.2, 'How many "н" letters should be written in the full passive participle vs. the short passive participle: "прочита(н/нн)ая книга" — "книга прочита(н/нн)а"?', 'To''liq va qisqa majhul sifatdoshlarda nechta "н" yoziladi: "прочита(н/нн)ая книга" — "книга прочита(н/нн)а"?', 'Сколько букв «н» пишется в полном и кратком страдательном причастии: «прочита(н/нн)ая книга» и «книга прочита(н/нн)а»?', 'Full passive past participles formed from perfective verbs take -нн- (прочитанная), while short passive participles ALWAYS take a single -н- (прочитана).', 'Совершенный вид fe''lidan yasalgan to''liq sifatdoshda -нн- (прочитанная), qisqa majhul sifatdoshlarda esa DOIMO bitta -н- (прочитана) yoziladi.', 'В полных страдательных причастиях прошедшего времени пишется НН, а в кратких страдательных причастиях — всегда одна буква Н.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-advanced-q5', 'ru-advanced', 5, 'advanced', 2.2, 'Which sentence properly uses an introductory word (вводное слово) set off by commas?', 'Qaysi gapda kirish so''z (вводное слово) vergul bilan to''g''ri ajratilgan?', 'В каком предложении вводное слово правильно выделено запятыми?', '"К счастью" (fortunately) is an introductory phrase expressing the speaker''s emotion and must be set off by commas on both sides.', '"К счастью" (baxtga ko''ra) so''zlovchining munosabatini bildiruvchi kirish so''z (вводное слово) bo''lib, ikki tomondan vergul bilan ajratiladi.', 'Вводное сочетание «к счастью» выражает чувства говорящего и выделяется запятыми с обеих сторон.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-advanced-q6', 'ru-advanced', 6, 'advanced', 2.2, 'Choose the correct genitive plural form of the nouns "чулки" (stockings) and "носки" (socks):', '"Чулки" va "носки" otlarining Родительный падеж ko''plik (пара чего?) shakli qaysi qatorda to''g''ri berilgan?', 'Укажите грамматически правильные формы родительного падежа множественного числа от слов «чулки» и «носки»:', 'In standard Russian, "чулки" has a zero ending in the genitive plural (нет чулок), whereas the shorter word "носки" takes -ов (нет носков).', 'Adabiy me''yorga ko''ra "чулки" so''zi Родительный падеж ko''plikda qo''shimchasiz (чулок), "носки" esa -ов qo''shimchasi bilan (носков) qo''llanadi.', 'По литературной норме: от слова «чулки» — форма с нулевым окончанием («чулок»), а от слова «носки» — с окончанием -ов («носков»).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-advanced-q7', 'ru-advanced', 7, 'advanced', 2.2, 'When is the prefix "пре-" used instead of "при-" in Russian orthography?', 'Rus imlosida qaysi holatda "при-" emas, balki "пре-" old qo''shimchasi (приставка) yoziladi?', 'В каком случае в словах пишется приставка «пре-»?', 'The prefix "пре-" denotes a high degree of quality ("очень": премудрый, прекрасный) or corresponds to "пере-" (преградить = перегородить).', '"Пре-" old qo''shimchasi belgining yuqori darajasini ("очень": прекрасный) yoki "пере-" ma''nosini (преградить) ifodalaganda yoziladi.', 'Приставка «пре-» пишется, если она близка по значению к слову «очень» или к приставке «пере-».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-advanced-q8', 'ru-advanced', 8, 'advanced', 2.2, 'How do you correctly decline the compound numeral 500 in the Instrumental case (Творительный падеж — кем? чем?)?', '500 (пятьсот) murakkab soni Творительный падеж (чем?) kelishigida qanday turlanadi?', 'Как правильно просклонять числительное «пятьсот» в творительном падеже (кем? чем?)?', 'In compound cardinal numerals like "пятьсот" (500), BOTH roots decline in every case: Творительный падеж -> пятью + стами = пятьюстами.', '500 (пятьсот) kabi murakkab sonlar turlanganda IKKALA qismi ham o''zgaradi: пятью + стами = пятьюстами.', 'У сложных количественных числительных от 500 до 900 при склонении изменяются обе части: чем? — пятьюстами.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-advanced-q9', 'ru-advanced', 9, 'advanced', 2.2, 'What does a colon (двоеточие) between two clauses in a conjunctionless compound sentence (БСП) indicate: "Я выглянул в окно: шёл густой снег"?', 'Bog''lovchisiz qo''shma gapda ikki nuqta (:) nimani bildiradi: "Я выглянул в окно: шёл густой снег"?', 'Какое смысловое отношение выражает двоеточие в бессоюзном сложном предложении (БСП): «Я выглянул в окно: шёл густой снег»?', 'In a conjunctionless sentence, a colon is placed when the second clause explains, gives the reason for, or states what was seen/heard in the first clause.', 'Ikkinchi gap birinchi gapdagi harakatning mazmunini izohlasa ("...va ko''rdimki...") yoki sababini bildirsa, ikki nuqta (:) qo''yiladi.', 'Двоеточие в БСП ставится, когда вторая часть поясняет первую, раскрывает её содержание («и увидел, что...») или указывает причину.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('ru-advanced-q10', 'ru-advanced', 10, 'advanced', 2.2, 'Which group of words belongs specifically to the official-business style (официально-деловой стиль) of Russian?', 'Qaysi qatordagi so''zlar rus tilining rasmiy-idoraviy uslubiga (официально-деловой стиль) xos?', 'Какой ряд слов характерен исключительно для официально-делового стиля речи?', 'Clerical and legal terms like "вышеуказанный" (aforementioned), "нижеподписавшиеся" (undersigned), and "уведомить" (to notify) are markers of the official-business register.', '"Вышеуказанный" (yuqorida ko''rsatilgan), "нижеподписавшиеся" (quyidagi imzo chekuvchilar), "уведомить" (xabardor qilmoq) rasmiy-idoraviy uslubga xosdir.', 'Канцеляризмы «вышеуказанный», «нижеподписавшиеся», «уведомить» являются лексическими маркерами официально-делового стиля.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-alphabet-q1', 'en-alphabet', 1, 'basic', 1, 'How many letters are in the modern English alphabet?', 'Zamonaviy ingliz alifbosida nechta harf bor?', 'Сколько букв в современном английском алфавите?', 'The modern English alphabet consists of 26 Latin letters: 5 vowels and 21 consonants.', 'Zamonaviy ingliz alifbosi 26 ta lotin harfidan iborat: 5 ta unli va 21 ta undosh.', 'Современный английский алфавит состоит из 26 букв: 5 гласных и 21 согласной.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-alphabet-q2', 'en-alphabet', 2, 'basic', 1, 'Which of the following lists contains all five standard English vowel letters?', 'Quyidagi qatorlardan qaysi birida ingliz tilining 5 ta asosiy unli harfi berilgan?', 'В каком из вариантов перечислены все 5 стандартных гласных букв английского алфавита?', 'The five primary vowel letters in English are A, E, I, O, and U (while Y can sometimes act as a vowel sound).', 'Ingliz tilida 5 ta asosiy unli harf mavjud: A, E, I, O va U.', 'Пять основных гласных букв в английском языке — это A, E, I, O и U.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-alphabet-q3', 'en-alphabet', 3, 'basic', 1, 'Which letter is silent in the English word "knight"?', 'Ingliz tilidagi "knight" so''zida qaysi undosh harf talaffuz qilinmaydi?', 'Какая согласная буква не произносится в начале слова "knight"?', 'In "knight", the initial "k" and "gh" are silent, so it is pronounced /naɪt/ (like "night").', '"Knight" so''zida boshidagi "k" va "gh" o''qilmaydi va /naɪt/ deb talaffuz qilinadi.', 'В слове "knight" начальная "k" и сочетание "gh" являются немыми, слово читается как /naɪt/.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-alphabet-q4', 'en-alphabet', 4, 'intermediate', 1.5, 'How is the digraph "ph" pronounced in words like "phone" and "photo"?', '"Phone" va "photo" so''zlaridagi "ph" harf birikmasi qanday tovush beradi?', 'Какой звук передает буквосочетание "ph" в словах "phone" и "photo"?', 'The digraph "ph" in words of Greek origin represents the voiceless labiodental fricative /f/.', 'Grek tilidan o''zlashgan so''zlardagi "ph" harf birikmasi /f/ tovushini ifodalaydi.', 'Диграф "ph" в словах греческого происхождения передает звук /f/.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-alphabet-q5', 'en-alphabet', 5, 'basic', 1, 'Which letter comes immediately after "P" in the English alphabet?', 'Ingliz alifbosida "P" harfidan keyin qaysi harf keladi?', 'Какая буква идет сразу после "P" в английском алфавите?', 'The alphabetical sequence is O, P, Q, R, S.', 'Alifbo ketma-ketligi: O, P, Q, R, S.', 'Алфавитный порядок: O, P, Q, R, S.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-alphabet-q6', 'en-alphabet', 6, 'intermediate', 1.5, 'In which of these words is the letter "C" pronounced as /s/ (soft C)?', 'Quyidagi so''zlarning qaysi birida "C" harfi /s/ deb o''qiladi?', 'В каком из следующих слов буква "C" читается как звук /s/?', 'Before the vowels E, I, and Y (as in "city"), the letter C is typically pronounced as a soft /s/.', 'E, I va Y unlilaridan oldin (masalan, "city" so''zida) C harfi /s/ deb o''qiladi.', 'Перед гласными E, I и Y (как в слове "city") буква C обычно читается как /s/.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-alphabet-q7', 'en-alphabet', 7, 'intermediate', 1.5, 'Which word contains a silent "B"?', 'Qaysi so''zda o''qilmaydigan (silent) "B" harfi bor?', 'В каком из этих слов буква "B" является немой (не читается)?', 'A final "b" following "m" in the same syllable (as in climb, lamb, thumb) is silent.', 'So''z oxirida "m" harfidan keyin kelgan "b" harfi (climb, lamb, thumb) o''qilmaydi.', 'Конечная буква "b" после "m" (climb, lamb, thumb) в английском языке не произносится.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-alphabet-q8', 'en-alphabet', 8, 'basic', 1, 'What is the 26th (last) letter of the English alphabet?', 'Ingliz alifbosining 26-chi (oxirgi) harfi qaysi?', 'Какая буква является 26-й (последней) в английском алфавите?', 'The English alphabet starts with A and ends with Z (pronounced "zee" in US and "zed" in UK).', 'Ingliz alifbosi A harfi bilan boshlanib, Z harfi bilan tugaydi.', 'Английский алфавит начинается с буквы A и заканчивается буквой Z.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-alphabet-q9', 'en-alphabet', 9, 'advanced', 2.2, 'Which phonetic symbol represents the schwa sound — the most common unstressed vowel sound in English (as in "about")?', 'Ingliz tilidagi eng ko''p uchraydigan urg''usiz unli tovush ("about" so''zidagi) qaysi fonetik belgi bilan ifodalanadi?', 'Какой фонетический символ обозначает звук «шва» — самый частый безударный гласный в английском (например, в "about")?', 'The IPA symbol /ə/ represents the mid-central unstressed vowel known as schwa.', 'Xalqaro fonetik alifboda /ə/ belgisi urg''usiz "schwa" unli tovushini bildiradi.', 'В транскрипции символ /ə/ обозначает нейтральный безударный гласный звук «шва».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-alphabet-q10', 'en-alphabet', 10, 'intermediate', 1.5, 'Which two letters can function as both vowel sounds and consonant sounds depending on their position in a word?', 'Qaysi harf so''zdagi o''rniga qarab ham unli, ham undosh tovushni ifodalashi mumkin?', 'Какие буквы могут передавать как гласные, так и полугласные/согласные звуки в зависимости от позиции в слове?', 'Y and W are glides/semivowels that act as consonants at the start of words ("yes", "wet") and contribute to vowel/diphthong sounds elsewhere ("gym", "how").', 'Y va W harflari so''z boshida undosh ("yes", "wet"), boshqa o''rinlarda esa unli yoki diftong ("gym", "how") vazifasini bajaradi.', 'Буквы Y и W выступают как согласные в начале слога ("yes", "wet") и входят в состав гласных/дифтонгов в других позициях ("gym", "how").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-vocabulary-q1', 'en-vocabulary', 1, 'basic', 1, 'Which word is a synonym for "happy"?', '"Happy" (baxtli, xursand) so''zining sinonimi qaysi?', 'Какое слово является синонимом к слову "happy" (счастливый)?', '"Joyful", "glad", and "cheerful" are direct synonyms for "happy".', '"Joyful" so''zi "happy" (xursand, shod) so''zining ma''nodoshidir.', '"Joyful" (радостный) — прямой синоним слова "happy".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-vocabulary-q2', 'en-vocabulary', 2, 'basic', 1, 'What is the opposite (antonym) of the adjective "ancient"?', '"Ancient" (qadimiy) sifatining antonimi (qarama-qarshi ma''nosi) qaysi?', 'Какое слово является антонимом к прилагательному "ancient" (древний)?', '"Ancient" means very old, so its antonym is "modern" (new/contemporary).', '"Ancient" qadimiy degani, uning antonimi "modern" (zamonaviy).', '"Ancient" означает древний, а противоположное по смыслу слово — "modern" (современный).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-vocabulary-q3', 'en-vocabulary', 3, 'intermediate', 1.5, 'Which verb correctly completes the collocation: "___ a decision"?', 'Qaysi fe''l "___ a decision" (qaror qabul qilish) birikmasini to''g''ri to''ldiradi?', 'Какой глагол образует устойчивое словосочетание "___ a decision" (принять решение)?', 'In natural English collocations, we say "make a decision" (not "do a decision").', 'Ingliz tilida "qaror qabul qilish" iborasi "make a decision" shaklida ishlatiladi.', 'В английском языке используется устойчивое выражение "make a decision" (принимать решение).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-vocabulary-q4', 'en-vocabulary', 4, 'basic', 1, 'What do you call a person who designs buildings?', 'Binolarni loyihalashtiruvchi mutaxassis ingliz tilida nima deb ataladi?', 'Как по-английски называется специалист, проектирующий здания?', 'An architect is a professional who plans and designs buildings.', '"Architect" (arxitektor/me''mor) binolarni loyihalashtiruvchi mutaxassisdir.', '"Architect" (архитектор) — специалист, который проектирует здания.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-vocabulary-q5', 'en-vocabulary', 5, 'intermediate', 1.5, 'Which prefix can be added to "possible" to give it a negative meaning?', '"Possible" (mumkin) so''ziga inkor ma''no berish uchun qaysi old qo''shimcha qo''shiladi?', 'Какую приставку нужно добавить к слову "possible", чтобы получить отрицательное значение?', 'Before words starting with "p" or "m", the negative prefix "im-" is used: "impossible".', '"P" yoki "m" bilan boshlanadigan sifatlar oldidan "im-" inkor qo''shimchasi qo''shiladi: "impossible".', 'Перед словами, начинающимися на "p" или "m", используется отрицательная приставка "im-": "impossible".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-vocabulary-q6', 'en-vocabulary', 6, 'intermediate', 1.5, 'What does the adjective "reliable" mean when describing a person?', 'Insonni ta''riflashda ishlatiladigan "reliable" sifati qanday ma''noni anglatadi?', 'Что означает прилагательное "reliable", когда оно описывает человека?', 'A reliable person is someone you can trust and depend on consistently.', '"Reliable" — ishonchli, so''zining ustidan chiqadigan inson degani.', '"Reliable" означает надежного человека, на которого можно положиться.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-vocabulary-q7', 'en-vocabulary', 7, 'basic', 1, 'Which word refers to the meal eaten in the morning?', 'Ertalab tanovul qilinadigan ovqat ingliz tilida nima deyiladi?', 'Как по-английски называется утренний прием пищи?', 'Breakfast is the first meal of the day, eaten in the morning.', '"Breakfast" (nonushta) — ertalabki birinchi ovqat.', '"Breakfast" (завтрак) — утренний прием пищи.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-vocabulary-q8', 'en-vocabulary', 8, 'intermediate', 1.5, 'Choose the correct word: "Please ___ me to call my mother tonight."', 'To''g''ri so''zni tanlang: "Please ___ me to call my mother tonight."', 'Выберите правильное слово: "Please ___ me to call my mother tonight."', '"Remind" means to cause someone else to remember ("remind me to do something").', '"Remind" birovning esiga solib qo''ymoq ma''nosini bildiradi ("remind me").', '"Remind" означает «напомнить кому-либо», тогда как "remember" — «помнить самому».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-vocabulary-q9', 'en-vocabulary', 9, 'advanced', 2.2, 'What is the meaning of the word "inevitable"?', '"Inevitable" so''zining ma''nosi nima?', 'Что означает слово "inevitable"?', '"Inevitable" describes an event or outcome that is certain to happen and cannot be prevented.', '"Inevitable" — sodir bo''lishi aniq bo''lgan, muqarrar narsa yoki hodisa.', '"Inevitable" означает «неизбежный», то, чего нельзя предотвратить.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-vocabulary-q10', 'en-vocabulary', 10, 'intermediate', 1.5, 'Which suffix turns the adjective "dark" into a noun?', 'Qaysi qo''shimcha "dark" (qorong''i) sifatini ot so''z turkumiga aylantiradi?', 'Какой суффикс превращает прилагательное "dark" (темный) в существительное (темнота)?', 'Adding "-ness" to adjectives like "dark", "kind", or "happy" forms abstract nouns ("darkness").', '"-ness" qo''shimchasi sifatlardan mavhum ot yasaydi: "dark" -> "darkness" (qorong''ilik).', 'Суффикс "-ness" образует существительные от прилагательных: "dark" -> "darkness" (темнота).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-grammar-q1', 'en-grammar', 1, 'basic', 1, 'Choose the correct article: "She is studying at ___ university in London."', 'To''g''ri artiklni tanlang: "She is studying at ___ university in London."', 'Выберите правильный артикль: "She is studying at ___ university in London."', 'Although "university" starts with the letter U, it begins with a consonant sound /juː/, so it takes "a".', '"University" so''zi U harfi bilan boshlansa-da, /juː/ undosh tovushi bilan talaffuz qilingani uchun "a" artikli ishlatiladi.', 'Слово "university" начинается с согласного звука /juː/, поэтому перед ним ставится артикль "a".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-grammar-q2', 'en-grammar', 2, 'basic', 1, 'What is the correct plural form of the noun "child"?', '"Child" (bola) otining to''g''ri ko''plik shakli qaysi?', 'Какова правильная форма множественного числа существительного "child"?', '"Child" is an irregular noun whose plural form is "children".', '"Child" noto''g''ri ot bo''lib, uning ko''plik shakli "children" bo''ladi.', '"Child" — существительное-исключение, во множественном числе имеет форму "children".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-grammar-q3', 'en-grammar', 3, 'intermediate', 1.5, 'Which of the following nouns is uncountable in English?', 'Quyidagi otlardan qaysi biri ingliz tilida sanalmaydigan ot (uncountable noun) hisoblanadi?', 'Какое из следующих существительных является неисчисляемым в английском языке?', '"Information" (like "advice" and "furniture") is uncountable in English and cannot take "an" or a plural "-s".', '"Information" (axborot/ma''lumot) ingliz tilida sanalmaydigan ot bo''lib, ko''plikda ishlatilmaydi.', 'Слово "information" в английском языке неисчисляемое и не употребляется во множественном числе.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-grammar-q4', 'en-grammar', 4, 'basic', 1, 'Choose the correct comparative form: "This problem is ___ than the previous one."', 'Qiyosiy darajaning to''g''ri shaklini tanlang: "This problem is ___ than the previous one."', 'Выберите правильную сравнительную степень: "This problem is ___ than the previous one."', 'Two-syllable adjectives ending in -y change -y to -ier in the comparative form ("easy" -> "easier").', '-y bilan tugagan ikki bo''g''inli sifatlar qiyosiy darajada -ier qo''shimchasini oladi ("easy" -> "easier").', 'Двусложные прилагательные на -y в сравнительной степени меняют -y на -ier ("easy" -> "easier").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-grammar-q5', 'en-grammar', 5, 'intermediate', 1.5, 'Complete the sentence: "We have lived in this city ___ 2019."', 'Gapni to''ldiring: "We have lived in this city ___ 2019."', 'Дополните предложение: "We have lived in this city ___ 2019."', '"Since" is used with a specific starting point in time (2019), whereas "for" is used with a duration.', 'Aniq boshlanish vaqti (2019-yil) ko''rsatilganda "since" predlogi ishlatiladi.', 'Предлог "since" используется с конкретной точкой начала действия в прошлом (2019 год).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-grammar-q6', 'en-grammar', 6, 'intermediate', 1.5, 'Which preposition is correct? "She is very good ___ solving mathematical puzzles."', 'Qaysi predlog to''g''ri? "She is very good ___ solving mathematical puzzles."', 'Какой предлог правильный? "She is very good ___ solving mathematical puzzles."', 'The standard adjective-preposition collocation for skill or ability is "good at (something)".', 'Qobiliyat va mahoratni ifodalashda "good at" birikmasi ishlatiladi.', 'Устойчивое выражение со значением «быть способным к чему-либо» — "good at".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-grammar-q7', 'en-grammar', 7, 'basic', 1, 'Choose the correct quantifier: "There isn''t ___ milk left in the fridge."', 'To''g''ri miqdor so''zini tanlang: "There isn''t ___ milk left in the fridge."', 'Выберите правильное местоимение: "There isn''t ___ milk left in the fridge."', '"Any" is used with uncountable and plural nouns in negative sentences and questions.', 'Inkor va so''roq gaplarda sanalmaydigan otlar ("milk") bilan "any" ishlatiladi.', 'В отрицательных предложениях с неисчисляемыми существительными ("milk") используется "any".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-grammar-q8', 'en-grammar', 8, 'intermediate', 1.5, 'Which sentence uses the saxon genitive (possessive ''s) correctly for plural nouns?', 'Qaysi gapda ko''plikdagi otning qaratqich kelishigi (possessive) to''g''ri qo''llangan?', 'В каком предложении правильно образован притяжательный падеж для существительного во множественном числе?', 'For regular plural nouns ending in -s ("students"), only an apostrophe is added after the -s ("students''").', '-s bilan tugagan ko''plikdagi otlarga qaratqich kelishigida faqat apostrof qo''yiladi ("students''").', 'К регулярным существительным во множественном числе на -s добавляется только апостроф после -s ("students''").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-grammar-q9', 'en-grammar', 9, 'advanced', 2.2, 'Choose the correct option: "Neither the manager nor the employees ___ aware of the schedule change."', 'To''g''ri variantni tanlang: "Neither the manager nor the employees ___ aware of the schedule change."', 'Выберите правильную форму: "Neither the manager nor the employees ___ aware of the schedule change."', 'With "neither... nor...", the verb agrees with the closer subject ("employees", which is plural -> "were").', '"Neither... nor..." qurilmasida fe''l o''ziga yaqin turgan ega ("employees" — ko''plik) bilan moslashadi ("were").', 'В конструкции "neither... nor..." глагол согласуется с ближайшим подлежащим ("employees" — мн. число -> "were").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-grammar-q10', 'en-grammar', 10, 'intermediate', 1.5, 'What is the superlative form of the adjective "bad"?', '"Bad" (yomon) sifatining orttirma darajasi (superlative) qaysi?', 'Какова превосходная степень прилагательного "bad" (плохой)?', '"Bad" has irregular degrees of comparison: bad -> worse (comparative) -> the worst (superlative).', '"Bad" sifatining darajalari noto''g''ri yasaladi: bad -> worse -> the worst.', 'Степени сравнения прилагательного "bad" образуются не по правилам: bad -> worse -> the worst.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-tenses-q1', 'en-tenses', 1, 'basic', 1, 'Which tense is used for daily routines and general scientific truths? "Water boils at 100°C."', 'Kundalik odatlar va ilmiy haqiqatlarni ifodalash uchun qaysi zamon ishlatiladi? ("Water boils at 100°C.")', 'Какое время используется для регулярных действий и общеизвестных фактов? ("Water boils at 100°C.")', 'Present Simple expresses permanent truths, laws of nature, and habitual actions.', 'Present Simple doimiy haqiqatlar, tabiat qonunlari va odatiy harakatlar uchun ishlatiladi.', 'Present Simple используется для выражения постоянных фактов, законов природы и привычек.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-tenses-q2', 'en-tenses', 2, 'basic', 1, 'Complete the sentence: "Listen! Someone ___ the piano in the next room."', 'Gapni to''ldiring: "Listen! Someone ___ the piano in the next room."', 'Дополните предложение: "Listen! Someone ___ the piano in the next room."', '"Listen!" indicates an action happening right now at the moment of speech, requiring Present Continuous ("is playing").', '"Listen!" undovi harakat ayni nutq paytida sodir bo''layotganini bildiradi, shuning uchun Present Continuous ("is playing") qo''llanadi.', 'Восклицание "Listen!" указывает на действие, происходящее прямо сейчас, поэтому требуется Present Continuous ("is playing").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-tenses-q3', 'en-tenses', 3, 'basic', 1, 'Choose the correct Past Simple form: "We ___ to Samarkand last weekend."', 'Past Simple shaklini tanlang: "We ___ to Samarkand last weekend."', 'Выберите правильную форму Past Simple: "We ___ to Samarkand last weekend."', '"Last weekend" is a finished past time expression, so Past Simple ("went") is required.', '"Last weekend" tugallangan o''tgan zamon ko''rsatkichi bo''lgani uchun Past Simple ("went") ishlatiladi.', '"Last weekend" указывает на завершенный момент в прошлом, поэтому используется Past Simple ("went").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-tenses-q4', 'en-tenses', 4, 'intermediate', 1.5, 'Complete the sentence: "I ___ my keys! I can''t open the door now."', 'Gapni to''ldiring: "I ___ my keys! I can''t open the door now."', 'Дополните предложение: "I ___ my keys! I can''t open the door now."', 'Present Perfect ("have lost") connects a past action to a present result ("I can''t open the door now").', 'O''tmishda sodir bo''lib, natijasi hozirda ko''rinib turgan harakat uchun Present Perfect ("have lost") ishlatiladi.', 'Present Perfect ("have lost") используется для действия в прошлом, результат которого важен в настоящем.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-tenses-q5', 'en-tenses', 5, 'intermediate', 1.5, 'Choose the correct verb form: "While I ___ dinner, the phone rang."', 'To''g''ri fe''l shaklini tanlang: "While I ___ dinner, the phone rang."', 'Выберите правильную форму глагола: "While I ___ dinner, the phone rang."', 'Past Continuous ("was cooking") describes a longer background action interrupted by a shorter Past Simple event ("rang").', 'O''tmishda davom etayotgan uzunroq harakat ("was cooking") qisqa harakat ("rang") bilan kesilganda Past Continuous ishlatiladi.', 'Past Continuous ("was cooking") описывает длительное действие в прошлом, прерванное кратким действием ("rang").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-tenses-q6', 'en-tenses', 6, 'intermediate', 1.5, 'Complete the sentence: "By the time we arrived at the station, the train ___."', 'Gapni to''ldiring: "By the time we arrived at the station, the train ___."', 'Дополните предложение: "By the time we arrived at the station, the train ___."', 'Past Perfect ("had already left") expresses an action completed before another past event ("arrived").', 'O''tgan zamondagi bir harakatdan ("arrived") oldin tugallangan boshqa harakat uchun Past Perfect ("had already left") ishlatiladi.', 'Past Perfect ("had already left") обозначает действие, завершишееся до другого момента в прошлом ("arrived").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-tenses-q7', 'en-tenses', 7, 'intermediate', 1.5, 'Which form expresses a prior plan or intention for the future? "Look at those dark clouds! It ___ rain."', 'Yaqqol belgiga asoslangan bashorat uchun qaysi shakl ishlatiladi? "Look at those dark clouds! It ___ rain."', 'Какая форма используется для прогноза на основе очевидных признаков? "Look at those dark clouds! It ___ rain."', '"Be going to" is used for predictions based on visible present evidence (dark clouds).', 'Ko''з oldimizdagi aniq dalillarga (qora bulutlar) asoslangan kelasi zamon taxmini uchun "is going to" ishlatiladi.', 'Конструкция "be going to" используется для предсказаний, основанных на очевидных фактах в настоящем.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-tenses-q8', 'en-tenses', 8, 'advanced', 2.2, 'Complete the sentence: "She ___ at this company for five years by next December."', 'Gapni to''ldiring: "She ___ at this company for five years by next December."', 'Дополните предложение: "She ___ at this company for five years by next December."', 'Future Perfect Continuous ("will have been working") emphasizes the duration of an ongoing action up to a specified future point ("by next December").', 'Kelajakdagi aniq bir vaqtgacha ("by next December") qancha vaqt davom etgan bo''lishini bildirish uchun Future Perfect Continuous ishlatiladi.', 'Future Perfect Continuous ("will have been working") подчеркивает длительность действия к определенному моменту в будущем.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-tenses-q9', 'en-tenses', 9, 'intermediate', 1.5, 'Choose the correct tense: "How long ___ you ___ English?"', 'To''g''ri zamon shaklini tanlang: "How long ___ you ___ English?"', 'Выберите правильную форму: "How long ___ you ___ English?"', 'Present Perfect Continuous ("have you been learning") asks about an activity that started in the past and continues up to the present.', 'O''tmishda boshlanib, hozir ham davom etayotgan jarayon davomiyligini so''rashda Present Perfect Continuous ishlatiladi.', 'Present Perfect Continuous ("have you been learning") используется для действия, начавшегося в прошлом и продолжающегося сейчас.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-tenses-q10', 'en-tenses', 10, 'advanced', 2.2, 'Why is "I am knowing the answer" grammatically incorrect in standard English?', 'Nima uchun standart ingliz tilida "I am knowing the answer" jumlasi grammatik jihatdan xato?', 'Почему предложение "I am knowing the answer" грамматически неверно в стандартном английском языке?', 'Stative verbs describing mental states (know, believe, understand, belong) are not used in progressive/continuous forms.', 'Aqliy holatni bildiruvchi fe''llar (stative verbs: know, believe, understand) Continuous shakllarida qo''llanmaydi.', 'Глаголы состояния (stative verbs: know, believe, understand) не используются в длительных временах (Continuous).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-verbs-q1', 'en-verbs', 1, 'basic', 1, 'What are the Past Simple (V2) and Past Participle (V3) forms of the irregular verb "write"?', '"Write" (yozmoq) noto''g''ri fe''lining V2 va V3 shakllari qaysi?', 'Каковы формы Past Simple (V2) и Past Participle (V3) неправильного глагола "write"?', 'The principal parts of "write" are write (V1) – wrote (V2) – written (V3).', '"Write" fe''lining uch asosiy shakli: write – wrote – written.', 'Три формы глагола "write": write (V1) – wrote (V2) – written (V3).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-verbs-q2', 'en-verbs', 2, 'basic', 1, 'Choose the correct modal verb for advice: "You look exhausted. You ___ get some rest."', 'Maslahat berish uchun mos modal fe''lni tanlang: "You look exhausted. You ___ get some rest."', 'Выберите модальный глагол для совета: "You look exhausted. You ___ get some rest."', 'The modal verb "should" (or "ought to") is used to give advice or recommendations.', '"Should" modal fe''li maslahat yoki tavsiya berish uchun ishlatiladi.', 'Модальный глагол "should" используется для выражения совета или рекомендации.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-verbs-q3', 'en-verbs', 3, 'intermediate', 1.5, 'Complete the sentence with a gerund or infinitive: "She enjoys ___ historical novels in her free time."', 'Gerund yoki infinitivni tanlang: "She enjoys ___ historical novels in her free time."', 'Выберите герундий или инфинитив: "She enjoys ___ historical novels in her free time."', 'The verb "enjoy" is always followed by a gerund (V-ing): "enjoys reading".', '"Enjoy" fe''lidan keyin doimo gerund (V-ing) shakli keladi: "enjoys reading".', 'После глагола "enjoy" всегда используется герундий (глагол с окончанием -ing): "enjoys reading".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-verbs-q4', 'en-verbs', 4, 'intermediate', 1.5, 'What does the phrasal verb "give up" mean in "He decided to give up smoking"?', '"He decided to give up smoking" gapidagi "give up" iborali fe''li qanday ma''noni bildiradi?', 'Что означает фразовый глагол "give up" в предложении "He decided to give up smoking"?', '"Give up" means to stop a habit or quit attempting something.', '"Give up" — biror odatni tashlash yoki urinishni to''xtatish ma''nosini anglatadi.', 'Фразовый глагол "give up" означает «бросить привычку» или «сдаться/прекратить».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-verbs-q5', 'en-verbs', 5, 'intermediate', 1.5, 'Complete the sentence: "They decided ___ the project deadline by two days."', 'Gapni to''ldiring: "They decided ___ the project deadline by two days."', 'Дополните предложение: "They decided ___ the project deadline by two days."', 'The verb "decide" is followed by a to-infinitive ("decided to extend").', '"Decide" fe''lidan keyin to-infinitiv ("to extend") ishlatiladi.', 'После глагола "decide" употребляется инфинитив с частицей to ("to extend").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-verbs-q6', 'en-verbs', 6, 'intermediate', 1.5, 'What is the difference between "mustn''t" and "don''t have to"?', '"Mustn''t" va "don''t have to" o''rtasida qanday ma''no farqi bor?', 'В чем разница между "mustn''t" и "don''t have to"?', '"Mustn''t" means something is forbidden, whereas "don''t have to" means it is optional / not required.', '"Mustn''t" — mumkin emas (taqiq), "don''t have to" esa shart emas (zarurat yo''q) degani.', '"Mustn''t" означает строгий запрет («нельзя»), а "don''t have to" — отсутствие необходимости («не нужно»).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-verbs-q7', 'en-verbs', 7, 'basic', 1, 'What are the three forms (V1 - V2 - V3) of the verb "begin"?', '"Begin" (boshlamoq) fe''lining uchta shakli (V1 - V2 - V3) qaysi?', 'Каковы три формы (V1 - V2 - V3) неправильного глагола "begin" (начинать)?', 'The irregular verb "begin" follows the i-a-u vowel pattern: begin – began – begun.', '"Begin" fe''li i-a-u unli almashinish qoidasiga bo''ysunadi: begin – began – begun.', 'Глагол "begin" изменяется по схеме i-a-u: begin – began – begun.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-verbs-q8', 'en-verbs', 8, 'intermediate', 1.5, 'What does the phrasal verb "look after" mean?', '"Look after" iborali fe''li qanday ma''noni anglatadi?', 'Что означает фразовый глагол "look after"?', '"Look after" means to take care of or be responsible for someone or something.', '"Look after" — birovga g''amxo''rlik qilmoq yoki qarab turmoq ("take care of").', '"Look after" означает «заботиться, присматривать за кем-либо или чем-либо».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-verbs-q9', 'en-verbs', 9, 'advanced', 2.2, 'Which modal structure expresses certainty deduction about a past event? "The streets are wet; it ___ rained last night."', 'O''tmishdagi voqea haqida ishonchli xulosani ifodalash uchun qaysi modal shakl ishlatiladi? "The streets are wet; it ___ rained last night."', 'Какая модальная конструкция выражает уверенное предположение о прошлом? "The streets are wet; it ___ rained last night."', '"Must have + V3" ("must have rained") expresses a logical deduction of high certainty about the past.', '"Must have + V3" o''tmishда sodir bo''lgan voqea bo''yicha kuchli mantiqiy taxminni ("yomg''ir yog''gan bo''lishi kerak") ifodalaydi.', 'Конструкция "must have + V3" выражает высокую степень уверенности в том, что действие произошло в прошлом.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-verbs-q10', 'en-verbs', 10, 'advanced', 2.2, 'In "I stopped to buy some water", what does "stopped to buy" mean compared to "stopped buying"?', '"I stopped to buy some water" gapidagi "stopped to buy" birikmasi nimani anglatadi?', 'Что означает конструкция "stopped to buy" в предложении "I stopped to buy some water"?', '"Stop + to-infinitive" means to pause an action in order to do something else, while "stop + gerund" means to quit an activity.', '"Stop + to V" biror ishni qilish maqsadida to''xtashni, "stop + V-ing" esa o''sha ishni bajarishni to''xtatishni bildiradi.', '"Stop + to-infinitive" означает остановиться с целью сделать что-то, а "stop + gerund" — прекратить само действие.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-pronouns-q1', 'en-pronouns', 1, 'basic', 1, 'Choose the correct object pronoun: "Sarah called ___ yesterday evening."', 'To''g''ri to''ldiruvchi olmoshni tanlang: "Sarah called ___ yesterday evening."', 'Выберите правильное объектное местоимение: "Sarah called ___ yesterday evening."', 'After a transitive verb ("called"), an object pronoun ("us") is required rather than a subject pronoun ("we").', 'Fe''ldan keyin to''ldiruvchi vazifasida obyekt olmoshi ("us" — bizga/bizni) ishlatiladi.', 'После переходного глагола ("called") используется объектное местоимение ("us").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-pronouns-q2', 'en-pronouns', 2, 'basic', 1, 'Choose the correct independent possessive pronoun: "This laptop is not mine; it is ___."', 'Mustaqil egalik olmoshini tanlang: "This laptop is not mine; it is ___."', 'Выберите абсолютную форму притяжательного местоимения: "This laptop is not mine; it is ___."', '"Hers" is a possessive pronoun that stands alone without a following noun ("her laptop" = "hers").', 'Otdan keyin mustaqil qo''llanadigan egalik olmoshi "hers" (uniki) shaklidir.', 'Абсолютная форма притяжательного местоимения "hers" используется самостоятельно без существительного после нее.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-pronouns-q3', 'en-pronouns', 3, 'basic', 1, 'Complete the sentence with a reflexive pronoun: "He taught ___ how to play the guitar."', 'O''zlik olmoshini tanlang: "He taught ___ how to play the guitar."', 'Дополните предложение возвратным местоимением: "He taught ___ how to play the guitar."', 'When the subject and object refer to the same masculine singular person ("He"), the reflexive pronoun is "himself".', 'Ega va to''ldiruvchi bir shaxs ("He") bo''lganda "himself" (o''z-o''ziga) o''zlik olmoshi qo''llanadi.', 'Когда подлежащее ("He") и дополнение совпадают, используется возвратное местоимение "himself".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-pronouns-q4', 'en-pronouns', 4, 'intermediate', 1.5, 'Which relative pronoun refers to people as the subject of a clause? "The engineer ___ designed this bridge won an award."', 'Shaxslarga nisbatan ega vazifasida qaysi nisbiy olmosh ishlatiladi? "The engineer ___ designed this bridge won an award."', 'Какое относительное местоимение используется для одушевленных лиц в роли подлежащего? "The engineer ___ designed this bridge won an award."', '"Who" (or "that") is used as the subject relative pronoun for people ("The engineer who designed...").', 'Insonlarga nisbatan ergash gapning egasi vazifasida "who" nisbiy olmoshi ishlatiladi.', 'Относительное местоимение "who" используется по отношению к людям в роли подлежащего придаточного предложения.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-pronouns-q5', 'en-pronouns', 5, 'intermediate', 1.5, 'Choose the correct relative pronoun showing possession: "That is the author ___ book became a global bestseller."', 'Tegishlilikni bildiruvchi nisbiy olmoshni tanlang: "That is the author ___ book became a global bestseller."', 'Выберите относительное местоимение, выражающее принадлежность: "That is the author ___ book became a global bestseller."', '"Whose" indicates possession ("the author''s book" -> "the author whose book"). Note that "who''s" means "who is".', '"Whose" tegishlilikni bildiradi ("muallifning kitobi" -> "whose book").', '"Whose" означает «чей/которого» и указывает на принадлежность.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-pronouns-q6', 'en-pronouns', 6, 'basic', 1, 'Which demonstrative pronoun is used for plural objects that are far away from the speaker?', 'So''zlovchidan uzoqda joylashgan ko''plikdagi narsalarni ko''rsatish uchun qaysi olmosh ishlatiladi?', 'Какое указательное местоимение используется для предметов во множественном числе, находящихся далеко от говорящего?', '"Those" is the plural form of "that", referring to distant plural items (while "these" is for near plural items).', 'Uzoqdagi ko''plikdagi predmetlar uchun "those" (anavilar), yaqindagilar uchun esa "these" (bular) ishlatiladi.', '"Those" (те) используется для множественного числа предметов на расстоянии, а "these" (эти) — для близких.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-pronouns-q7', 'en-pronouns', 7, 'intermediate', 1.5, 'Complete the sentence: "The door opened by ___."', 'Gapni to''ldiring: "The door opened by ___."', 'Дополните предложение: "The door opened by ___."', 'The idiomatic phrase "by itself" means automatically or without anyone''s help.', '"By itself" iborasi "o''z-o''zidan" yoki hech kimning yordamisiz degan ma''noni anglatadi.', 'Выражение "by itself" означает «само по себе, самостоятельно».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-pronouns-q8', 'en-pronouns', 8, 'intermediate', 1.5, 'Choose the correct indefinite pronoun: "Did ___ call while I was out of the office?"', 'To''g''ri gumon olmoshini tanlang: "Did ___ call while I was out of the office?"', 'Выберите правильное неопределенное местоимение: "Did ___ call while I was out of the office?"', 'In general questions, "anyone" (or "anybody") is used to refer to an unspecified person.', 'Umumiy so''roq gaplarda shaxsga nisbatan "anyone" (yoki "anybody" — kimdir/biror kishi) ishlatiladi.', 'В общих вопросах по отношению к людям используется местоимение "anyone" (или "anybody").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-pronouns-q9', 'en-pronouns', 9, 'advanced', 2.2, 'Notice the difference: "Each of the candidates ___ required to submit a portfolio." Which verb agrees with the pronoun "Each"?', '"Each of the candidates ___ required to submit a portfolio." "Each" olmoshiga qaysi fe''l mos keladi?', '"Each of the candidates ___ required to submit a portfolio." Какой глагол согласуется с местоимением "Each"?', 'The distributive pronoun "each" is grammatically singular, so it takes a singular verb ("is").', '"Each" (har biri) olmoshi grammatik jihatdan birlikda bo''lgani uchun birlikdagi fe''l ("is") bilan keladi.', 'Местоимение "each" (каждый) грамматически всегда единственного числа и требует глагола "is".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-pronouns-q10', 'en-pronouns', 10, 'intermediate', 1.5, 'What is the difference between "its" and "it''s"?', '"Its" va "it''s" o''rtasida qanday farq bor?', 'В чем разница между "its" и "it''s"?', '"Its" (without an apostrophe) shows possession ("The cat licked its paw"), whereas "it''s" is short for "it is" or "it has".', 'Apostrofsiz "its" egalikni ("uning"), apostrofli "it''s" esa "it is" yoki "it has" qisqartmasini bildiradi.', '"Its" без апострофа — притяжательное местоимение, а "it''s" — краткая форма от "it is" или "it has".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-sentences-q1', 'en-sentences', 1, 'basic', 1, 'What is the standard word order in an affirmative English declarative sentence?', 'Ingliz tilidagi darak gaplarda standart so''z tartibi qanday bo''ladi?', 'Каков стандартный порядок слов в английском повествовательном предложении?', 'English follows a strict Subject–Verb–Object (SVO) word order in declarative clauses.', 'Ingliz tilida darak gaplar qat''iy Ega + Kesim + To''ldiruvchi (SVO) tartibida tuziladi.', 'Английское повествовательное предложение строится по схеме: Подлежащее + Сказуемое + Дополнение (SVO).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-sentences-q2', 'en-sentences', 2, 'intermediate', 1.5, 'Choose the correct First Conditional sentence:', 'Birinchi tur shart ergash gapning (First Conditional) to''g''ri shaklini tanlang:', 'Выберите грамматически правильное условное предложение первого типа (First Conditional):', 'In a First Conditional sentence, the "if" clause uses Present Simple ("if it rains") and the main clause uses "will + base verb".', 'First Conditional gaplarda "if" qismida Present Simple ("rains"), bosh gapda esa "will + V1" ishlatiladi.', 'В First Conditional в придаточном с "if" используется Present Simple ("rains"), а в главном — "will + инфинитив".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-sentences-q3', 'en-sentences', 3, 'intermediate', 1.5, 'Transform into Passive Voice: "Alexander Fleming discovered penicillin in 1928."', 'Majhul nisbatga (Passive Voice) aylantiring: "Alexander Fleming discovered penicillin in 1928."', 'Преобразуйте в страдательный залог (Passive Voice): "Alexander Fleming discovered penicillin in 1928."', 'Past Simple Active ("discovered") becomes "was/were + Past Participle" ("was discovered") in the Passive Voice.', 'Past Simple majhul nisbatda "was/were + V3" ("was discovered") shaklida yasaladi.', 'В Past Simple Passive используется конструкция "was/were + V3" ("was discovered").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-sentences-q4', 'en-sentences', 4, 'intermediate', 1.5, 'Choose the correct question tag: "You have already finished the assignment, ___?"', 'Tasdiq/so''roq quyrug''ini (question tag) to''g''ri tanlang: "You have already finished the assignment, ___?"', 'Выберите правильный разделительный вопрос (question tag): "You have already finished the assignment, ___?"', 'An affirmative statement with the auxiliary "have" takes the negative tag "haven''t you?".', 'Bosh gapda "have" yordamchi fe''li tasdiq shaklda bo''lsa, so''roq qismi inkor shaklda ("haven''t you?") bo''ladi.', 'К утвердительному предложению со вспомогательным глаголом "have" добавляется отрицательный хвостик "haven''t you?".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-sentences-q5', 'en-sentences', 5, 'intermediate', 1.5, 'Complete the Second Conditional sentence: "If I ___ more free time, I would learn a fourth language."', 'Second Conditional gapni to''ldiring: "If I ___ more free time, I would learn a fourth language."', 'Дополните условное предложение второго типа (Second Conditional): "If I ___ more free time, I would learn a fourth language."', 'Second Conditional describes hypothetical present/future situations using Past Simple ("had") in the if-clause and "would + V1" in the main clause.', 'Second Conditional (noreal hozirgi/kelasi shart) "if" qismida Past Simple ("had") shaklini talab qiladi.', 'В Second Conditional в условии после "if" используется Past Simple ("had"), а в главной части — "would + V1".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-sentences-q6', 'en-sentences', 6, 'basic', 1, 'Which sentence has the adverb of frequency in the correct position?', 'Qaysi gapda takroriylik ravishi (always) to''g''ri o''rinda qo''llangan?', 'В каком предложении наречие частотности (always) стоит на правильном месте?', 'Adverbs of frequency (always, usually, often, never) are placed before the main verb (and after the verb "to be").', 'Takroriylik ravishlari (always, usually, often) asosiy fe''ldan oldin ("always goes") qo''yiladi.', 'Наречия частотности (always, usually, often) ставятся перед смысловым глаголом ("always goes").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-sentences-q7', 'en-sentences', 7, 'intermediate', 1.5, 'Convert into Reported (Indirect) Speech: He said, "I am working on a new project."', 'O''zlashtirma gapga (Reported Speech) aylantiring: He said, "I am working on a new project."', 'Переведите в косвенную речь (Reported Speech): He said, "I am working on a new project."', 'In reported speech after a past reporting verb ("said"), Present Continuous ("am working") backshifts to Past Continuous ("was working").', 'O''zlashtirma gapda zamon bir pog''ona orqaga suriladi: Present Continuous -> Past Continuous ("was working").', 'По правилу согласования времен в косвенной речи Present Continuous переходит в Past Continuous ("was working").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-sentences-q8', 'en-sentences', 8, 'advanced', 2.2, 'Choose the correct word order for an indirect/embedded question: "Could you tell me ___?"', 'Ichki so''roq gap (Indirect Question) uchun to''g''ri so''z tartibini tanlang: "Could you tell me ___?"', 'Выберите правильный порядок слов в косвенном вопросе: "Could you tell me ___?"', 'Indirect questions use statement word order (Subject + Verb: "where the nearest metro station is") rather than inverted question order.', 'Bilvosita so''roq gaplarda so''roq emas, darak gap tartibi (Ega + Kesim: "where the nearest metro station is") ishlatiladi.', 'В косвенных вопросах после вопросительного слова используется прямой порядок слов (Подлежащее + Сказуемое).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-sentences-q9', 'en-sentences', 9, 'advanced', 2.2, 'Complete the Third Conditional sentence: "If they had left earlier, they ___ the flight."', 'Third Conditional gapni to''ldiring: "If they had left earlier, they ___ the flight."', 'Дополните условное предложение третьего типа (Third Conditional): "If they had left earlier, they ___ the flight."', 'Third Conditional expresses unreal past situations using "If + Past Perfect" and "would have + Past Participle" ("wouldn''t have missed").', 'O''tmishdagi noreal shartni ifodalovchi Third Conditional bosh gapida "would have + V3" ("wouldn''t have missed") ishlatiladi.', 'В главной части Third Conditional (нереальное условие в прошлом) используется "would have + V3".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-sentences-q10', 'en-sentences', 10, 'intermediate', 1.5, 'Which conjunction expresses contrast? "___ it was raining heavily, they continued the match."', 'Qaysi bog''lovchi zidlik ma''nosini ifodalaydi? "___ it was raining heavily, they continued the match."', 'Какой союз выражает уступку/противопоставление? "___ it was raining heavily, they continued the match."', '"Although" (or "Even though") is a subordinating conjunction followed by a full clause (Subject + Verb), whereas "Despite" is followed by a noun/gerund.', 'Ega va kesimli to''liq ergash gapdan oldin "Although" (-ga qaramay) bog''lovchisi ishlatiladi ("Despite" dan keyin esa ot keladi).', 'Союз "Although" (хотя) вводит полноценное придаточное предложение с подлежащим и сказуемым.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-reading-q1', 'en-reading', 1, 'basic', 1, 'Read the passage: "The Sahara is the largest hot desert in the world, covering much of North Africa. Despite its arid climate, it is home to resilient plants and animals adapted to extreme temperatures." What is the main idea?', 'Matnni o''qing: "The Sahara is the largest hot desert in the world, covering much of North Africa. Despite its arid climate, it is home to resilient plants and animals adapted to extreme temperatures." Asosiy g''oya nima?', 'Прочитайте отрывок: "The Sahara is the largest hot desert in the world, covering much of North Africa. Despite its arid climate, it is home to resilient plants and animals adapted to extreme temperatures." Какова главная мысль?', 'The text highlights both the Sahara''s scale as the largest hot desert and the survival of adapted flora and fauna.', 'Matnda Sahroi Kabirning eng katta issiq cho''l ekani va unda ekstremal iqlimga moslashgan jonzotlar yashashi aytilgan.', 'В тексте говорится о масштабах Сахары и о том, что несмотря на засушливость, там живут адаптированные растения и животные.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-reading-q2', 'en-reading', 2, 'intermediate', 1.5, 'In the sentence above, what does the word "arid" most nearly mean?', 'Yuqoridagi matnda qo''llangan "arid" so''zi qanday ma''noni bildiradi?', 'Что означает слово "arid" в приведенном выше отрывке?', '"Arid" describes a region or climate having little or no rain; extremely dry.', '"Arid" — yog''ingarchilik juda kam bo''ladigan quruq, qurg''oqchil iqlim.', '"Arid" означает «засушливый, сухой» климат с минимальным количеством осадков.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-reading-q3', 'en-reading', 3, 'intermediate', 1.5, 'Read: "While printed books remain popular for leisure reading, digital textbooks have transformed university education by offering instant searchability and portability." How does the author organize this sentence?', 'Matnni o''qing: "While printed books remain popular for leisure reading, digital textbooks have transformed university education by offering instant searchability and portability." Muallif fikrni qanday ifodalagan?', 'Прочитайте: "While printed books remain popular for leisure reading, digital textbooks have transformed university education by offering instant searchability and portability." Какой прием использует автор?', 'Using "While...", the author contrasts the continued popularity of printed books with the practical benefits of digital textbooks.', '"While..." bog''lovchisi orqali muallif bosma kitoblar va raqamli darsliklarning qulayliklarini o''zaro solishtirgan.', 'С помощью союза "While..." автор сопоставляет печатные книги и функциональные преимущества электронных учебников.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-reading-q4', 'en-reading', 4, 'intermediate', 1.5, 'Read: "Honeybees communicate the location of flowers to their hive mates through a precise sequence of movements known as the waggle dance." According to the text, why do bees perform the waggle dance?', 'Matnni o''qing: "Honeybees communicate the location of flowers to their hive mates through a precise sequence of movements known as the waggle dance." Asalarilar nima uchun "waggle dance" harakatini bajaradi?', 'Прочитайте: "Honeybees communicate the location of flowers to their hive mates through a precise sequence of movements known as the waggle dance." Зачем пчелы исполняют этот танец?', 'The passage explicitly states that bees use the waggle dance to communicate the location of flowers.', 'Matnda asalarilar bu raqs orqali gullarning qayerda ekanligini boshqa arilarga yetkazishi aniq aytilgan.', 'В тексте прямо указано, что с помощью танца пчелы передают сородичам информацию о местонахождении цветов.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-reading-q5', 'en-reading', 5, 'basic', 1, 'Read: "Notice: The central library will close at 4:00 PM this Friday for electrical maintenance and will reopen at 9:00 AM on Saturday." When can visitors return to the library?', 'E''lonni o''qing: "Notice: The central library will close at 4:00 PM this Friday for electrical maintenance and will reopen at 9:00 AM on Saturday." Kitobxonlar kutubxonaga qachon qaytib kelishlari mumkin?', 'Прочитайте объявление: "Notice: The central library will close at 4:00 PM this Friday for electrical maintenance and will reopen at 9:00 AM on Saturday." Когда посетители снова смогут прийти в библиотеку?', 'The notice states that the library "will reopen at 9:00 AM on Saturday."', 'E''londa kutubxona shanba kuni ertalab soat 9:00 da qayta ochilishi ("reopen at 9:00 AM on Saturday") ko''rsatilgan.', 'В объявлении сказано, что библиотека снова откроется в субботу в 9:00 утра.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-reading-q6', 'en-reading', 6, 'intermediate', 1.5, 'Read: "When Clara stepped onto the stage, her palms were sweating and her voice trembled during the first sentence, yet by the final chorus she sang with commanding confidence." How did Clara''s state change?', 'Matnni o''qing: "When Clara stepped onto the stage, her palms were sweating and her voice trembled during the first sentence, yet by the final chorus she sang with commanding confidence." Klaraning holati qanday o''zgardi?', 'Прочитайте: "When Clara stepped onto the stage, her palms were sweating and her voice trembled during the first sentence, yet by the final chorus she sang with commanding confidence." Как изменилось состояние Клары?', 'Sweating palms and a trembling voice infer initial nervousness, which transformed into "commanding confidence" by the end.', 'Kaft терlashi va ovoz titrashi dastlabki hayajonni, oxirida esa o''ziga bo''lgan yuqori ishonchni ("commanding confidence") ko''rsatadi.', 'Потеющие ладони и дрожащий голос говорят о начальном волнении, которое сменилось полной уверенностью к финалу.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-reading-q7', 'en-reading', 7, 'intermediate', 1.5, 'What is the purpose of the discourse marker "Furthermore" at the beginning of a paragraph?', 'Abzas boshida kelgan "Furthermore" (Bundan tashqari) kirish so''zining vazifasi nima?', 'Какую функцию выполняет связующее слово "Furthermore" (Кроме того) в начале предложения?', '"Furthermore" (like "moreover" and "in addition") adds further evidence supporting the preceding statement.', '"Furthermore" ("bundan tashqari", "ustiga-ustak") oldingi fikrni qo''llab-quvvatlovchi yangi dalil qo''shish uchun ishlatiladi.', '"Furthermore" («кроме того, более того») используется для добавления нового аргумента к уже сказанному.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-reading-q8', 'en-reading', 8, 'advanced', 2.2, 'Read: "Critics initially dismissed the architect''s glass pyramid as an jarring intrusion into the historic courtyard; within a decade, however, it had become the museum''s most celebrated emblem." What can be inferred?', 'Matnni o''qing: "Critics initially dismissed the architect''s glass pyramid as a jarring intrusion into the historic courtyard; within a decade, however, it had become the museum''s most celebrated emblem." Matndan qanday xulosa chiqarish mumkin?', 'Прочитайте: "Critics initially dismissed the architect''s glass pyramid as a jarring intrusion into the historic courtyard; within a decade, however, it had become the museum''s most celebrated emblem." Какой вывод можно сделать?', 'The contrast between "initially dismissed" and "become the museum''s most celebrated emblem" shows a complete shift in reception.', '"Initially dismissed" (avvaliga rad etilgan) va "most celebrated emblem" (eng mashhur ramzga aylandi) iboralari fikr ijobiy tomonga o''zgarganini ko''rsatadi.', 'Переход от "initially dismissed" (сначала отвергли) к "most celebrated emblem" (самый знаменитый символ) показывает перемену общественного мнения.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-reading-q9', 'en-reading', 9, 'intermediate', 1.5, 'In academic reading, what does "skimming" a text mean?', 'Matnni o''qish texnikasida "skimming" atamasi nimani anglatadi?', 'Что означает техника чтения "skimming" при работе с текстом?', 'Skimming is reading a text quickly to get the gist (general main idea), whereas scanning is looking for specific details.', '"Skimming" — matnning umumiy g''oyasini (gist) bilib olish uchun tez ko''z yugurtirib chiqish usulidir.', '"Skimming" — это ознакомительное беглое чтение для понимания общей сути текста.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-reading-q10', 'en-reading', 10, 'advanced', 2.2, 'Read: "Far from reducing employment, the introduction of automated bookkeeping software allowed accountants to pivot from repetitive data entry to high-value financial strategy." What is the author''s stance on automation here?', 'Matnni o''qing: "Far from reducing employment, the introduction of automated bookkeeping software allowed accountants to pivot from repetitive data entry to high-value financial strategy." Muallifning avtomatlashtirishga munosabati qanday?', 'Прочитайте: "Far from reducing employment, the introduction of automated bookkeeping software allowed accountants to pivot from repetitive data entry to high-value financial strategy." Какова позиция автора?', '"Far from reducing employment... allowed accountants to pivot... to high-value financial strategy" shows a positive, constructive view of automation.', 'Muallif dasturiy avtomatlashtirish ish o''rinlarini kamaytirmasdan, mutaxassislar ishini yuqori bosqichga olib chiqqanini ta''kidlaydi.', 'Автор показывает, что автоматизация освободила специалистов от рутины в пользу высококвалифицированной работы.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-advanced-q1', 'en-advanced', 1, 'advanced', 2.2, 'Choose the correct negative inversion structure: "Never before ___ such a breathtaking aurora borealis."', 'Inkor inversiyaning (Negative Inversion) to''g''ri shaklini tanlang: "Never before ___ such a breathtaking aurora borealis."', 'Выберите правильную конструкцию с отрицательной инверсией: "Never before ___ such a breathtaking aurora borealis."', 'When a negative or restrictive adverbial ("Never before", "Rarely", "Seldom") opens a sentence, auxiliary-subject inversion is required ("have I witnessed").', 'Gap "Never before", "Rarely", "Seldom" kabi inkor ravishlar bilan boshlanganda yordamchi fe''l egadan oldinga o''tadi ("have I witnessed").', 'При вынесении отрицательного наречия ("Never before") в начало предложения используется инверсия: вспомогательный глагол перед подлежащим ("have I witnessed").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-advanced-q2', 'en-advanced', 2, 'advanced', 2.2, 'Complete the formal subjunctive sentence: "The committee recommended that the regulation ___ immediately."', 'Subjunctive mood (rasmiy istak mayli) shaklini tanlang: "The committee recommended that the regulation ___ immediately."', 'Выберите правильную форму сослагательного наклонения (Subjunctive): "The committee recommended that the regulation ___ immediately."', 'After verbs of recommendation or demand (recommend, insist, suggest, demand + that), the mandative subjunctive uses the bare infinitive ("be amended").', '"Recommend", "suggest", "insist" fe''llaridan keyin "that" ergash gapida fe''lning boshlang''ich shakli (bare infinitive: "be amended") ishlatiladi.', 'После глаголов recommend, suggest, insist в придаточном с "that" используется форма Subjunctive — чистый инфинитив без to ("be amended").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-advanced-q3', 'en-advanced', 3, 'advanced', 2.2, 'Analyze this Mixed Conditional: "If she had accepted the scholarship in Paris five years ago, she ___ fluent in French now."', 'Aralash shart gapni (Mixed Conditional) to''ldiring: "If she had accepted the scholarship in Paris five years ago, she ___ fluent in French now."', 'Дополните смешанное условное предложение (Mixed Conditional): "If she had accepted the scholarship in Paris five years ago, she ___ fluent in French now."', 'A past unreal condition ("If she had accepted...") with a present result ("now") takes "would + base verb" ("would be").', 'O''tmishdagi noreal shartning ("If she had accepted") hozirgi zamondagi ("now") natijasini ifodalash uchun "would + V1" ("would be") qo''llanadi.', 'Нереальное условие в прошлом ("had accepted") с результатом в настоящем ("now") требует формы "would + V1" ("would be").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-advanced-q4', 'en-advanced', 4, 'advanced', 2.2, 'What does the English idiom "to play devil''s advocate" mean?', '"To play devil''s advocate" idiomasining ma''nosi nima?', 'Что означает английская идиома "to play devil''s advocate"?', 'Playing devil''s advocate means taking a contrary position for the sake of rigorous debate and critical analysis.', 'Bu ibora bahsda masala har tomonlama tahlil qilinishi uchun ataylab qarshi taraf dalillarini keltirishni anglatadi.', 'Идиома означает намеренно защищать противоположную точку зрения, чтобы выявить слабые места в обсуждаемой идее.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-advanced-q5', 'en-advanced', 5, 'advanced', 2.2, 'Choose the correct cleft sentence structure emphasizing the time: "It was not until the 20th century ___ commercial aviation became widespread."', 'Vaqtni kuchaytirib ko''rsatuvchi Cleft Sentence shaklini tanlang: "It was not until the 20th century ___ commercial aviation became widespread."', 'Выберите правильную часть эмфатической конструкции (Cleft Sentence): "It was not until the 20th century ___ commercial aviation became widespread."', 'The emphatic cleft construction "It was not until [X] that [Y]..." always uses the conjunction "that".', '"It was not until [X] that [Y]..." kuchaytiruvchi qurilmasida doimo "that" bog''lovchisi ishlatiladi.', 'В эмфатической конструкции "It was not until ... that ..." всегда используется союз "that".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-advanced-q6', 'en-advanced', 6, 'advanced', 2.2, 'Complete the sentence: "No sooner ___ the summit than a blizzard engulfed the mountain."', 'Gapni to''ldiring: "No sooner ___ the summit than a blizzard engulfed the mountain."', 'Дополните предложение с инверсией: "No sooner ___ the summit than a blizzard engulfed the mountain."', '"No sooner ... than ..." requires Past Perfect inversion ("had they reached") when placed at the start of a clause.', '"No sooner ... than ..." (చo''qqiga yetib ulgurmasdanoq...) qurilmasi gap boshida kelganda Past Perfect inversiyasi ("had they reached") qo''llanadi.', 'Конструкция "No sooner ... than ..." в начале предложения требует инверсии в Past Perfect ("had they reached").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-advanced-q7', 'en-advanced', 7, 'advanced', 2.2, 'What does the C1/C2 academic adjective "ubiquitous" mean?', 'Akademik ingliz tilidagi "ubiquitous" sifati qanday ma''noni anglatadi?', 'Что означает академическое прилагательное уровня C1/C2 "ubiquitous"?', '"Ubiquitous" means seeming to be everywhere at the same time; omnipresent (e.g., "Smartphones have become ubiquitous").', '"Ubiquitous" — har yerda mavjud bo''lgan, hamma joyda uchraydigan degan ma''noni bildiradi.', '"Ubiquitous" означает «вездесущий, повсеместный».') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-advanced-q8', 'en-advanced', 8, 'advanced', 2.2, 'Choose the correct participle clause: "___ from a distance, the island resembled a sleeping dragon."', 'Sifatdoshli qurilmani (Participle Clause) to''g''ri tanlang: "___ from a distance, the island resembled a sleeping dragon."', 'Выберите правильный причастный оборот: "___ from a distance, the island resembled a sleeping dragon."', 'Because the subject ("the island") is the receiver of the action (it is seen from a distance), a Past Participle ("Seen") is required.', 'Gapning egasi ("the island" — orol) harakatni o''z ustida qabul qilgani ("uzoqdан ko''rilganda") sababli Past Participle ("Seen") ishlatiladi.', 'Так как подлежащее ("the island") испытывает действие на себе (остров виден издали), используется причастие прошедшего времени ("Seen").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-advanced-q9', 'en-advanced', 9, 'advanced', 2.2, 'Complete the structure after "It''s high time": "It''s high time we ___ concrete action on climate resilience."', '"It''s high time" qurilmasidan keyin to''g''ri fe''l shaklini tanlang: "It''s high time we ___ concrete action on climate resilience."', 'Выберите правильную форму после оборота "It''s high time": "It''s high time we ___ concrete action on climate resilience."', 'The expression "It''s (high/about) time + subject" takes a Past Simple verb ("took") to express that something should have been done already.', '"It''s high time + ega" (allaqachon vaqti keldi) qurilmasidan keyin Past Simple ("took") shakli ishlatiladi.', 'После выражения "It''s high time + подлежащее" («давно пора») используется глагол в форме Past Simple ("took").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('en-advanced-q10', 'en-advanced', 10, 'advanced', 2.2, 'Which sentence demonstrates correct formal inversion in a conditional clause without "if"?', 'Qaysi gapda "if" bog''lovchisisiz rasmiy shart gap inversiyasi to''g''ri qo''llangan?', 'В каком предложении правильно использована формальная инверсия в условном предложении без союза "if"?', '"Should you require..." is the formal inverted equivalent of "If you should require / If you require...".', '"Should you require..." rasmiy uslubda "If you require..." (Agar sizga qo''shimcha yordam kerak bo''lsa...) ma''nosini beradi.', '"Should you require..." — это формальная инверсия первого типа условных предложений (вместо "If you should require...").') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-fractions-q1', 'math-fractions', 1, 'basic', 1, 'What is the simplified form of the fraction 6/8?', '6/8 kasrning qisqartirilgan (soddalashtirilgan) ko''rinishi qanday?', 'Каков сокращенный вид дроби 6/8?', 'Dividing both the numerator (6) and the denominator (8) by their greatest common divisor 2 gives 3/4.', 'Surati (6) va maxrajini (8) ularning eng katta umumiy bo''luvchisi 2 ga bo''lsak, 3/4 hosil bo''ladi.', 'Разделив числитель (6) и знаменатель (8) на их наибольший общий делитель 2, получаем 3/4.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-fractions-q2', 'math-fractions', 2, 'basic', 1, 'Calculate the sum: 1/4 + 2/4 = ?', 'Yig''indini hisoblang: 1/4 + 2/4 = ?', 'Вычислите сумму: 1/4 + 2/4 = ?', 'When adding fractions with the same denominator, add the numerators (1 + 2 = 3) and keep the denominator 4.', 'Bir xil maxrajli kasrlarni qo''shishda suratlar qo''shiladi (1 + 2 = 3), maxraj (4) esa o''zgarishsiz qoladi.', 'При сложении дробей с одинаковыми знаменателями складываются числители (1 + 2 = 3), а знаменатель (4) остается прежним.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-fractions-q3', 'math-fractions', 3, 'basic', 1, 'How is the mixed number 2 1/3 written as an improper fraction?', '2 1/3 aralash son noto''g''ri kasr ko''rinishida qanday yoziladi?', 'Как записывается смешанное число 2 1/3 в виде неправильной дроби?', 'Multiply the whole part by the denominator and add the numerator: (2 × 3 + 1) / 3 = 7/3.', 'Butun qismni maxrajga ko''paytirib, suratni qo''shamiz: (2 × 3 + 1) / 3 = 7/3.', 'Умножаем целую часть на знаменатель и прибавляем числитель: (2 × 3 + 1) / 3 = 7/3.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-fractions-q4', 'math-fractions', 4, 'basic', 1, 'Which decimal number is equal to the fraction 3/5?', '3/5 oddiy kasr qaysi o''nli kasrga teng?', 'Какая десятичная дробь равна обыкновенной дроби 3/5?', 'Dividing 3 by 5 (or writing 3/5 as 6/10) gives the decimal 0.6.', '3 ni 5 ga bo''lish (yoki 3/5 ni 6/10 ko''rinishiga keltirish) 0.6 o''nli kasrini beradi.', 'Деление 3 на 5 (или приведение 3/5 к виду 6/10) дает десятичную дробь 0.6.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-fractions-q5', 'math-fractions', 5, 'intermediate', 1.5, 'Calculate the sum: 2/3 + 1/6 = ?', 'Yig''indini hisoblang: 2/3 + 1/6 = ?', 'Вычислите сумму: 2/3 + 1/6 = ?', 'Convert 2/3 to an equivalent fraction with denominator 6 (4/6), then add: 4/6 + 1/6 = 5/6.', '2/3 kasrni maxraji 6 ga teng kasrga keltiramiz (4/6) va qo''shamiz: 4/6 + 1/6 = 5/6.', 'Приводим 2/3 к знаменателю 6 (получаем 4/6) и складываем: 4/6 + 1/6 = 5/6.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-fractions-q6', 'math-fractions', 6, 'intermediate', 1.5, 'Calculate the difference: 5/6 − 1/4 = ?', 'Ayirmani hisoblang: 5/6 − 1/4 = ?', 'Вычислите разность: 5/6 − 1/4 = ?', 'Using the least common denominator 12: 5/6 − 1/4 = 10/12 − 3/12 = 7/12.', 'Eng kichik umumiy maxraj 12 dan foydalansak: 5/6 − 1/4 = 10/12 − 3/12 = 7/12.', 'Используя наименьший общий знаменатель 12: 5/6 − 1/4 = 10/12 − 3/12 = 7/12.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-fractions-q7', 'math-fractions', 7, 'intermediate', 1.5, 'Multiply the fractions and simplify: (3/5) × (10/9) = ?', 'Kasrlarni ko''paytiring va qisqartiring: (3/5) × (10/9) = ?', 'Умножьте дроби и сократите результат: (3/5) × (10/9) = ?', 'Multiply numerators and denominators: (3 × 10) / (5 × 9) = 30/45, which simplifies by dividing by 15 to 2/3.', 'Surat va maxrajlarni ko''paytiramiz: (3 × 10) / (5 × 9) = 30/45, uni 15 ga qisqartirsak 2/3 chiqadi.', 'Перемножаем числители и знаменатели: (3 × 10) / (5 × 9) = 30/45, что после сокращения на 15 дает 2/3.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-fractions-q8', 'math-fractions', 8, 'intermediate', 1.5, 'Divide the fractions: (4/7) ÷ (2/21) = ?', 'Kasrlarni bo''ling: (4/7) ÷ (2/21) = ?', 'Разделите дроби: (4/7) ÷ (2/21) = ?', 'Multiply by the reciprocal of the second fraction: (4/7) × (21/2) = 84/14 = 6.', 'Ikkinchi kasrga teskari kasrga ko''paytiramiz: (4/7) × (21/2) = 84/14 = 6.', 'Умножаем на перевернутую вторую дробь: (4/7) × (21/2) = 84/14 = 6.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-fractions-q9', 'math-fractions', 9, 'advanced', 2.2, 'Evaluate the compound fraction: (1/2 + 1/3) ÷ (1 − 1/6) = ?', 'Murakkab kasr ifodaning qiymatini toping: (1/2 + 1/3) ÷ (1 − 1/6) = ?', 'Найдите значение выражения: (1/2 + 1/3) ÷ (1 − 1/6) = ?', 'Since 1/2 + 1/3 = 5/6 and 1 − 1/6 = 5/6, dividing 5/6 by 5/6 equals 1.', '1/2 + 1/3 = 5/6 va 1 − 1/6 = 5/6 bo''lgani uchun, 5/6 ni 5/6 ga bo''lsak 1 chiqadi.', 'Так как 1/2 + 1/3 = 5/6 и 1 − 1/6 = 5/6, при делении 5/6 на 5/6 получается 1.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-fractions-q10', 'math-fractions', 10, 'advanced', 2.2, 'A tank is 2/5 full of water. After adding 14 liters, it becomes 3/4 full. What is the total capacity of the tank?', 'Idishning 2/5 qismi suv bilan to''la. Unga 14 litr suv qo''shilgach, idishning 3/4 qismi to''ldi. Idishning umumiy sig''imi necha litr?', 'Бак заполнен водой на 2/5. После того как в него добавили 14 литров, он оказался заполнен на 3/4. Какова полная вместимость бака?', 'The added fraction is 3/4 − 2/5 = 15/20 − 8/20 = 7/20 of the tank; since 7/20 of capacity is 14 L, total capacity is 14 × (20/7) = 40 L.', 'Qo''shilgan suv ulushi 3/4 − 2/5 = 15/20 − 8/20 = 7/20 ga teng; sig''imning 7/20 qismi 14 litr bo''lsa, to''liq sig''im 14 × (20/7) = 40 litr.', 'Доля добавленной воды равна 3/4 − 2/5 = 15/20 − 8/20 = 7/20 бака; так как 7/20 вместимости составляют 14 л, полный объем равен 14 × (20/7) = 40 л.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-addition-q1', 'math-addition', 1, 'basic', 1, 'What is 47 + 38?', '47 + 38 yig''indisi nechaga teng?', 'Чему равна сумма 47 + 38?', 'Adding tens and ones: (40 + 30) + (7 + 8) = 70 + 15 = 85.', 'O''nliklar va birliklarni qo''shamiz: (40 + 30) + (7 + 8) = 70 + 15 = 85.', 'Складываем десятки и единицы: (40 + 30) + (7 + 8) = 70 + 15 = 85.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-addition-q2', 'math-addition', 2, 'basic', 1, 'Calculate: 256 + 144 = ?', 'Hisoblang: 256 + 144 = ?', 'Вычислите: 256 + 144 = ?', 'Since 56 + 44 = 100 and 200 + 100 = 300, the total sum is 300 + 100 = 400.', '56 + 44 = 100 va 200 + 100 = 300 bo''lgani uchun, umumiy yig''indi 300 + 100 = 400 ga teng.', 'Так как 56 + 44 = 100 и 200 + 100 = 300, общая сумма равна 300 + 100 = 400.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-addition-q3', 'math-addition', 3, 'basic', 1, 'What is the sum of the decimals 12.75 + 4.5?', '12.75 + 4.5 o''nli kasrlar yig''indisi nechaga teng?', 'Чему равна сумма десятичных дробей 12.75 + 4.5?', 'Aligning decimal points: 12.75 + 4.50 = 17.25.', 'Vergullarni tekislab qo''shsak: 12.75 + 4.50 = 17.25.', 'Выравнивая десятичные запятые: 12.75 + 4.50 = 17.25.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-addition-q4', 'math-addition', 4, 'basic', 1, 'Which property of addition states that a + b = b + a?', 'Qo''shishning qaysi xossasi a + b = b + a ekanligini ifodalaydi?', 'Какое свойство сложения утверждает, что a + b = b + a?', 'The commutative property of addition states that changing the order of addends does not change the sum.', 'Qo''shishning o''rin almashtirish (kommutativlik) xossasiga ko''ra, qo''shiluvchilarning o''rni almashgani bilan yig''indi o''zgarmaydi.', 'Переместительное (коммутативное) свойство сложения гласит, что от перестановки мест слагаемых сумма не меняется.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-addition-q5', 'math-addition', 5, 'intermediate', 1.5, 'Calculate: 1,489 + 2,765 = ?', 'Hisoblang: 1 489 + 2 765 = ?', 'Вычислите: 1 489 + 2 765 = ?', 'Adding place by place with carrying: 1489 + 2765 = 4254.', 'Xona birliklari bo''yicha dildagi sonlar bilan qo''shsak: 1489 + 2765 = 4254.', 'Складывая поразрядно с переносом: 1489 + 2765 = 4254.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-addition-q6', 'math-addition', 6, 'intermediate', 1.5, 'What is the sum of the integers (−18) + 25 + (−12)?', '(−18) + 25 + (−12) butun sonlar yig''indisi nechaga teng?', 'Чему равна сумма целых чисел (−18) + 25 + (−12)?', 'Combining the negative numbers first gives (−18) + (−12) = −30, and −30 + 25 = −5.', 'Avval manfiy sonlarni qo''shsak (−18) + (−12) = −30 bo''ladi, so''ngra −30 + 25 = −5.', 'Сначала сложим отрицательные числа: (−18) + (−12) = −30, затем −30 + 25 = −5.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-addition-q7', 'math-addition', 7, 'intermediate', 1.5, 'Find the missing number x in the addition: 348 + x = 615.', '348 + x = 615 tenglikdagi noma''lum qo''shiluvchi x ni toping.', 'Найдите неизвестное слагаемое x в равенстве: 348 + x = 615.', 'Subtract the known addend from the sum: x = 615 − 348 = 267.', 'Yig''indidan ma''lum qo''shiluvchini ayiramiz: x = 615 − 348 = 267.', 'Вычитаем известное слагаемое из суммы: x = 615 − 348 = 267.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-addition-q8', 'math-addition', 8, 'intermediate', 1.5, 'A library had 1,350 fiction books, 875 science books, and 625 history books. How many books are there in total?', 'Kutubxonada 1 350 ta badiiy, 875 ta ilmiy va 625 ta tarixiy kitob bor. Jami kitoblar soni nechta?', 'В библиотеке было 1 350 художественных книг, 875 научных и 625 исторических. Сколько всего книг в библиотеке?', 'Group conveniently: 875 + 625 = 1,500, and 1,500 + 1,350 = 2,850.', 'Qulay usulda guruhlab qo''shamiz: 875 + 625 = 1 500, so''ng 1 500 + 1 350 = 2 850.', 'Сгруппируем удобным способом: 875 + 625 = 1 500, и 1 500 + 1 350 = 2 850.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-addition-q9', 'math-addition', 9, 'advanced', 2.2, 'What is the sum of the first 20 positive integers: 1 + 2 + 3 + ... + 20?', 'Dastlabki 20 ta natural sonning yig''indisi nechaga teng: 1 + 2 + 3 + ... + 20?', 'Чему равна сумма первых 20 натуральных чисел: 1 + 2 + 3 + ... + 20?', 'Using Gauss''s formula n(n + 1) / 2 for n = 20 gives 20 × 21 / 2 = 210.', 'Gauss formulasidan (n(n + 1) / 2) n = 20 uchun foydalansak: 20 × 21 / 2 = 210.', 'По формуле Гаусса n(n + 1) / 2 при n = 20 получаем: 20 × 21 / 2 = 210.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-addition-q10', 'math-addition', 10, 'advanced', 2.2, 'The sum of three consecutive even numbers is 78. What is the largest of these three numbers?', 'Ketma-ket kelgan uchta juft sonning yig''indisi 78 ga teng. Shu sonlarning eng kattasini toping.', 'Сумма трех последовательных четных чисел равна 78. Найдите наибольшее из этих трех чисел.', 'The middle number is 78 / 3 = 26, so the three consecutive even numbers are 24, 26, and 28, making 28 the largest.', 'O''rtadagi son 78 / 3 = 26 ga teng, demak ketma-ket uchta juft son 24, 26 va 28 bo''lib, eng kattasi 28 dir.', 'Среднее число равно 78 / 3 = 26, значит три последовательных четных числа — это 24, 26 и 28, а наибольшее из них — 28.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-subtraction-q1', 'math-subtraction', 1, 'basic', 1, 'What is 93 − 47?', '93 − 47 ayirmasi nechaga teng?', 'Чему равна разность 93 − 47?', 'Regrouping 93 as 80 + 13: (80 − 40) + (13 − 7) = 40 + 6 = 46.', '93 ni 80 + 13 ko''rinishida olsak: (80 − 40) + (13 − 7) = 40 + 6 = 46.', 'Заняв десяток (93 = 80 + 13), получаем: (80 − 40) + (13 − 7) = 40 + 6 = 46.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-subtraction-q2', 'math-subtraction', 2, 'basic', 1, 'Calculate: 500 − 168 = ?', 'Hisoblang: 500 − 168 = ?', 'Вычислите: 500 − 168 = ?', '500 − 100 = 400, 400 − 60 = 340, and 340 − 8 = 332.', '500 − 100 = 400, 400 − 60 = 340 va 340 − 8 = 332.', '500 − 100 = 400, 400 − 60 = 340 и 340 − 8 = 332.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-subtraction-q3', 'math-subtraction', 3, 'basic', 1, 'In the subtraction equation 50 − 18 = 32, what is the number 50 called?', '50 − 18 = 32 ayirish amalida 50 soni nima deb ataladi?', 'Как называется число 50 в выражении на вычитание 50 − 18 = 32?', 'In a − b = c, the first number (a) from which another is subtracted is the minuend, b is the subtrahend, and c is the difference.', 'a − b = c ifodada a — kamayuvchi, b — ayiriluvchi va c — ayirma deb ataladi.', 'В выражении a − b = c число a, из которого вычитают, называется уменьшаемым, b — вычитаемым, а c — разностью.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-subtraction-q4', 'math-subtraction', 4, 'basic', 1, 'Calculate the decimal difference: 15.4 − 6.85 = ?', 'O''nli kasrlar ayirmasini hisoblang: 15.4 − 6.85 = ?', 'Вычислите разность десятичных дробей: 15.4 − 6.85 = ?', 'Write 15.4 as 15.40, then subtract: 15.40 − 6.85 = 8.55.', '15.4 ni 15.40 ko''rinishida yozib ayiramiz: 15.40 − 6.85 = 8.55.', 'Запишем 15.4 как 15.40 и вычтем: 15.40 − 6.85 = 8.55.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-subtraction-q5', 'math-subtraction', 5, 'intermediate', 1.5, 'What is the value of (−14) − (−21)?', '(−14) − (−21) ifodaning qiymati nechaga teng?', 'Чему равно значение выражения (−14) − (−21)?', 'Subtracting a negative number is the same as adding its positive opposite: −14 + 21 = 7.', 'Manfiy sonni ayirish unga qarama-qarshi musbat sonni qo''shish bilan bir xil: −14 + 21 = 7.', 'Вычитание отрицательного числа равносильно сложению с противоположным положительным числом: −14 + 21 = 7.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-subtraction-q6', 'math-subtraction', 6, 'intermediate', 1.5, 'Calculate: 10,000 − 3,456 = ?', 'Hisoblang: 10 000 − 3 456 = ?', 'Вычислите: 10 000 − 3 456 = ?', 'Since 3,456 + 6,544 = 10,000, the difference is 6,544.', '3 456 + 6 544 = 10 000 bo''lgani uchun, ayirma 6 544 ga teng.', 'Так как 3 456 + 6 544 = 10 000, разность равна 6 544.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-subtraction-q7', 'math-subtraction', 7, 'intermediate', 1.5, 'Find x if 820 − x = 475.', 'Agar 820 − x = 475 bo''lsa, x ni toping.', 'Найдите x, если 820 − x = 475.', 'To find the unknown subtrahend, subtract the difference from the minuend: x = 820 − 475 = 345.', 'Noma''lum ayiriluvchini topish uchun kamayuvchidan ayirmani ayiramiz: x = 820 − 475 = 345.', 'Чтобы найти неизвестное вычитаемое, нужно из уменьшаемого вычесть разность: x = 820 − 475 = 345.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-subtraction-q8', 'math-subtraction', 8, 'intermediate', 1.5, 'The temperature in a mountain town dropped from 8 °C during the day to −11 °C at night. By how many degrees did the temperature drop?', 'Tog''li shaharchada havo harorati kunduzi 8 °C dan kechasi −11 °C gacha pasaydi. Harorat necha darajaga tushgan?', 'Температура в горном городе упала с 8 °C днем до −11 °C ночью. На сколько градусов понизилась температура?', 'The magnitude of the drop is the difference between the initial and final temperatures: 8 − (−11) = 8 + 11 = 19 °C.', 'Haroratning pasayish miqdori boshlang''ich va oxirgi haroratlar ayirmasiga teng: 8 − (−11) = 8 + 11 = 19 °C.', 'Величина падения температуры равна разности между начальной и конечной температурой: 8 − (−11) = 8 + 11 = 19 °C.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-subtraction-q9', 'math-subtraction', 9, 'advanced', 2.2, 'Evaluate: 1,000 − (245 + 355) − (180 − 60) = ?', 'Ifodaning qiymatini toping: 1 000 − (245 + 355) − (180 − 60) = ?', 'Найдите значение выражения: 1 000 − (245 + 355) − (180 − 60) = ?', 'Evaluate parentheses first: 245 + 355 = 600 and 180 − 60 = 120; then 1,000 − 600 − 120 = 280.', 'Avval qavs ichidagi amallarni bajaramiz: 245 + 355 = 600 va 180 − 60 = 120; so''ngra 1 000 − 600 − 120 = 280.', 'Сначала вычисляем выражения в скобках: 245 + 355 = 600 и 180 − 60 = 120; затем 1 000 − 600 − 120 = 280.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-subtraction-q10', 'math-subtraction', 10, 'advanced', 2.2, 'If the minuend is increased by 35 and the subtrahend is decreased by 15, how does the difference change?', 'Agar kamayuvchi 35 ga orttirilsa va ayiriluvchi 15 ga kamaytirilsa, ayirma qanday o''zgaradi?', 'Если уменьшаемое увеличить на 35, а вычитаемое уменьшить на 15, как изменится разность?', '(a + 35) − (b − 15) = a + 35 − b + 15 = (a − b) + 50, so the difference increases by 50.', '(a + 35) − (b − 15) = a + 35 − b + 15 = (a − b) + 50, demak ayirma 50 ga ortadi.', '(a + 35) − (b − 15) = a + 35 − b + 15 = (a − b) + 50, следовательно, разность увеличится на 50.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-multiplication-q1', 'math-multiplication', 1, 'basic', 1, 'What is 14 × 6?', '14 × 6 ko''paytmasi nechaga teng?', 'Чему равно произведение 14 × 6?', 'Using the distributive property: (10 × 6) + (4 × 6) = 60 + 24 = 84.', 'Taqsimot xossasidan foydalansak: (10 × 6) + (4 × 6) = 60 + 24 = 84.', 'Используя распределительное свойство: (10 × 6) + (4 × 6) = 60 + 24 = 84.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-multiplication-q2', 'math-multiplication', 2, 'basic', 1, 'What is the product of 378 × 0?', '378 × 0 ko''paytmasi nechaga teng?', 'Чему равно произведение 378 × 0?', 'By the zero property of multiplication, any number multiplied by 0 equals 0.', 'Ko''paytirishning nol xossasiga ko''ra, har qanday sonni 0 ga ko''paytirganda natija 0 ga teng bo''ladi.', 'По свойству умножения на ноль любое число, умноженное на 0, дает 0.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-multiplication-q3', 'math-multiplication', 3, 'basic', 1, 'Calculate: 25 × 16 = ?', 'Hisoblang: 25 × 16 = ?', 'Вычислите: 25 × 16 = ?', 'Rewrite 16 as 4 × 4: 25 × 4 × 4 = 100 × 4 = 400.', '16 ni 4 × 4 ko''rinishida yozsak: 25 × 4 × 4 = 100 × 4 = 400.', 'Представим 16 как 4 × 4: 25 × 4 × 4 = 100 × 4 = 400.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-multiplication-q4', 'math-multiplication', 4, 'basic', 1, 'What is 3.45 × 100?', '3.45 × 100 nechaga teng?', 'Чему равно 3.45 × 100?', 'Multiplying a decimal by 100 shifts the decimal point two places to the right, giving 345.', 'O''nli kasrni 100 ga ko''paytirganda vergul ikki xona o''ngga suriladi va 345 hosil bo''ladi.', 'При умножении десятичной дроби на 100 запятая переносится на два знака вправо, что дает 345.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-multiplication-q5', 'math-multiplication', 5, 'intermediate', 1.5, 'What is the product of (−8) × (−9)?', '(−8) × (−9) ko''paytmasi nechaga teng?', 'Чему равно произведение (−8) × (−9)?', 'The product of two negative numbers is always positive: (−8) × (−9) = 72.', 'Ikkita manfiy sonning ko''paytmasi har doim musbat bo''ladi: (−8) × (−9) = 72.', 'Произведение двух отрицательных чисел всегда положительно: (−8) × (−9) = 72.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-multiplication-q6', 'math-multiplication', 6, 'intermediate', 1.5, 'Calculate the decimal product: 1.5 × 0.04 = ?', 'O''nli kasrlar ko''paytmasini hisoblang: 1.5 × 0.04 = ?', 'Вычислите произведение десятичных дробей: 1.5 × 0.04 = ?', 'Multiply 15 × 4 = 60, and place three decimal digits in total (1 + 2 = 3): 0.060 = 0.06.', '15 × 4 = 60 ni hisoblab, verguldan keyin jami 3 ta xona (1 + 2 = 3) ajratamiz: 0.060 = 0.06.', 'Умножаем 15 × 4 = 60 и отделяем запятой три знака (1 + 2 = 3): 0.060 = 0.06.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-multiplication-q7', 'math-multiplication', 7, 'intermediate', 1.5, 'Calculate: 125 × 24 = ?', 'Hisoblang: 125 × 24 = ?', 'Вычислите: 125 × 24 = ?', 'Factor 24 as 8 × 3: (125 × 8) × 3 = 1,000 × 3 = 3,000.', '24 ni 8 × 3 ko''rinishida yozsak: (125 × 8) × 3 = 1 000 × 3 = 3 000.', 'Разложим 24 как 8 × 3: (125 × 8) × 3 = 1 000 × 3 = 3 000.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-multiplication-q8', 'math-multiplication', 8, 'intermediate', 1.5, 'Use the distributive property to evaluate quickly: 37 × 64 + 37 × 36 = ?', 'Taqsimot xossasidan foydalanib qulay usulda hisoblang: 37 × 64 + 37 × 36 = ?', 'Вычислите рациональным способом, используя распределительное свойство: 37 × 64 + 37 × 36 = ?', 'Factor out 37: 37 × (64 + 36) = 37 × 100 = 3,700.', '37 ni qavsdan tashqariga chiqaramiz: 37 × (64 + 36) = 37 × 100 = 3 700.', 'Вынесем общий множитель 37 за скобки: 37 × (64 + 36) = 37 × 100 = 3 700.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-multiplication-q9', 'math-multiplication', 9, 'advanced', 2.2, 'What is the units (last) digit of the product 73 × 47 × 29?', '73 × 47 × 29 ko''paytmasining oxirgi (birliklar xonasidagi) raqami nechaga teng?', 'Какой цифрой оканчивается произведение 73 × 47 × 29?', 'Multiply only the units digits: 3 × 7 = 21 (ends in 1), and 1 × 9 = 9.', 'Faqat oxirgi raqamlarni ko''paytiramiz: 3 × 7 = 21 (1 bilan tugaydi) va 1 × 9 = 9.', 'Перемножим только последние цифры: 3 × 7 = 21 (оканчивается на 1), и 1 × 9 = 9.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-multiplication-q10', 'math-multiplication', 10, 'advanced', 2.2, 'Evaluate using the difference of squares shortcut: 98 × 102 = ?', 'Kvadratlar ayirmasi formulasidan foydalanib hisoblang: 98 × 102 = ?', 'Вычислите, используя формулу разности квадратов: 98 × 102 = ?', 'Write 98 × 102 as (100 − 2)(100 + 2) = 100² − 2² = 10,000 − 4 = 9,996.', '98 × 102 ni (100 − 2)(100 + 2) ko''rinishida yozsak: 100² − 2² = 10 000 − 4 = 9 996.', 'Представим 98 × 102 как (100 − 2)(100 + 2) = 100² − 2² = 10 000 − 4 = 9 996.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-division-q1', 'math-division', 1, 'basic', 1, 'What is 144 ÷ 12?', '144 ÷ 12 bo''linmasi nechaga teng?', 'Чему равно частное 144 ÷ 12?', 'Since 12 × 12 = 144, dividing 144 by 12 equals 12.', '12 × 12 = 144 bo''lgani uchun, 144 ni 12 ga bo''lsak 12 chiqadi.', 'Так как 12 × 12 = 144, деление 144 на 12 дает 12.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-division-q2', 'math-division', 2, 'basic', 1, 'What is the remainder when 29 is divided by 6?', '29 ni 6 ga bo''lganda qoldiq nechaga teng bo''ladi?', 'Чему равен остаток от деления 29 на 6?', 'Since 29 = 6 × 4 + 5, the quotient is 4 and the remainder is 5.', '29 = 6 × 4 + 5 bo''lgani uchun, to''liqsiz bo''linma 4 ga, qoldiq esa 5 ga teng.', 'Так как 29 = 6 × 4 + 5, неполное частное равно 4, а остаток равен 5.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-division-q3', 'math-division', 3, 'basic', 1, 'What is the result of dividing any non-zero number by 0 (e.g., 15 ÷ 0)?', 'Noldan farqli har qanday sonni 0 ga bo''lish (masalan, 15 ÷ 0) natijasi nima bo''ladi?', 'Чему равен результат деления любого ненулевого числа на 0 (например, 15 ÷ 0)?', 'Division by zero is undefined in arithmetic because no number multiplied by 0 can equal 15.', 'Arifmetikada nolga bo''lish aniqlanmagan, chunki hech qanday sonni 0 ga ko''paytirib 15 ni hosil qilib bo''lmaydi.', 'Деление на ноль в арифметике не определено, так как ни одно число при умножении на 0 не даст 15.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-division-q4', 'math-division', 4, 'basic', 1, 'Calculate: 840 ÷ 20 = ?', 'Hisoblang: 840 ÷ 20 = ?', 'Вычислите: 840 ÷ 20 = ?', 'Cancel a factor of 10 from both numbers: 840 ÷ 20 = 84 ÷ 2 = 42.', 'Ikkala sonni ham 10 ga qisqartiramiz: 840 ÷ 20 = 84 ÷ 2 = 42.', 'Сократим оба числа на 10: 840 ÷ 20 = 84 ÷ 2 = 42.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-division-q5', 'math-division', 5, 'intermediate', 1.5, 'Divide the decimals: 7.2 ÷ 0.08 = ?', 'O''nli kasrlarni bo''ling: 7.2 ÷ 0.08 = ?', 'Разделите десятичные дроби: 7.2 ÷ 0.08 = ?', 'Multiply both dividend and divisor by 100 to clear decimals: 720 ÷ 8 = 90.', 'Bo''linuvchi va bo''luvchini 100 ga ko''paytirib butun songa keltiramiz: 720 ÷ 8 = 90.', 'Умножим делимое и делитель на 100, чтобы избавиться от запятой: 720 ÷ 8 = 90.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-division-q6', 'math-division', 6, 'intermediate', 1.5, 'Which of the following numbers is divisible by 9 without a remainder?', 'Quyidagi sonlardan qaysi biri 9 ga qoldiqsiz bo''linadi?', 'Какое из следующих чисел делится на 9 без остатка?', 'A number is divisible by 9 if the sum of its digits is divisible by 9; for 4,752, 4 + 7 + 5 + 2 = 18, which is divisible by 9.', 'Raqamlari yig''indisi 9 ga bo''linadigan son 9 ga bo''linadi; 4 752 sonida 4 + 7 + 5 + 2 = 18 bo''lib, u 9 ga qoldiqsiz bo''linadi.', 'Число делится на 9, если сумма его цифр делится на 9; у числа 4 752 сумма цифр 4 + 7 + 5 + 2 = 18 делится на 9.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-division-q7', 'math-division', 7, 'intermediate', 1.5, 'When a number N is divided by 14, the quotient is 8 and the remainder is 5. What is N?', 'N sonini 14 ga bo''lganda to''liqsiz bo''linma 8 va qoldiq 5 chiqdi. N sonini toping.', 'При делении числа N на 14 частное равно 8, а остаток равен 5. Чему равно число N?', 'By the division algorithm, Dividend = Divisor × Quotient + Remainder: N = 14 × 8 + 5 = 112 + 5 = 117.', 'Qoldiqli bo''lish formulasiga ko''ra (Bo''linuvchi = Bo''luvchi × Bo''linma + Qoldiq): N = 14 × 8 + 5 = 112 + 5 = 117.', 'По формуле деления с остатком (Делимое = Делитель × Частное + Остаток): N = 14 × 8 + 5 = 112 + 5 = 117.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-division-q8', 'math-division', 8, 'intermediate', 1.5, 'What is (−96) ÷ 16?', '(−96) ÷ 16 nechaga teng?', 'Чему равно (−96) ÷ 16?', 'Dividing a negative number by a positive number gives a negative result: −96 ÷ 16 = −6.', 'Manfiy sonni musbat songa bo''lganda natija manfiy bo''ladi: −96 ÷ 16 = −6.', 'Деление отрицательного числа на положительное дает отрицательный результат: −96 ÷ 16 = −6.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-division-q9', 'math-division', 9, 'advanced', 2.2, 'A bus holds at most 45 passengers. What is the minimum number of buses needed to transport 380 students at the same time?', 'Bitta avtobusga ko''pi bilan 45 nafar yo''lovchi sig''adi. 380 nafar o''quvchini bir vaqtda olib ketish uchun eng kamida nechta avtobus kerak bo''ladi?', 'Один автобус вмещает не более 45 пассажиров. Какое наименьшее количество автобусов потребуется, чтобы перевезти 380 учеников одновременно?', '380 ÷ 45 = 8 with a remainder of 20 students, so an 9th bus is required to carry the remaining 20 students.', '380 ÷ 45 = 8 va 20 nafar o''quvchi ortib qoladi, shuning uchun qolgan 20 o''quvchi uchun 9-avtobus ham kerak.', '380 ÷ 45 = 8 и 20 учеников в остатке, поэтому для оставшихся 20 учеников необходим 9-й автобус.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-division-q10', 'math-division', 10, 'advanced', 2.2, 'What is the greatest common divisor (GCD) of 84 and 126?', '84 va 126 sonlarining eng katta umumiy bo''luvchisini (EKUB) toping.', 'Чему равен наибольший общий делитель (НОД) чисел 84 и 126?', '84 = 42 × 2 and 126 = 42 × 3; since 2 and 3 are coprime, GCD(84, 126) = 42.', '84 = 42 × 2 va 126 = 42 × 3; 2 va 3 o''zaro tub bo''lgani uchun EKUB(84, 126) = 42.', '84 = 42 × 2 и 126 = 42 × 3; так как 2 и 3 взаимно просты, НОД(84, 126) = 42.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-percentages-q1', 'math-percentages', 1, 'basic', 1, 'What is 25% of 160?', '160 sonining 25 foizi nechaga teng?', 'Чему равны 25% от числа 160?', '25% is equivalent to 1/4, and 160 ÷ 4 = 40.', '25% ulush 1/4 kasrga teng, 160 ÷ 4 = 40.', '25% — это четверть числа (1/4), а 160 ÷ 4 = 40.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-percentages-q2', 'math-percentages', 2, 'basic', 1, 'How is the fraction 3/4 expressed as a percentage?', '3/4 kasr foiz ko''rinishida qanday ifodalanadi?', 'Как выражается дробь 3/4 в процентах?', 'Multiply the fraction by 100%: (3/4) × 100% = 75%.', 'Kasrni 100% ga ko''paytiramiz: (3/4) × 100% = 75%.', 'Умножаем дробь на 100%: (3/4) × 100% = 75%.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-percentages-q3', 'math-percentages', 3, 'basic', 1, 'Which decimal represents 18%?', '18% qaysi o''nli kasrga teng?', 'Какая десятичная дробь соответствует 18%?', 'Per cent means per hundred, so 18% = 18 / 100 = 0.18.', 'Foiz yuzdan bir ulush degani, shuning uchun 18% = 18 / 100 = 0.18.', 'Процент означает сотую часть, поэтому 18% = 18 / 100 = 0.18.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-percentages-q4', 'math-percentages', 4, 'basic', 1, 'What percentage of 50 is 15?', '15 soni 50 ning necha foizini tashkil qiladi?', 'Сколько процентов составляет число 15 от 50?', '(15 / 50) × 100% = (30 / 100) × 100% = 30%.', '(15 / 50) × 100% = (30 / 100) × 100% = 30%.', '(15 / 50) × 100% = (30 / 100) × 100% = 30%.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-percentages-q5', 'math-percentages', 5, 'intermediate', 1.5, 'A jacket priced at $80 is on sale with a 15% discount. What is the sale price?', 'Narxi $80 bo''lgan kurtka 15% chegirma bilan sotilmoqda. Kurtkaning chegirmadagi narxi qancha?', 'Куртка стоимостью $80 продается со скидкой 15%. Какова цена куртки со скидкой?', 'The discount is 15% of $80 = $12, so the sale price is $80 − $12 = $68.', 'Chegirma miqdori $80 ning 15% qismi, ya''ni $12 ga teng; demak yangi narx $80 − $12 = $68.', 'Скидка составляет 15% от $80 = $12, следовательно, цена со скидкой равна $80 − $12 = $68.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-percentages-q6', 'math-percentages', 6, 'intermediate', 1.5, 'If 20% of a number is 45, what is the whole number?', 'Agar sonning 20% qismi 45 ga teng bo''lsa, shu sonning o''zini toping.', 'Если 20% некоторого числа равны 45, чему равно всё число?', 'Since 20% is 1/5 of the number, the full number is 45 × 5 = 225.', '20% sonning 1/5 qismi bo''lgani uchun, to''liq son 45 × 5 = 225 ga teng.', 'Так как 20% — это 1/5 числа, то всё число равно 45 × 5 = 225.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-percentages-q7', 'math-percentages', 7, 'intermediate', 1.5, 'The price of a ticket increased from $40 to $50. What was the percentage increase?', 'Chipta narxi $40 dan $50 ga oshdi. Narx necha foizga oshgan?', 'Цена билета выросла с $40 до $50. На сколько процентов увеличилась цена?', 'Percentage increase = ((50 − 40) / 40) × 100% = (10 / 40) × 100% = 25%.', 'Foiz o''sishi = ((50 − 40) / 40) × 100% = (10 / 40) × 100% = 25%.', 'Процентный рост = ((50 − 40) / 40) × 100% = (10 / 40) × 100% = 25%.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-percentages-q8', 'math-percentages', 8, 'intermediate', 1.5, 'You deposit $500 in a savings account at 6% simple annual interest. How much total money will be in the account after 2 years?', 'Siz jamg''arma hisobiga yillik 6% oddiy foiz stavkasi bilan $500 qo''ydingiz. 2 yildan so''ng hisobda jami qancha pul bo''ladi?', 'Вы положили $500 на сберегательный счет под 6% простых годовых. Какая сумма будет на счете через 2 года?', 'Simple interest I = P × r × t = 500 × 0.06 × 2 = $60, so the total amount is $500 + $60 = $560.', 'Oddiy foiz daromadi I = 500 × 0.06 × 2 = $60, demak jami summa $500 + $60 = $560 bo''ladi.', 'Простые проценты за 2 года составят 500 × 0.06 × 2 = $60, поэтому итоговая сумма равна $500 + $60 = $560.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-percentages-q9', 'math-percentages', 9, 'advanced', 2.2, 'A price is first increased by 20% and then decreased by 20%. How does the final price compare to the original price?', 'Mahsulot narxi avval 20% ga oshirildi, keyin esa yangi narx 20% ga arzonlashtirildi. Hosil bo''lgan oxirgi narx dastlabki narxga nisbatan qanday o''zgardi?', 'Цену товара сначала повысили на 20%, а затем новую цену снизили на 20%. Как итоговая цена соотносится с первоначальной?', 'Multiplying the multipliers gives 1.20 × 0.80 = 0.96, which is 96% of the original price (a 4% decrease).', 'Ko''paytiruvchilarni ko''paytirsak: 1.20 × 0.80 = 0.96, ya''ni dastlabki narxning 96% qismi qoladi (4% ga kamaygan).', 'Перемножение коэффициентов дает 1.20 × 0.80 = 0.96, что составляет 96% от начальной цены (снижение на 4%).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-percentages-q10', 'math-percentages', 10, 'advanced', 2.2, 'After a 25% discount, a laptop costs $600. What was the original price before the discount?', '25% chegirmadan so''ng noutbukning narxi $600 bo''ldi. Chegirmagacha bo''lgan dastlabki narx qancha edi?', 'После скидки 25% ноутбук стоит $600. Какова была его первоначальная цена до скидки?', '$600 represents 75% (or 3/4) of the original price, so the original price is $600 ÷ 0.75 = $800.', '$600 dastlabki narxning 75% (yoki 3/4) qismini tashkil etadi, shuning uchun dastlabki narx $600 ÷ 0.75 = $800.', '$600 составляют 75% (или 3/4) от исходной цены, поэтому первоначальная цена равна $600 ÷ 0.75 = $800.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-algebra-q1', 'math-algebra', 1, 'basic', 1, 'Evaluate the algebraic expression 3x + 5 when x = 4.', 'x = 4 bo''lganda 3x + 5 algebraik ifodaning qiymatini toping.', 'Найдите значение алгебраического выражения 3x + 5 при x = 4.', 'Substitute x = 4 into the expression: 3(4) + 5 = 12 + 5 = 17.', 'Ifodaga x = 4 ni qo''yamiz: 3(4) + 5 = 12 + 5 = 17.', 'Подставляем x = 4 в выражение: 3(4) + 5 = 12 + 5 = 17.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-algebra-q2', 'math-algebra', 2, 'basic', 1, 'Simplify by combining like terms: 5a + 3b − 2a + 4b.', 'O''xshash hadlarni ixchamlang: 5a + 3b − 2a + 4b.', 'Упростите выражение, приведя подобные слагаемые: 5a + 3b − 2a + 4b.', 'Combine the a-terms (5a − 2a = 3a) and the b-terms (3b + 4b = 7b) to get 3a + 7b.', 'a qatnashgan hadlarni (5a − 2a = 3a) va b qatnashgan hadlarni (3b + 4b = 7b) qo''shib, 3a + 7b ni olamiz.', 'Группируем слагаемые с a (5a − 2a = 3a) и с b (3b + 4b = 7b), получая 3a + 7b.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-algebra-q3', 'math-algebra', 3, 'basic', 1, 'Expand the brackets: 4(2x − 3).', 'Qavslarni oching: 4(2x − 3).', 'Раскройте скобки: 4(2x − 3).', 'Multiply each term inside the brackets by 4: 4 × 2x − 4 × 3 = 8x − 12.', 'Qavs ichidagi har bir hadni 4 ga ko''paytiramiz: 4 × 2x − 4 × 3 = 8x − 12.', 'Умножаем каждое слагаемое в скобках на 4: 4 × 2x − 4 × 3 = 8x − 12.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-algebra-q4', 'math-algebra', 4, 'basic', 1, 'Simplify using exponent rules: x³ · x⁴.', 'Daraja xossalaridan foydalanib soddalashtiring: x³ · x⁴.', 'Упростите, используя свойства степеней: x³ · x⁴.', 'When multiplying powers with the same base, add the exponents: x³⁺⁴ = x⁷.', 'Asoslari bir xil bo''lgan darajalarni ko''paytirishda daraja ko''rsatkichlari qo''shiladi: x³⁺⁴ = x⁷.', 'При умножении степеней с одинаковым основанием показатели складываются: x³⁺⁴ = x⁷.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-algebra-q5', 'math-algebra', 5, 'intermediate', 1.5, 'Expand and simplify: (x + 5)(x − 2).', 'Qavslarni oching va soddalashtiring: (x + 5)(x − 2).', 'Раскройте скобки и упростите: (x + 5)(x − 2).', 'Using FOIL: x² − 2x + 5x − 10 = x² + 3x − 10.', 'Ko''phadlarni ko''paytirish qoidasiga ko''ra: x² − 2x + 5x − 10 = x² + 3x − 10.', 'Перемножая двучлены: x² − 2x + 5x − 10 = x² + 3x − 10.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-algebra-q6', 'math-algebra', 6, 'intermediate', 1.5, 'Factor completely using the difference of squares: x² − 49.', 'Kvadratlar ayirmasi formulasidan foydalanib ko''paytuvchilarga ajrating: x² − 49.', 'Разложите на множители по формуле разности квадратов: x² − 49.', 'By the difference of squares identity a² − b² = (a − b)(a + b), x² − 7² = (x − 7)(x + 7).', 'a² − b² = (a − b)(a + b) qisqa ko''paytirish formulasiga ko''ra, x² − 7² = (x − 7)(x + 7).', 'По формуле разности квадратов a² − b² = (a − b)(a + b) получаем x² − 7² = (x − 7)(x + 7).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-algebra-q7', 'math-algebra', 7, 'intermediate', 1.5, 'Expand the square of a binomial: (2x + 3)².', 'Ikki had yig''indisining kvadratini oching: (2x + 3)².', 'Преобразуйте квадрат двучлена в многочлен: (2x + 3)².', 'Using (a + b)² = a² + 2ab + b²: (2x)² + 2(2x)(3) + 3² = 4x² + 12x + 9.', '(a + b)² = a² + 2ab + b² formulasiga ko''ra: (2x)² + 2(2x)(3) + 3² = 4x² + 12x + 9.', 'По формуле (a + b)² = a² + 2ab + b²: (2x)² + 2(2x)(3) + 3² = 4x² + 12x + 9.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-algebra-q8', 'math-algebra', 8, 'intermediate', 1.5, 'Evaluate 2x² − 3y when x = −3 and y = 4.', 'x = −3 va y = 4 bo''lganda 2x² − 3y ifodaning qiymatini hisoblang.', 'Найдите значение выражения 2x² − 3y при x = −3 и y = 4.', 'Since (−3)² = 9, we have 2(9) − 3(4) = 18 − 12 = 6.', '(−3)² = 9 bo''lgani uchun: 2(9) − 3(4) = 18 − 12 = 6.', 'Так как (−3)² = 9, получаем: 2(9) − 3(4) = 18 − 12 = 6.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-algebra-q9', 'math-algebra', 9, 'advanced', 2.2, 'Simplify the rational algebraic expression (x² − 9) / (x² + 6x + 9) for x ≠ −3.', 'x ≠ −3 bo''lganda (x² − 9) / (x² + 6x + 9) ratsional kasrni qisqartiring.', 'Сократите алгебраическую дробь (x² − 9) / (x² + 6x + 9) при x ≠ −3.', 'Factor numerator as (x − 3)(x + 3) and denominator as (x + 3)², then cancel (x + 3) to get (x − 3) / (x + 3).', 'Suratini (x − 3)(x + 3) va maxrajini (x + 3)² ko''rinishida ko''paytuvchilarga ajratib, (x + 3) ga qisqartirsak, (x − 3) / (x + 3) qoladi.', 'Разложим числитель на (x − 3)(x + 3), а знаменатель на (x + 3)², после сокращения на (x + 3) получим (x − 3) / (x + 3).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-algebra-q10', 'math-algebra', 10, 'advanced', 2.2, 'If x + 1/x = 5, what is the value of x² + 1/x²?', 'Agar x + 1/x = 5 bo''lsa, x² + 1/x² ifodaning qiymati nechaga teng?', 'Если x + 1/x = 5, чему равно значение выражения x² + 1/x²?', 'Squaring both sides gives (x + 1/x)² = x² + 2 + 1/x² = 25, so x² + 1/x² = 25 − 2 = 23.', 'Tenglikning ikkala tomonini kvadratga ko''tarsak: (x + 1/x)² = x² + 2 + 1/x² = 25, bundan x² + 1/x² = 25 − 2 = 23.', 'Возведем обе части в квадрат: (x + 1/x)² = x² + 2 + 1/x² = 25, откуда x² + 1/x² = 25 − 2 = 23.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-equations-q1', 'math-equations', 1, 'basic', 1, 'Solve for x: 2x + 7 = 19.', 'Tenglamani yeching: 2x + 7 = 19.', 'Решите уравнение: 2x + 7 = 19.', 'Subtract 7 from both sides to get 2x = 12, then divide by 2 to get x = 6.', 'Ikkala tomondan 7 ni ayirsak 2x = 12 bo''ladi, so''ng 2 ga bo''lib x = 6 ni topamiz.', 'Вычтем 7 из обеих частей (2x = 12) и разделим на 2, получив x = 6.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-equations-q2', 'math-equations', 2, 'basic', 1, 'Solve for x: x / 4 − 3 = 5.', 'Tenglamani yeching: x / 4 − 3 = 5.', 'Решите уравнение: x / 4 − 3 = 5.', 'Add 3 to both sides to get x / 4 = 8, then multiply by 4 to get x = 32.', 'Ikkala tomonga 3 ni qo''shsak x / 4 = 8 bo''ladi, so''ng 4 ga ko''paytirib x = 32 ni olamiz.', 'Прибавим 3 к обеим частям (x / 4 = 8) и умножим на 4, получив x = 32.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-equations-q3', 'math-equations', 3, 'basic', 1, 'Solve for x: 5x − 12 = 2x + 6.', 'Tenglamani yeching: 5x − 12 = 2x + 6.', 'Решите уравнение: 5x − 12 = 2x + 6.', 'Subtract 2x and add 12 to both sides: 3x = 18, so x = 6.', 'Hadlarni bir tomonga o''tkazsak: 5x − 2x = 6 + 12, ya''ni 3x = 18 va x = 6.', 'Перенесем слагаемые: 5x − 2x = 6 + 12, откуда 3x = 18 и x = 6.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-equations-q4', 'math-equations', 4, 'basic', 1, 'Which value of x is a solution to the equation 3(x − 2) = 15?', 'x ning qaysi qiymati 3(x − 2) = 15 tenglamaning ildizi bo''ladi?', 'Какое значение x является корнем уравнения 3(x − 2) = 15?', 'Divide both sides by 3 to get x − 2 = 5, then add 2 to get x = 7.', 'Ikkala tomonni 3 ga bo''lsak x − 2 = 5 chiqadi, so''ng 2 ni qo''shib x = 7 ni topamiz.', 'Разделим обе части на 3 (x − 2 = 5) и прибавим 2, получив x = 7.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-equations-q5', 'math-equations', 5, 'intermediate', 1.5, 'What are the roots of the quadratic equation x² − 5x + 6 = 0?', 'x² − 5x + 6 = 0 kvadrat tenglamaning ildizlarini toping.', 'Найдите корни квадратного уравнения x² − 5x + 6 = 0.', 'Factoring the quadratic gives (x − 2)(x − 3) = 0, so the roots are x = 2 and x = 3.', 'Kvadrat uchhadni ko''paytuvchilarga ajratsak (x − 2)(x − 3) = 0 bo''ladi, demak ildizlar x = 2 va x = 3.', 'Разложив левую часть на множители (x − 2)(x − 3) = 0, получаем корни x = 2 и x = 3.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-equations-q6', 'math-equations', 6, 'intermediate', 1.5, 'Solve the proportion for x: (x + 1) / 3 = (x + 5) / 4.', 'Proporsiyadan x ni toping: (x + 1) / 3 = (x + 5) / 4.', 'Решите уравнение-пропорцию: (x + 1) / 3 = (x + 5) / 4.', 'Cross-multiply: 4(x + 1) = 3(x + 5) ⇒ 4x + 4 = 3x + 15 ⇒ x = 11.', 'Proporsiyaning asosiy xossasiga ko''ra: 4(x + 1) = 3(x + 5) ⇒ 4x + 4 = 3x + 15 ⇒ x = 11.', 'По основному свойству пропорции: 4(x + 1) = 3(x + 5) ⇒ 4x + 4 = 3x + 15 ⇒ x = 11.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-equations-q7', 'math-equations', 7, 'intermediate', 1.5, 'In the system of equations x + y = 10 and x − y = 4, what is the value of x?', 'x + y = 10 va x − y = 4 tenglamalar sistemasidan x ning qiymatini toping.', 'В системе уравнений x + y = 10 и x − y = 4 найдите значение x.', 'Adding the two equations eliminates y: (x + y) + (x − y) = 10 + 4 ⇒ 2x = 14 ⇒ x = 7.', 'Ikkala tenglamani hadlab qo''shsak y yo''qoladi: 2x = 14, bundan x = 7.', 'Сложив оба уравнения почленно, исключаем y: 2x = 14, откуда x = 7.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-equations-q8', 'math-equations', 8, 'intermediate', 1.5, 'How many real solutions does the equation |2x − 1| = 5 have?', '|2x − 1| = 5 modulli tenglama nechta haqiqiy ildizga ega?', 'Сколько действительных корней имеет уравнение с модулем |2x − 1| = 5?', 'Either 2x − 1 = 5 (giving x = 3) or 2x − 1 = −5 (giving x = −2), so there are 2 solutions.', '2x − 1 = 5 (bundan x = 3) yoki 2x − 1 = −5 (bundan x = −2) bo''ladi, demak tenglama 2 ta ildizga ega.', 'Либо 2x − 1 = 5 (откуда x = 3), либо 2x − 1 = −5 (откуда x = −2), то есть уравнение имеет 2 корня.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-equations-q9', 'math-equations', 9, 'advanced', 2.2, 'For a quadratic equation ax² + bx + c = 0, what condition on the discriminant D = b² − 4ac guarantees two distinct real roots?', 'ax² + bx + c = 0 kvadrat tenglama ikkita turli haqiqiy ildizga ega bo''lishi uchun D = b² − 4ac diskriminant qanday shartni qanoatlantirishi kerak?', 'Какое условие для дискриминанта D = b² − 4ac квадратного уравнения ax² + bx + c = 0 гарантирует наличие двух различных действительных корней?', 'When the discriminant D = b² − 4ac is strictly positive (D > 0), the quadratic formula yields two distinct real roots.', 'Diskriminant D = b² − 4ac qat''iy musbat (D > 0) bo''lganda, kvadrat tenglama ikkita turli haqiqiy ildizga ega bo''ladi.', 'Когда дискриминант D = b² − 4ac строго положителен (D > 0), квадратное уравнение имеет два различных действительных корня.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-equations-q10', 'math-equations', 10, 'advanced', 2.2, 'By Vieta''s formulas, what is the sum of the roots (x₁ + x₂) of the equation 2x² − 14x + 9 = 0?', 'Viyet teoremasiga ko''ra, 2x² − 14x + 9 = 0 kvadrat tenglama ildizlarining yig''indisi (x₁ + x₂) nechaga teng?', 'Чему по теореме Виета равна сумма корней (x₁ + x₂) уравнения 2x² − 14x + 9 = 0?', 'By Vieta''s theorem, the sum of the roots of ax² + bx + c = 0 is −b / a = −(−14) / 2 = 7.', 'Viyet teoremasiga ko''ra, ax² + bx + c = 0 tenglama ildizlari yig''indisi −b / a = −(−14) / 2 = 7 ga teng.', 'По теореме Виета сумма корней уравнения ax² + bx + c = 0 равна −b / a = −(−14) / 2 = 7.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-geometry-q1', 'math-geometry', 1, 'basic', 1, 'What is the perimeter of a rectangle with length 12 cm and width 7 cm?', 'Bo''yi 12 sm va eni 7 sm bo''lgan to''g''ri to''rtburchakning perimetrini toping.', 'Чему равен периметр прямоугольника с длиной 12 см и шириной 7 см?', 'Perimeter of a rectangle is P = 2 × (length + width) = 2 × (12 + 7) = 38 cm.', 'To''g''ri to''rtburchakning perimetri P = 2 × (bo''yi + eni) = 2 × (12 + 7) = 38 sm.', 'Периметр прямоугольника равен P = 2 × (длина + ширина) = 2 × (12 + 7) = 38 см.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-geometry-q2', 'math-geometry', 2, 'basic', 1, 'What is the sum of the interior angles of any triangle?', 'Ixtiyoriy uchburchakning ichki burchaklari yig''indisi necha gradusga teng?', 'Чему равна сумма внутренних углов любого треугольника?', 'In Euclidean geometry, the three interior angles of any triangle always add up to 180°.', 'Yevklid geometriyasida har qanday uchburchakning uchta ichki burchagi yig''indisi doimo 180° ga teng.', 'В евклидовой геометрии сумма трех внутренних углов любого треугольника всегда равна 180°.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-geometry-q3', 'math-geometry', 3, 'basic', 1, 'What is the area of a square whose side length is 9 m?', 'Tomoni 9 m bo''lgan kvadratning yuzi nechaga teng?', 'Чему равна площадь квадрата со стороной 9 м?', 'The area of a square is side² = 9 × 9 = 81 m².', 'Kvadratning yuzi S = a² formula bo''yicha hisoblanadi: 9 × 9 = 81 m².', 'Площадь квадрата равна квадрату его стороны: 9 × 9 = 81 м².') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-geometry-q4', 'math-geometry', 4, 'basic', 1, 'What is the area of a triangle with base 10 cm and height 6 cm?', 'Asosi 10 sm va balandligi 6 sm bo''lgan uchburchakning yuzini toping.', 'Чему равна площадь треугольника с основанием 10 см и высотой 6 см?', 'The area of a triangle is (1/2) × base × height = (1/2) × 10 × 6 = 30 cm².', 'Uchburchakning yuzi S = (1/2) × asos × balandlik = (1/2) × 10 × 6 = 30 sm².', 'Площадь треугольника равна (1/2) × основание × высота = (1/2) × 10 × 6 = 30 см².') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-geometry-q5', 'math-geometry', 5, 'intermediate', 1.5, 'In a right triangle, the two legs have lengths 6 cm and 8 cm. What is the length of the hypotenuse?', 'To''g''ri burchakli uchburchakning katetlari 6 sm va 8 sm ga teng. Uning gipotenuzasi uzunligini toping.', 'Катеты прямоугольного треугольника равны 6 см и 8 см. Чему равна длина гипотенузы?', 'By the Pythagorean theorem, c = √(6² + 8²) = √(36 + 64) = √100 = 10 cm.', 'Pifagor teoremasiga ko''ra, c = √(6² + 8²) = √(36 + 64) = √100 = 10 sm.', 'По теореме Пифагора c = √(6² + 8²) = √(36 + 64) = √100 = 10 см.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-geometry-q6', 'math-geometry', 6, 'intermediate', 1.5, 'What is the area of a circle with radius r = 5 cm?', 'Radiusi r = 5 sm bo''lgan doiraning yuzi nechaga teng?', 'Чему равна площадь круга с радиусом r = 5 см?', 'The area of a circle is A = πr² = π × 5² = 25π cm².', 'Doiraning yuzi A = πr² formula bilan topiladi: π × 5² = 25π sm².', 'Площадь круга вычисляется по формуле A = πr² = π × 5² = 25π см².') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-geometry-q7', 'math-geometry', 7, 'intermediate', 1.5, 'What is the volume of a rectangular prism (box) measuring 4 cm by 5 cm by 6 cm?', 'O''lchamlari 4 sm, 5 sm va 6 sm bo''lgan to''g''ri burchakli parallelepipedning hajmini toping.', 'Чему равен объем прямоугольного параллелепипеда с измерениями 4 см, 5 см и 6 см?', 'Volume = length × width × height = 4 × 5 × 6 = 120 cm³.', 'Hajm = bo''yi × eni × balandligi = 4 × 5 × 6 = 120 sm³.', 'Объем равен произведению длины, ширины и высоты: 4 × 5 × 6 = 120 см³.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-geometry-q8', 'math-geometry', 8, 'intermediate', 1.5, 'What is the sum of the interior angles of a convex pentagon (5-sided polygon)?', 'Qavariq beshburchakning ichki burchaklari yig''indisi necha gradusga teng?', 'Чему равна сумма внутренних углов выпуклого пятиугольника?', 'Using the polygon interior angle sum formula (n − 2) × 180° for n = 5 gives 3 × 180° = 540°.', 'Ko''pburchak ichki burchaklari yig''indisi (n − 2) × 180° formulasiga n = 5 ni qo''ysak: 3 × 180° = 540°.', 'По формуле суммы внутренних углов n-угольника (n − 2) × 180° при n = 5 получаем 3 × 180° = 540°.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-geometry-q9', 'math-geometry', 9, 'advanced', 2.2, 'A trapezoid has parallel bases of lengths 8 cm and 14 cm, and a height of 5 cm. What is its area?', 'Trapetsiyaning asoslari 8 sm va 14 sm ga, balandligi esa 5 sm ga teng. Uning yuzini toping.', 'Основания трапеции равны 8 см и 14 см, а её высота равна 5 см. Чему равна площадь трапеции?', 'The area of a trapezoid is ((a + b) / 2) × h = ((8 + 14) / 2) × 5 = 11 × 5 = 55 cm².', 'Trapetsiya yuzi S = ((a + b) / 2) × h = ((8 + 14) / 2) × 5 = 11 × 5 = 55 sm².', 'Площадь трапеции равна полусумме оснований, умноженной на высоту: ((8 + 14) / 2) × 5 = 11 × 5 = 55 см².') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-geometry-q10', 'math-geometry', 10, 'advanced', 2.2, 'What is the distance between the points A(1, 2) and B(4, 6) in the Cartesian coordinate plane?', 'Dekart koordinatalar tekisligida A(1, 2) va B(4, 6) nuqtalar orasidagi masofani toping.', 'Чему равно расстояние между точками A(1, 2) и B(4, 6) на координатной плоскости?', 'By the distance formula, d = √((4 − 1)² + (6 − 2)²) = √(3² + 4²) = √(9 + 16) = √25 = 5.', 'Ikki nuqta orasidagi masofa formulasiga ko''ra: d = √((4 − 1)² + (6 − 2)²) = √(3² + 4²) = √25 = 5.', 'По формуле расстояния между двумя точками d = √((4 − 1)² + (6 − 2)²) = √(3² + 4²) = √25 = 5.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-advanced-q1', 'math-advanced', 1, 'basic', 1, 'What is the value of the logarithm log₂(32)?', 'log₂(32) logarifmning qiymati nechaga teng?', 'Чему равно значение логарифма log₂(32)?', 'Since 2⁵ = 32, the base-2 logarithm of 32 is 5.', '2⁵ = 32 bo''lgani uchun, 2 asosga ko''ra 32 ning logarifmi 5 ga teng.', 'Так как 2⁵ = 32, логарифм числа 32 по основанию 2 равен 5.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-advanced-q2', 'math-advanced', 2, 'basic', 1, 'What is the value of 5! (5 factorial)?', '5! (5 faktorial) ning qiymati nechaga teng?', 'Чему равно значение 5! (5 факториал)?', '5! = 5 × 4 × 3 × 2 × 1 = 120.', '5! = 5 × 4 × 3 × 2 × 1 = 120.', '5! = 5 × 4 × 3 × 2 × 1 = 120.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-advanced-q3', 'math-advanced', 3, 'basic', 1, 'According to the fundamental Pythagorean trigonometric identity, what does sin²(θ) + cos²(θ) equal for any angle θ?', 'Asosiy trigonometrik ayniyatga ko''ra, ixtiyoriy θ burchak uchun sin²(θ) + cos²(θ) nechaga teng?', 'Чему согласно основному тригонометрическому тождеству равно выражение sin²(θ) + cos²(θ) для любого угла θ?', 'By the Pythagorean identity on the unit circle, sin²(θ) + cos²(θ) = 1 for all real angles θ.', 'Birlik aylanadagi asosiy trigonometrik ayniyatga ko''ra, barcha θ burchaklar uchun sin²(θ) + cos²(θ) = 1.', 'По основному тригонометрическому тождеству на единичной окружности sin²(θ) + cos²(θ) = 1 для любого угла θ.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-advanced-q4', 'math-advanced', 4, 'intermediate', 1.5, 'In an arithmetic progression where the first term is a₁ = 4 and the common difference is d = 3, what is the 10th term (a₁₀)?', 'Birinchi hadi a₁ = 4 va ayirmasi d = 3 bo''lgan arifmetik progressiyaning 10-hadini (a₁₀) toping.', 'В арифметической прогрессии первый член a₁ = 4, а разность d = 3. Чему равен 10-й член прогрессии (a₁₀)?', 'Using aₙ = a₁ + (n − 1)d: a₁₀ = 4 + (10 − 1) × 3 = 4 + 27 = 31.', 'aₙ = a₁ + (n − 1)d formulasiga ko''ra: a₁₀ = 4 + (10 − 1) × 3 = 4 + 27 = 31.', 'По формуле n-го члена aₙ = a₁ + (n − 1)d получаем: a₁₀ = 4 + (10 − 1) × 3 = 4 + 27 = 31.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-advanced-q5', 'math-advanced', 5, 'intermediate', 1.5, 'What is the derivative f''(x) of the function f(x) = 3x² − 4x + 7?', 'f(x) = 3x² − 4x + 7 funksiyaning hosilasi f''(x) ni toping.', 'Чему равна производная f''(x) функции f(x) = 3x² − 4x + 7?', 'Applying the power rule term by term: d/dx(3x²) = 6x, d/dx(−4x) = −4, and d/dx(7) = 0, giving 6x − 4.', 'Daraja hosilasi qoidasini hadma-had qo''llasak: (3x²)'' = 6x, (−4x)'' = −4 va (7)'' = 0, natijada 6x − 4 hosil bo''ladi.', 'Применяя правило дифференцирования степенной функции почленно, получаем: (3x²)'' = 6x, (−4x)'' = −4 и (7)'' = 0, то есть 6x − 4.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-advanced-q6', 'math-advanced', 6, 'intermediate', 1.5, 'How many ways can you choose a committee of 2 people from a group of 6 people (combinations C(6, 2))?', '6 kishilik guruhdan 2 kishilik hay''atni necha xil usulda tanlab olish mumkin (C(6, 2) gruppalash)?', 'Сколькими способами можно выбрать комитет из 2 человек в группе из 6 человек (число сочетаний C(6, 2))?', 'Using the combinations formula C(n, k) = n! / (k!(n − k)!): C(6, 2) = (6 × 5) / 2 = 15.', 'Gruppalash formulasiga ko''ra C(n, k) = n! / (k!(n − k)!): C(6, 2) = (6 × 5) / 2 = 15.', 'По формуле числа сочетаний C(n, k) = n! / (k!(n − k)!) получаем: C(6, 2) = (6 × 5) / 2 = 15.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-advanced-q7', 'math-advanced', 7, 'intermediate', 1.5, 'What is the sum of the infinite geometric series 1 + 1/2 + 1/4 + 1/8 + ...?', '1 + 1/2 + 1/4 + 1/8 + ... cheksiz kamayuvchi geometrik progressiyaning yig''indisi nechaga teng?', 'Чему равна сумма бесконечной геометрической прогрессии 1 + 1/2 + 1/4 + 1/8 + ...?', 'For an infinite geometric series with |r| < 1, Sum = a / (1 − r) = 1 / (1 − 1/2) = 2.', '|q| < 1 bo''lgan cheksiz kamayuvchi geometrik progressiya yig''indisi S = b₁ / (1 − q) = 1 / (1 − 1/2) = 2.', 'Сумма бесконечно убывающей геометрической прогрессии со знаменателем |q| < 1 равна S = b₁ / (1 − q) = 1 / (1 − 1/2) = 2.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-advanced-q8', 'math-advanced', 8, 'advanced', 2.2, 'Evaluate the definite integral ∫₀² (3x²) dx.', '∫₀² (3x²) dx aniq integralning qiymatini hisoblang.', 'Вычислите определенный интеграл ∫₀² (3x²) dx.', 'The antiderivative of 3x² is x³; evaluating [x³] from 0 to 2 gives 2³ − 0³ = 8.', '3x² ning boshlang''ich funksiyasi x³ ga teng; Nyuton-Leybnits formulasiga ko''ra 2³ − 0³ = 8.', 'Первообразная функции 3x² равна x³; по формуле Ньютона-Лейбница 2³ − 0³ = 8.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-advanced-q9', 'math-advanced', 9, 'advanced', 2.2, 'What is the limit: lim(x → 0) [sin(x) / x] (where x is in radians)?', 'lim(x → 0) [sin(x) / x] limitning qiymati nechaga teng (x radianda)?', 'Чему равен первый замечательный предел: lim(x → 0) [sin(x) / x] (где x в радианах)?', 'The fundamental trigonometric limit states that as x approaches 0 in radians, sin(x) / x approaches 1.', 'Birinchi ajoyib limitga ko''ra, x radianda 0 ga intilganda sin(x) / x nisbat 1 ga intiladi.', 'Согласно первому замечательному пределу, при стремлении x (в радианах) к 0 отношение sin(x) / x стремится к 1.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id, topic_id, question_number, difficulty, difficulty_weight, question_text_en, question_text_uz, question_text_ru, explanation_en, explanation_uz, explanation_ru) VALUES ('math-advanced-q10', 'math-advanced', 10, 'advanced', 2.2, 'What is the determinant of the 2×2 matrix [[4, 3], [2, 5]]?', '[[4, 3], [2, 5]] ko''rinishidagi 2×2 matritsaning determinantini toping.', 'Чему равен определитель (детерминант) матрицы 2×2 вида [[4, 3], [2, 5]]?', 'For a 2×2 matrix [[a, b], [c, d]], the determinant is ad − bc = (4 × 5) − (3 × 2) = 20 − 6 = 14.', '[[a, b], [c, d]] matritsaning determinanti ad − bc formula bilan hisoblanadi: (4 × 5) − (3 × 2) = 20 − 6 = 14.', 'Определитель матрицы 2×2 [[a, b], [c, d]] равен ad − bc = (4 × 5) − (3 × 2) = 20 − 6 = 14.') ON CONFLICT (id) DO NOTHING;
