INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-forms-q9-opt0', 'html-forms-q9', 0, 'Disabled fields are NOT sent with form data, while readonly fields ARE sent', 'Disabled maydonlar forma ma''lumotlari bilan YUBORILMAYDI, readonly maydonlar esa YUBORILADI', 'Поля с disabled НЕ отправляются с данными формы, а поля с readonly отправляются', true) ON CONFLICT (id) DO NOTHING;
