INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-attributes-q1-opt0', 'html-attributes-q1', 0, 'Its value must be unique within the entire document', 'Uning qiymati butun hujjat bo''yicha noyob (yagona) bo''lishi shart', 'Его значение должно быть уникальным в пределах всего документа', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-attributes-q1-opt1', 'html-attributes-q1', 1, 'It can only be used on <div> elements', 'U faqat <div> elementlarida ishlatilishi mumkin', 'Его можно использовать только на элементах <div>', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-attributes-q1-opt2', 'html-attributes-q1', 2, 'An element can have multiple space-separated IDs', 'Bitta elementda probel bilan ajratilgan bir nechta ID bo''lishi mumkin', 'Элемент может иметь несколько ID, разделённых пробелом', false) ON CONFLICT (id) DO NOTHING;
