INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-attributes-q9-opt0', 'html-attributes-q9', 0, 'It adds the element to the natural keyboard Tab focus order', 'Elementni klaviaturaning Tab tugmasi orqali tabiiy ketma-ketlikda fokus oladigan qiladi', 'Добавляет элемент в естественный порядок фокусировки клавишей Tab', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-attributes-q9-opt1', 'html-attributes-q9', 1, 'It removes the element from keyboard focus completely', 'Elementni klaviatura fokusidan butunlay chiqarib tashlaydi', 'Полностью исключает элемент из фокусировки с клавиатуры', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-attributes-q9-opt2', 'html-attributes-q9', 2, 'It makes the element the very first item focused on the page', 'Elementni sahifada eng birinchi bo''lib fokus oladigan qiladi', 'Делает элемент самым первым в очереди фокусировки на странице', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-attributes-q9-opt3', 'html-attributes-q9', 3, 'It disables mouse clicks on the element', 'Elementga sichqoncha bilan bosishni o''chirib qo''yadi', 'Отключает клики мышью по этому элементу', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-attributes-q10-opt0', 'html-attributes-q10', 0, 'It places the element last in the Tab key order', 'Elementni Tab tugmasi navbatida eng oxiriga qo''yadi', 'Помещает элемент в самый конец очереди клавиши Tab', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-attributes-q10-opt1', 'html-attributes-q10', 1, 'It removes the element from the Tab key order, but allows it to be focused programmatically via JavaScript (.focus())', 'Elementni Tab navbatidan chiqaradi, lekin JavaScript (.focus()) orqali dasturiy fokus berish imkonini qoldiradi', 'Исключает элемент из перехода по Tab, но позволяет установить на него фокус программно через JS (.focus())', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-attributes-q10-opt2', 'html-attributes-q10', 2, 'It throws a DOM syntax error', 'DOM sintaksis xatoligini keltirib chiqaradi', 'Вызывает синтаксическую ошибку DOM', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-attributes-q10-opt3', 'html-attributes-q10', 3, 'It hides the element from screen readers', 'Elementni ekran o''quvchi dasturlardan yashiradi', 'Скрывает элемент от программ чтения с экрана', false) ON CONFLICT (id) DO NOTHING;
