INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-advanced-q4-opt0', 'html-advanced-q4', 0, '<svg> requires WebGL, while <canvas> only uses CSS', '<svg> WebGL talab qiladi, <canvas> esa faqat CSS ishlatadi', '<svg> требует WebGL, а <canvas> работает только через CSS', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-advanced-q4-opt1', 'html-advanced-q4', 1, '<canvas> is vector-based, while <svg> is pixel-based', '<canvas> vektorli, <svg> esa pikselli', '<canvas> векторный, а <svg> растровый', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-advanced-q4-opt2', 'html-advanced-q4', 2, 'There is no difference; they are aliases', 'Farqi yo''q, ular bir xil', 'Между ними нет разницы', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-advanced-q4-opt3', 'html-advanced-q4', 3, '<svg> is resolution-independent vector XML in the DOM, while <canvas> is a pixel-based bitmap drawn via JS', '<svg> DOM-dagi sifatini yo''qotmaydigan vektorli XML bo''lsa, <canvas> JS orqali chiziladigan pikselli (raster) maydondir', '<svg> — это векторная XML-графика в DOM без потери качества, а <canvas> — растровый холст, рисуемый через JS', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-advanced-q5-opt0', 'html-advanced-q5', 0, 'defer executes in order after HTML parsing completes; async executes as soon as downloaded, potentially out of order', 'defer HTML tahlili tugagach tartib bilan ishga tushadi; async esa yuklanishi bilanoq (tartibsiz) ishga tushadi', 'defer выполняет скрипты по порядку после разбора HTML; async выполняет скрипт сразу после загрузки без гарантии порядка', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-advanced-q5-opt1', 'html-advanced-q5', 1, 'async waits for the footer; defer blocks HTML parsing immediately', 'async sahifa oxirini kutadi; defer esa HTML o''qilishini darhol to''xtatadi', 'async ждёт конца страницы; defer сразу блокирует парсинг HTML', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-advanced-q5-opt2', 'html-advanced-q5', 2, 'defer only works for inline scripts; async only works for CSS', 'defer faqat ichki skriptlarda ishlaydi; async esa faqat CSS uchun', 'defer работает только со встроенными скриптами; async — только с CSS', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-advanced-q5-opt3', 'html-advanced-q5', 3, 'Both block HTML parsing identically', 'Ikkalasi ham HTML o''qilishini birdek to''xtatib qo''yadi', 'Оба атрибута одинаково блокируют парсинг HTML', false) ON CONFLICT (id) DO NOTHING;
