INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-advanced-q9-opt0', 'html-advanced-q9', 0, 'It provides an accessible string label for an element when no visible text label is present', 'Elementda ko''rinadigan matn bo''lmaganda (masalan, faqat ikonka bo''lsa), ekran o''quvchilar uchun tushunarli nom beradi', 'Задаёт текстовую метку для скринридеров, когда у элемента нет видимого текстового описания (например, кнопка-иконка)', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-advanced-q9-opt1', 'html-advanced-q9', 1, 'It automatically translates the element text into other languages', 'Element matnini avtomatik ravishda boshqa tillarga tarjima qiladi', 'Автоматически переводит текст элемента на другие языки', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-advanced-q9-opt2', 'html-advanced-q9', 2, 'It styles the element with a high-contrast border', 'Elementga yuqori kontrastli ramka qo''shadi', 'Добавляет элементу высококонтрастную рамку', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('html-advanced-q9-opt3', 'html-advanced-q9', 3, 'It creates a visible floating caption below the element', 'Element ostida ko''rinadigan suzuvchi yozuv hosil qiladi', 'Создаёт видимую подпись под элементом', false) ON CONFLICT (id) DO NOTHING;
