INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-flexbox-q10-opt1', 'css-flexbox-q10', 1, 'space-between puts first/last items flush against the edges; space-evenly puts equal space between items AND at both outer edges', 'space-between birinchi va oxirgi elementni chekkalarga taqaydi; space-evenly esa elementlar orasiga HAM, ikkala chekkaga HAM bir xil bo''sh joy qo''yadi', 'space-between прижимает крайние элементы к границам контейнера; space-evenly делает абсолютно равные отступы и между элементами, и по краям', true) ON CONFLICT (id) DO NOTHING;
