INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-grid-q5-opt0', 'css-grid-q5', 0, 'It makes the item start at column line 1 and end at column line 3 (spanning 2 columns)', 'Elementni 1-vertikal chiziqdan 3-vertikal chiziqqacha cho''zadi (2 ta ustunni egallaydi)', 'Размещает элемент от 1-й до 3-й вертикальной линии сетки (занимает 2 столбца)', true) ON CONFLICT (id) DO NOTHING;
