INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-grid-q6-opt1', 'css-grid-q6', 1, 'Defines a size range greater than or equal to 200px and up to 1fr of available space', 'Ustun/qator o''lchamini kamida 200px va bo''sh joyga qarab ko''pi bilan 1fr gacha bo''lishini belgilaydi', 'Задаёт диапазон размера: не меньше 200px и не больше 1fr доступного пространства', true) ON CONFLICT (id) DO NOTHING;
