INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-grid-q9-opt0', 'css-grid-q9', 0, 'auto-fit collapses empty tracks so existing items expand to fill the row; auto-fill keeps empty tracks occupying space', 'auto-fit bo''sh ustunlarni qisqartirib, mavjud elementlarni qator to''lguncha kengaytiradi; auto-fill esa bo''sh ustunlar o''rnini saqlab qoladi', 'auto-fit схлопывает пустые дорожки, растягивая существующие элементы на всю строку; auto-fill сохраняет пустые колонки', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-grid-q9-opt1', 'css-grid-q9', 1, 'auto-fill deletes extra items from the DOM; auto-fit hides them', 'auto-fill ortiqcha elementlarni DOM-dan o''chiradi; auto-fit yashiradi', 'auto-fill удаляет лишние элементы из DOM, а auto-fit скрывает их', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-grid-q9-opt2', 'css-grid-q9', 2, 'auto-fit only works on rows; auto-fill only works on columns', 'auto-fit faqat qatorlarda, auto-fill esa faqat ustunlarda ishlaydi', 'auto-fit работает только для строк, а auto-fill — только для столбцов', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-grid-q9-opt3', 'css-grid-q9', 3, 'They behave identically in all situations', 'Ular barcha holatlarda mutlaqo bir xil ishlaydi', 'Они работают абсолютно одинаково во всех случаях', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-grid-q10-opt0', 'css-grid-q10', 0, 'It disables CSS Grid on the child element', 'Farzand elementda CSS Grid-ni o''chirib qo''yadi', 'Отключает CSS Grid у дочернего элемента', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-grid-q10-opt1', 'css-grid-q10', 1, 'It makes the nested grid inherit and align directly with its parent grid''s column tracks', 'Ichki gridning ustunlarini bevosita ota gridning ustun chiziqlariga moslab tekislaydi (meros qilib oladi)', 'Позволяет вложенному гриду унаследовать линии столбцов родительской сетки для идеального выравнивания', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-grid-q10-opt2', 'css-grid-q10', 2, 'It automatically converts the grid into a table', 'Gridni avtomatik ravishda HTML jadvalga aylantiradi', 'Автоматически превращает грид в таблицу', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-grid-q10-opt3', 'css-grid-q10', 3, 'It halves the gap size on every nesting level', 'Har bir ichki darajada gap masofasini ikki barobar kamaytiradi', 'Уменьшает размер отступов gap вдвое на каждом уровне вложенности', false) ON CONFLICT (id) DO NOTHING;
