INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q4-opt1', 'css-positioning-q4', 1, 'depth', 'depth', 'depth', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q4-opt2', 'css-positioning-q4', 2, 'stack-order', 'stack-order', 'stack-order', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q4-opt3', 'css-positioning-q4', 3, 'z-index', 'z-index', 'z-index', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q5-opt0', 'css-positioning-q5', 0, 'Its nearest positioned ancestor (an ancestor with position other than static), or the initial containing block if none exists', 'O''zining eng yaqin pozitsiyalangan ajdodiga (position qiymati static bo''lmagan ota elementga), agar u bo''lmasa dastlabki hujjat blokiga', 'Относительно ближайшего позиционированного предка (у которого position не равен static), либо относительно документа (<html>)', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q5-opt1', 'css-positioning-q5', 1, 'Always the direct parent element regardless of its position property', 'Position xossasi qanday bo''lishidan qat''i nazar, har doim bevosita ota elementiga', 'Всегда относительно прямого родителя независимо от его свойств', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q5-opt2', 'css-positioning-q5', 2, 'Always the browser viewport', 'Har doim brauzerning ko''rish oynasiga (viewport)', 'Всегда относительно окна браузера (viewport)', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q5-opt3', 'css-positioning-q5', 3, 'The previous sibling element', 'O''zidan oldingi qo''shni elementga', 'Относительно предыдущего соседнего элемента', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q6-opt0', 'css-positioning-q6', 0, 'It acts like fixed forever across the entire website', 'Butun sayt bo''ylab har doim fixed kabi ishlaydi', 'Ведёт себя как fixed всегда и везде на странице', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q6-opt1', 'css-positioning-q6', 1, 'It acts like relative until scrolled to a specified threshold (e.g., top: 0), then sticks like fixed within its parent container', 'Belgilangan chegaraga (masalan, top: 0) yetguncha relative kabi turadi, so''ngra o''z ota konteyneri ichida fixed kabi yopishib qoladi', 'Ведёт себя как relative до достижения заданного порога прокрутки (например, top: 0), после чего фиксируется в пределах родительского блока', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q6-opt2', 'css-positioning-q6', 2, 'It glues two sibling elements together horizontally', 'Ikkita qo''shni elementni gorizontal ravishda bir-biriga yopishtiradi', 'Склеивает два соседних элемента по горизонтали', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q6-opt3', 'css-positioning-q6', 3, 'It prevents the user from scrolling the page', 'Foydalanuvchiga sahifani aylantirishni (scroll) taqiqlaydi', 'Запрещает пользователю прокручивать страницу', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q7-opt0', 'css-positioning-q7', 0, 'offset', 'offset', 'offset', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q7-opt1', 'css-positioning-q7', 1, 'bounds', 'bounds', 'bounds', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q7-opt2', 'css-positioning-q7', 2, 'inset', 'inset', 'inset', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q7-opt3', 'css-positioning-q7', 3, 'edges', 'edges', 'edges', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q8-opt0', 'css-positioning-q8', 0, 'Because z-index maximum value is 100', 'Chunki z-index ning eng katta qiymati 100 ga teng', 'Потому что максимальное значение z-index равно 100', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q8-opt1', 'css-positioning-q8', 1, 'Because z-index only works on <img> elements', 'Chunki z-index faqat <img> elementlarida ishlaydi', 'Потому что z-index работает только для картинок <img>', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q8-opt2', 'css-positioning-q8', 2, 'Because z-index requires an !important flag', 'Chunki z-index har doim !important bilan yozilishi shart', 'Потому что z-index требует обязательного флага !important', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q8-opt3', 'css-positioning-q8', 3, 'Because the element still has position: static (and is not a flex or grid item)', 'Chunki element hali ham position: static holatida (va flex yoki grid elementi emas)', 'Потому что у элемента остаётся position: static (и он не является дочерним элементом flex или grid)', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q9-opt0', 'css-positioning-q9', 0, 'Add transform: translate(-50%, -50%);', 'transform: translate(-50%, -50%); qo''shish orqali', 'Добавить transform: translate(-50%, -50%);', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q9-opt1', 'css-positioning-q9', 1, 'Add margin: 50%;', 'margin: 50%; qo''shish orqali', 'Добавить margin: 50%;', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q9-opt2', 'css-positioning-q9', 2, 'Add text-align: center;', 'text-align: center; qo''shish orqali', 'Добавить text-align: center;', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q9-opt3', 'css-positioning-q9', 3, 'Add float: center;', 'float: center; qo''shish orqali', 'Добавить float: center;', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q10-opt0', 'css-positioning-q10', 0, 'Because overflow disables all CSS positioning properties', 'Chunki overflow barcha CSS position xossalarini o''chirib qo''yadi', 'Потому что overflow отключает любые свойства позиционирования', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q10-opt1', 'css-positioning-q10', 1, 'Because setting overflow creates a new scroll container, so sticky tracks that ancestor''s scroll instead of the window viewport', 'Chunki overflow yangi scroll konteyner yaratadi va sticky brauzer oynasini emas, o''sha ota elementning ichki scrollini kuzata boshlaydi', 'Потому что не-visible значение overflow создаёт новый контейнер прокрутки, к которому и привязывается sticky вместо окна браузера', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q10-opt2', 'css-positioning-q10', 2, 'Because sticky requires overflow: scroll on the body tag', 'Chunki sticky body tegida overflow: scroll bo''lishini talab qiladi', 'Потому что для sticky требуется overflow: scroll на теге body', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-positioning-q10-opt3', 'css-positioning-q10', 3, 'Because overflow resets top to auto', 'Chunki overflow top qiymatini auto ga qaytarib yuboradi', 'Потому что overflow сбрасывает значение top в auto', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q1-opt0', 'css-animations-q1', 0, 'transition', 'transition', 'transition', true) ON CONFLICT (id) DO NOTHING;
