INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q2-opt2', 'css-animations-q2', 2, '@steps', '@steps', '@steps', false) ON CONFLICT (id) DO NOTHING;
