INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q3-opt2', 'css-animations-q3', 2, 'transform', 'transform', 'transform', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q3-opt3', 'css-animations-q3', 3, 'matrix-move', 'matrix-move', 'matrix-move', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q4-opt0', 'css-animations-q4', 0, 'animation-loop: forever;', 'animation-loop: forever;', 'animation-loop: forever;', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q4-opt1', 'css-animations-q4', 1, 'animation-repeat: always;', 'animation-repeat: always;', 'animation-repeat: always;', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q4-opt2', 'css-animations-q4', 2, 'animation-duration: infinite;', 'animation-duration: infinite;', 'animation-duration: infinite;', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q4-opt3', 'css-animations-q4', 3, 'animation-iteration-count: infinite;', 'animation-iteration-count: infinite;', 'animation-iteration-count: infinite;', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q5-opt0', 'css-animations-q5', 0, 'The element retains the style values from the final keyframe (100%) instead of snapping back to its initial state', 'Element dastlabki holatiga qaytib ketmasdan, oxirgi kadrdagi (100%) uslublarni o''zida saqlab qoladi', 'Элемент сохраняет стили последнего ключевого кадра (100%), а не возвращается рывком в исходное состояние', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q5-opt1', 'css-animations-q5', 1, 'The animation plays a second time in fast-forward', 'Animatsiyani ikkinchi marta tezlashtirib ijro etadi', 'Анимация проигрывается второй раз в ускоренном режиме', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q5-opt2', 'css-animations-q5', 2, 'The element moves forward along the Z-axis', 'Elementni Z o''qi bo''ylab oldinga chiqaradi', 'Элемент выдвигается вперёд по оси Z', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q5-opt3', 'css-animations-q5', 3, 'The animation starts before the delay finishes', 'Animatsiyani kechikish (delay) tugamasdan oldin boshlaydi', 'Анимация запускается до истечения задержки delay', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q6-opt0', 'css-animations-q6', 0, 'The total number of frames rendered by the monitor', 'Monitor chiqaradigan jami kadrlar sonini', 'Общее количество кадров, отрисовываемых монитором', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q6-opt1', 'css-animations-q6', 1, 'The acceleration and deceleration curve (speed progression) over the duration of the animation', 'Animatsiya davomida tezlanish va sekinlashish egri chizig''ini (tezlik dinamikasini)', 'Кривую ускорения и замедления (изменение скорости движения) на протяжении анимации', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q6-opt2', 'css-animations-q6', 2, 'The delay before the animation starts', 'Animatsiya boshlanishidan oldingi kutish vaqtini', 'Задержку перед стартом анимации', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q6-opt3', 'css-animations-q6', 3, 'The color palette used during the transition', 'O''tish davomida ishlatiladigan ranglar palitrasini', 'Цветовую палитру во время перехода', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q7-opt0', 'css-animations-q7', 0, 'rotate-center', 'rotate-center', 'rotate-center', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q7-opt1', 'css-animations-q7', 1, 'pivot-point', 'pivot-point', 'pivot-point', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q7-opt2', 'css-animations-q7', 2, 'transform-origin', 'transform-origin', 'transform-origin', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q7-opt3', 'css-animations-q7', 3, 'anchor-point', 'anchor-point', 'anchor-point', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q8-opt0', 'css-animations-q8', 0, 'It skips every second keyframe', 'Har ikkinchi kadrni tashlab ketadi', 'Пропускает каждый второй ключевой кадр', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q8-opt1', 'css-animations-q8', 1, 'It switches to a different @keyframes rule on each cycle', 'Har bir siklda boshqa @keyframes qoidasiga o''tadi', 'Переключается на другое правило @keyframes в каждом цикле', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q8-opt2', 'css-animations-q8', 2, 'It pauses the animation after every cycle', 'Har bir sikldan keyin animatsiyani to''xtatib qo''yadi', 'Ставит анимацию на паузу после каждого прохода', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q8-opt3', 'css-animations-q8', 3, 'It plays the animation forwards on odd cycles and backwards (in reverse) on even cycles', 'Toq sikllarda animatsiyani to''g''ri (0% -> 100%), juft sikllarda esa teskari (100% -> 0%) yo''nalishda o''ynatadi', 'Проигрывает анимацию вперёд на нечётных повторах и в обратную сторону (назад) на чётных', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q9-opt0', 'css-animations-q9', 0, 'transform and opacity', 'transform va opacity', 'transform и opacity', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q9-opt1', 'css-animations-q9', 1, 'width and height', 'width va height', 'width и height', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q9-opt2', 'css-animations-q9', 2, 'top and left', 'top va left', 'top и left', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q9-opt3', 'css-animations-q9', 3, 'margin and padding', 'margin va padding', 'margin и padding', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-animations-q10-opt0', 'css-animations-q10', 0, '@media (animation: disabled)', '@media (animation: disabled)', '@media (animation: disabled)', false) ON CONFLICT (id) DO NOTHING;
