INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q5-opt0', 'css-responsive-q5', 0, '"rem" is always relative to the root (<html>) font-size, while "em" is relative to the current element''s or parent''s font-size', '"rem" har doim ildiz (<html>) shrift o''lchamiga nisbatan olinadi, "em" esa joriy yoki ota elementning shrift o''lchamiga bog''liq bo''ladi', '"rem" всегда зависит от размера шрифта корневого элемента (<html>), а "em" — от размера шрифта текущего или родительского элемента', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q5-opt1', 'css-responsive-q5', 1, '"em" is relative to the screen width, while "rem" is relative to screen height', '"em" ekran kengligiga, "rem" esa ekran balandligiga nisbatan olinadi', '"em" зависит от ширины экрана, а "rem" — от высоты экрана', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q5-opt2', 'css-responsive-q5', 2, '"rem" only works for margins, while "em" only works for font-size', '"rem" faqat margin uchun, "em" esa faqat font-size uchun ishlaydi', '"rem" работает только для отступов, а "em" — только для шрифтов', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q5-opt3', 'css-responsive-q5', 3, 'They are identical aliases', 'Ular bir-birining aynan sinonimi', 'Между ними нет никакой разницы', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q6-opt0', 'css-responsive-q6', 0, 'Base styles target 4K monitors, and max-width queries shrink them down', 'Bazaviy uslublar 4K monitorlar uchun yozilib, max-width orqali kichraytiriladi', 'Базовые стили пишутся для 4K-мониторов, а затем сжимаются через max-width', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q6-opt1', 'css-responsive-q6', 1, 'Base styles target small mobile screens first, and @media (min-width: ...) queries progressively enhance the layout for larger screens', 'Bazaviy uslublar avval kichik mobil ekranlar uchun yoziladi va @media (min-width: ...) orqali kattaroq ekranlar uchun kengaytirib boriladi', 'Базовые стили пишутся для маленьких экранов, а для планшетов и десктопов макет расширяется через @media (min-width: ...)', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q6-opt2', 'css-responsive-q6', 2, 'Separate HTML files are required for every screen size', 'Har bir ekran o''lchami uchun alohida HTML fayl talab qilinadi', 'Для каждого размера экрана создаётся отдельный HTML-файл', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q6-opt3', 'css-responsive-q6', 3, 'Media queries are prohibited in Mobile-First design', 'Mobile-First dizaynida media so''rovlar taqiqlanadi', 'В подходе Mobile-First медиа-запросы не используются', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q7-opt0', 'css-responsive-q7', 0, 'It picks one of the three values randomly', 'Uchta qiymatdan birini tasodifiy tanlaydi', 'Случайным образом выбирает одно из трёх значений', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q7-opt1', 'css-responsive-q7', 1, 'It sets font-size to 1rem on desktop and 2rem on mobile', 'Kompyuterda shriftni 1rem, telefonda esa 2rem qiladi', 'Устанавливает шрифт 1rem на компьютерах и 2rem на телефонах', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q7-opt2', 'css-responsive-q7', 2, 'It scales the value fluidly with 2.5vw, but never lets it go below 1rem or above 2rem', 'Qiymatni 2.5vw asosida moslashuvchan o''zgartiradi, lekin uning 1rem dan kichrayib yoki 2rem dan kattalashib ketishiga yo''l qo''ymaydi', 'Плавно масштабирует значение по 2.5vw, но не позволяет ему стать меньше 1rem или больше 2rem', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q7-opt3', 'css-responsive-q7', 3, 'It adds 1rem, 2.5vw, and 2rem together', '1rem, 2.5vw va 2rem qiymatlarini bir-biriga qo''shadi', 'Складывает значения 1rem, 2.5vw и 2rem вместе', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q8-opt0', 'css-responsive-q8', 0, 'box-ratio', 'box-ratio', 'box-ratio', false) ON CONFLICT (id) DO NOTHING;
