INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q8-opt2', 'css-responsive-q8', 2, 'scale-ratio', 'scale-ratio', 'scale-ratio', false) ON CONFLICT (id) DO NOTHING;
