INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q9-opt0', 'css-responsive-q9', 0, '@container responds to the size of a specific parent container element rather than the entire browser viewport', '@container butun brauzer oynasiga (viewport) emas, balki muayyan ota konteyner elementining o''lchamiga qarab ishlaydi', '@container реагирует на размеры конкретного родительского контейнера, а не всего окна браузера (viewport)', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q9-opt1', 'css-responsive-q9', 1, '@container only works on the <body> tag', '@container faqat <body> tegida ishlaydi', '@container работает только на теге <body>', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q9-opt2', 'css-responsive-q9', 2, '@container is used exclusively for printing pages', '@container faqat sahifani printerdan chiqarish uchun ishlatiladi', '@container используется исключительно для стилей печати', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q9-opt3', 'css-responsive-q9', 3, '@media can style individual components based on their parent div width, while @container cannot', '@media ota div kengligiga qarab ishlay oladi, @container esa ishlay olmaydi', '@media может отслеживать ширину родительского div, а @container — нет', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q10-opt0', 'css-responsive-q10', 0, '100dvh doubles the resolution of retina images', '100dvh retina rasmlarning tiniqligini ikki barobar oshiradi', '100dvh удваивает разрешение изображений на Retina-экранах', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q10-opt1', 'css-responsive-q10', 1, '100dvh dynamically adjusts as the mobile browser''s address bar and toolbars expand or retract, preventing content from being cut off', 'Mobil brauzerning manzil satri (address bar) chiqib-kirganda 100dvh dinamik ravishda moslashadi va pastki kontent kesilib qolishining oldini oladi', '100dvh динамически подстраивается при появлении и скрытии адресной строки мобильного браузера, не обрезая контент снизу', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('css-responsive-q10-opt2', 'css-responsive-q10', 2, '100dvh locks the device into landscape orientation', '100dvh qurilmani gorizontal (landscape) holatda qulflaydi', '100dvh принудительно поворачивает экран в горизонтальный режим', false) ON CONFLICT (id) DO NOTHING;
