INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-props-q8-opt3', 'react-props-q8', 3, 'Passing props through multiple intermediate components that do not need them just to reach a deeply nested child', 'Chuqur joylashgan bola komponentga yetkazish uchungina kerak bo''lmagan bir nechta oraliq komponentlar orqali props uzatish', 'Передача пропсов через несколько промежуточных компонентов, которым они не нужны, только чтобы доставить их глубоко вложенному компоненту', true) ON CONFLICT (id) DO NOTHING;
