INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-props-q10-opt0', 'react-props-q10', 0, 'A technique for sharing logic between components using a prop whose value is a function that returns JSX', 'Qiymati JSX qaytaruvchi funksiya bo''lgan prop yordamida komponentlar o''rtasida mantiqni ulashish usuli', 'Техника совместного использования логики между компонентами с помощью пропа, значением которого является функция, возвращающая JSX', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-props-q10-opt1', 'react-props-q10', 1, 'A method for rendering props directly into the browser console', 'Props-larni to''g''ridan-to''g''ri brauzer konsoliga chiqarish metodi', 'Метод вывода пропсов напрямую в консоль браузера', true) ON CONFLICT (id) DO NOTHING;
