INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-state-q1-opt0', 'react-state-q1', 0, 'Component-specific memory that persists across renders and triggers a re-render when updated', 'Renderlar orasida saqlanib qoladigan va yangilanganda qayta renderlashni ishga tushiradigan komponentga xos xotira', 'Специфичная для компонента память, которая сохраняется между рендерами и вызывает повторный рендер при обновлении', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-state-q1-opt1', 'react-state-q1', 1, 'A read-only configuration file on the server', 'Serverdagi faqat o''qish uchun mo''ljallangan sozlamalar fayli', 'Конфигурационный файл только для чтения на сервере', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-state-q1-opt2', 'react-state-q1', 2, 'A permanent table in an external SQL database', 'Tashqi SQL ma''lumotlar bazasidagi doimiy jadval', 'Постоянная таблица во внешней базе данных SQL', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-state-q1-opt3', 'react-state-q1', 3, 'The URL address of the browser window', 'Brauzer oynasining URL manzili', 'URL-адрес окна браузера', false) ON CONFLICT (id) DO NOTHING;
