INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-state-q2-opt1', 'react-state-q2', 1, 'React does not know the state changed and will not trigger a re-render', 'React holat o''zgarganini bilmaydi va qayta renderlashni ishga tushirmaydi', 'React не узнает об изменении состояния и не запустит повторный рендеринг', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-state-q2-opt2', 'react-state-q2', 2, 'The browser refreshes the entire page', 'Brauzer butun sahifani yangilaydi', 'Браузер перезагрузит всю страницу', false) ON CONFLICT (id) DO NOTHING;
