INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-state-q3-opt0', 'react-state-q3', 0, 'By using .push() or mutating properties directly', '.push() metodidan foydalanib yoki xususiyatlarni to''g''ridan-to''g''ri o''zgartirib', 'Используя .push() или изменяя свойства напрямую', false) ON CONFLICT (id) DO NOTHING;
