INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-usestate-q7-opt1', 'react-usestate-q7', 1, 'useState converts objects into arrays', 'useState obyektlarni massivlarga aylantiradi', 'useState преобразует объекты в массивы', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-usestate-q7-opt2', 'react-usestate-q7', 2, 'useState replaces the entire state object instead of shallowly merging it', 'useState obyektni yuzaki birlashtirish o''rniga butun holat obyektini to''liq almashtiradi', 'useState полностью заменяет объект состояния вместо его поверхностного слияния', true) ON CONFLICT (id) DO NOTHING;
