INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-usestate-q8-opt0', 'react-usestate-q8', 0, 'Delaying state creation by 5 seconds using setTimeout', 'setTimeout yordamida holat yaratilishini 5 soniyaga kechiktirish', 'Задержка создания состояния на 5 секунд с помощью setTimeout', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-usestate-q8-opt1', 'react-usestate-q8', 1, 'Initializing state with undefined', 'Holatni undefined bilan boshlash', 'Инициализация состояния значением undefined', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-usestate-q8-opt2', 'react-usestate-q8', 2, 'Loading state from an external CSS file', 'Holatni tashqi CSS faylidan yuklash', 'Загрузка состояния из внешнего CSS-файла', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-usestate-q8-opt3', 'react-usestate-q8', 3, 'Passing a function `useState(() => expensiveComputation())` so it only runs on the initial render', 'Faqat dastlabki renderda ishlashi uchun `useState(() => expensiveComputation())` ko''rinishida funksiya uzatish', 'Передача функции `useState(() => expensiveComputation())`, чтобы тяжелое вычисление выполнялось только при первом рендере', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-usestate-q9-opt0', 'react-usestate-q9', 0, 'React bails out and skips re-rendering the component and its children', 'React jarayonni to''xtatadi hamda komponent va uning bolalarini qayta render qilishni o''tkazib yuboradi', 'React отменяет обновление и пропускает повторный рендеринг компонента и его потомков', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-usestate-q9-opt1', 'react-usestate-q9', 1, 'React throws an infinite loop error', 'React cheksiz sikl xatosini chiqaradi', 'React выбрасывает ошибку бесконечного цикла', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-usestate-q9-opt2', 'react-usestate-q9', 2, 'React resets the state to null', 'React holatni null qiymatiga tushiradi', 'React сбрасывает состояние в null', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-usestate-q9-opt3', 'react-usestate-q9', 3, 'React forces a full DOM reload', 'React to''liq DOM-ni qayta yuklashga majbur qiladi', 'React принудительно перезагружает весь DOM', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-usestate-q10-opt0', 'react-usestate-q10', 0, 'Because JavaScript functions cannot be passed as arguments', 'Chunki JavaScript funksiyalarini argument sifatida uzatib bo''lmaydi', 'Потому что функции JavaScript нельзя передавать в качестве аргументов', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-usestate-q10-opt1', 'react-usestate-q10', 1, 'Because React treats a bare function argument to useState/setState as a lazy initializer or updater and calls it immediately', 'Chunki React useState/setState-ga to''g''ridan-to''g''ri uzatilgan funksiyani initsializator yoki yangilovchi funksiya deb qabul qiladi va uni darhol chaqirib yuboradi', 'Потому что React воспринимает функцию, переданную напрямую в useState/setState, как ленивый инициализатор или функцию обновления и сразу вызывает её', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-usestate-q10-opt2', 'react-usestate-q10', 2, 'Because arrow functions are faster than regular functions', 'Chunki strelkali funksiyalar oddiy funksiyalardan tezroq ishlaydi', 'Потому что стрелочные функции быстрее обычных', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-usestate-q10-opt3', 'react-usestate-q10', 3, 'Because React converts bare functions into strings', 'Chunki React oddiy funksiyalarni satrlarga aylantirib yuboradi', 'Потому что React преобразует обычные функции в строки', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q1-opt0', 'react-useeffect-q1', 0, 'To synchronize a component with an external system (side effects like data fetching, subscriptions, or timers)', 'Komponentni tashqi tizim bilan sinxronlashtirish (ma''lumot yuklash, obunalar yoki taymerlar kabi yon ta''sirlar)', 'Синхронизация компонента с внешней системой (побочные эффекты, такие как загрузка данных, подписки или таймеры)', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q1-opt1', 'react-useeffect-q1', 1, 'To style components with CSS animations', 'Komponentlarni CSS animatsiyalari bilan bezash', 'Стилизация компонентов с помощью CSS-анимаций', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q1-opt2', 'react-useeffect-q1', 2, 'To replace JSX with plain HTML', 'JSX-ni oddiy HTML bilan almashtirish', 'Замена JSX на обычный HTML', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q1-opt3', 'react-useeffect-q1', 3, 'To compile TypeScript files', 'TypeScript fayllarini kompilyatsiya qilish', 'Компиляция файлов TypeScript', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q2-opt0', 'react-useeffect-q2', 0, 'On every state or prop change', 'Har bir state yoki prop o''zgarganda', 'При каждом изменении state или props', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q2-opt1', 'react-useeffect-q2', 1, 'Only once after the component mounts (initial render)', 'Komponent o''rnatilgandan (dastlabki renderdan) keyin faqat bir marta', 'Только один раз после монтирования компонента (первичного рендера)', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q2-opt2', 'react-useeffect-q2', 2, 'Before the component renders for the first time', 'Komponent birinchi marta render bo''lishidan oldin', 'До того, как компонент отрендерится в первый раз', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q2-opt3', 'react-useeffect-q2', 3, 'Only when the user clicks a button', 'Faqat foydalanuvchi tugmani bosganda', 'Только когда пользователь нажимает кнопку', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q3-opt0', 'react-useeffect-q3', 0, 'The effect never runs', 'Effekt hech qachon ishga tushmaydi', 'Эффект никогда не запустится', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q3-opt1', 'react-useeffect-q3', 1, 'The effect runs only when the component unmounts', 'Effekt faqat komponent o''chirilganda (unmount) ishlaydi', 'Эффект запустится только при размонтировании компонента', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q3-opt2', 'react-useeffect-q3', 2, 'The effect runs after the initial render AND after every single re-render', 'Effekt dastlabki renderdan keyin VA har bir qayta renderlashdan keyin ishga tushadi', 'Эффект будет запускаться после первого рендера И после каждого повторного рендера', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q3-opt3', 'react-useeffect-q3', 3, 'React throws a syntax error', 'React sintaksis xatosini chiqaradi', 'React выбросит синтаксическую ошибку', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q4-opt0', 'react-useeffect-q4', 0, 'By calling React.cleanup()', 'React.cleanup() funksiyasini chaqirish orqali', 'Вызвав React.cleanup()', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q4-opt1', 'react-useeffect-q4', 1, 'By passing a second callback parameter to useEffect', 'useEffect-ga ikkinchi callback parametrini uzatish orqali', 'Передав второй callback-параметр в useEffect', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q4-opt2', 'react-useeffect-q4', 2, 'By throwing an Error at the end of the effect', 'Effekt oxirida Error chiqarish orqali', 'Выбросив Error в конце эффекта', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q4-opt3', 'react-useeffect-q4', 3, 'By returning a cleanup function from the effect callback', 'Effekt callback funksiyasidan tozalash (cleanup) funksiyasini qaytarish (return) orqali', 'Вернув функцию очистки (cleanup function) из колбэка эффекта', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q5-opt0', 'react-useeffect-q5', 0, 'Both before the effect re-runs on a dependency change AND when the component unmounts', 'Ham bog''liqlik o''zgarganda effekt qayta ishlashidan oldin, HAM komponent o''chirilganda (unmount)', 'И перед повторным запуском эффекта при изменении зависимостей, И при размонтировании компонента', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q5-opt1', 'react-useeffect-q5', 1, 'Only when the browser window closes', 'Faqat brauzer oynasi yopilganda', 'Только при закрытии окна браузера', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q5-opt2', 'react-useeffect-q5', 2, 'Before the initial render of the component', 'Komponentning dastlabki renderidan oldin', 'Перед первичным рендером компонента', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q5-opt3', 'react-useeffect-q5', 3, 'Only when an error is thrown', 'Faqat xatolik yuz berganda', 'Только при возникновении ошибки', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q6-opt0', 'react-useeffect-q6', 0, 'Because setState blocks the JavaScript thread', 'Chunki setState JavaScript oqimini bloklaydi', 'Потому что setState блокирует поток JavaScript', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q6-opt1', 'react-useeffect-q6', 1, 'Because setState triggers a re-render, which runs useEffect again, which calls setState again endlessly', 'Chunki setState qayta renderlashni chaqiradi, u esa useEffect-ni qayta ishga tushiradi va bu jarayon cheksiz davom etadi', 'Потому что setState вызывает ререндер, который снова запускает useEffect, который снова вызывает setState до бесконечности', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q6-opt2', 'react-useeffect-q6', 2, 'Because React forbids calling setState inside any Hook', 'Chunki React har qanday Hook ichida setState chaqirishni taqiqlaydi', 'Потому что React запрещает вызывать setState внутри любых хуков', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q6-opt3', 'react-useeffect-q6', 3, 'Because the dependency array defaults to null', 'Chunki bog''liqliklar massivi standart holatda null bo''ladi', 'Потому что массив зависимостей по умолчанию равен null', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q7-opt0', 'react-useeffect-q7', 0, 'Make the useEffect callback itself async: useEffect(async () => { ... }, [])', 'useEffect callback funksiyasining o''zini async qilish: useEffect(async () => { ... }, [])', 'Сделать сам колбэк useEffect асинхронным: useEffect(async () => { ... }, [])', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q7-opt1', 'react-useeffect-q7', 1, 'Pass a Promise as the dependency array', 'Bog''liqliklar massivi sifatida Promise uzatish', 'Передать Promise вместо массива зависимостей', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q7-opt2', 'react-useeffect-q7', 2, 'Define an async function inside the effect callback (or outside) and call it', 'Effekt callback funksiyasi ichida (yoki tashqarisida) async funksiya e''lon qilib, uni chaqirish', 'Объявить async-функцию внутри колбэка эффекта (или снаружи) и вызвать её', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q7-opt3', 'react-useeffect-q7', 3, 'Use await directly outside any function', 'Hech qanday funksiyasiz to''g''ridan-to''g''ri await ishlatish', 'Использовать await напрямую вне функции', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q8-opt0', 'react-useeffect-q8', 0, 'Only global window properties', 'Faqat global window xususiyatlari', 'Только глобальные свойства window', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q8-opt1', 'react-useeffect-q8', 1, 'Only string literals', 'Faqat satr literallari', 'Только строковые литералы', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q8-opt2', 'react-useeffect-q8', 2, 'Nothing; dependency arrays should always be empty', 'Hech narsa; bog''liqliklar massivi har doim bo''sh bo''lishi kerak', 'Ничего; массив зависимостей всегда должен быть пустым', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q8-opt3', 'react-useeffect-q8', 3, 'All reactive values (props, state, and variables/functions derived from them) read inside the effect', 'Effekt ichida o''qiladigan barcha reaktiv qiymatlar (props, state va ulardan hosil qilingan o''zgaruvchilar/funksiyalar)', 'Все реактивные значения (props, state и производные от них переменные/функции), используемые внутри эффекта', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q9-opt0', 'react-useeffect-q9', 0, 'Use an AbortController or an `ignore` boolean flag inside the effect''s cleanup function to discard stale responses', 'Eskirgan javoblarni bekor qilish uchun effektning tozalash (cleanup) funksiyasida AbortController yoki `ignore` mantiqiy bayrog''idan foydalanish', 'Использовать AbortController или булев флаг `ignore` в функции очистки эффекта для отбрасывания устаревших ответов', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q9-opt1', 'react-useeffect-q9', 1, 'Remove userId from the dependency array', 'userId-ni bog''liqliklar massividan olib tashlash', 'Удалить userId из массива зависимостей', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q9-opt2', 'react-useeffect-q9', 2, 'Use synchronous XMLHttpRequest instead of fetch', 'fetch o''rniga sinxron XMLHttpRequest ishlatish', 'Использовать синхронный XMLHttpRequest вместо fetch', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q9-opt3', 'react-useeffect-q9', 3, 'Call window.stop() after every fetch', 'Har bir so''rovdan keyin window.stop() ni chaqirish', 'Вызывать window.stop() после каждого запроса', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q10-opt0', 'react-useeffect-q10', 0, 'useLayoutEffect only works on mobile devices', 'useLayoutEffect faqat mobil qurilmalarda ishlaydi', 'useLayoutEffect работает только на мобильных устройствах', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q10-opt1', 'react-useeffect-q10', 1, 'useLayoutEffect fires synchronously after DOM mutations but before the browser paints the screen', 'useLayoutEffect DOM o''zgarishlaridan so''ng, lekin brauzer ekranni chizishidan (paint) oldin sinxron ravishda ishga tushadi', 'useLayoutEffect выполняется синхронно после мутаций DOM, но до того, как браузер отрисует (paint) экран', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q10-opt2', 'react-useeffect-q10', 2, 'useLayoutEffect runs on the server during SSR', 'useLayoutEffect SSR vaqtida serverda ishlaydi', 'useLayoutEffect запускается на сервере во время SSR', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-useeffect-q10-opt3', 'react-useeffect-q10', 3, 'useEffect runs before the component function executes', 'useEffect komponent funksiyasi bajarilishidan oldin ishlaydi', 'useEffect запускается до выполнения функции компонента', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-router-q1-opt0', 'react-router-q1', 0, 'Client-side routing and navigation between views without full page reloads', 'Sahifani to''liq qayta yuklamasdan sahifalar o''rtasida mijoz tomonida (client-side) yo''naltirish va navigatsiya', 'Клиентская маршрутизация и навигация между страницами без полной перезагрузки страницы', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-router-q1-opt1', 'react-router-q1', 1, 'Managing backend SQL migrations', 'Backend SQL migratsiyalarini boshqarish', 'Управление миграциями баз данных SQL на бэкенде', false) ON CONFLICT (id) DO NOTHING;
