INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-router-q3-opt1', 'react-router-q3', 1, 'Because <Link> automatically translates the page into 10 languages', 'Chunki <Link> sahifani avtomatik ravishda 10 ta tilga tarjima qiladi', 'Потому что <Link> автоматически переводит страницу на 10 языков', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-router-q3-opt2', 'react-router-q3', 2, 'Because <Link> intercepts the click and navigates client-side without reloading the entire browser page', 'Chunki <Link> bosishni ushlab qoladi va butun brauzer sahifasini qayta yuklamasdan mijoz tomonida o''tishni bajaradi', 'Потому что <Link> перехватывает клик и выполняет переход на клиенте без перезагрузки всей страницы браузера', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-router-q3-opt3', 'react-router-q3', 3, 'Because <a> tags cannot be styled with CSS', 'Chunki <a> teglariga CSS bilan uslub berib bo''lmaydi', 'Потому что теги <a> нельзя стилизовать с помощью CSS', false) ON CONFLICT (id) DO NOTHING;
