INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-router-q9-opt0', 'react-router-q9', 0, '<NavLink> knows whether its destination matches the current URL and provides `isActive` for styling active navigation items', '<NavLink> o''z manzili joriy URL-ga mos kelish-kelmasligini biladi va faol menyu elementlarini bezash uchun `isActive` holatini taqdim etadi', '<NavLink> знает, совпадает ли его адрес с текущим URL, и предоставляет `isActive` для стилизации активных пунктов меню', true) ON CONFLICT (id) DO NOTHING;
