INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-router-q9-opt2', 'react-router-q9', 2, '<NavLink> reloads the page on every click', '<NavLink> har bir bosishda sahifani qayta yuklaydi', '<NavLink> перезагружает страницу при каждом клике', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-router-q9-opt3', 'react-router-q9', 3, '<NavLink> cannot accept a `to` prop', '<NavLink> `to` prop-ini qabul qila olmaydi', '<NavLink> не может принимать проп `to`', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-router-q10-opt0', 'react-router-q10', 0, 'To delete the login page from history', 'Login sahifasini tarixdan o''chirish uchun', 'Чтобы удалить страницу входа из истории', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-router-q10-opt1', 'react-router-q10', 1, 'The `replace` prop replaces the unauthorized entry in the history stack so pressing the browser Back button does not loop back to the protected page', '`replace` prop-i tarix stekidagi ruxsatsiz yozuvni almashtiradi, natijada brauzerning "Orqaga" tugmasini bosish foydalanuvchini yana himoyalangan sahifaga qaytarib yubormaydi', 'Проп `replace` заменяет неавторизованную запись в стеке истории, чтобы нажатие кнопки «Назад» в браузере не возвращало пользователя снова на защищенную страницу', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-router-q10-opt2', 'react-router-q10', 2, 'To encrypt the /login route parameters', '/login yo''nalishi parametrlarini shifrlash uchun', 'Чтобы зашифровать параметры маршрута /login', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-router-q10-opt3', 'react-router-q10', 3, 'To open the login page in a new browser window', 'Login sahifasini yangi brauzer oynasida ochish uchun', 'Чтобы открыть страницу входа в новом окне браузера', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q1-opt0', 'react-events-q1', 0, 'Using camelCase, such as onClick and onChange', 'camelCase yordamida, masalan onClick va onChange', 'В стиле camelCase, например onClick и onChange', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q1-opt1', 'react-events-q1', 1, 'Using all lowercase, such as onclick and onchange', 'Barchasi kichik harflarda, masalan onclick va onchange', 'Всеми строчными буквами, например onclick и onchange', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q1-opt2', 'react-events-q1', 2, 'Using snake_case, such as on_click and on_change', 'snake_case yordamida, masalan on_click va on_change', 'В стиле snake_case, например on_click и on_change', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q1-opt3', 'react-events-q1', 3, 'Using UPPERCASE, such as ONCLICK', 'KATTA HARFLARDA, masalan ONCLICK', 'ЗАГЛАВНЫМИ БУКВАМИ, например ONCLICK', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q2-opt0', 'react-events-q2', 0, 'There is no difference', 'Hech qanday farq yo''q', 'Разницы нет', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q2-opt1', 'react-events-q2', 1, '`onClick={handleClick}` passes the function to be called on click, while `onClick={handleClick()}` calls it immediately during rendering', '`onClick={handleClick}` funksiyani bosilganda chaqirish uchun uzatadi, `onClick={handleClick()}` esa uni render vaqtidayoq darhol chaqirib yuboradi', '`onClick={handleClick}` передает функцию для вызова при клике, а `onClick={handleClick()}` вызывает её немедленно во время рендеринга', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q2-opt2', 'react-events-q2', 2, '`onClick={handleClick()}` is the recommended way to bind events', '`onClick={handleClick()}` hodisalarni bog''lashning tavsiya etilgan usuli', '`onClick={handleClick()}` — рекомендуемый способ привязки событий', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q2-opt3', 'react-events-q2', 3, '`onClick={handleClick}` causes a syntax error', '`onClick={handleClick}` sintaksis xatosiga olib keladi', '`onClick={handleClick}` вызывает синтаксическую ошибку', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q3-opt0', 'react-events-q3', 0, 'Return false from the component', 'Komponentdan false qaytarish orqali', 'Вернуть false из компонента', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q3-opt1', 'react-events-q3', 1, 'Call window.cancelSubmit()', 'window.cancelSubmit() ni chaqirish orqali', 'Вызвать window.cancelSubmit()', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q3-opt2', 'react-events-q3', 2, 'Call event.preventDefault() inside the onSubmit handler', 'onSubmit ishlovchisi ichida event.preventDefault() ni chaqirish orqali', 'Вызвать event.preventDefault() внутри обработчика onSubmit', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q3-opt3', 'react-events-q3', 3, 'Add reload="false" to the form tag', 'form tegiga reload="false" qo''shish orqali', 'Добавить reload="false" к тегу form', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q4-opt0', 'react-events-q4', 0, 'event.input.text', 'event.input.text', 'event.input.text', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q4-opt1', 'react-events-q4', 1, 'event.currentText()', 'event.currentText()', 'event.currentText()', false) ON CONFLICT (id) DO NOTHING;
