INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q4-opt3', 'react-events-q4', 3, 'event.target.value', 'event.target.value', 'event.target.value', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q5-opt0', 'react-events-q5', 0, 'Use an arrow function wrapper: `onClick={() => handleDelete(item.id)}`', 'Strelkali funksiya o''ramidan foydalanib: `onClick={() => handleDelete(item.id)}`', 'Использовать обертку из стрелочной функции: `onClick={() => handleDelete(item.id)}`', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q5-opt1', 'react-events-q5', 1, 'Write `onClick={handleDelete(item.id)}` directly', 'To''g''ridan-to''g''ri `onClick={handleDelete(item.id)}` deb yozib', 'Написать напрямую `onClick={handleDelete(item.id)}`', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q5-opt2', 'react-events-q5', 2, 'Pass it as a separate HTML attribute: `onClick={handleDelete} arg={item.id}`', 'Alohida HTML atributi sifatida uzatib: `onClick={handleDelete} arg={item.id}`', 'Передать отдельным HTML-атрибутом: `onClick={handleDelete} arg={item.id}`', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q5-opt3', 'react-events-q5', 3, 'React event handlers cannot accept arguments', 'React hodisa ishlovchilari argument qabul qila olmaydi', 'Обработчики событий в React не могут принимать аргументы', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q6-opt0', 'react-events-q6', 0, 'A fake event used only in unit tests', 'Faqat unit-testlarda ishlatiladigan soxta hodisa', 'Фиктивное событие, используемое только в модульных тестах', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q6-opt1', 'react-events-q6', 1, 'A cross-browser wrapper around the browser''s native event that provides a consistent API across all browsers', 'Barcha brauzerlarda bir xil API taqdim etish uchun brauzerning mahalliy hodisasi (native event) ustidan yozilgan kross-brauzer o''ram (wrapper)', 'Кроссбраузерная обертка вокруг нативного события браузера, обеспечивающая единый API во всех браузерах', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q6-opt2', 'react-events-q6', 2, 'A custom WebSocket message format', 'Maxsus WebSocket xabar formati', 'Пользовательский формат сообщений WebSocket', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q6-opt3', 'react-events-q6', 3, 'A CSS animation trigger', 'CSS animatsiya ishga tushiruvchisi', 'Триггер CSS-анимации', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q7-opt0', 'react-events-q7', 0, 'event.preventDefault()', 'event.preventDefault()', 'event.preventDefault()', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q7-opt1', 'react-events-q7', 1, 'event.halt()', 'event.halt()', 'event.halt()', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q7-opt2', 'react-events-q7', 2, 'event.stopPropagation()', 'event.stopPropagation()', 'event.stopPropagation()', true) ON CONFLICT (id) DO NOTHING;
