INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q8-opt0', 'react-events-q8', 0, 'React onChange only fires when the user presses Enter', 'React onChange faqat foydalanuvchi Enter tugmasini bosganda ishlaydi', 'React onChange срабатывает только при нажатии клавиши Enter', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q8-opt1', 'react-events-q8', 1, 'React onChange only fires when the input loses focus (on blur)', 'React onChange faqat kiritish maydoni fokusni yo''qotganda (blur) ishlaydi', 'React onChange срабатывает только при потере фокуса полем (on blur)', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q8-opt2', 'react-events-q8', 2, 'React onChange fires every 5 seconds on a timer', 'React onChange taymer bo''yicha har 5 soniyada ishlaydi', 'React onChange срабатывает каждые 5 секунд по таймеру', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q8-opt3', 'react-events-q8', 3, 'React onChange fires on every keystroke (like the native `input` event), whereas native `change` fires on blur', 'React onChange har bir tugma bosilganda (mahalliy `input` hodisasi kabi) ishlaydi, mahalliy `change` esa fokus yo''qolganda ishlaydi', 'React onChange срабатывает при каждом нажатии клавиши (как нативное событие `input`), тогда как нативный `change` срабатывает при потере фокуса', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q9-opt0', 'react-events-q9', 0, 'To the root DOM container where the React tree is mounted (instead of `document` as in React 16)', 'React daraxti o''rnatilgan ildiz (root) DOM konteyneriga (React 16 dagi `document` o''rniga)', 'К корневому DOM-контейнеру, в который смонтировано дерево React (вместо `document`, как было в React 16)', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q9-opt1', 'react-events-q9', 1, 'Individually to every single DOM node', 'Har bir DOM tuguniga alohida-alohida', 'Отдельно к каждому DOM-узлу', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q9-opt2', 'react-events-q9', 2, 'To the window.navigator object', 'window.navigator obyektiga', 'К объекту window.navigator', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q9-opt3', 'react-events-q9', 3, 'To the HTML <head> element', 'HTML <head> elementiga', 'К HTML-элементу <head>', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q10-opt0', 'react-events-q10', 0, 'Pass `{ capture: true }` as a second argument inside onClick', 'onClick ichida ikkinchi argument sifatida `{ capture: true }` uzatish orqali', 'Передать `{ capture: true }` вторым аргументом в onClick', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q10-opt1', 'react-events-q10', 1, 'Append `Capture` to the event prop name, such as `onClickCapture`', 'Hodisa prop nomiga `Capture` qo''shimchasini qo''shish orqali, masalan `onClickCapture`', 'Добавить `Capture` в конец имени пропа события, например `onClickCapture`', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q10-opt2', 'react-events-q10', 2, 'Prefix the event name with `capture_`, such as `capture_onClick`', 'Hodisa nomi oldiga `capture_` qo''shish orqali, masalan `capture_onClick`', 'Добавить префикс `capture_` к имени события, например `capture_onClick`', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-events-q10-opt3', 'react-events-q10', 3, 'React does not support the capture phase', 'React tutib olish (capture) bosqichini qo''llab-quvvatlamaydi', 'React не поддерживает фазу перехвата (capture)', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q1-opt0', 'react-advanced-q1', 0, 'Sharing data (like theme, locale, or authenticated user) across the component tree without manual prop drilling', 'Ma''lumotlarni (masalan, mavzu, til yoki foydalanuvchi) qo''lda prop drilling qilmasdan komponentlar daraxti bo''ylab ulashish', 'Передача данных (например, темы, языка или текущего пользователя) по дереву компонентов без ручного пробрасывания пропсов (prop drilling)', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q1-opt1', 'react-advanced-q1', 1, 'Optimizing SQL database queries', 'SQL ma''lumotlar bazasi so''rovlarini optimallashtirish', 'Оптимизация запросов к базе данных SQL', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q1-opt2', 'react-advanced-q1', 2, 'Compiling JSX without Babel', 'JSX-ni Babel-siz kompilyatsiya qilish', 'Компиляция JSX без Babel', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q1-opt3', 'react-advanced-q1', 3, 'Automatically generating unit tests', 'Unit-testlarni avtomatik yaratish', 'Автоматическая генерация модульных тестов', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q2-opt0', 'react-advanced-q2', 0, 'Fetching API data and managing URL routes', 'API ma''lumotlarini yuklash va URL yo''nalishlarini boshqarish', 'Загрузка данных из API и управление маршрутами URL', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q2-opt1', 'react-advanced-q2', 1, 'Accessing DOM nodes directly and storing a mutable value that persists across renders without triggering re-renders', 'DOM tugunlariga bevosita murojaat qilish va qayta renderlashni chaqirmasdan renderlar orasida saqlanadigan o''zgaruvchan qiymatni saqlash', 'Прямой доступ к узлам DOM и хранение изменяемого значения, сохраняющегося между рендерами без вызова повторного рендеринга', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q2-opt2', 'react-advanced-q2', 2, 'Creating global CSS styles and animations', 'Global CSS uslublari va animatsiyalarini yaratish', 'Создание глобальных CSS-стилей и анимаций', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q2-opt3', 'react-advanced-q2', 3, 'Validating prop types and encrypting state', 'Prop turlarini tekshirish va holatni shifrlash', 'Проверка типов пропсов и шифрование состояния', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q3-opt0', 'react-advanced-q3', 0, 'useMemo runs on the server, while useCallback runs on the client', 'useMemo serverda, useCallback esa mijozda ishlaydi', 'useMemo работает на сервере, а useCallback — на клиенте', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q3-opt1', 'react-advanced-q3', 1, 'useMemo is for class components, while useCallback is for functional components', 'useMemo klass komponentlar uchun, useCallback esa funksional komponentlar uchun', 'useMemo предназначен для классовых компонентов, а useCallback — для функциональных', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q3-opt2', 'react-advanced-q3', 2, 'useMemo caches the computed result of calling a function, whereas useCallback caches the function reference itself', 'useMemo funksiya chaqiruvining hisoblangan natijasini keshlaydi, useCallback esa funksiyaning o''z havolasini (reference) keshlaydi', 'useMemo кэширует вычисленный результат вызова функции, тогда как useCallback кэширует саму ссылку на функцию', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q3-opt3', 'react-advanced-q3', 3, 'useMemo triggers a re-render, whereas useCallback prevents mounting', 'useMemo qayta renderlashni chaqiradi, useCallback esa o''rnatishni to''xtatadi', 'useMemo вызывает ререндер, а useCallback предотвращает монтирование', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q4-opt0', 'react-advanced-q4', 0, 'When storing a single boolean toggle', 'Bitta mantiqiy (boolean) almashtirgichni saqlashda', 'При хранении одного булева переключателя', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q4-opt1', 'react-advanced-q4', 1, 'When you never need to update the state', 'Holatni hech qachon yangilash kerak bo''lmaganda', 'Когда состояние никогда не нужно обновлять', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q4-opt2', 'react-advanced-q4', 2, 'When rendering static HTML without interactivity', 'Interaktivliksiz statik HTML-ni render qilishda', 'При рендеринге статического HTML без интерактивности', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q4-opt3', 'react-advanced-q4', 3, 'When state logic is complex, involves multiple sub-values, or the next state depends on structured actions', 'Holat mantiqi murakkab bo''lganda, bir nechta qism qiymatlarni o''z ichiga olganda yoki keyingi holat tuzilmali harakatlarga (actions) bog''liq bo''lganda', 'Когда логика состояния сложна, включает несколько взаимосвязанных значений или следующее состояние зависит от структурированных действий (actions)', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q5-opt0', 'react-advanced-q5', 0, 'With the prefix "use" followed by a capital letter (e.g., useAuth, useWindowSize)', '"use" old qo''shimchasi va undan keyin katta harf bilan (masalan, useAuth, useWindowSize)', 'С префикса "use", за которым следует заглавная буква (например, useAuth, useWindowSize)', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q5-opt1', 'react-advanced-q5', 1, 'With the prefix "hook" (e.g., hookAuth)', '"hook" old qo''shimchasi bilan (masalan, hookAuth)', 'С префикса "hook" (например, hookAuth)', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q5-opt2', 'react-advanced-q5', 2, 'With an underscore (e.g., _authHook)', 'Pastki chiziq bilan (masalan, _authHook)', 'С символа подчеркивания (например, _authHook)', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q5-opt3', 'react-advanced-q5', 3, 'With a capital letter like a component (e.g., UseAuth)', 'Komponent kabi katta harf bilan (masalan, UseAuth)', 'С заглавной буквы, как компонент (например, UseAuth)', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q6-opt0', 'react-advanced-q6', 0, 'They compress images into WebP format at runtime', 'Ular ish vaqtida rasmlarni WebP formatiga siqadi', 'Они сжимают изображения в формат WebP во время выполнения', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q6-opt1', 'react-advanced-q6', 1, '`React.lazy` dynamically imports a component bundle on demand, and `<Suspense fallback={...}>` displays a loading UI while it downloads', '`React.lazy` komponent paketini talab bo''yicha dinamik import qiladi, `<Suspense fallback={...}>` esa u yuklanayotgan vaqtda kutish interfeysini ko''rsatadi', '`React.lazy` динамически импортирует бандл компонента по требованию, а `<Suspense fallback={...}>` отображает индикатор загрузки во время скачивания', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q6-opt2', 'react-advanced-q6', 2, 'They pre-render the database schema on the client', 'Ular mijozda ma''lumotlar bazasi sxemasini oldindan render qiladi', 'Они предварительно рендерят схему базы данных на клиенте', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q6-opt3', 'react-advanced-q6', 3, 'They convert asynchronous functions into synchronous loops', 'Ular asinxron funksiyalarni sinxron sikllarga aylantiradi', 'Они преобразуют асинхронные функции в синхронные циклы', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q7-opt0', 'react-advanced-q7', 0, 'To transfer state between two different websites', 'Ikki xil veb-sayt o''rtasida holatni o''tkazish uchun', 'Для передачи состояния между двумя разными веб-сайтами', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q7-opt1', 'react-advanced-q7', 1, 'To connect a React frontend directly to a PostgreSQL port', 'React frontendini to''g''ridan-to''g''ri PostgreSQL portiga ulash uchun', 'Для прямого подключения фронтенда React к порту PostgreSQL', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q7-opt2', 'react-advanced-q7', 2, 'To render a child component into a DOM node outside its parent DOM hierarchy (useful for modals, tooltips, and popovers)', 'Bola komponentni o''zining ona DOM iyerarxiyasidan tashqaridagi DOM tuguniga render qilish uchun (modal oynalar, tooltip va popoverlar uchun foydali)', 'Для рендеринга дочернего компонента в узел DOM вне родительской DOM-иерархии (полезно для модальных окон, тултипов и поповеров)', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q7-opt3', 'react-advanced-q7', 3, 'To speed up network fetch requests', 'Tarmoq fetch so''rovlarini tezlashtirish uchun', 'Для ускорения сетевых запросов fetch', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q8-opt0', 'react-advanced-q8', 0, 'Because functional components cannot return fallback JSX', 'Chunki funksional komponentlar zaxira JSX qaytara olmaydi', 'Потому что функциональные компоненты не могут возвращать запасной JSX', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q8-opt1', 'react-advanced-q8', 1, 'Because try/catch blocks are illegal inside functional components', 'Chunki funksional komponentlar ichida try/catch bloklarini ishlatish taqiqlangan', 'Потому что блоки try/catch запрещены внутри функциональных компонентов', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q8-opt2', 'react-advanced-q8', 2, 'Because class components execute faster in all browsers', 'Chunki klass komponentlari barcha brauzerlarda tezroq ishlaydi', 'Потому что классовые компоненты выполняются быстрее во всех браузерах', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q8-opt3', 'react-advanced-q8', 3, 'Because there is currently no Hook equivalent for `getDerivedStateFromError` or `componentDidCatch`', 'Chunki hozircha `getDerivedStateFromError` yoki `componentDidCatch` uchun Hook ekvivalenti mavjud emas', 'Потому что в настоящее время не существует хука-эквивалента для `getDerivedStateFromError` или `componentDidCatch`', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q9-opt0', 'react-advanced-q9', 0, 'To mark certain state updates as non-urgent transitions so the UI stays responsive during heavy re-renders', 'Og''ir qayta renderlar vaqtida interfeys qotib qolmasligi uchun ayrim holat yangilanishlarini shoshilinch bo''lmagan o''tishlar (transitions) sifatida belgilash', 'Помечать определенные обновления состояния как несрочные переходы (transitions), чтобы интерфейс оставался отзывчивым во время тяжелых перерисовок', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q9-opt1', 'react-advanced-q9', 1, 'To animate CSS opacity and transform properties automatically', 'CSS opacity va transform xususiyatlarini avtomatik animatsiya qilish', 'Автоматически анимировать CSS-свойства opacity и transform', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q9-opt2', 'react-advanced-q9', 2, 'To transition components from JavaScript to TypeScript', 'Komponentlarni JavaScript-dan TypeScript-ga o''tkazish', 'Переводить компоненты с JavaScript на TypeScript', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q9-opt3', 'react-advanced-q9', 3, 'To migrate data between Redux and Context', 'Ma''lumotlarni Redux va Context o''rtasida ko''chirish', 'Переносить данные между Redux и Context', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q10-opt0', 'react-advanced-q10', 0, 'Yes, custom Hooks act as global singletons', 'Ha, maxsus Hook-lar global yagona obyekt (singleton) sifatida ishlaydi', 'Да, пользовательские хуки работают как глобальные синглтоны', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q10-opt1', 'react-advanced-q10', 1, 'No, custom Hooks share stateful logic, not state itself—each call creates completely isolated state', 'Yo''q, maxsus Hook-lar holatning o''zini emas, balki holat bilan ishlash mantiqini ulashadi — har bir chaqiruv butunlay alohida holat yaratadi', 'Нет, пользовательские хуки делятся логикой работы с состоянием, а не самим состоянием — каждый вызов создает полностью изолированное состояние', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q10-opt2', 'react-advanced-q10', 2, 'Yes, if both components are rendered inside the same parent', 'Ha, agar ikkala komponent ham bitta ona komponent ichida render qilingan bo''lsa', 'Да, если оба компонента рендерятся внутри одного родителя', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('react-advanced-q10-opt3', 'react-advanced-q10', 3, 'Only when the custom Hook uses useReducer', 'Faqat maxsus Hook useReducer ishlatganda', 'Только если пользовательский хук использует useReducer', false) ON CONFLICT (id) DO NOTHING;
