INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('ru-verbs-q4-opt0', 'ru-verbs-q4', 0, 'By gender (in singular) and number (читал, читала, читало, читали)', 'Birlikda jins (род) bo''yicha va son (число) bo''yicha (читал, читала, читало, читали)', 'По родам (в единственном числе) и числам (читал, читала, читало, читали)', true) ON CONFLICT (id) DO NOTHING;
