INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('ru-verbs-q4-opt3', 'ru-verbs-q4', 3, 'They never change their endings', 'Hech qachon o''zgarmaydi', 'Не изменяются совсем', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('ru-verbs-q5-opt0', 'ru-verbs-q5', 0, '"Делать" is plural and "сделать" is singular', '"Делать" ko''plikda, "сделать" esa birlikda', '«Делать» — множественное число, «сделать» — единственное', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('ru-verbs-q5-opt1', 'ru-verbs-q5', 1, '"Делать" focuses on an ongoing or repeated process, while "сделать" focuses on a completed action and its result', '"Делать" davomiy yoki takroriy jarayonni, "сделать" esa tugallangan harakat va natijani bildiradi', '«Делать» обозначает процесс или повторяющееся действие, а «сделать» — завершённое действие и его результат', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('ru-verbs-q5-opt2', 'ru-verbs-q5', 2, '"Делать" is only used in the future, "сделать" only in the past', '"Делать" faqat kelasi zamonda, "сделать" faqat o''tgan zamonda ishlatiladi', '«Делать» используется только в будущем времени', false) ON CONFLICT (id) DO NOTHING;
