INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('ru-sentences-q4-opt0', 'ru-sentences-q4', 0, '"Что" reports a statement or fact ("Я знаю, что..."), while "чтобы" expresses purpose or desire ("Я хочу, чтобы...")', '"Что" xabar yoki faktni ("Я знаю, что..."), "чтобы" esa maqsad yoki istakni ("Я хочу, чтобы...") ifodalaydi', '«Что» вводит изъяснение факта («Я знаю, что...»), а «чтобы» — цель или желание («Я хочу, чтобы...»)', true) ON CONFLICT (id) DO NOTHING;
