INSERT INTO public.answer_options (id, question_id, option_index, option_text_en, option_text_uz, option_text_ru, is_correct) VALUES ('ru-sentences-q5-opt1', 'ru-sentences-q5', 1, 'In Russian, new or emphasized information (the rheme) is typically placed at the end of the sentence', 'Rus tilida yangi yoki mantiqiy urg''u tushgan ma''lumot (рема) odatda gap oxiriga qo''yiladi', 'В русском языке новая, наиболее важная информация (рема) обычно помещается в конец предложения', true) ON CONFLICT (id) DO NOTHING;
